# File logging is attached only when the server actually starts (see
# main() / _setup_file_logging). Importing this module — e.g. from pytest
# fixtures — must NOT touch ~/.vireo/vireo.log, or test tracebacks end up
# in the user's real log file.
def _setup_file_logging(log_dir=None):
    root = logging.getLogger()
    if any(getattr(h, "_vireo_file_handler", False) for h in root.handlers):
        return
    if log_dir is None:
        log_dir = os.path.expanduser("~/.vireo")
    os.makedirs(log_dir, exist_ok=True)
    handler = logging.handlers.RotatingFileHandler(
        os.path.join(log_dir, "vireo.log"),
        maxBytes=5 * 1024 * 1024,  # 5 MB
        backupCount=3,
    )
    handler._vireo_file_handler = True
    handler.setFormatter(
        logging.Formatter(
            "%(asctime)s %(levelname)s %(name)s: %(message)s",
            datefmt="%Y-%m-%d %H:%M:%S",
        )
    )
    root.addHandler(handler)


# Suppress noisy werkzeug request logs for polling endpoints
class _QuietRequestFilter(logging.Filter):
    """Filter out repetitive GET requests from werkzeug logs."""

    _quiet_paths = {"/api/jobs", "/api/logs/stream", "/api/logs/recent", "/thumbnails/"}

    def filter(self, record):
        msg = record.getMessage()
        if "200" in msg or "304" in msg:
            for path in self._quiet_paths:
                if f"GET {path}" in msg:
                    return False
        return True


logging.getLogger("werkzeug").addFilter(_QuietRequestFilter())


def _sync_preview_coordinate_text(location):
    """Return a compact, truthful coordinate label for sync review."""
    if not location:
        return None
    latitude = location.get("latitude")
    longitude = location.get("longitude")
    if latitude is not None and longitude is not None:
        return f"{latitude:.5f}, {longitude:.5f}"
    raw_latitude = location.get("raw_latitude")
    raw_longitude = location.get("raw_longitude")
    if raw_latitude is None and raw_longitude is None:
        return None
    return ", ".join(
        str(value) for value in (raw_latitude, raw_longitude)
        if value is not None
    )


def _sync_preview_location_name(location):
    """Format a location keyword leaf and its parents from specific to broad."""
    if not location:
        return None
    names = [location.get("name")]
    names.extend(
        parent.get("name")
        for parent in reversed(location.get("parent_chain") or [])
    )
    result = []
    seen = set()
    for name in names:
        if not name:
            continue
        key = name.casefold()
        if key in seen:
            continue
        seen.add(key)
        result.append(name)
    return ", ".join(result) or None


def _sync_preview_absent_xmp_value(metadata, empty_value):
    if metadata.get("status") == "missing":
        return "No XMP sidecar"
    if metadata.get("status") == "unreadable":
        return "Unreadable XMP sidecar"
    return empty_value


_SYNC_PREVIEW_FIELD_LABELS = {
    "keyword_add": "Keyword",
    "keyword_remove": "Keyword",
    "keyword_remove_flat": "Keyword",
    "rating": "Rating",
    "flag": "Flag",
    "location": "Location",
    "edit_recipe": "Photo edits",
}


def _sync_preview_folder_offline_presentation(change_type):
    """Presentation for a change whose photo folder isn't accessible.

    ``sync_to_xmp`` calls ``os.path.isdir(os.path.dirname(xmp_path))`` before
    every write; when it returns False the photo is recorded as
    ``folder not accessible`` and none of the writers run. Mirror that no-op
    in the review so a NAS-offline or unmounted-folder photo does not appear
    to promise XMP changes that will never happen.
    """
    field = _SYNC_PREVIEW_FIELD_LABELS.get(
        change_type,
        change_type.replace("_", " ").strip().title() or "Metadata",
    )
    placeholder = "Folder not accessible"
    return {
        "field": field,
        "action": "unchanged",
        "before": placeholder,
        "after": placeholder,
        "after_detail": (
            "Sync will skip this photo because its folder is offline; "
            "no XMP will be written"
        ),
    }


def _sync_preview_rating_label(value):
    if value in (None, "", "0", 0):
        return "Unrated"
    try:
        rating = int(value)
    except (TypeError, ValueError):
        return str(value)
    return f"{rating} star" if rating == 1 else f"{rating} stars"


def _sync_preview_flag_label(value):
    return {
        None: "Unflagged",
        "": "Unflagged",
        "none": "Unflagged",
        "flagged": "Picked",
        "rejected": "Rejected",
    }.get(value, str(value))


def _discard_history_items(db, changes):
    """Build durable discard history without conflating keyword homonyms."""
    items = []
    for change in changes:
        discarded_keyword_id = ""
        if change["change_type"] == "keyword_add":
            associations = db.conn.execute(
                """SELECT pk.keyword_id, pk.source,
                          EXISTS (
                              SELECT 1
                              FROM edit_history_items item
                              JOIN edit_history edit ON edit.id = item.edit_id
                              WHERE item.photo_id = pk.photo_id
                                AND edit.action_type = 'keyword_add'
                                AND edit.undone = 0
                                AND item.new_value = CAST(pk.keyword_id AS TEXT)
                          ) AS has_exact_history
                   FROM photo_keywords pk
                   JOIN keywords k ON k.id = pk.keyword_id
                   WHERE pk.photo_id = ?
                     AND k.name = ? COLLATE NOCASE""",
                (change["photo_id"], change["value"]),
            ).fetchall()
            evidenced = [
                row for row in associations
                if row["source"] == "manual" or row["has_exact_history"]
            ]
            if len(associations) == 1:
                discarded_keyword_id = str(associations[0]["keyword_id"])
            elif len(evidenced) == 1:
                discarded_keyword_id = str(evidenced[0]["keyword_id"])
        items.append({
            "photo_id": change["photo_id"],
            "old_value": f'{change["change_type"]}:{change["value"]}',
            "new_value": discarded_keyword_id,
        })
    return items


def _sync_preview_presentation(
    change, metadata, *, assigned_location=None, write_locations=False,
    sidecar_will_exist=False, sync_flags=False, paired_keyword_rename=False,
    paired_add_value=None, folder_offline=False,
):
    """Translate one internal pending row into user-facing XMP before/after data."""
    change_type = change["change_type"]
    value = change["value"]

    if folder_offline:
        return _sync_preview_folder_offline_presentation(change_type)

    if change_type in {"keyword_add", "keyword_remove", "keyword_remove_flat"}:
        existing = next(
            (
                keyword for keyword in metadata.get("keywords", set())
                if keyword_match_key(keyword) == keyword_match_key(value)
            ),
            None,
        )
        # Solo keyword_remove routes through remove_keywords() with
        # hierarchical=True in sync.py, which drops every
        # lr:hierarchicalSubject whose segments match this key in addition
        # to the flat dc:subject entry. Collect every hierarchy sync would
        # touch so the review reflects the full deletion.
        matching_hierarchies = []
        if change_type == "keyword_remove":
            matching_hierarchies = sorted(
                keyword
                for keyword in metadata.get("hierarchical_keywords", set())
                if any(
                    keyword_match_key(segment) == keyword_match_key(value)
                    for segment in keyword.split("|")
                )
            )
        hierarchy_display = [
            keyword.replace("|", " › ") for keyword in matching_hierarchies
        ]
        if (
            change_type == "keyword_remove"
            and paired_keyword_rename
            and hierarchy_display
        ):
            hierarchy_text = "; ".join(hierarchy_display)
            return {
                "field": "Keyword hierarchy",
                "action": "unchanged",
                "before": hierarchy_text,
                "after": hierarchy_text,
                "after_detail": (
                    "The matching keyword addition replaces only the "
                    "flat spelling; this hierarchy stays in XMP"
                ),
            }
        # A paired flat-only rename (e.g. remove `‘apapane` + add `apapane`)
        # is dispatched through the flat-only remove path in sync.py, and
        # the paired write_sidecar then adds the clean spelling. Reporting
        # the removal as `Not in XMP` hides that the keyword survives with
        # a canonicalized flat spelling; show it as an unchanged keyword
        # whose flat entry is being rewritten by the paired addition.
        if (
            change_type == "keyword_remove"
            and paired_keyword_rename
            and existing
            and paired_add_value
            and not hierarchy_display
        ):
            return {
                "field": "Keyword",
                "action": "unchanged",
                "before": existing,
                "after": paired_add_value,
                "after_detail": (
                    "The matching keyword addition rewrites this flat "
                    "spelling; the keyword itself stays in XMP"
                ),
            }
        xmp_value = existing or _sync_preview_absent_xmp_value(
            metadata, "Not in XMP",
        )
        if change_type == "keyword_add":
            return {
                "field": "Keyword",
                "action": "added",
                "before": xmp_value,
                "after": value,
            }
        if change_type == "keyword_remove" and not paired_keyword_rename:
            removed_entries = []
            if existing:
                removed_entries.append(existing)
            removed_entries.extend(hierarchy_display)
            if removed_entries:
                return {
                    "field": "Keyword",
                    "action": "removed",
                    "before": "; ".join(removed_entries),
                    "after": "Not in XMP",
                }
        if existing is None:
            if metadata.get("status") == "unreadable":
                detail = (
                    f"{value} cannot be removed because the XMP sidecar "
                    "is unreadable"
                )
            elif metadata.get("status") == "missing":
                detail = f"No XMP sidecar contains {value} to remove"
            else:
                detail = f"{value} is not present in XMP"
            return {
                "field": "XMP keyword",
                "action": "unchanged",
                "before": xmp_value,
                "after": xmp_value,
                "after_detail": detail,
            }
        return {
            "field": "Keyword",
            "action": "removed",
            "before": xmp_value,
            "after": "Not in XMP",
        }

    if change_type == "rating":
        before = _sync_preview_rating_label(metadata.get("rating"))
        if not metadata.get("rating_writable") and not sidecar_will_exist:
            before = _sync_preview_absent_xmp_value(metadata, before)
            return {
                "field": "XMP rating",
                "action": "unchanged",
                "before": before,
                "after": before,
                "after_detail": (
                    f"{_sync_preview_rating_label(value)} stays in Vireo; "
                    "rating sync only updates an existing, readable XMP sidecar"
                ),
            }
        if not metadata.get("rating_writable"):
            before = _sync_preview_absent_xmp_value(metadata, before)
            return {
                "field": "Rating",
                "action": "updated",
                "before": before,
                "after": _sync_preview_rating_label(value),
                "after_detail": (
                    "Another selected change creates the XMP sidecar first"
                ),
            }
        return {
            "field": "Rating",
            "action": "updated",
            "before": before,
            "after": _sync_preview_rating_label(value),
        }

    if change_type == "flag":
        before = _sync_preview_flag_label(metadata.get("flag"))
        if metadata.get("status") != "ok":
            before = _sync_preview_absent_xmp_value(metadata, before)
        if not sync_flags:
            return {
                "field": "XMP flag",
                "action": "unchanged",
                "before": before,
                "after": before,
                "after_detail": (
                    f"{_sync_preview_flag_label(value)} stays in Vireo; "
                    "flag sync to XMP is turned off"
                ),
            }
        return {
            "field": "Flag",
            "action": "updated",
            "before": before,
            "after": _sync_preview_flag_label(value),
        }

    if change_type == "location":
        current_coordinates = _sync_preview_coordinate_text(
            metadata.get("location")
        )
        before = current_coordinates or _sync_preview_absent_xmp_value(
            metadata, "No GPS in XMP",
        )
        location_coordinates = _sync_preview_coordinate_text(assigned_location)
        location_name = _sync_preview_location_name(assigned_location)

        if write_locations and location_coordinates:
            return {
                "field": "Location",
                "action": "updated",
                "before": before,
                "after": location_name or location_coordinates,
                "after_detail": (
                    f"{location_coordinates} · from a location keyword"
                ),
            }

        if assigned_location:
            if location_coordinates:
                detail = (
                    f"{location_name} is assigned in Vireo; writing its GPS "
                    "to XMP is turned off"
                )
            else:
                detail = (
                    f"{location_name or 'This location'} is assigned in Vireo; "
                    "it has no GPS coordinates to write to XMP"
                )

            if metadata.get("location_source"):
                restored_coordinates = _sync_preview_coordinate_text(
                    metadata.get("previous_location")
                )
                if restored_coordinates:
                    detail += f"; XMP GPS returns to {restored_coordinates}"
                else:
                    detail += "; previously Vireo-assigned GPS is removed from XMP"

            return {
                "field": "Location",
                "action": "added",
                "before": before,
                "after": location_name or "Assigned location",
                "after_detail": detail,
            }

        if metadata.get("location_source"):
            restored_coordinates = _sync_preview_coordinate_text(
                metadata.get("previous_location")
            )
            return {
                "field": "Location",
                "action": "cleared",
                "before": before,
                "after": restored_coordinates or "No GPS in XMP",
                "after_detail": (
                    "Restores the GPS that existed before Vireo"
                    if restored_coordinates
                    else "Removes Vireo-assigned GPS"
                ),
            }

        return {
            "field": "XMP location",
            "action": "unchanged",
            "before": before,
            "after": before,
            "after_detail": "No Vireo-assigned GPS needs to be removed",
        }

    if change_type == "edit_recipe":
        before = (
            "Existing Vireo edits"
            if metadata.get("edit_recipe")
            else _sync_preview_absent_xmp_value(metadata, "No Vireo edits")
        )
        if not value and not metadata.get("edit_recipe"):
            if metadata.get("status") == "unreadable":
                detail = (
                    "The Vireo edit marker cannot be cleared because the "
                    "XMP sidecar is unreadable"
                )
            elif metadata.get("status") == "missing":
                detail = "No XMP sidecar contains Vireo edits to clear"
            else:
                detail = "No Vireo edit marker exists in XMP to clear"
            return {
                "field": "XMP photo edits",
                "action": "unchanged",
                "before": before,
                "after": before,
                "after_detail": detail,
            }
        return {
            "field": "Photo edits",
            "action": "updated" if value else "cleared",
            "before": before,
            "after": "Updated Vireo edits" if value else "No Vireo edits",
        }

    field = change_type.replace("_", " ").strip().title() or "Metadata"
    return {
        "field": field,
        "action": "updated",
        "before": "Current XMP value",
        "after": value or "Cleared",
    }


# Server-side snapshot cache for /api/sync/preview. Progressive page loads
# request the same pending-changes revision many times in a row; without a
# cache each request re-scans the full queue and re-hashes every change,
# making preview preparation quadratic in the queue size. Keyed by
# (database path, workspace_id, revision) so separate catalogs whose default
# workspace and pending rows happen to match cannot reuse each other's photo
# paths. Only the newest revision for each catalog/workspace is retained, and
# the remaining entries are bounded by count with LRU eviction.
_SYNC_PREVIEW_SNAPSHOTS = OrderedDict()
_SYNC_PREVIEW_SNAPSHOTS_LOCK = threading.Lock()
_SYNC_PREVIEW_SNAPSHOTS_MAX = 8


def _sync_preview_pending_fingerprint(db, ws_id):
    """Return the per-workspace monotonic write generation for pending_changes.

    A dedicated ``db_meta`` counter — ``pending_changes_version:<ws>`` —
    is bumped by INSERT/UPDATE/DELETE triggers on ``pending_changes``
    (see ``db.py`` next to the ``folder_health_version`` triggers).
    Reading it is a single-row lookup and, crucially, it changes for
    every row write including a delete of the top id followed by an
    INSERT that reuses it — ``pending_changes.id`` is a plain
    ``INTEGER PRIMARY KEY`` without ``AUTOINCREMENT``, so SQLite will
    do exactly that on the next INSERT after the highest row is
    deleted. A cheaper COUNT/MAX/SUM aggregate would stay identical
    across such a replacement even though ``change_token``, ``value``,
    ``change_type``, or ``photo_id`` differ, and the cached snapshot
    would then be served to a client that had never seen the new row.
    """
    row = db.conn.execute(
        "SELECT value FROM db_meta WHERE key = ?",
        (f"pending_changes_version:{ws_id}",),
    ).fetchone()
    return int(row[0]) if row else 0


def _sync_preview_build_snapshot(db, ws_id):
    """Load pending changes, group by photo, and compute the revision hash."""
    # Read the version counter BEFORE the row scan. If a concurrent write
    # commits between the two reads, the stored fingerprint is one behind
    # the actual queue state, and the next cache lookup will see a
    # mismatched (larger) counter and rebuild. Reading the counter after
    # the rows would risk stamping stale rows with a post-write version
    # and serving them from cache.
    fingerprint = _sync_preview_pending_fingerprint(db, ws_id)
    changes = db.conn.execute(
        """
        SELECT pc.*, p.filename, p.folder_id, f.path AS folder_path
        FROM pending_changes pc
        JOIN photos p ON p.id = pc.photo_id
        LEFT JOIN folders f ON f.id = p.folder_id
        WHERE pc.workspace_id = ?
        ORDER BY pc.created_at, pc.id
        """,
        (ws_id,),
    ).fetchall()

    revision_hash = hashlib.sha256()
    change_type_counts = {}
    by_photo = {}
    for change in changes:
        revision_hash.update(
            (
                f"{change['id']}\0{change['change_token'] or ''}\0"
                f"{change['photo_id']}\0{change['change_type']}\0"
                f"{change['value'] or ''}\n"
            ).encode()
        )
        change_type = change["change_type"]
        change_type_counts[change_type] = (
            change_type_counts.get(change_type, 0) + 1
        )
        cid = change["id"]
        pid = change["photo_id"]
        photo = by_photo.get(pid)
        if photo is None:
            photo = {
                "photo_id": pid,
                "filename": change["filename"],
                "folder": change["folder_path"] or "",
                "changes": [],
            }
            by_photo[pid] = photo
        photo["changes"].append({
            "id": cid,
            "type": change_type,
            # ``_sync_preview_change_creates_sidecar`` and
            # ``_sync_preview_presentation`` both read ``change_type`` and
            # ``value`` off the row they're passed; storing them under both
            # names lets the enrichment loop use these dicts directly
            # without a per-request lookup back into the DB row.
            "change_type": change_type,
            "value": change["value"],
        })

    return {
        "revision": revision_hash.hexdigest()[:24],
        "all_photos": list(by_photo.values()),
        "total_changes": len(changes),
        "change_type_counts": change_type_counts,
        "fingerprint": fingerprint,
    }


def _sync_preview_get_snapshot(db, ws_id, requested_revision):
    """Return a cached or freshly computed snapshot of pending changes.

    Progressive page loads normally arrive back-to-back with the same
    ``requested_revision``; on cache hit a lightweight aggregate check
    verifies the pending queue hasn't shifted since the snapshot was
    stored. On miss (or when the queue has shifted) the full snapshot is
    rebuilt and cached under its computed revision.
    """
    database_key = os.path.abspath(db._db_path)
    if requested_revision:
        key = (database_key, ws_id, requested_revision)
        with _SYNC_PREVIEW_SNAPSHOTS_LOCK:
            snapshot = _SYNC_PREVIEW_SNAPSHOTS.get(key)
            if snapshot is not None:
                _SYNC_PREVIEW_SNAPSHOTS.move_to_end(key)
        if snapshot is not None:
            if _sync_preview_pending_fingerprint(db, ws_id) == snapshot["fingerprint"]:
                return snapshot
            with _SYNC_PREVIEW_SNAPSHOTS_LOCK:
                _SYNC_PREVIEW_SNAPSHOTS.pop(key, None)

    snapshot = _sync_preview_build_snapshot(db, ws_id)
    key = (database_key, ws_id, snapshot["revision"])
    with _SYNC_PREVIEW_SNAPSHOTS_LOCK:
        obsolete_keys = [
            cached_key
            for cached_key in _SYNC_PREVIEW_SNAPSHOTS
            if cached_key[:2] == (database_key, ws_id) and cached_key != key
        ]
        for obsolete_key in obsolete_keys:
            _SYNC_PREVIEW_SNAPSHOTS.pop(obsolete_key, None)
        _SYNC_PREVIEW_SNAPSHOTS[key] = snapshot
        _SYNC_PREVIEW_SNAPSHOTS.move_to_end(key)
        while len(_SYNC_PREVIEW_SNAPSHOTS) > _SYNC_PREVIEW_SNAPSHOTS_MAX:
            _SYNC_PREVIEW_SNAPSHOTS.popitem(last=False)
    return snapshot


def _sync_preview_change_creates_sidecar(
    change, *, sync_flags=False, write_locations=False, assigned_location=None,
):
    """Mirror sync operations that create a missing XMP sidecar before rating.

    Matches the write order in ``sync.py``: ``add_keywords`` (keyword_add),
    ``set_pick_flag`` when flag sync is enabled, ``set_gps_location``
    when location sync is enabled and the linked location has valid
    coordinates, and ``set_edit_recipe`` with a non-empty payload all
    create a missing sidecar through ``SidecarEditor``. ``set_rating``
    and the ``remove_*`` paths do not, so they are excluded.
    """
    change_type = change["change_type"]
    if change_type == "keyword_add":
        return True
    if change_type == "flag":
        return sync_flags
    if change_type == "location":
        if not write_locations or not assigned_location:
            return False
        return (
            assigned_location.get("latitude") is not None
            and assigned_location.get("longitude") is not None
        )
    if change_type == "edit_recipe":
        return bool(change["value"])
    return False


def _rank01(value, values):
    valid = [v for v in values if v is not None]
    if value is None:
        return 0.0
    if len(valid) <= 1:
        return 0.5 if valid else 0.0
    below = sum(1 for v in valid if v < value)
    equal = sum(1 for v in valid if v == value)
    return (below + 0.5 * equal) / len(valid)


def _highlight_exposure_score(photo):
    clip_high = photo.get("subject_clip_high") or 0.0
    clip_low = photo.get("subject_clip_low") or 0.0
    y_median = photo.get("subject_y_median")
    if y_median is None:
        return 0.5
    clip_penalty = math.exp(-6.0 * clip_high - 3.0 * clip_low)
    lum_penalty = math.exp(-abs((y_median / 255.0) - 0.45) / 0.30)
    return max(0.0, min(1.0, clip_penalty * lum_penalty))


def _highlight_area_score(subject_size):
    if subject_size is None or subject_size <= 0:
        return 0.0
    return min(1.0, math.sqrt(subject_size) * 2.0)


def _highlight_score_bucket(photos, picked_first=False):
    """Attach highlight scores and compact reason labels to one species bucket.

    picked_first promotes flagged photos above unflagged ones regardless of
    score — desired on the Highlights page. It is off by default so callers
    such as Life List can calculate the ranked baseline before applying their
    own Representative / Pick curation tiers.
    """
    subject_values = [p.get("subject_tenengrad") for p in photos]
    eye_values = [p.get("eye_tenengrad") for p in photos if p.get("eye_tenengrad") is not None]
    bg_values = [p.get("bg_tenengrad") for p in photos]
    bg_sep_values = [p.get("bg_separation") for p in photos if p.get("bg_separation") is not None]
    noise_values = [p.get("noise_estimate") for p in photos if p.get("noise_estimate") is not None]
    max_bg_sep = max(bg_sep_values) if bg_sep_values else None

    for p in photos:
        if p.get("eye_tenengrad") is not None and eye_values:
            focus = _rank01(p.get("eye_tenengrad"), eye_values)
            focus_label = "eye focus"
        else:
            subject_t = p.get("subject_tenengrad")
            rank = _rank01(subject_t, subject_values)
            if subject_t is not None and p.get("bg_tenengrad") is not None:
                ratio = math.log((subject_t + 1e-8) / (p.get("bg_tenengrad") + 1e-8))
                bg_term = 1.0 / (1.0 + math.exp(-ratio))
                focus = 0.70 * rank + 0.30 * bg_term
            elif subject_t is not None:
                focus = rank
            else:
                focus = p.get("quality_score") if p.get("quality_score") is not None else 0.0
            focus_label = "focus"

        exposure = _highlight_exposure_score(p)
        crop = p.get("crop_complete")
        crop_score = crop if crop is not None else 0.5
        if max_bg_sep and p.get("bg_separation") is not None:
            bg_sep = 1.0 - min(1.0, p.get("bg_separation") / max_bg_sep)
        else:
            bg_sep = 0.5
        composition = 0.55 * crop_score + 0.45 * bg_sep
        area = _highlight_area_score(p.get("subject_size"))
        if p.get("noise_estimate") is not None and noise_values:
            noise = 1.0 - _rank01(p.get("noise_estimate"), noise_values)
        else:
            noise = 1.0 - _rank01(p.get("bg_tenengrad"), bg_values) if bg_values else 0.5

        rich_available = any(
            p.get(k) is not None
            for k in (
                "subject_tenengrad", "eye_tenengrad", "crop_complete",
                "subject_clip_high", "subject_y_median", "noise_estimate",
            )
        )
        if rich_available:
            score = (
                0.42 * focus
                + 0.18 * exposure
                + 0.16 * composition
                + 0.10 * area
                + 0.08 * noise
                + 0.06 * (p.get("quality_score") or 0.0)
            )
        else:
            score = p.get("quality_score") if p.get("quality_score") is not None else 0.0

        rating = p.get("rating") or 0
        if rating >= 4:
            score += 0.04 + 0.02 * (rating - 4)
        elif rating == 3:
            score += 0.015
        # Baseline BEFORE the pick bonus, so the client can recompute
        # highlight_score on a lightbox pick/unpick via clamp(base + bonus)
        # instead of subtracting the bonus from the already-clamped value —
        # which loses precision when the raw score exceeded 1.0 pre-clamp
        # (e.g. base 0.97 → cached 1.0 → subtract 0.08 → 0.92, but the
        # correct unpicked value is 0.97).
        base_score_pre_pick = score
        if p.get("flag") == "flagged":
            score += 0.08

        reasons = []
        if p.get("flag") == "flagged":
            reasons.append("picked")
        if rating:
            reasons.append(f"{rating} star")
        if focus >= 0.72:
            reasons.append(f"strong {focus_label}")
        elif focus < 0.35 and rich_available:
            reasons.append("soft subject")
        if exposure >= 0.70:
            reasons.append("good exposure")
        elif p.get("subject_clip_high") is not None and p.get("subject_clip_high") > 0.30:
            reasons.append("highlight clipping")
        if crop is not None:
            if crop >= 0.90:
                reasons.append("clean crop")
            elif crop < 0.60:
                reasons.append("clipped subject")
        if area >= 0.50:
            reasons.append("large subject")
        if not reasons:
            reasons.append("legacy quality")

        p["highlight_score"] = round(max(0.0, min(1.0, score)), 4)
        p["highlight_base_score"] = round(
            max(0.0, min(1.0, base_score_pre_pick)), 4
        )
        p["score_parts"] = {
            "focus": round(focus, 3),
            "exposure": round(exposure, 3),
            "composition": round(composition, 3),
            "subject": round(area, 3),
            "noise": round(noise, 3),
        }
        p["reasons"] = reasons[:3]

    if picked_first:
        # Highlights page ordering: three contiguous regions —
        #   1. picks (flagged): analyzed first (by score desc), then
        #      unanalyzed picks in capture order;
        #   2. analyzed non-picks: by highlight_score desc;
        #   3. unanalyzed non-picks: capture order (earliest first).
        # The analyzed-before-unanalyzed tier separates the groups so the
        # score term only reorders analyzed rows and the timestamp term only
        # reorders unanalyzed rows — they never compete. Timestamps are ISO
        # text, so lexicographic order is chronological; missing timestamps
        # sort to the end of their group. This is an ascending sort (no
        # reverse), negating the score to rank analyzed rows high-first.
        def _bucket_sort_key(p):
            analyzed = p.get("quality_score") is not None
            ts = p.get("timestamp")
            return (
                0 if p.get("flag") == "flagged" else 1,
                0 if analyzed else 1,
                -(p.get("highlight_score") or 0) if analyzed else 0.0,
                (ts is None, ts),
                p.get("id", 0),
            )

        photos.sort(key=_bucket_sort_key)
    else:
        photos.sort(
            key=lambda p: (
                p.get("highlight_score") or 0,
                p.get("predicted_confidence") or 0,
                p.get("quality_score") or 0,
                p.get("rating") or 0,
                -p.get("id", 0),
            ),
            reverse=True,
        )


def _apply_preferred_photo(photos, preferred_photo_id, marker_key):
    """Move a valid preferred photo to the front of an already-ranked list."""
    for p in photos:
        p[marker_key] = False
    if preferred_photo_id is None:
        return False
    for idx, photo in enumerate(photos):
        if photo.get("id") == preferred_photo_id:
            photo[marker_key] = True
            if idx:
                photos.insert(0, photos.pop(idx))
            return True
    return False


def _sort_photos_with_representatives_first(photos, representative_order):
    """Promote representative photos while preserving ranked order otherwise."""
    ranked_position = {photo["id"]: idx for idx, photo in enumerate(photos)}
    photos.sort(key=lambda photo: (
        0 if photo["id"] in representative_order else 1,
        representative_order.get(photo["id"], 0),
        ranked_position.get(photo["id"], 0),
    ))


def _bucket_best_score(photos):
    """Return the highest highlight_score in a bucket, or None if empty.

    Used to rank buckets on the Highlights page. Reads the max across all
    photos so a pick-first (or user-preferred) reorder at photos[0] can't
    demote a species by anchoring the bucket score to a lower-scored photo.
    """
    scores = [p.get("highlight_score") for p in photos if p.get("highlight_score") is not None]
    return max(scores) if scores else None


def _bucket_unanalyzed_count(photos):
    """Length of the trailing "Not yet analyzed" tail of a bucket.

    Counts only the contiguous run of unscored non-pick photos at the END of
    ``photos``. This is what the divider labels, so callers can trust that a
    non-zero value marks a real tail below the divider.

    Only the trailing run is counted (not every unscored non-pick in the
    bucket) so that curated ordering — where
    :func:`_apply_ordered_highlights` or :func:`_apply_highlight_preferences`
    can promote an unscored, non-flagged photo to the front as a species
    highlight or representative — doesn't inflate the count with photos that
    now live above the divider. Unscored picks are excluded because they
    stay grouped with the other picks at the front regardless.
    """
    if not photos:
        return 0
    tail = 0
    for p in reversed(photos):
        if p.get("quality_score") is None and p.get("flag") != "flagged":
            tail += 1
        else:
            break
    return tail


def _apply_highlight_preferences(db, buckets):
    preferences = db.get_species_representative_lists(eligible_only=True)
    for bucket in buckets:
        representative_ids = preferences.get(bucket["species"]) or []
        representative_set = set(representative_ids)
        representative_order = {
            photo_id: idx for idx, photo_id in enumerate(representative_ids)
        }
        preferred_id = representative_ids[0] if representative_ids else None
        applied = False
        for photo in bucket.get("photos") or []:
            is_rep = photo.get("id") in representative_set
            photo["is_species_representative"] = is_rep
            applied = applied or is_rep
        # Promote representatives to the front so cross-workspace reps
        # (visible via species_representatives but without a workspace-scoped
        # species_highlights rank) become the bucket's primary photo.
        # _apply_ordered_highlights runs before this and only sorts when a
        # visible photo has a workspace highlight rank, so without this pass
        # a rep chosen in another workspace stays buried in score order.
        # Matches the Life List behavior which also promotes reps over
        # workspace highlights.
        if applied:
            _sort_photos_with_representatives_first(
                bucket["photos"], representative_order
            )
        top = bucket["photos"][0] if bucket["photos"] else {}
        bucket["preferred_photo_id"] = preferred_id
        # Species-level state stays true even when the representative photo is
        # outside the current folder or search result.
        bucket["has_species_representative"] = preferred_id is not None
        bucket["has_preferred_photo"] = applied
        bucket["best_quality"] = top.get("quality_score")
        # Rank by the highest-scored photo in the bucket, not photos[0].
        # A picked (or manually preferred) photo may sit at photos[0] with a
        # lower highlight_score; using its score for bucket ranking would
        # demote the whole species below buckets with worse actual best
        # photos.
        bucket["best_score"] = _bucket_best_score(bucket["photos"])
        bucket["best_timestamp"] = top.get("timestamp")
        # Run last so curated promotion (an unscored rep pushed to the front)
        # doesn't leave a stale tail count that anchors the divider above
        # analyzed content.
        bucket["unanalyzed_count"] = _bucket_unanalyzed_count(bucket.get("photos"))


def _apply_ordered_highlights(db, buckets):
    highlights = db.get_species_highlights(eligible_only=True)
    for bucket in buckets:
        ranks = highlights.get(bucket["species"], {})
        # Species-level state stays true even when every selected highlight is
        # outside the current folder or search result.
        bucket["has_highlight_selection"] = bool(ranks)
        photos = bucket.get("photos") or []
        matched = False
        for p in photos:
            rank = ranks.get(p.get("id"))
            p["is_highlighted"] = rank is not None
            p["highlight_rank"] = rank
            if rank is not None:
                matched = True
        # Only re-sort when at least one visible photo actually maps to a
        # stored highlight rank. `ranks` is workspace-scoped, so a folder
        # or search view of the same species can be truthy here while none
        # of its photos are highlights — re-sorting then discards the
        # picked-first order that _highlight_score_bucket already applied.
        if matched:
            bucket["photos"].sort(
                key=lambda p: (
                    0 if p.get("is_highlighted") else 1,
                    p.get("highlight_rank") if p.get("highlight_rank") is not None else 10**9,
                    -(p.get("highlight_score") or 0),
                    -(p.get("predicted_confidence") or 0),
                    -(p.get("quality_score") or 0),
                    -(p.get("rating") or 0),
                    p.get("id", 0),
                )
            )
        best = bucket["photos"][0] if bucket.get("photos") else {}
        bucket["highlight_count"] = sum(
            1 for p in bucket.get("photos") or [] if p.get("is_highlighted")
        )
        # unanalyzed_count is assigned in _apply_highlight_preferences instead:
        # that runs after this pass and can still reorder photos, so anchoring
        # the tail count here would be stale under curated ordering.
        bucket["best_quality"] = best.get("quality_score")
        bucket["best_score"] = best.get("highlight_score")
        bucket["best_timestamp"] = best.get("timestamp")


def _photo_highlight_entries(db, photo_id):
    """Return highlight-eligible species entries for one visible photo.

    Restricts both the candidate scan and the species-highlights lookup to
    the requested photo so the photo-detail endpoint doesn't rebuild every
    workspace bucket for each call (browse detail, lightbox, batch actions).
    """
    candidates = db.get_highlights_candidates(
        None, min_quality=0.0, photo_id=photo_id
    )
    buckets, _unidentified = _collect_highlight_buckets(
        candidates, confidence_threshold=0.0,
        canonicalize_species=_species_canonicalizer(db),
    )
    entries = []
    for bucket in buckets:
        species = bucket.get("species")
        if not species:
            continue
        ranks = db.get_species_highlights(species).get(species, {})
        for photo in bucket.get("photos") or []:
            if photo.get("id") != photo_id:
                continue
            rank = ranks.get(photo_id)
            entries.append({
                "species": species,
                "is_highlighted": rank is not None,
                "highlight_rank": rank,
                "is_confirmed": bool(photo.get("has_accepted_species")),
            })
            break
    return entries


def _highlight_confidence_label(confidence, is_accepted):
    if is_accepted:
        return "confirmed"
    if confidence is None:
        return "unknown"
    if confidence >= 0.85:
        return "likely"
    return "candidate"


def _normalize_highlight_confirmation_filter(value):
    value = (value or "all").strip().lower()
    if value not in {"all", "confirmed", "unconfirmed"}:
        return "all"
    return value


def _normalize_highlight_presence_filter(value):
    value = (value or "all").strip().lower()
    if value not in {"all", "yes", "no"}:
        return "all"
    return value


def _species_canonicalizer(db):
    """Memoized wrapper around db.resolve_species_display_name.

    Bucket collection resolves the same handful of species strings for
    thousands of candidate rows; caching avoids a keyword lookup per row.
    """
    cache = {}

    def canonicalize(name):
        if name not in cache:
            cache[name] = db.resolve_species_display_name(name)
        return cache[name]

    return canonicalize


def _collect_highlight_buckets(
    candidates,
    confidence_threshold,
    confirmation_filter="all",
    canonicalize_species=None,
):
    confirmation_filter = _normalize_highlight_confirmation_filter(
        confirmation_filter
    )
    bucket_map = {}
    unidentified_photos = []

    for row in candidates:
        r = dict(row)
        accepted = r.get("species")
        if confirmation_filter == "confirmed" and accepted is None:
            continue
        if confirmation_filter == "unconfirmed" and accepted is not None:
            continue
        predicted_conf = r.get("predicted_confidence")
        if accepted:
            species = accepted
            if canonicalize_species is not None:
                species = canonicalize_species(species) or species
            is_accepted = True
        elif (
            r.get("predicted_species")
            and predicted_conf is not None
            and predicted_conf >= confidence_threshold
        ):
            # Prediction labels are external vocabulary (classifier label
            # files) with their own casing. Bucket by the spelling
            # add_keyword would store so a predicted `Common Waxbill` and
            # photos already accepted as `Common waxbill` land in ONE
            # bucket, and so curation written from this bucket's label keys
            # on the string the keyword row and eligibility queries use.
            species = r["predicted_species"]
            if canonicalize_species is not None:
                species = canonicalize_species(species) or species
            is_accepted = False
        else:
            species = None
            is_accepted = False

        photo = {
            "id": r["id"],
            "filename": r["filename"],
            "timestamp": r.get("timestamp"),
            "folder_name": r.get("folder_name"),
            "folder_path": r.get("folder_path"),
            "keyword_names": r.get("keyword_names") or "",
            "rating": r.get("rating") or 0,
            "flag": r.get("flag") or "none",
            "quality_score": r.get("quality_score"),
            "is_analyzed": r.get("quality_score") is not None,
            "subject_sharpness": r.get("subject_sharpness"),
            "subject_size": r.get("subject_size"),
            "sharpness": r.get("sharpness"),
            "mask_path": r.get("mask_path"),
            "subject_tenengrad": r.get("subject_tenengrad"),
            "bg_tenengrad": r.get("bg_tenengrad"),
            "crop_complete": r.get("crop_complete"),
            "bg_separation": r.get("bg_separation"),
            "subject_clip_high": r.get("subject_clip_high"),
            "subject_clip_low": r.get("subject_clip_low"),
            "subject_y_median": r.get("subject_y_median"),
            "noise_estimate": r.get("noise_estimate"),
            "eye_tenengrad": r.get("eye_tenengrad"),
            "species": accepted,
            "prediction_id": r.get("prediction_id"),
            "predicted_species": r.get("predicted_species"),
            "predicted_confidence": predicted_conf,
            "has_accepted_species": accepted is not None,
            "is_unidentified": species is None,
            "is_confirmable_prediction": (
                accepted is None
                and species is not None
                and r.get("prediction_id") is not None
            ),
        }

        if species is None:
            unidentified_photos.append(photo)
        else:
            entry = bucket_map.setdefault(
                species, {"is_accepted": True, "photos": []}
            )
            entry["is_accepted"] = entry["is_accepted"] and is_accepted
            entry["photos"].append(photo)

    buckets = []
    for species, entry in bucket_map.items():
        photos = entry["photos"]
        _highlight_score_bucket(photos, picked_first=True)
        confidences = [
            p["predicted_confidence"]
            for p in photos
            if p.get("predicted_confidence") is not None
        ]
        avg_confidence = (
            round(sum(confidences) / len(confidences), 4)
            if confidences else None
        )
        top = photos[0] if photos else {}
        buckets.append({
            "species": species,
            "is_accepted": entry["is_accepted"],
            "certainty": _highlight_confidence_label(
                avg_confidence, entry["is_accepted"]
            ),
            "avg_confidence": avg_confidence,
            "photo_count": len(photos),
            "best_quality": top.get("quality_score"),
            "best_score": _bucket_best_score(photos),
            "best_timestamp": top.get("timestamp"),
            "photos": photos,
        })

    _highlight_score_bucket(unidentified_photos, picked_first=True)
    buckets.sort(
        key=lambda b: (
            b.get("best_score") or 0,
            b.get("avg_confidence") or 0,
            b.get("photo_count") or 0,
        ),
        reverse=True,
    )
    return buckets, unidentified_photos


def _highlight_search_fields(photo):
    return [
        photo.get("filename") or "",
        photo.get("folder_name") or "",
        photo.get("folder_path") or "",
        photo.get("keyword_names") or "",
        photo.get("species") or "",
        photo.get("predicted_species") or "",
        "unidentified" if photo.get("is_unidentified") else "",
    ]


def _highlight_photo_matches_query(
    photo,
    query,
    match_case=False,
    whole_word=False,
):
    tokens = str(query or "").split()
    if not tokens:
        return True
    fields = _highlight_search_fields(photo)
    return all(
        any(
            text_search_match(field, token, match_case, whole_word)
            for field in fields
        )
        for token in tokens
    )


def _refresh_highlight_bucket_metadata(bucket):
    photos = bucket.get("photos") or []
    confidences = [
        p.get("predicted_confidence")
        for p in photos
        if p.get("predicted_confidence") is not None
    ]
    avg_confidence = (
        round(sum(confidences) / len(confidences), 4)
        if confidences else None
    )
    top = photos[0] if photos else {}
    # Filtering can drop the unconfirmed photos from a mixed bucket, leaving
    # only confirmed ones — recompute so the "candidate" badge and the
    # `confirmed` sort match what the row now actually contains.
    bucket["is_accepted"] = bool(photos) and all(
        p.get("has_accepted_species") for p in photos
    )
    bucket["avg_confidence"] = avg_confidence
    bucket["certainty"] = _highlight_confidence_label(
        avg_confidence, bucket.get("is_accepted")
    )
    bucket["photo_count"] = len(photos)
    bucket["best_quality"] = top.get("quality_score")
    bucket["best_score"] = _bucket_best_score(photos)
    bucket["best_timestamp"] = top.get("timestamp")
    return bucket


def _filter_highlight_sections(
    buckets,
    unidentified_photos,
    query,
    match_case=False,
    whole_word=False,
):
    query = (query or "").strip()
    if not query:
        for bucket in buckets:
            _refresh_highlight_bucket_metadata(bucket)
        return buckets, unidentified_photos

    filtered_buckets = []
    for bucket in buckets:
        photos = [
            p for p in (bucket.get("photos") or [])
            if _highlight_photo_matches_query(p, query, match_case, whole_word)
        ]
        if photos:
            updated = {**bucket, "photos": photos}
            filtered_buckets.append(_refresh_highlight_bucket_metadata(updated))

    unidentified = [
        p for p in unidentified_photos
        if _highlight_photo_matches_query(p, query, match_case, whole_word)
    ]
    return filtered_buckets, unidentified


def _filter_highlight_curation_state(
    buckets,
    unidentified_photos,
    highlight_filter="all",
    representative_filter="all",
):
    highlight_filter = _normalize_highlight_presence_filter(highlight_filter)
    representative_filter = _normalize_highlight_presence_filter(
        representative_filter
    )

    def matches(bucket, filter_value, field):
        if filter_value == "all":
            return True
        return bool(bucket.get(field)) == (filter_value == "yes")

    filtered = [
        bucket for bucket in buckets
        if matches(bucket, highlight_filter, "has_highlight_selection")
        and matches(
            bucket,
            representative_filter,
            "has_species_representative",
        )
    ]
    # These two states only apply to named species. Unidentified photos have
    # neither a species highlight list nor a species representative assignment.
    if highlight_filter != "all" or representative_filter != "all":
        unidentified_photos = []
    return filtered, unidentified_photos


# Maximum number of bound parameters per SQL statement. SQLite's
# ``SQLITE_MAX_VARIABLE_NUMBER`` defaults to 32766 on builds since 3.32 but
# remains 999 on older builds (and on some packagers' default builds). Bulk
# duplicate-cleanup actions can hand us thousands of photo ids at once, so
# we chunk every IN-clause query under this cap to stay portable across
# SQLite versions. Sized below 999 to leave headroom for additional bound
# parameters in joined statements.
_SQL_PARAM_CHUNK = 900


# Largest photo selection the Browse selection panels will act on. Owned here
# rather than inline so the producer (``/api/selection/*``, which reads a
# selection) and the consumers (``/api/predictions/batch-*``, which write one)
# are bounded by the same number. A batch payload is validated in photos, not
# in prediction ids, precisely so it cannot be tighter than what the producer
# is allowed to emit for that selection.
_MAX_SELECTION_PHOTOS = 1000


def _chunked(seq, size=_SQL_PARAM_CHUNK):
    """Yield ``seq`` in successive lists of at most ``size`` items."""
    for i in range(0, len(seq), size):
        yield seq[i:i + size]


def _scan_dir_file_count(root_path, file_limit=None, dir_limit=None):
    """Count files (non-directory entries) under ``root_path`` with a lazy
    ``os.scandir`` walk. ``os.scandir`` yields entries one at a time, so with
    ``file_limit``/``dir_limit`` set we bail the moment either cap is reached
    rather than waiting for the OS to enumerate a directory with millions of
    entries. Pass ``None`` for both to count the whole tree exactly.

    Returns ``(file_count, truncated)`` where ``truncated`` is True iff a cap
    stopped the walk early.
    """
    file_count = 0
    dirs_seen = 0
    truncated = False
    stack = [root_path]
    # `not truncated` in the outer condition stops the walk the moment the
    # inner loop trips a cap. Without it, we'd keep popping queued sibling
    # directories until `dirs_seen` mechanically caught up to `dir_limit` —
    # which on a flat fanout means opening every already-queued child, the
    # exact worker-stalling case the cap is supposed to prevent.
    while stack and not truncated:
        if file_limit is not None and file_count >= file_limit:
            truncated = True
            break
        if dir_limit is not None and dirs_seen >= dir_limit:
            truncated = True
            break
        current = stack.pop()
        dirs_seen += 1
        try:
            scanner = os.scandir(current)
        except OSError:
            continue
        with scanner:
            for entry in scanner:
                # Check the caps inside the inner loop so a single directory
                # with a huge number of children cannot blow past either limit
                # before we bail out.
                if file_limit is not None and file_count >= file_limit:
                    truncated = True
                    break
                if dir_limit is not None and dirs_seen + len(stack) >= dir_limit:
                    truncated = True
                    break
                try:
                    is_dir = entry.is_dir(follow_symlinks=False)
                except OSError:
                    is_dir = False
                if is_dir:
                    stack.append(entry.path)
                else:
                    file_count += 1
    return file_count, truncated


def _filename_sequence_key(filename):
    """Return (prefix, number, width, ext) for names like DSC_3069.NEF."""
    stem, ext = os.path.splitext(filename or "")
    match = re.match(r"^(.*?)(\d+)$", stem)
    if not match:
        return None
    digits = match.group(2)
    return (match.group(1), int(digits), len(digits), ext.lower())


def _parse_capture_timestamp(value):
    if value is None or isinstance(value, datetime):
        return value
    try:
        return datetime.fromisoformat(str(value))
    except (TypeError, ValueError):
        return None


def _time_gap_seconds(a, b):
    ta = _parse_capture_timestamp(a)
    tb = _parse_capture_timestamp(b)
    if ta is None or tb is None:
        return None
    try:
        return abs((ta - tb).total_seconds())
    except TypeError:
        return None


def _best_batch_scope(db, seed_photo_id, max_gap_seconds=8.0, max_sequence_gap=2, max_photos=120):
    """Find a likely burst/batch around one seed photo.

    The first pass follows same-folder filename sequence numbers, which matches
    camera batches such as DSC_3069...DSC_3133. Capture time is used as a
    boundary when available. If a filename has no trailing number, fall back to
    neighboring capture-time rows in the folder.
    """
    seed = db.get_photo(seed_photo_id, verify_workspace=True)
    if not seed:
        return None, "Photo not found"

    folder_id = seed["folder_id"]
    seed_key = _filename_sequence_key(seed["filename"])
    seed_ext = (seed["extension"] or os.path.splitext(seed["filename"])[1]).lower()
    ws = db._ws_id()

    def _limited(rows):
        if len(rows) <= max_photos:
            return rows
        seed_idx = next(
            (i for i, row in enumerate(rows) if row["id"] == seed_photo_id),
            len(rows) // 2,
        )
        half = max_photos // 2
        start = max(0, seed_idx - half)
        end = min(len(rows), start + max_photos)
        start = max(0, end - max_photos)
        return rows[start:end]

    def _time_ok(left, right, require_timestamps=False):
        gap = _time_gap_seconds(left["timestamp"], right["timestamp"])
        if gap is None:
            return not require_timestamps
        return gap <= max_gap_seconds

    if seed_key:
        prefix, _, width, _ = seed_key
        rows = db.conn.execute(
            """SELECT p.id, p.folder_id, p.filename, p.extension, p.timestamp,
                      p.flag, p.rating, p.quality_score, p.sharpness
               FROM photos p
               JOIN workspace_folders wf ON wf.folder_id = p.folder_id
               JOIN folders f ON f.id = p.folder_id AND f.status IN ('ok', 'partial')
               WHERE wf.workspace_id = ? AND p.folder_id = ? AND p.filename LIKE ?
               ORDER BY p.filename ASC, p.id ASC""",
            (ws, folder_id, f"{prefix}%"),
        ).fetchall()
        seq_rows = []
        for row in rows:
            key = _filename_sequence_key(row["filename"])
            row_ext = (row["extension"] or os.path.splitext(row["filename"])[1]).lower()
            if (
                key
                and key[0] == prefix
                and key[2] == width
                and row_ext == seed_ext
            ):
                seq_rows.append((key[1], row))
        seq_rows.sort(key=lambda item: (item[0], item[1]["filename"], item[1]["id"]))
        seed_idx = next(
            (i for i, (_, row) in enumerate(seq_rows) if row["id"] == seed_photo_id),
            None,
        )
        if seed_idx is not None:
            left = seed_idx
            while left > 0:
                prev_num, prev_row = seq_rows[left - 1]
                curr_num, curr_row = seq_rows[left]
                if curr_num - prev_num > max_sequence_gap or not _time_ok(prev_row, curr_row):
                    break
                left -= 1
            right = seed_idx
            while right < len(seq_rows) - 1:
                curr_num, curr_row = seq_rows[right]
                next_num, next_row = seq_rows[right + 1]
                if next_num - curr_num > max_sequence_gap or not _time_ok(curr_row, next_row):
                    break
                right += 1
            batch = [row for _, row in seq_rows[left:right + 1]]
            if len(batch) >= 2:
                return _limited(batch), "filename_sequence"

    rows = db.conn.execute(
        """SELECT p.id, p.folder_id, p.filename, p.extension, p.timestamp,
                  p.flag, p.rating, p.quality_score, p.sharpness
           FROM photos p
           JOIN workspace_folders wf ON wf.folder_id = p.folder_id
           JOIN folders f ON f.id = p.folder_id AND f.status IN ('ok', 'partial')
           WHERE wf.workspace_id = ? AND p.folder_id = ?
           ORDER BY p.timestamp IS NULL, p.timestamp ASC, p.filename ASC, p.id ASC""",
        (ws, folder_id),
    ).fetchall()
    seed_idx = next((i for i, row in enumerate(rows) if row["id"] == seed_photo_id), None)
    if seed_idx is None:
        return None, "Photo not found"
    left = seed_idx
    while (
        left > 0
        and _time_ok(rows[left - 1], rows[left], require_timestamps=True)
    ):
        left -= 1
    right = seed_idx
    while (
        right < len(rows) - 1
        and _time_ok(rows[right], rows[right + 1], require_timestamps=True)
    ):
        right += 1
    batch = rows[left:right + 1]
    if len(batch) < 2:
        return None, "No neighboring batch photos found"
    return _limited(batch), "capture_time"


def _quality_rank(photos, key, photo_id):
    values = [
        (p["id"], p.get(key))
        for p in photos
        if p.get(key) is not None
    ]
    if not values:
        return None
    values.sort(key=lambda item: item[1], reverse=True)
    for idx, (pid, _) in enumerate(values, start=1):
        if pid == photo_id:
            return idx
    return None


def _best_batch_reasons(photo, photos, is_best=False):
    reasons = []
    reject_reasons = photo.get("reject_reasons") or []
    if reject_reasons:
        return [str(r).replace("_", " ") for r in reject_reasons[:3]]

    q_rank = _quality_rank(photos, "quality_composite", photo["id"])
    focus_key = "eye_focus_score" if photo.get("eye_focus_score") is not None else "focus_score"
    focus_rank = _quality_rank(photos, focus_key, photo["id"])
    exposure_rank = _quality_rank(photos, "exposure_score", photo["id"])

    if q_rank == 1:
        reasons.append("highest overall quality")
    elif q_rank is not None and q_rank <= 3:
        reasons.append(f"quality rank #{q_rank}")
    if focus_rank == 1:
        reasons.append("sharpest eye" if focus_key == "eye_focus_score" else "sharpest subject")
    elif focus_rank is not None and focus_rank <= 3:
        reasons.append(f"focus rank #{focus_rank}")
    if exposure_rank == 1 and photo.get("exposure_score", 0) >= 0.7:
        reasons.append("cleanest exposure")
    if photo.get("crop_complete") is not None and photo.get("crop_complete") >= 0.9:
        reasons.append("full subject in frame")
    if is_best and not reasons:
        reasons.append("best available score in this batch")
    if not reasons:
        reasons.append("usable alternate")
    return reasons[:4]


def _build_best_batch_response(db, seed_photo_id, rows):
    import config as cfg
    from pipeline import (
        load_photo_features,
        run_selected_batch_review,
        serialize_results,
    )

    effective_cfg = db.get_effective_config(cfg.load())
    photo_ids = [row["id"] for row in rows]
    loaded = load_photo_features(db, config=effective_cfg, photo_ids=photo_ids)
    by_id = {p["id"]: p for p in loaded}
    photos = [by_id[pid] for pid in photo_ids if pid in by_id]
    if len(photos) < 2:
        return None, "At least two batch photos with pipeline features are required"
    if not any(
        p.get("mask_path")
        or p.get("subject_tenengrad") is not None
        or p.get("eye_tenengrad") is not None
        for p in photos
    ):
        return None, "Run the pipeline on these photos before using Best Batch"

    results = serialize_results(run_selected_batch_review(photos, config=effective_cfg))
    result_photos = results.get("photos", [])
    if len(result_photos) < 2:
        return None, "Could not score this batch"

    ranked = sorted(
        result_photos,
        key=lambda p: (
            p.get("label") != "REJECT",
            p.get("quality_composite") if p.get("quality_composite") is not None else -1,
            p.get("focus_score") if p.get("focus_score") is not None else -1,
        ),
        reverse=True,
    )
    best = ranked[0]
    alternate_ids = [p["id"] for p in ranked[1:5] if p.get("label") != "REJECT"]
    reject_ids = [p["id"] for p in result_photos if p["id"] != best["id"]]
    sequence_keys = [_filename_sequence_key(p.get("filename")) for p in result_photos]
    sequence_nums = [key[1] for key in sequence_keys if key]

    cards = []
    for idx, photo in enumerate(ranked, start=1):
        if photo["id"] == best["id"]:
            role = "best"
        elif photo["id"] in alternate_ids:
            role = "alternate"
        else:
            role = "reject"
        cards.append({
            "id": photo["id"],
            "filename": photo.get("filename"),
            "width": photo.get("width"),
            "height": photo.get("height"),
            "rank": idx,
            "role": role,
            "label": photo.get("label"),
            "quality": photo.get("quality_composite"),
            "quality_pct": (
                round(photo["quality_composite"] * 100)
                if photo.get("quality_composite") is not None else None
            ),
            "focus": photo.get("eye_focus_score", photo.get("focus_score")),
            "focus_basis": "eye" if photo.get("eye_focus_score") is not None else "subject",
            "sharpness": photo.get("subject_tenengrad"),
            "eye_x": photo.get("eye_x"),
            "eye_y": photo.get("eye_y"),
            "eye_conf": photo.get("eye_conf"),
            "eye_tenengrad": photo.get("eye_tenengrad"),
            "exposure": photo.get("exposure_score"),
            "flag": photo.get("flag") or "none",
            "rating": photo.get("rating"),
            "reasons": _best_batch_reasons(photo, result_photos, is_best=photo["id"] == best["id"]),
        })

    best_reasons = _best_batch_reasons(best, result_photos, is_best=True)
    return {
        "seed_photo_id": seed_photo_id,
        "photo_ids": photo_ids,
        "count": len(photo_ids),
        "sequence_range": (
            [min(sequence_nums), max(sequence_nums)] if sequence_nums else None
        ),
        "best_photo_id": best["id"],
        "best_filename": best.get("filename"),
        "best_reasons": best_reasons,
        "summary": results.get("summary", {}),
        "cards": cards,
        "alternate_ids": alternate_ids,
        "suggested_reject_ids": reject_ids,
    }, None


def _file_manager_labels():
    """Friendly OS file-manager wording for UI labels.

    Keeps Linux/Windows users from seeing macOS-only "Finder" terminology in
    menus and buttons. Keyed off the *server* platform because the reveal
    action shells out server-side (``open`` / ``explorer`` / ``xdg-open``).
    """
    if sys.platform == "darwin":
        return {
            "name": "Finder",
            "reveal": "Reveal in Finder",
            "editor_placeholder": "/Applications/Adobe Lightroom Classic/Adobe Lightroom Classic.app",
        }
    if sys.platform.startswith("win"):
        return {
            "name": "File Explorer",
            "reveal": "Show in File Explorer",
            "editor_placeholder": r"C:\Program Files\Adobe\Adobe Lightroom Classic\lightroom.exe",
        }
    return {
        "name": "file manager",
        "reveal": "Reveal in File Manager",
        "editor_placeholder": "/usr/bin/darktable",
    }


_FINDER_TRASH_TIMEOUT_SECS = 30
_FINDER_TRASH_BATCH_SIZE = 20
_MOUNT_QUERY_TIMEOUT_SECS = 5

# Distinct from ``None`` so ``_trash_paths`` can tell "caller didn't pass
# network_roots" (re-query is safe) apart from "caller's own mount query
# already failed and it is passing that fail-closed signal through"
# (re-querying would overwrite the caller's classification with a stale
# or empty set the moment the share detaches, reclassifying an
# already-known custom mount point as local and reintroducing the
# unbounded-I/O hang this routing exists to prevent).
_NETWORK_ROOTS_UNSET = object()


class _NetworkVolumeRoots(set):
    """Network roots plus the live /Volumes roots from one mount snapshot."""

    def __init__(self, network_roots=(), mounted_volume_roots=()):
        super().__init__(network_roots)
        self.mounted_volume_roots = frozenset(mounted_volume_roots)


def _mounted_volume_roots(mounts):
    """Return live top-level ``/Volumes/<name>`` roots from parsed mounts."""
    roots = set()
    for mount in mounts:
        normalized = posixpath.normpath(mount["mount_point"])
        parts = normalized.split("/")
        if len(parts) == 3 and parts[1] == "Volumes" and parts[2]:
            roots.add(normalized)
    return roots


def _volume_root_for_path(filepath):
    """Return ``/Volumes/<name>`` for a path on a macOS mounted volume."""
    try:
        normalized = os.path.normpath(os.path.abspath(filepath))
    except (OSError, TypeError, ValueError):
        return None
    parts = normalized.split(os.sep)
    if len(parts) < 4 or parts[0] != "" or parts[1] != "Volumes" or not parts[2]:
        return None
    return os.sep.join(parts[:3])


def _network_volume_roots(run=subprocess.run):
    """Return mounted macOS network-volume roots without touching the shares.

    ``mount`` reads the kernel mount table, so this stays responsive even when
    an SMB server is unhealthy.  ``None`` means the mount table could not be
    read; callers fail closed and treat ``/Volumes`` paths as network-backed
    rather than risking an unbounded in-process filesystem call.
    """
    if sys.platform != "darwin":
        return set()
    try:
        result = run(
            ["mount"], capture_output=True, text=True,
            timeout=_MOUNT_QUERY_TIMEOUT_SECS,
            **no_window_kwargs(),
        )
    except (OSError, subprocess.SubprocessError):
        return None
    if result.returncode != 0:
        return None
    output = result.stdout or ""
    mounts = remote_setup.parse_mount_table(output)
    return _NetworkVolumeRoots(
        # ``mount`` always reports macOS/POSIX paths.  Keep parsing independent
        # of the host running the test suite (notably Windows' ``ntpath``).
        (
            posixpath.normpath(mount["mount_point"])
            for mount in mounts
            if remote_setup.mount_type_is_network_or_unknown(
                mount["fs_type"],
            )
        ),
        _mounted_volume_roots(mounts),
    )


def _expand_first_symlink_prefix(filepath):
    """Expand one local symlink prefix without resolving its target.

    ``realpath`` follows the target and can block when that target is an
    unhealthy network share. Reading the first symlink itself only touches
    its local directory entry; the unvisited suffix is then appended
    lexically so network-volume classification stays free of share I/O.
    """
    try:
        normalized = os.path.normpath(os.path.abspath(filepath))
    except (OSError, TypeError, ValueError):
        return None
    drive, tail = os.path.splitdrive(normalized)
    parts = [part for part in tail.split(os.sep) if part]
    prefix = drive + os.sep
    for index, part in enumerate(parts):
        prefix = os.path.join(prefix, part)
        try:
            target = os.readlink(prefix)
        except OSError:
            continue
        if os.name == "nt":
            # Windows junctions commonly expose their substitution path
            # through os.readlink() with an extended-length prefix. Strip it
            # so comparisons against ordinary drive or UNC mount roots use
            # the same spelling.
            if target.startswith("\\\\?\\UNC\\"):
                target = "\\\\" + target[8:]
            elif target.startswith("\\\\?\\"):
                target = target[4:]
        if not os.path.isabs(target):
            target = os.path.join(os.path.dirname(prefix), target)
        return os.path.normpath(os.path.join(target, *parts[index + 1:]))
    return None


def _path_on_network_volume(filepath, network_roots):
    """Whether ``filepath`` should avoid in-process mounted-volume I/O."""
    normalized = os.path.normpath(os.path.abspath(filepath))
    if network_roots is None:
        # Discovery failed, so there is no trustworthy evidence that any
        # candidate is local. Route every macOS path through bounded Finder
        # handling instead of risking an in-process stat on a custom mount.
        # Preserve the explicit /Volumes fallback on non-macOS test hosts.
        return (
            sys.platform == "darwin"
            or _volume_root_for_path(normalized) is not None
        )
    for _depth in range(16):
        for root in network_roots:
            try:
                if os.path.commonpath((normalized, root)) == root:
                    return True
            except ValueError:
                continue
        if sys.platform == "darwin":
            volume_root = _volume_root_for_path(normalized)
            if volume_root is not None:
                mounted_roots = getattr(
                    network_roots, "mounted_volume_roots", None,
                )
                # A detached network mount disappears from the snapshot but
                # leaves its /Volumes directory behind. Conversely, a live
                # local USB/APFS root in the same snapshot must retain the
                # local-trash path. Plain sets from older callers/tests carry
                # no liveness evidence, so continue to fail closed for them.
                if mounted_roots is None or volume_root not in mounted_roots:
                    return True
        if sys.platform != "darwin":
            return False
        expanded = _expand_first_symlink_prefix(normalized)
        if expanded is None:
            return False
        normalized = expanded
    # A symlink loop or unusually deep chain cannot be classified safely.
    # Fail closed on macOS so no subsequent stat reaches a possible share.
    return True


def _deepest_network_root_for_path(filepath, network_roots):
    """Return the *deepest* ``network_roots`` entry ``filepath`` resolves into.

    ``_path_on_network_volume`` answers the yes/no membership question and
    short-circuits on the first matching root, which is enough for routing
    decisions but not for reachability probing.  When mounts are nested —
    e.g. a still-reachable ``/Volumes/NAS`` share with a detached
    ``/Volumes/NAS/archive`` share mounted underneath it — the caller must
    probe reachability of the *exact* mount the path depends on rather than
    any reachable ancestor; otherwise a healthy outer mount would vouch for
    a nested inner mount that is actually gone, and Finder's false
    ``missing`` result would prune catalog rows for photos that reappear on
    reconnect.  Returns ``None`` when no root matches (either directly or
    via symlink expansion, mirroring ``_path_on_network_volume``'s traversal).
    """
    if not network_roots:
        return None
    normalized = os.path.normpath(os.path.abspath(filepath))
    for _depth in range(16):
        best = None
        best_len = -1
        for root in network_roots:
            try:
                if (
                    os.path.commonpath((normalized, root)) == root
                    and len(root) > best_len
                ):
                    # Longest matching root wins so nested mounts probe the
                    # inner share rather than an outer one that happens to
                    # be iterated first from the roots set.
                    best = root
                    best_len = len(root)
            except ValueError:
                continue
        if best is not None:
            return best
        if sys.platform != "darwin":
            return None
        expanded = _expand_first_symlink_prefix(normalized)
        if expanded is None:
            return None
        normalized = expanded
    return None


def _missing_paths_via_finder(filepaths, timeout=_FINDER_TRASH_TIMEOUT_SECS):
    """Boundedly confirm which paths remain absent according to Finder."""
    filepaths = [os.fspath(path) for path in filepaths]
    if not filepaths:
        return set(), set(), []
    result = subprocess.run(
        [
            "osascript",
            "-e", "on run argv",
            "-e", "set statuses to {}",
            "-e", "repeat with posixPath in argv",
            "-e", "set statusValue to \"error\"",
            "-e", "try",
            "-e", "set fileRef to POSIX file (contents of posixPath)",
            "-e", "tell application \"Finder\"",
            "-e", "if exists fileRef then",
            "-e", "set statusValue to \"exists\"",
            "-e", "else",
            "-e", "set statusValue to \"missing\"",
            "-e", "end if",
            "-e", "end tell",
            "-e", "end try",
            "-e", "set end of statuses to statusValue",
            "-e", "end repeat",
            "-e", "set AppleScript's text item delimiters to linefeed",
            "-e", "return statuses as text",
            "-e", "end run",
            "--",
            *filepaths,
        ],
        capture_output=True,
        text=True,
        timeout=timeout,
        **no_window_kwargs(),
    )
    if result.returncode != 0:
        raise OSError(
            result.stderr.strip()
            or f"Finder existence check failed ({result.returncode})"
        )
    statuses = result.stdout.splitlines()
    if len(statuses) != len(filepaths):
        raise OSError("Finder returned an invalid existence response")
    missing = set()
    existing = set()
    failures = []
    for filepath, outcome in zip(filepaths, statuses, strict=True):
        if outcome == "missing":
            missing.add(filepath)
        elif outcome == "exists":
            existing.add(filepath)
        else:
            failures.append({
                "path": filepath, "error": "Finder existence check failed",
            })
    return missing, existing, failures


def _ensure_volume_trashes_dir(filepath, ensured_volumes):
    """Make sure ``/Volumes/<X>/.Trashes/<uid>/`` exists when ``filepath`` is on
    an external/network mount. macOS ``send2trash`` legacy mode raises
    ``OSError: Directory not found`` on volumes where this directory was never
    created (fresh SMB shares, NAS mounts, USB drives) — without it the caller
    falls back to AppleScript Finder, which then times out under load (-1712)
    and stalls the whole bulk trash for hours.

    No-op for paths outside ``/Volumes/`` (the system Trash already handles
    those) and for volumes already ensured this request. ``OSError`` from
    ``makedirs`` (read-only mount, ACL block) is swallowed so the actual
    trash call surfaces a more specific error than "could not mkdir".
    """
    volume_root = _volume_root_for_path(filepath)
    if volume_root is None:
        return
    if volume_root in ensured_volumes:
        return
    ensured_volumes.add(volume_root)
    trashes_dir = os.path.join(volume_root, ".Trashes", str(os.getuid()))
    try:
        os.makedirs(trashes_dir, mode=0o700, exist_ok=True)
    except OSError as exc:
        log.debug("could not ensure %s: %s", trashes_dir, exc)


def _move_to_volume_trash(filepath):
    """Move one file directly into a local mounted volume's Trash directory.

    Finder ultimately performs a same-volume move into
    ``/Volumes/<name>/.Trashes/<uid>``. Doing that move directly avoids the
    legacy Carbon ``send2trash`` failure on removable drives. Network mounts
    must be filtered by :func:`_trash_paths` before calling this helper because
    their rename syscall can block indefinitely. Returns ``True`` only when
    the move completed; callers retain their normal trash fallbacks on
    ``False``.
    """
    if sys.platform != "darwin":
        return False
    volume_root = _volume_root_for_path(filepath)
    if volume_root is None:
        return False

    trash_dir = os.path.join(volume_root, ".Trashes", str(os.getuid()))
    try:
        os.makedirs(trash_dir, mode=0o700, exist_ok=True)
        # Refuse a redirected Trash directory. The destination must remain on
        # the same mounted volume as the source.
        real_trash = os.path.realpath(trash_dir)
        if os.path.commonpath((volume_root, real_trash)) != volume_root:
            raise OSError("volume Trash directory resolves outside its volume")

        basename = os.path.basename(filepath)
        stem, ext = os.path.splitext(basename)
        # Atomically reserve the destination name with O_CREAT|O_EXCL so two
        # concurrent moves for same-named files from different folders can't
        # both observe an empty slot and then rename to the same path — POSIX
        # rename would silently replace one file, permanently losing a photo
        # the user meant to send to Trash.
        candidate = os.path.join(trash_dir, basename)
        reserved = None
        reserved_stat = None
        for _ in range(32):
            try:
                fd = os.open(
                    candidate, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600,
                )
                try:
                    reserved_stat = os.fstat(fd)
                finally:
                    os.close(fd)
                reserved = candidate
                break
            except FileExistsError:
                candidate = os.path.join(
                    trash_dir, f"{stem} {uuid.uuid4().hex[:8]}{ext}",
                )
        if reserved is None:
            raise OSError(
                f"could not reserve a unique Trash destination in {trash_dir}",
            )
        try:
            # ``os.replace`` (not ``os.rename``) so the O_EXCL placeholder we
            # just reserved is overwritten. POSIX rename replaces silently,
            # but Windows rename raises when the destination exists.
            os.replace(filepath, reserved)
        except OSError:
            # A network filesystem can commit a rename but lose the success
            # response. Never unlink ``reserved`` unless it is still the exact
            # placeholder we created; otherwise that path may now be the photo.
            try:
                current_stat = os.lstat(reserved)
                try:
                    os.lstat(filepath)
                    source_still_exists = True
                except FileNotFoundError:
                    source_still_exists = False
                if not source_still_exists:
                    return True
                placeholder_unchanged = (
                    reserved_stat.st_ino
                    and current_stat.st_dev == reserved_stat.st_dev
                    and current_stat.st_ino == reserved_stat.st_ino
                    and current_stat.st_size == reserved_stat.st_size
                )
                if placeholder_unchanged:
                    os.unlink(reserved)
            except OSError:
                pass
            raise
        return True
    except OSError as exc:
        log.debug("Direct volume Trash move failed for %s: %s", filepath, exc)
        return False


def _trash_via_finder(filepaths, timeout=_FINDER_TRASH_TIMEOUT_SECS):
    """Trash paths via one bounded Finder call with per-item outcomes.

    Fallback for when send2trash fails (e.g. external volumes where the
    legacy Carbon API can't locate .Trashes). macOS-only: on Linux/Windows
    ``send2trash`` already implements the platform trash spec, so there is no
    equivalent fallback. Raising here (instead of spawning a doomed
    ``osascript``) lets the caller surface the original send2trash failure.

    The script catches each path's error and continues so a retry containing
    files already moved by a timed-out earlier batch cannot abort before later
    files. Returns ``(moved_paths, missing_paths, failures)``. A "missing"
    outcome (Finder saw ``sourceExists=false`` but the parent directory still
    exists) is reported separately so the caller can revalidate mount
    identity before accepting it: an unmounted network volume leaves its
    mount-point directory in place on the underlying local FS, so Finder's
    ``parentExists`` check alone cannot distinguish a genuine delete from a
    silently detached mount.
    """
    if sys.platform != "darwin":
        raise OSError("Finder trash fallback is only available on macOS")
    if isinstance(filepaths, (str, bytes, os.PathLike)):
        filepaths = [os.fspath(filepaths)]
    else:
        filepaths = [os.fspath(path) for path in filepaths]
    if not filepaths:
        return set(), set(), []
    result = subprocess.run(
        [
            "osascript",
            "-e", "on run argv",
            "-e", "set statuses to {}",
            "-e", "repeat with posixPath in argv",
            "-e", "set statusValue to \"error\"",
            "-e", "set fileRef to POSIX file (contents of posixPath)",
            "-e", "try",
            "-e", "tell application \"Finder\" to delete fileRef",
            "-e", "set statusValue to \"moved\"",
            "-e", "on error",
            "-e", "try",
            "-e", (
                "set parentPath to do shell script \"/usr/bin/dirname \" & "
                "quoted form of (contents of posixPath)"
            ),
            "-e", "set parentRef to POSIX file parentPath",
            "-e", "tell application \"Finder\"",
            "-e", "set sourceExists to exists fileRef",
            "-e", "set parentExists to exists parentRef",
            "-e", "end tell",
            "-e", (
                "if (not sourceExists) and parentExists then "
                "set statusValue to \"missing\""
            ),
            "-e", "end try",
            "-e", "end try",
            "-e", "set end of statuses to statusValue",
            "-e", "end repeat",
            "-e", "set AppleScript's text item delimiters to linefeed",
            "-e", "return statuses as text",
            "-e", "end run",
            "--",
            *filepaths,
        ],
        capture_output=True,
        text=True,
        timeout=timeout,
        **no_window_kwargs(),
    )
    if result.returncode != 0:
        raise OSError(result.stderr.strip() or f"Finder trash failed ({result.returncode})")
    statuses = result.stdout.splitlines()
    if len(statuses) != len(filepaths):
        raise OSError(
            "Finder trash returned an invalid per-file status response"
        )
    moved_paths = set()
    missing_paths = set()
    failures = []
    for filepath, outcome in zip(filepaths, statuses, strict=True):
        if outcome == "moved":
            moved_paths.add(filepath)
        elif outcome == "missing":
            missing_paths.add(filepath)
        else:
            failures.append({
                "path": filepath, "error": "Finder Trash failed",
            })
    return moved_paths, missing_paths, failures


def _snapshot_parent_device(filepath):
    """Return the parent directory's ``st_dev`` for later mount verification.

    Callers snapshot this before any deletion attempt and pass it to
    :func:`_path_confirmed_gone` afterwards. A network mount that
    disconnects mid-op leaves the mount-point directory visible on the
    underlying local filesystem, so ``os.path.isdir`` alone reports the
    parent as live even though the actual volume is gone. Comparing the
    pre-op and post-op ``st_dev`` catches that drop. ``None`` means no
    baseline could be captured, so the device check is skipped.
    """
    parent = os.path.dirname(filepath) or os.sep
    try:
        return os.stat(parent).st_dev
    except OSError:
        return None


def _path_confirmed_gone(filepath, expected_parent_dev=None):
    """Return True only when the file is verifiably absent from a live volume.

    ``os.path.exists`` returning False is ambiguous on network volumes: it
    also returns False when the underlying stat call errors out because the
    mount went away mid-operation. Treating that as "successfully moved to
    Trash" would prune the catalog row for a photo that reappears when the
    mount comes back. Confirm both that the file is missing *and* that the
    parent directory is still reachable so a genuine live-volume delete is
    accepted while a mid-flight disconnect is preserved as a failure.

    When ``expected_parent_dev`` is provided (from
    :func:`_snapshot_parent_device`), also require the parent's current
    ``st_dev`` to match — a network mount that vanishes can leave its
    mount-point directory in place on the underlying local filesystem, so
    the ``os.path.isdir`` check alone would incorrectly accept the file
    as gone.
    """
    if os.path.exists(filepath):
        return False
    parent = os.path.dirname(filepath) or os.sep
    try:
        parent_stat = os.stat(parent)
    except OSError:
        return False
    if not stat.S_ISDIR(parent_stat.st_mode):
        return False
    return not (
        expected_parent_dev is not None
        and parent_stat.st_dev != expected_parent_dev
    )


def _trash_paths(filepaths, progress_callback=None, already_missing_out=None,
                 network_roots=_NETWORK_ROOTS_UNSET):
    """Move paths to Trash and return ``(moved, successful, failures)``.

    Missing paths are successful (the requested end state already holds) but
    are not counted as moved. On macOS mounted volumes we try a direct,
    same-volume rename first. Network volumes skip all in-process move APIs:
    an SMB ``rename(2)`` can wait in the kernel indefinitely, so those paths
    go directly to the time-bounded Finder subprocess. Remaining paths use
    send2trash individually so failures can be attributed, then one Finder
    process per bounded batch.

    ``already_missing_out``, when a mutable set, is populated with every
    path treated as successful because the requested end state already
    held (local preflight found it absent, or Finder reported it missing
    on a still-mounted volume). Callers surface those to users as
    "already missing" rather than as trashed, so a duplicate-cleanup that
    finds every loser already gone can return an explicit terminal
    result instead of a silent ``{trashed: 0}``.

    ``network_roots`` lets a caller reuse a mount-table classification it
    already performed. When omitted we re-query ``_network_volume_roots()``.
    Callers whose own mount query already failed should pass ``None``
    explicitly: that preserves the fail-closed classification they made
    against ``/Volumes`` paths instead of us re-querying and — if the second
    query succeeds with the share now detached — silently reclassifying an
    already-known custom mount point (``/Users/me/mnt/photos``) as local,
    which is the exact case we routed through Finder in the first place.
    """
    ordered = list(dict.fromkeys(filepaths))
    successful = set()
    moved = 0
    fallback = []
    preflight_errors = {}
    finder_candidates = []
    network_finder_candidates = set()
    send_errors = {}
    if network_roots is _NETWORK_ROOTS_UNSET:
        network_roots = _network_volume_roots()
    processed = set()

    def report_processed(filepath):
        if filepath in processed:
            return
        processed.add(filepath)
        if progress_callback:
            progress_callback(
                len(processed), len(ordered), os.path.basename(filepath),
            )

    # Classify paths using the kernel mount table before any source or parent
    # stat.  Those metadata calls can themselves block indefinitely while an
    # unhealthy SMB mount is reconnecting, so network candidates must go
    # straight to the bounded Finder subprocess.
    local_paths = []
    for filepath in ordered:
        if _path_on_network_volume(filepath, network_roots):
            finder_candidates.append(filepath)
            network_finder_candidates.add(filepath)
            send_errors[filepath] = "Network volume Trash operation failed"
        else:
            local_paths.append(filepath)

    # Snapshot each local parent's st_dev before we touch anything. A network
    # mount that vanishes mid-batch can leave the mount-point directory
    # visible on the underlying local FS, so ``os.path.isdir`` alone would
    # accept the file as gone. Comparing pre-op vs post-op st_dev catches
    # the mount drop even when the directory still stats cleanly.
    parent_devs = {path: _snapshot_parent_device(path) for path in local_paths}

    for filepath in local_paths:
        if not os.path.isfile(filepath):
            # ``os.path.isfile`` returning False is ambiguous on network
            # volumes — it also happens when the underlying stat fails
            # because the mount is already disconnected. Only treat the
            # path as "already gone" when the parent directory is still
            # reachable AND its device matches the pre-op snapshot;
            # otherwise preserve as a failure so the caller doesn't prune
            # the catalog row for a photo that reappears when the mount
            # comes back.
            if _path_confirmed_gone(filepath, parent_devs.get(filepath)):
                log.warning("File already missing: %s", filepath)
                successful.add(filepath)
                if already_missing_out is not None:
                    already_missing_out.add(filepath)
            else:
                preflight_errors[filepath] = (
                    "Source path is unreachable"
                )
                log.warning(
                    "Trash preflight: source unreachable for %s", filepath,
                )
            report_processed(filepath)
            continue
        if _move_to_volume_trash(filepath):
            successful.add(filepath)
            moved += 1
            report_processed(filepath)
        else:
            fallback.append(filepath)

    if fallback:
        from send2trash import send2trash as _trash
        for filepath in fallback:
            try:
                _trash(filepath)
                successful.add(filepath)
                moved += 1
                report_processed(filepath)
            except BaseException as exc:
                if isinstance(exc, (KeyboardInterrupt, GeneratorExit)):
                    raise
                # Some platform Trash APIs can complete the move and still
                # report a post-operation error. Only trust the "not there"
                # signal when we can positively verify it — a disconnected
                # network volume also makes ``os.path.exists`` return False
                # (the underlying stat fails), which would otherwise mask a
                # real failure and prune the catalog row for a photo that
                # reappears when the mount comes back.
                if _path_confirmed_gone(filepath, parent_devs.get(filepath)):
                    successful.add(filepath)
                    moved += 1
                    report_processed(filepath)
                    continue
                send_errors[filepath] = str(exc)
                if sys.platform == "darwin":
                    finder_candidates.append(filepath)
                else:
                    report_processed(filepath)

    def _finder_missing_is_trustworthy(
        filepath, current_network_roots, reachable_network_roots,
        confirmed_network_missing, path_to_deepest_root,
    ):
        """Reject Finder's "missing" outcome when the underlying mount is gone.

        Finder reports "missing" when ``sourceExists=false`` but
        ``parentExists=true``. An unmounted network volume leaves its
        mount-point directory in place on the underlying local FS, so the
        parent-exists check alone cannot distinguish a genuine delete from a
        silently detached mount. Accepting "missing" in that case would
        prune the catalog row for a photo that reappears on remount.

        For network-classified paths we require three independent signals:
        (1) the mount table (already re-queried once per Finder batch by
        the caller and passed in via ``current_network_roots``) still
        lists a root the path resolves into; (2) an out-of-process
        ``stat`` probe on the *deepest* matching root the path resolves
        into — separate from Finder's cache — responds within its bounded
        timeout, so a still-listed but unreachable SMB server cannot
        masquerade as "empty" and, crucially, a reachable ancestor mount
        cannot vouch for a nested inner mount that is actually gone; and
        (3) Finder's second-look ``exists`` query also confirmed the path
        as missing. Doing the mount recheck and reachability probes per
        batch instead of per path keeps the worst-case cost bounded — a
        20-item retry of already-moved paths would otherwise spawn one
        ``mount`` (or ``stat``) subprocess per path. For local fallbacks
        we reuse the parent-device snapshot check that guards the
        send2trash path already.
        """
        if filepath in network_finder_candidates:
            if current_network_roots is None:
                # Mount discovery failed on the recheck — we cannot
                # confirm the volume is still mounted, so refuse to trust
                # "missing" and let the caller retry.
                return False
            if not _path_on_network_volume(filepath, current_network_roots):
                return False
            if filepath not in confirmed_network_missing:
                return False
            # Require the *exact* mount the path depends on — not just any
            # reachable ancestor — to respond to the out-of-process stat
            # probe. When a detached inner share is nested beneath a
            # reachable outer share (e.g. ``/Volumes/NAS/archive`` under a
            # still-live ``/Volumes/NAS``), only the deepest match tells us
            # whether the photo could reappear on reconnect.
            deepest_root = path_to_deepest_root.get(filepath)
            if deepest_root is None:
                return False
            return deepest_root in reachable_network_roots
        return _path_confirmed_gone(filepath, parent_devs.get(filepath))

    for finder_batch in _chunked(
        finder_candidates, size=_FINDER_TRASH_BATCH_SIZE,
    ):
        try:
            finder_moved_paths, finder_missing_paths, finder_failures = (
                _trash_via_finder(finder_batch)
            )
            moved += len(finder_moved_paths)
            successful.update(finder_moved_paths)
            # Query the mount table at most once per batch. A retry that
            # contains many paths already moved by an earlier timed-out
            # Finder call comes back with every path in ``missing`` — doing
            # a fresh ``mount`` subprocess per path could otherwise burn up
            # to ``_MOUNT_QUERY_TIMEOUT_SECS`` × ``len(batch)`` seconds and
            # undermine the bounded batch behaviour this code establishes.
            batch_network_missing = any(
                path in network_finder_candidates
                for path in finder_missing_paths
            )
            batch_network_roots = (
                _network_volume_roots() if batch_network_missing else None
            )
            # Probe each still-relevant mount root with a bounded
            # out-of-process ``stat`` — a signal independent of Finder's
            # exists-cache — so a still-listed but unreachable SMB server
            # cannot make ``missing`` outcomes look legitimate. Run the
            # probes concurrently so a Finder batch spanning many
            # unavailable shares completes within one probe timeout
            # rather than accumulating ``len(distinct_roots)`` ×
            # ``_MOUNT_QUERY_TIMEOUT_SECS`` serially — a full 20-item
            # batch across unreachable roots would otherwise add up to
            # ~100 seconds of hang time before the Finder recheck.
            reachable_network_roots = set()
            path_to_deepest_root = {}
            confirmed_network_missing = set()
            finder_recheck_errors = set()
            if batch_network_missing and batch_network_roots is not None:
                paths_still_on_network = {
                    path for path in finder_missing_paths
                    if path in network_finder_candidates
                    and _path_on_network_volume(path, batch_network_roots)
                }
                # Associate each path with the *deepest* mount root it
                # resolves into so nested mounts probe reachability of the
                # inner share rather than an outer one that happens to be
                # iterated first. Set iteration is order-independent, so
                # picking the first match could otherwise validate a
                # detached inner mount using a live outer one and prune
                # rows for photos that reappear on reconnect.
                for path in paths_still_on_network:
                    root = _deepest_network_root_for_path(
                        path, batch_network_roots,
                    )
                    if root is not None:
                        path_to_deepest_root[path] = root
                distinct_roots = list(set(path_to_deepest_root.values()))
                if distinct_roots:
                    with concurrent.futures.ThreadPoolExecutor(
                        max_workers=len(distinct_roots),
                    ) as executor:
                        probe_results = executor.map(
                            _network_root_reachable, distinct_roots,
                        )
                        for root, is_reachable in zip(
                            distinct_roots, probe_results, strict=True,
                        ):
                            if is_reachable:
                                reachable_network_roots.add(root)
                if paths_still_on_network:
                    try:
                        (
                            confirmed_network_missing,
                            reappeared_paths,
                            recheck_failures,
                        ) = _missing_paths_via_finder(paths_still_on_network)
                        for path in reappeared_paths:
                            finder_recheck_errors.add(path)
                            send_errors[path] = (
                                "Source reappeared during Trash operation"
                            )
                        for failure in recheck_failures:
                            finder_recheck_errors.add(failure["path"])
                            send_errors[failure["path"]] = failure["error"]
                    except subprocess.TimeoutExpired:
                        for path in paths_still_on_network:
                            finder_recheck_errors.add(path)
                            send_errors[path] = (
                                "Finder existence check timed out"
                            )
                    except Exception as exc:
                        for path in paths_still_on_network:
                            finder_recheck_errors.add(path)
                            send_errors[path] = (
                                str(exc) or "Finder existence check failed"
                            )
            for missing_path in finder_missing_paths:
                if _finder_missing_is_trustworthy(
                    missing_path, batch_network_roots,
                    reachable_network_roots,
                    confirmed_network_missing,
                    path_to_deepest_root,
                ):
                    successful.add(missing_path)
                    if already_missing_out is not None:
                        already_missing_out.add(missing_path)
                else:
                    if missing_path not in finder_recheck_errors:
                        send_errors[missing_path] = "Source path is unreachable"
                    log.warning(
                        "Rejecting Finder 'missing' outcome for %s: "
                        "underlying mount appears to have detached",
                        missing_path,
                    )
            for failure in finder_failures:
                send_errors[failure["path"]] = failure["error"]
        except subprocess.TimeoutExpired:
            log.warning(
                "Finder Trash timed out after %ss for %d file(s)",
                _FINDER_TRASH_TIMEOUT_SECS, len(finder_batch),
            )
            for filepath in finder_batch:
                send_errors[filepath] = (
                    f"Finder Trash timed out after "
                    f"{_FINDER_TRASH_TIMEOUT_SECS}s"
                )
        except Exception as exc:
            log.warning("Finder Trash failed for a file batch", exc_info=True)
            for filepath in finder_batch:
                send_errors[filepath] = str(exc) or "Finder Trash failed"
        for filepath in finder_batch:
            report_processed(filepath)

    failures = []
    for filepath in ordered:
        if filepath in successful:
            continue
        error = (
            preflight_errors.get(filepath)
            or send_errors.get(filepath)
            or "Trash operation failed"
        )
        failures.append({"path": filepath, "error": error})
        log.warning("Trash failed for %s: %s", filepath, error)
    return moved, successful, failures


def _inventory_pair(label_set, label_set_path, fingerprint, is_tol,
                    is_intrinsic, db_pair, total):
    """Build one (model × label-set) row for the classification inventory."""
    classified = db_pair.get("classified_dets", 0)
    pending = max(0, total - classified) if not is_intrinsic else max(
        0, total - classified
    )
    if classified == 0:
        status = "never_run"
    elif pending == 0:
        status = "complete"
    else:
        status = "partial"
    denom = classified + pending
    coverage = round(100.0 * classified / denom, 1) if denom > 0 else 0.0
    return {
        "label_set": label_set,
        "label_set_path": label_set_path,
        "fingerprint": fingerprint,
        "is_tol": is_tol,
        "is_intrinsic": is_intrinsic,
        "status": status,
        "classified_dets": classified,
        "pending_dets": pending,
        "coverage_pct": coverage,
        "photos_covered": db_pair.get("photos_covered", 0),
        "last_run": db_pair.get("last_run"),
        "median_top1_conf": db_pair.get("median_top1_conf"),
        "median_sample_size": db_pair.get("median_sample_size", 0),
    }


def _inventory_subtotal(pairs):
    """Sum classified/pending across a model's pairs into a subtotal dict."""
    classified = sum(p["classified_dets"] for p in pairs)
    pending = sum(p["pending_dets"] for p in pairs)
    denom = classified + pending
    coverage = round(100.0 * classified / denom, 1) if denom > 0 else 0.0
    return {
        "classified_dets": classified,
        "pending_dets": pending,
        "coverage_pct": coverage,
    }


# The canonical implementation lives in ``new_images.py`` so non-Flask
# modules (e.g. ``pipeline_job.py``) can import it without pulling in the
# app module. Kept aliased here under the original private name for
# backward-compatibility with existing call sites and tests.
from new_images import invalidate_new_images_after_scan as _invalidate_new_images_after_scan  # noqa: E402


def _migrate_legacy_preview_cache(app):
    """One-shot migration of pre-refactor preview cache files.

    Two classes of pre-existing files are made visible to the LRU here:

    1. Unsized {id}.jpg from the old /full endpoint. These are renamed to
       {id}_<preview_max_size>.jpg and tracked.
    2. Sized {id}_{size}.jpg files written by an earlier /preview before
       preview_cache existed. These already match the new naming scheme,
       so we just insert a tracking row pointing at the file in place.

    Both classes were previously invisible to accounting and eviction —
    they sat on disk indefinitely unless the user hit Clear Cache. Runs
    once per process start; a no-op when nothing needs adopting.

    If preview_max_size=0 (meaning "full") we can't assign a size tier
    to unsized {id}.jpg, so those are left in place for Clear Cache to
    remove later. Sized files are still adopted in that case.
    """
    import re

    import config as cfg

    vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
    preview_dir = os.path.join(vireo_dir, "previews")
    if not os.path.isdir(preview_dir):
        return

    unsized_pat = re.compile(r"^(\d+)\.jpg$")
    sized_pat = re.compile(r"^(\d+)_(\d+)\.jpg$")
    try:
        all_files = os.listdir(preview_dir)
    except OSError:
        return
    unsized_files = [f for f in all_files if unsized_pat.match(f)]
    sized_files = [f for f in all_files if sized_pat.match(f)]
    if not unsized_files and not sized_files:
        return

    # Read preview_max_size explicitly so a configured 0 ("full res")
    # stays 0 and the tier-assignment guard below is reachable.
    raw_size = cfg.load().get("preview_max_size")
    target_size = 0 if raw_size == 0 else int(raw_size or 1920)

    db = Database(app.config["DB_PATH"])
    try:
        migrated = 0
        orphaned = 0
        adopted = 0
        if unsized_files and target_size == 0:
            log.info(
                "Leaving %d legacy preview files (preview_max_size=0 — can't assign tier)",
                len(unsized_files),
            )

        # Pass 1: rename unsized {id}.jpg → {id}_<target>.jpg + insert.
        if target_size:
            for fname in unsized_files:
                m = unsized_pat.match(fname)
                photo_id = int(m.group(1))
                src = os.path.join(preview_dir, fname)
                dst = os.path.join(preview_dir, f"{photo_id}_{target_size}.jpg")
                # Skip orphans: if the photo was deleted, inserting into
                # preview_cache would raise a FK error and rolling back the
                # already-performed os.rename is ugly. Unlink the orphan so
                # disk doesn't keep pointing at vanished photos.
                photo_row = db.conn.execute(
                    "SELECT 1 FROM photos WHERE id=?", (photo_id,)
                ).fetchone()
                if photo_row is None:
                    try:
                        os.remove(src)
                        orphaned += 1
                    except OSError:
                        pass
                    continue
                if os.path.exists(dst):
                    try:
                        os.remove(src)
                    except OSError:
                        pass
                    continue
                try:
                    os.rename(src, dst)
                    st = os.stat(dst)
                    db.preview_cache_insert(photo_id, target_size, st.st_size)
                    migrated += 1
                except OSError as e:
                    log.warning("Failed to migrate legacy preview %s: %s", src, e)

        # Pass 2: adopt pre-existing sized {id}_{size}.jpg files that
        # aren't tracked yet. These are produced by older /preview calls
        # that ran before preview_cache existed; without this pass they
        # stay invisible to accounting/eviction even though they already
        # match the new naming scheme.
        for fname in sized_files:
            m = sized_pat.match(fname)
            photo_id = int(m.group(1))
            size = int(m.group(2))
            path = os.path.join(preview_dir, fname)
            if db.preview_cache_get(photo_id, size):
                continue
            photo_row = db.conn.execute(
                "SELECT 1 FROM photos WHERE id=?", (photo_id,)
            ).fetchone()
            if photo_row is None:
                try:
                    os.remove(path)
                    orphaned += 1
                except OSError:
                    pass
                continue
            try:
                st = os.stat(path)
                db.preview_cache_insert(photo_id, size, st.st_size)
                adopted += 1
            except OSError as e:
                log.warning("Failed to adopt sized preview %s: %s", path, e)

        if migrated:
            log.info(
                "Migrated %d legacy preview cache files to size %d",
                migrated, target_size,
            )
        if adopted:
            log.info("Adopted %d untracked sized preview files into LRU", adopted)
        if orphaned:
            log.info("Removed %d orphaned legacy preview files", orphaned)
    finally:
        try:
            db.conn.close()
        except Exception:
            pass


def _migrate_edit_math_render_caches(app):
    """Invalidate rendered caches when the edit-math version has bumped.

    Cached previews/thumbnails are keyed by ``(photo_id, size)`` only — the
    edit recipe isn't part of the key. When the per-pixel rendering math in
    ``image_edits`` / ``tone`` changes, the old bytes on disk are no longer
    what we'd produce now, but a recipe-unchanged photo would otherwise keep
    serving them until the user manually cleared the cache.

    On each startup we compare ``db_meta["edit_math_version"]`` against
    ``image_edits.EDIT_MATH_VERSION``. If it lags, we drop:

      * every ``preview_cache`` row plus its on-disk JPEG
      * every per-photo thumbnail file plus its ``photos.thumb_path``

    for photos that have a non-null edit recipe (recipe-free photos render
    identically across math versions and don't need re-rendering). Then we
    write the new version so the migration is a no-op next boot.

    On a fresh DB with no recipes, the walk does nothing and we still bump
    the version so future deploys only act on real prior state.
    """
    from image_edits import EDIT_MATH_VERSION

    vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
    thumb_dir = app.config["THUMB_CACHE_DIR"]
    preview_dir = os.path.join(vireo_dir, "previews")
    db = Database(app.config["DB_PATH"])
    try:
        stored = db.get_meta("edit_math_version")
        try:
            stored_version = int(stored) if stored is not None else 1
        except (TypeError, ValueError):
            stored_version = 1
        if stored_version >= EDIT_MATH_VERSION:
            return

        rows = db.conn.execute(
            "SELECT photo_id FROM photo_edit_recipes"
        ).fetchall()
        photo_ids = [row["photo_id"] for row in rows]

        invalidated_previews = 0
        invalidated_thumbs = 0
        # If any unlink fails (locked file on Windows, transient permission
        # error), we must NOT stamp the new version: a stale file/preview_cache
        # row could still be served, and bumping the version would make the
        # next boot skip the migration and never retry. Leaving the version
        # behind makes the migration idempotent and self-retrying.
        purge_failed = False

        # Scan preview_dir once and group untracked preview files by photo id.
        # The per-photo listdir would otherwise be O(N*M) (N edited photos x M
        # preview files) and can spend minutes just rescanning the same
        # directory on a large library before the server even starts.
        edited_set = set(photo_ids)
        untracked_previews_by_pid = {}
        try:
            preview_names = os.listdir(preview_dir)
        except FileNotFoundError:
            # Cache dir doesn't exist yet — nothing untracked to clean up.
            preview_names = ()
        except OSError:
            # Permissions / locked network volume / other transient read
            # failure: we can't see what's in there, so we don't know whether
            # there are stale orphans to purge. Skip the scan but leave the
            # version old so the next boot retries — matches the unlink-error
            # contract instead of taking the app down for a disposable cache
            # problem.
            log.warning(
                "Failed to list preview cache dir %s during edit-math "
                "migration; leaving version at %s to retry next boot",
                preview_dir, stored_version, exc_info=True,
            )
            preview_names = ()
            purge_failed = True

        for name in preview_names:
            if not name.endswith(".jpg"):
                continue
            underscore = name.find("_")
            if underscore <= 0:
                continue
            try:
                file_pid = int(name[:underscore])
            except ValueError:
                continue
            if file_pid in edited_set:
                untracked_previews_by_pid.setdefault(file_pid, []).append(name)
        for pid in photo_ids:
            for row in db.conn.execute(
                "SELECT size FROM preview_cache WHERE photo_id = ?", (pid,)
            ).fetchall():
                size_value = row["size"]
                path = os.path.join(preview_dir, f"{pid}_{size_value}.jpg")
                try:
                    if os.path.exists(path):
                        os.remove(path)
                except OSError:
                    log.warning(
                        "Failed to remove stale preview cache %s during "
                        "edit-math migration", path, exc_info=True,
                    )
                    purge_failed = True
                    continue
                db.conn.execute(
                    "DELETE FROM preview_cache WHERE photo_id=? AND size=?",
                    (pid, size_value),
                )
                invalidated_previews += 1
            for name in untracked_previews_by_pid.get(pid, ()):
                path = os.path.join(preview_dir, name)
                try:
                    if os.path.exists(path):
                        os.remove(path)
                except OSError:
                    purge_failed = True
            thumb_cache = os.path.join(thumb_dir, f"{pid}.jpg")
            try:
                if os.path.exists(thumb_cache):
                    os.remove(thumb_cache)
                    invalidated_thumbs += 1
            except OSError:
                log.warning(
                    "Failed to remove stale thumbnail %s during "
                    "edit-math migration", thumb_cache, exc_info=True,
                )
                purge_failed = True
                continue
            for source in ("raw", "jpeg"):
                variant = os.path.join(thumb_dir, f"{pid}_{source}.jpg")
                try:
                    if os.path.exists(variant):
                        os.remove(variant)
                        invalidated_thumbs += 1
                except OSError:
                    log.warning(
                        "Failed to remove paired thumbnail %s during "
                        "edit-math migration", variant, exc_info=True,
                    )
                    purge_failed = True
            db.conn.execute(
                "UPDATE photos SET thumb_path = NULL WHERE id = ?", (pid,),
            )

        if purge_failed:
            # Commit the row deletions that did succeed, but leave the stored
            # version unchanged so the next boot re-runs and retries the
            # paths that couldn't be purged this time.
            db.conn.commit()
            log.warning(
                "edit_math_version %s -> %s: some cache purges failed; "
                "leaving version at %s so the migration retries next boot "
                "(invalidated %d preview-cache entries, %d thumbnails so far)",
                stored_version, EDIT_MATH_VERSION, stored_version,
                invalidated_previews, invalidated_thumbs,
            )
            return

        db.set_meta("edit_math_version", EDIT_MATH_VERSION, _commit=False)
        db.conn.commit()

        if photo_ids:
            log.info(
                "edit_math_version %s -> %s: invalidated %d preview-cache "
                "entries and %d thumbnails across %d edited photos",
                stored_version, EDIT_MATH_VERSION,
                invalidated_previews, invalidated_thumbs, len(photo_ids),
            )
        else:
            log.info(
                "edit_math_version %s -> %s: no edited photos, nothing to "
                "invalidate", stored_version, EDIT_MATH_VERSION,
            )
    finally:
        try:
            db.conn.close()
        except Exception:
            pass


def _migrate_unedited_raw_preview_sources(app):
    """Drop previews that may have used an edit-quality RAW working copy.

    RAW working copies deliberately preserve highlight headroom and therefore
    look flatter/darker than the camera-rendered rendition used for browsing.
    Older preview routing treated that working copy as the canonical source
    even when a RAW had no edit recipe.  Those bytes are keyed only by
    ``(photo_id, size)``, so fixing source selection alone would keep serving
    already-cached dark tiers indefinitely.

    Purge only recipe-free RAWs that currently have a working copy, and gate
    the migration in ``db_meta`` so large libraries pay the directory scan
    once.  If any cache file cannot be inspected or removed, leave the marker
    unset so the next launch retries instead of permanently adopting stale
    pixels.
    """
    from image_loader import RAW_EXTENSIONS

    marker = "unedited_raw_camera_preview_source_v1"
    vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
    preview_dir = os.path.join(vireo_dir, "previews")
    db = Database(app.config["DB_PATH"])
    try:
        if db.get_meta(marker) == "1":
            return

        rows = db.conn.execute(
            """SELECT p.id, p.filename
               FROM photos p
               LEFT JOIN photo_edit_recipes r ON r.photo_id = p.id
               WHERE p.working_copy_path IS NOT NULL
                 AND r.photo_id IS NULL"""
        ).fetchall()
        affected = {
            int(row["id"])
            for row in rows
            if os.path.splitext(row["filename"] or "")[1].lower()
            in RAW_EXTENSIONS
        }

        purge_failed = False
        names_by_pid = {}
        try:
            preview_names = os.listdir(preview_dir)
        except FileNotFoundError:
            preview_names = ()
        except OSError:
            log.warning(
                "Failed to list preview cache dir %s while migrating "
                "unedited RAW preview sources; retrying next launch",
                preview_dir,
                exc_info=True,
            )
            preview_names = ()
            purge_failed = True

        for name in preview_names:
            if not name.endswith(".jpg"):
                continue
            underscore = name.find("_")
            if underscore <= 0:
                continue
            try:
                photo_id = int(name[:underscore])
            except ValueError:
                continue
            if photo_id in affected:
                names_by_pid.setdefault(photo_id, set()).add(name)

        invalidated = 0
        for photo_id in affected:
            tracked = db.conn.execute(
                "SELECT size FROM preview_cache WHERE photo_id=?",
                (photo_id,),
            ).fetchall()
            names = names_by_pid.get(photo_id, set())
            names.update(
                f"{photo_id}_{row['size']}.jpg" for row in tracked
            )
            photo_failed = False
            for name in names:
                path = os.path.join(preview_dir, name)
                try:
                    if os.path.exists(path):
                        os.remove(path)
                except OSError:
                    log.warning(
                        "Failed to remove stale unedited RAW preview %s",
                        path,
                        exc_info=True,
                    )
                    photo_failed = True
                    purge_failed = True
            if photo_failed:
                continue
            cursor = db.conn.execute(
                "DELETE FROM preview_cache WHERE photo_id=?", (photo_id,)
            )
            invalidated += max(cursor.rowcount, 0)

        if purge_failed:
            db.conn.commit()
            return

        db.set_meta(marker, "1", _commit=False)
        db.conn.commit()
        if affected:
            log.info(
                "Invalidated %d preview-cache entries across %d unedited "
                "RAW photos so camera-rendered previews can regenerate",
                invalidated,
                len(affected),
            )
    finally:
        try:
            db.conn.close()
        except Exception:
            pass


def _enforce_preview_cache_quota_at_startup(app):
    """Reconcile and evict at startup so prior runs / external deletes
    can't leave the table out of sync or over quota.

    Reconcile first: if a previous session left ghost rows (files
    deleted while cache was under quota), eviction would see inflated
    totals and stay asleep when it shouldn't, or wake up and run a
    no-op pass over rows whose files don't exist.
    """
    from preview_cache import evict_if_over_quota

    vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
    db = Database(app.config["DB_PATH"])
    try:
        reconcile_preview_cache(db, vireo_dir)
        evict_if_over_quota(db, vireo_dir)
    finally:
        try:
            db.conn.close()
        except Exception:
            pass


def _enforce_working_copy_cache_quota_at_startup(app):
    """Apply the persistent working-copy ceiling when the app starts.

    Quota eviction records a source-mtime marker on each removed row so later
    scans do not immediately regenerate files that were deliberately removed.

    Sweeps ``.<id>.render.*.jpg.tmp`` orphans in ``working/`` first so a
    process kill during a prior on-demand extraction does not permanently
    consume disk outside the configured ceiling (quota accounting skips these
    files by design, so the sweep is their only cleanup path). Passes
    ``startup=True`` so a legacy ``working/<id>.jpg`` whose mtime happens to
    fall inside the concurrent-writer grace window is still reclaimed on the
    first pass — no cache writer can be active this early.
    """
    from working_copy_cache import sweep_abandoned_render_tempfiles

    vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
    sweep_abandoned_render_tempfiles(vireo_dir)
    db = Database(app.config["DB_PATH"])
    try:
        evict_working_copy_cache_if_over_quota(db, vireo_dir, startup=True)
    finally:
        try:
            db.conn.close()
        except Exception:
            pass


def _sweep_abandoned_transient_originals(app):
    """Reclaim non-cacheable ``/original`` renditions the process orphaned.

    When ``_serve_generated_original`` streams a rendition too large for the
    quota (or when the quota is zero), it moves the file into
    ``<vireo_dir>/originals/.<id>.transient.*.jpg`` and unlinks it in the
    generator's ``finally`` block after streaming. A process kill or crash
    during that stream leaves the ``.transient.*.jpg`` behind: working-copy
    eviction only scans ``working/`` and cannot see it, so repeated
    interrupted requests can accumulate arbitrary bytes outside the quota
    with no other cleanup path.
    """
    vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
    originals_dir = os.path.join(vireo_dir, "originals")
    if not os.path.isdir(originals_dir):
        return
    try:
        with os.scandir(originals_dir) as entries:
            for entry in entries:
                try:
                    if not entry.is_file():
                        continue
                except OSError:
                    continue
                name = entry.name
                if not (
                    name.startswith(".")
                    and ".transient." in name
                    and name.endswith(".jpg")
                ):
                    continue
                try:
                    os.remove(entry.path)
                except OSError as exc:
                    log.warning(
                        "Could not remove abandoned transient rendition %s: %s",
                        entry.path, exc,
                    )
    except OSError as exc:
        log.warning(
            "Could not scan originals directory for transient renditions %s: %s",
            originals_dir, exc,
        )


def _collection_accepts_manual_photos(rules):
    """Return True when collection rules are static photo-id membership only."""
    if isinstance(rules, list):
        return all(_collection_accepts_manual_photos(child) for child in rules)

    if not isinstance(rules, dict):
        return False

    if rules.get("field") == "photo_ids":
        return isinstance(rules.get("value", []), list)

    if "rules" in rules and "field" not in rules:
        return (
            rules.get("mode", "all") == "all"
            and isinstance(rules.get("rules"), list)
            and all(
                _collection_accepts_manual_photos(child)
                for child in rules.get("rules")
            )
        )

    return False


def _scan_metadata_warning():
    """Thin wrapper over ``metadata.scan_metadata_warning`` for the scan paths.

    Kept as a module-level alias so callers don't import ``metadata`` directly
    at every call site; the implementation lives in ``metadata`` so the
    pipeline-job module can share it.
    """
    from metadata import scan_metadata_warning
    return scan_metadata_warning()


_EXPLORER_RANKS = ["order", "family", "genus", "species"]
_EXPLORER_CHILD_RANK = {"class": "order", "order": "family",
                        "family": "genus", "genus": "species"}


def _build_explorer_payload(db, root_id=None):
    """Completeness tree (down to genus) for one class. Species leaves load
    separately via _build_explorer_species. Honest about the two failure
    states: taxonomy-not-downloaded and unmatched species."""
    root = (db.get_explorer_root() if root_id is None
            else db.get_taxon_by_id(root_id))
    if root is None:
        # Taxonomy absent (default lookup found no Aves class) -> not ready.
        return {"taxonomy_ready": False, "valid_root": False, "root": None,
                "summary": {}, "nodes": [],
                "unmatched_species": {"count": 0, "names": []},
                "uncounted_identifications": {
                    "count": 0, "scoped_count": 0, "workspace_count": 0,
                    "scoped": [], "workspace": [],
                },
                "classes": []}
    if root["rank"] != "class":
        # Explorer roots must be class-rank; an order/family/etc. root produces a
        # semantically confusing summary (e.g. an order counting itself). The
        # taxonomy exists, but this root is not valid.
        return {"taxonomy_ready": True, "valid_root": False, "root": None,
                "summary": {}, "nodes": [],
                "unmatched_species": {"count": 0, "names": []},
                "uncounted_identifications": {
                    "count": 0, "scoped_count": 0, "workspace_count": 0,
                    "scoped": [], "workspace": [],
                },
                "classes": []}

    rows = db.get_taxon_subtree(root["id"])
    found = db.get_life_list_taxon_ids()

    # Build node index + children lists.
    nodes = {r["id"]: {**r, "children": [], "found_species": 0,
                       "total_species": 0} for r in rows}
    for n in nodes.values():
        pid = n["parent_id"]
        if pid in nodes and pid != n["id"]:
            nodes[pid]["children"].append(n)

    # Post-order rollup of species totals/found.
    def rollup(node):
        if node["rank"] == "species":
            node["total_species"] = 1
            node["found_species"] = 1 if node["id"] in found else 0
        else:
            for c in node["children"]:
                rollup(c)
                node["total_species"] += c["total_species"]
                node["found_species"] += c["found_species"]
    rollup(nodes[root["id"]])

    # Per-rank summary across the whole class.
    summary = {r: {"found": 0, "total": 0} for r in _EXPLORER_RANKS}
    for n in nodes.values():
        if n["rank"] in summary:
            summary[n["rank"]]["total"] += 1
            if n["found_species"] > 0:
                summary[n["rank"]]["found"] += 1

    def to_out(node):
        child_rank = _EXPLORER_CHILD_RANK.get(node["rank"])
        kids = list(node["children"])
        found_children = sum(1 for c in kids if c["found_species"] > 0)
        out = {
            "id": node["id"], "name": node["name"],
            "common_name": node["common_name"], "rank": node["rank"],
            "found_species": node["found_species"],
            "total_species": node["total_species"],
            "child_rank": child_rank,
            "found_children": found_children,
            "total_children": len(kids),
        }
        # Materialize tree down to genus; species leaves load on demand.
        if node["rank"] != "genus":
            out["children"] = [to_out(c) for c in sorted(
                kids, key=lambda c: (c["found_species"] == 0,
                                     (c["common_name"] or c["name"]).lower()))]
        else:
            out["children"] = []  # species fetched via leaf endpoint
        return out

    top = [to_out(c) for c in sorted(
        nodes[root["id"]]["children"],
        key=lambda c: (c["found_species"] == 0,
                       (c["common_name"] or c["name"]).lower()))]

    uncounted = db.get_life_list_uncounted_identifications()
    scoped_uncounted = [
        entry for entry in uncounted
        if entry["class"] is not None and entry["class"]["id"] == root["id"]
    ]
    # An unlinked label (or a taxon broader than class, such as the plant
    # phylum behind "Trees") cannot honestly be assigned to the selected
    # class. Surface it separately as workspace-wide taxonomy cleanup instead
    # of making mammals/reptiles/plants look like missing Birds entries.
    workspace_uncounted = [
        entry for entry in uncounted if entry["class"] is None
    ]
    visible_uncounted = scoped_uncounted + workspace_uncounted

    # A class represented only by a broad identification still belongs in the
    # selector. Otherwise (for example) a workspace containing only the genus
    # "Sheep" would have no Mammals option in which to review that label.
    class_seed_taxa = set(found)
    class_seed_taxa.update(
        entry["taxon_id"] for entry in uncounted
        if entry["taxon_id"] is not None
    )
    classes = db.get_classes_for_taxa(class_seed_taxa)
    # Always include the default Aves class in the selector, regardless of the
    # currently selected root. `get_classes_for_taxa(found)` only returns classes
    # the user has actually tagged in, so a user who tags only non-bird species
    # and then picks that class would otherwise lose Birds from the selector with
    # no in-page way back to the default view.
    default_root = root if root_id is None else db.get_explorer_root()
    if default_root is not None and not any(
        c["id"] == default_root["id"] for c in classes
    ):
        classes.insert(0, {"id": default_root["id"],
                           "name": default_root["name"],
                           "common_name": default_root.get("common_name")})
    return {
        "taxonomy_ready": True,
        "valid_root": True,
        "root": {"id": root["id"], "name": root["name"],
                 "common_name": root.get("common_name"), "rank": root["rank"]},
        "summary": summary,
        "nodes": top,
        # Retain the old name-only field for API compatibility. New clients use
        # the structured, reasoned field below.
        "unmatched_species": {
            "count": len(visible_uncounted),
            "names": [entry["name"] for entry in visible_uncounted[:200]],
        },
        "uncounted_identifications": {
            "count": len(visible_uncounted),
            "scoped_count": len(scoped_uncounted),
            "workspace_count": len(workspace_uncounted),
            "scoped": scoped_uncounted[:200],
            "workspace": workspace_uncounted[:200],
        },
        "classes": classes,
    }


def _build_explorer_species(db, genus_id):
    """Found+missing species directly under a genus, found ones with a
    representative photo. Found sorted first, then missing; each alphabetical."""
    rows = [r for r in db.get_taxon_subtree(genus_id, max_depth=1)
            if r["rank"] == "species"]
    found = db.get_life_list_taxon_ids()
    found_ids = [r["id"] for r in rows if r["id"] in found]
    photos = db.get_life_list_best_photo_by_taxon(found_ids)
    species = []
    for r in rows:
        is_found = r["id"] in found
        species.append({
            "id": r["id"], "name": r["name"], "common_name": r["common_name"],
            "found": is_found,
            "photo": photos.get(r["id"]) if is_found else None,
        })
    species.sort(key=lambda s: (not s["found"],
                                (s["common_name"] or s["name"]).lower()))
    return {"genus_id": genus_id, "species": species}


def _build_explorer_rank(db, rank, root_id=None):
    """Flat list of all taxa at `rank` under the class root, each flagged
    found/unfound. Server-authoritative so it agrees with the summary chips."""
    if rank not in _EXPLORER_RANKS:
        rank = "family"
    root = (db.get_explorer_root() if root_id is None
            else db.get_taxon_by_id(root_id))
    empty = {"taxonomy_ready": root is not None, "valid_root": False,
             "rank": rank, "root": None, "found": 0, "total": 0, "items": []}
    if root is None:
        empty["taxonomy_ready"] = False
        return empty
    if root["rank"] != "class":
        return empty

    rows = db.get_taxon_subtree(root["id"])
    found = db.get_life_list_taxon_ids()
    nodes = {r["id"]: {**r, "children": [], "found_species": 0,
                       "total_species": 0}
             for r in rows}
    for n in nodes.values():
        pid = n["parent_id"]
        if pid in nodes and pid != n["id"]:
            nodes[pid]["children"].append(n)

    def rollup(node):
        if node["rank"] == "species":
            node["total_species"] = 1
            node["found_species"] = 1 if node["id"] in found else 0
        else:
            for c in node["children"]:
                rollup(c)
                node["total_species"] += c["total_species"]
                node["found_species"] += c["found_species"]
    rollup(nodes[root["id"]])

    def order_label(node):
        cur = node["parent_id"]
        while cur in nodes and nodes[cur]["rank"] != "order":
            cur = nodes[cur]["parent_id"]
        if cur in nodes and nodes[cur]["rank"] == "order":
            o = nodes[cur]
            return o["common_name"] or o["name"]
        return None

    targets = [n for n in nodes.values() if n["rank"] == rank]
    found_species_ids = [n["id"] for n in targets
                         if rank == "species" and n["found_species"] > 0]
    photos = (db.get_life_list_best_photo_by_taxon(found_species_ids)
              if found_species_ids else {})

    items = []
    for n in targets:
        is_found = n["found_species"] > 0
        items.append({
            "id": n["id"], "name": n["name"], "common_name": n["common_name"],
            "rank": rank, "found": is_found,
            "found_species": n["found_species"],
            "total_species": n["total_species"],
            "order": order_label(n),
            "photo": (photos.get(n["id"])
                      if (rank == "species" and is_found) else None),
        })
    items.sort(key=lambda i: (not i["found"],
                              (i["common_name"] or i["name"]).lower()))
    return {
        "taxonomy_ready": True, "valid_root": True, "rank": rank,
        "root": {"id": root["id"], "name": root["name"],
                 "common_name": root.get("common_name"), "rank": root["rank"]},
        "found": sum(1 for i in items if i["found"]), "total": len(items),
        "items": items,
    }


_LIFE_LIST_LEADING_APOSTROPHE_RE = re.compile(
    r"^['`´ʹʻʼ‘’‛]+"
)


def _life_list_alphabetical_key(name):
    """Sort key that ignores a leading Hawaiian ʻokina or apostrophe variant.

    Kept in sync with ``lifeListAlphabeticalName`` in ``life_list.html`` so
    server-side lifer numbering ties break under the same letter the client
    displays the species under.
    """
    return _LIFE_LIST_LEADING_APOSTROPHE_RE.sub("", str(name or "")).lower()


def create_app(db_path, thumb_cache_dir=None, api_token=None):
    """Create the Flask app for the Vireo photo browser.

    Args:
        db_path: path to the SQLite database
        thumb_cache_dir: path to thumbnail cache directory
        api_token: optional token required on /api/v1/* requests via the
            ``X-Vireo-Token`` header. When ``None`` (default), all /api/v1/*
            traffic is rejected with 401 — the token is expected to be
            supplied by ``main()`` after calling ``runtime.generate_token``.
    """
    app = Flask(
        __name__, template_folder=os.path.join(os.path.dirname(__file__), "templates")
    )
    app.config["DB_PATH"] = db_path
    app.config["COMPUTATION_CACHE_DIR"] = os.path.expanduser(
        "~/.vireo/computation-cache"
    )
    app.config["THUMB_CACHE_DIR"] = thumb_cache_dir or os.path.expanduser(
        "~/.vireo/thumbnails"
    )
    app.config["API_TOKEN"] = api_token
    app.config["TRUSTED_HOSTS"] = ["localhost", "127.0.0.1", "::1"]
    app.config["BROWSER_SESSION_COOKIE"] = "vireo_session"
    app.config["BROWSER_SESSION_TOKEN"] = secrets.token_urlsafe(32)
    app.config["BROWSER_AUTH_ENABLED"] = (
        os.environ.get("VIREO_DISABLE_BROWSER_AUTH") != "1"
    )
    app.config["REQUIRE_EXIFTOOL_FOR_IMPORT"] = (
        os.environ.get("VIREO_REQUIRE_EXIFTOOL_FOR_IMPORT", "1") != "0"
    )
    app.config["CARD_CLEANUP_DIR"] = os.path.join(
        os.path.dirname(os.path.abspath(db_path)), "card_cleanup"
    )
    # Built here rather than on first request: a check-then-set in the request
    # path lets two concurrent first requests each build their own store, and a
    # token handed out by whichever store loses the race is never found again.
    # The endpoint would then silently re-derive the whole comparison — the
    # multi-second cost this store exists to avoid.
    app.config["ID_CONFLICTS_SNAPSHOTS"] = id_conflicts.SnapshotStore()

    # Schema creation and migrations are startup work, never request work.
    # `:memory:` is the development exception because each SQLite connection
    # owns a distinct database and therefore must initialize itself.
    ensure_schema(db_path)

    _migrate_legacy_preview_cache(app)
    _migrate_edit_math_render_caches(app)
    _migrate_unedited_raw_preview_sources(app)
    _enforce_preview_cache_quota_at_startup(app)
    _sweep_abandoned_transient_originals(app)
    _enforce_working_copy_cache_quota_at_startup(app)

    # Request timing middleware — logs slow requests and user actions
    @app.before_request
    def _start_timer():
        request._start_time = time.time()
        supplied_request_id = request.headers.get("X-Request-ID", "")
        if re.fullmatch(r"[A-Za-z0-9._-]{1,64}", supplied_request_id):
            g.request_id = supplied_request_id
        else:
            g.request_id = uuid.uuid4().hex

    @app.before_request
    def _protect_browser_surface():
        """Keep hostile web pages away from Vireo's localhost interface.

        `/api/v1` remains token-authenticated for automation.  The internal
        browser API and photo responses use an HttpOnly, SameSite-strict
        session established by a Vireo HTML page.  Unsafe browser requests
        additionally carry a header that cross-origin forms cannot emit.
        """
        if not app.config["BROWSER_AUTH_ENABLED"]:
            return None

        path = request.path
        if path.startswith("/api/v1/") or path in {
            "/api/health",
            "/api/shutdown",
        }:
            return None

        protected = (
            path.startswith("/api/")
            or path.startswith("/photos/")
            or path.startswith("/thumbnails/")
        )
        if not protected:
            return None

        # Native desktop clients cannot use the HttpOnly browser cookie.
        # They authenticate with the same per-runtime secret as /api/v1.
        expected_api_token = app.config.get("API_TOKEN")
        supplied_api_token = request.headers.get("X-Vireo-Token", "")
        if (
            expected_api_token
            and supplied_api_token
            and secrets.compare_digest(
                supplied_api_token.encode("utf-8"),
                expected_api_token.encode("utf-8"),
            )
        ):
            return None

        fetch_site = request.headers.get("Sec-Fetch-Site", "").lower()
        if fetch_site and fetch_site not in {"same-origin", "none"}:
            return json_error(
                "Non-origin requests are not allowed",
                403,
                code="cross_site_request",
            )

        origin = request.headers.get("Origin")
        if origin:
            parsed = urlsplit(origin)
            expected = urlsplit(request.host_url)
            if (parsed.scheme, parsed.netloc) != (expected.scheme, expected.netloc):
                return json_error(
                    "Cross-origin requests are not allowed",
                    403,
                    code="cross_origin_request",
                )

        cookie_name = app.config["BROWSER_SESSION_COOKIE"]
        expected_token = app.config["BROWSER_SESSION_TOKEN"]
        if not secrets.compare_digest(
            request.cookies.get(cookie_name, "").encode("utf-8"),
            expected_token.encode("utf-8"),
        ):
            return json_error(
                "Browser session required",
                401,
                code="browser_session_required",
            )

        if (
            request.method not in {"GET", "HEAD", "OPTIONS"}
            and request.headers.get("X-Vireo-Client") != "browser"
        ):
            return json_error(
                "Missing browser request header",
                403,
                code="browser_header_required",
            )
        return None

    @app.after_request
    def _log_requests(response):
        if hasattr(request, "_start_time"):
            elapsed = time.time() - request._start_time
            if request.method in ("POST", "DELETE"):
                # Log user actions with details about what changed
                detail = ""
                path = request.path
                if path in ("/api/capture-time/preview", "/api/jobs/capture-time"):
                    body = {}
                else:
                    body = request.get_json(silent=True) or {}
                    if not isinstance(body, dict):
                        # Valid non-object JSON (5, "x", [..]) — the
                        # .get() calls below would 500 the response of
                        # any endpoint after it already ran.
                        body = {}
                if "/rating" in path:
                    detail = f" rating={body.get('rating')}"
                elif "/flag" in path:
                    detail = f" flag={body.get('flag')}"
                elif "/keywords" in path and request.method == "POST":
                    detail = f" keyword={body.get('name')}"
                elif "/accept" in path:
                    detail = " (accept prediction)"
                elif "/reject" in path:
                    detail = " (reject prediction)"
                elif "batch" in path:
                    ids = body.get("photo_ids", [])
                    detail = f" ({len(ids)} photos)"
                elif "/classify" in path:
                    detail = f" collection={body.get('collection_id')}"
                elif "/scan" in path:
                    detail = f" root={body.get('root', '')}"
                log.info(
                    "Action: %s %s → %s (%.1fs)%s request_id=%s",
                    request.method,
                    path,
                    response.status_code,
                    elapsed,
                    detail,
                    getattr(g, "request_id", "-"),
                )
            elif elapsed > 0.5:
                log.warning(
                    "Slow request: %s %s took %.1fs request_id=%s",
                    request.method,
                    request.path,
                    elapsed,
                    getattr(g, "request_id", "-"),
                )
            if request.path.startswith("/api/"):
                _quiet = request.method == "GET" and request.path == "/api/jobs"
                (log.debug if _quiet else log.info)(
                    "API: %s %s → %s (%.3fs) request_id=%s",
                    request.method,
                    request.path,
                    response.status_code,
                    elapsed,
                    getattr(g, "request_id", "-"),
                )
        request_id = getattr(g, "request_id", None)
        if request_id:
            response.headers["X-Request-ID"] = request_id
        response.headers["X-Content-Type-Options"] = "nosniff"
        response.headers["X-Frame-Options"] = "DENY"
        response.headers["Referrer-Policy"] = "same-origin"
        response.headers["Content-Security-Policy-Report-Only"] = (
            "default-src 'self'; "
            "script-src 'self' 'unsafe-inline' 'unsafe-eval' https://unpkg.com; "
            "style-src 'self' 'unsafe-inline' https://unpkg.com; "
            "img-src 'self' data: blob: https:; "
            "connect-src 'self' https:; frame-ancestors 'none'; "
            "base-uri 'self'; form-action 'self'"
        )
        if (
            app.config["BROWSER_AUTH_ENABLED"]
            and response.mimetype == "text/html"
            and 200 <= response.status_code < 400
        ):
            response.set_cookie(
                app.config["BROWSER_SESSION_COOKIE"],
                app.config["BROWSER_SESSION_TOKEN"],
                httponly=True,
                samesite="Strict",
                secure=request.is_secure,
                path="/",
            )
        return response

    # Catch uncaught exceptions so they don't disappear silently
    @app.errorhandler(Exception)
    def _handle_error(e):
        from jobs import WorkspaceBusyError
        from werkzeug.exceptions import HTTPException
        if isinstance(e, WorkspaceBusyError):
            return json_error(str(e), 409)
        if isinstance(e, HTTPException):
            return e
        log.exception("Unhandled error: %s %s", request.method, request.path)
        return jsonify({
            "error": "Internal server error",
            "code": "internal_error",
            "message": "Something went wrong in Vireo. Try again.",
            "request_id": getattr(g, "request_id", None),
        }), 500

    _MAX_PER_PAGE = 500

    def json_error(msg, status=400, *, code=None, message=None):
        """Return a JSON error response with an optional user-facing message."""
        if code is None:
            code = {
                400: "invalid_request",
                401: "unauthorized",
                403: "forbidden",
                404: "not_found",
                409: "conflict",
            }.get(status, "request_failed")
        payload = {
            "error": msg,
            "code": code,
            "request_id": getattr(g, "request_id", None),
        }
        if message:
            payload["message"] = message
        return jsonify(payload), status

    def _photo_not_found_error(*, legacy_error="photo_not_found"):
        return json_error(
            legacy_error,
            404,
            message=(
                "This photo is no longer available in the active workspace. "
                "Refresh the page and try again."
            ),
        )

    def _keyword_not_found_error():
        return json_error(
            "keyword_not_found",
            404,
            message=(
                "That saved location no longer exists. Refresh the page and "
                "select another location."
            ),
        )

    def _google_maps_not_configured_error():
        return json_error(
            "no_api_key",
            400,
            message=(
                "Google Maps isn’t configured. Add an API key in Settings to "
                "use Google place search."
            ),
        )

    def _google_place_not_found_error():
        return json_error(
            "place_not_found",
            404,
            message=(
                "Google Maps couldn’t find that place. Search again and choose "
                "another result."
            ),
        )

    def _location_name_conflict_payload(err):
        """Describe a location-keyword collision for both people and clients.

        ``error`` remains the stable legacy code because existing clients use
        it for branching. ``message`` is the text browser surfaces should show
        to a person; ``error_detail`` retains the lower-level diagnostic for
        logs and troubleshooting.
        """
        detail = str(err)
        match = re.search(r"(?:child )?keyword '(.+?)' \((?:parent_id|id)=", detail)
        if match:
            message = (
                f"Couldn’t assign this location because “{match.group(1)}” is "
                "already used by another keyword. Rename that keyword in "
                "Keywords, then try again."
            )
        else:
            message = (
                "Couldn’t assign this location because one of its place names "
                "conflicts with an existing keyword. Rename the conflicting "
                "keyword in Keywords, then try again."
            )
        return {
            "error": "name_conflict",
            "code": "name_conflict",
            "message": message,
            "error_detail": detail,
        }

    def _location_name_conflict_response(err):
        payload = _location_name_conflict_payload(err)
        payload["request_id"] = getattr(g, "request_id", None)
        return jsonify(payload), 409

    def _coerce_collection_id(raw):
        """Parse an optional collection_id from a request body.

        Returns ``None`` if absent/blank, an ``int`` if valid, or the
        sentinel ``False`` if present but unparseable (so callers can
        distinguish "not provided" from "invalid"). ``bool`` is rejected
        because it's an ``int`` subclass.
        """
        if raw is None or raw == "":
            return None
        if isinstance(raw, bool):
            return False
        if isinstance(raw, int):
            return raw
        if isinstance(raw, str):
            try:
                return int(raw)
            except ValueError:
                return False
        return False

    def _get_db():
        """Get a Database instance. One connection per request via Flask g."""
        if "db" not in g:
            g.db = Database(
                db_path,
                initialize_schema=(db_path == ":memory:"),
            )
        return g.db

    # Shared prologue for routes that launch background jobs. See
    # web/background_jobs.py: the decorated view receives a ``JobLaunch``
    # (runner + active workspace + worker-thread db factory) as its first
    # argument and returns ``ctx.start(job_type, work, ...)``.
    background_job = make_background_job(
        lambda: app._job_runner, _get_db, db_path, Database
    )

    def _requested_pair_source(photo, folder_path):
        """Resolve an explicit RAW/JPEG display choice for a paired photo.

        Paired files remain one catalog record, but browser image requests can
        select which physical source supplies the pixels with
        ``?source=jpeg`` or ``?source=raw``. Invalid and non-paired choices
        fall back to the established canonical rendering path so old clients
        and ordinary photos are unchanged. Live files are preferred, with the
        offline-original cache as the fallback; a known pair missing both
        returns the source name with no path so routes can fail explicitly
        instead of showing RAW pixels under a JPEG label.
        """
        requested = (request.args.get("source") or "").strip().lower()
        if requested not in {"jpeg", "raw"}:
            return None, None

        from image_loader import RAW_EXTENSIONS

        primary_ext = os.path.splitext(photo["filename"])[1].lower()
        if primary_ext not in RAW_EXTENSIONS or not photo["companion_path"]:
            return None, None

        def _offline_path(column):
            try:
                row = _get_db().offline_original_get(photo["id"])
            except Exception:
                return None
            if not row or not row[column]:
                return None
            cached = row[column]
            if not os.path.isabs(cached):
                vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
                cached = os.path.join(vireo_dir, cached)
            return cached if os.path.isfile(cached) else None

        if requested == "raw":
            primary = os.path.join(folder_path, photo["filename"])
            if os.path.isfile(primary):
                return "raw", primary
            return "raw", _offline_path("original_path")

        companion = os.path.join(folder_path, photo["companion_path"])
        companion_ext = os.path.splitext(companion)[1].lower()
        if companion_ext not in {".jpg", ".jpeg"}:
            return "jpeg", None
        if os.path.isfile(companion):
            return "jpeg", companion
        return "jpeg", _offline_path("companion_path")

    _invalid_preview_cache_paths = set()

    # Canonical definitions live in preview_cache so the recycled-rowid
    # purge (which runs in the scanner, outside this app factory) writes
    # the same marker _serve_preview's lazy-adoption branch consults.
    def _ensure_preview_cache_invalidations_table(db):
        from preview_cache import ensure_preview_cache_invalidations_table
        ensure_preview_cache_invalidations_table(db)

    def _mark_preview_cache_invalid(db, photo_id, size, *, commit=True):
        from preview_cache import mark_preview_cache_invalid
        mark_preview_cache_invalid(db, photo_id, size, commit=commit)

    def _clear_preview_cache_invalid(db, photo_id, size, *, commit=True):
        _ensure_preview_cache_invalidations_table(db)
        db.conn.execute(
            "DELETE FROM preview_cache_invalidations WHERE photo_id=? AND size=?",
            (photo_id, size),
        )
        if commit:
            db.conn.commit()

    def _is_preview_cache_invalid(db, photo_id, size):
        _ensure_preview_cache_invalidations_table(db)
        row = db.conn.execute(
            "SELECT 1 FROM preview_cache_invalidations "
            "WHERE photo_id=? AND size=?",
            (photo_id, size),
        ).fetchone()
        return row is not None

    def _full_resolution_render_signature(photo, recipe, file_state=None):
        """Describe every catalogued input to a cached inspection render.

        The source size/mtime pair is refreshed by scans, the canonical recipe
        JSON includes content-addressed local-mask references, and the edit-math
        version invalidates bytes produced by older rendering code. Hashing the
        signature into the JPEG filename lets /original safely reuse prepared
        renders without a database table or cross-recipe cache race.
        """
        from image_edits import EDIT_MATH_VERSION, recipe_to_json

        return {
            "photo_id": int(photo["id"]),
            "source_size": photo["file_size"],
            "source_mtime": photo["file_mtime"],
            "filename": photo["filename"],
            "companion_path": photo["companion_path"],
            "file_state": file_state,
            "recipe": recipe_to_json(recipe),
            "edit_math_version": EDIT_MATH_VERSION,
        }

    def _full_resolution_render_path(
        vireo_dir, photo, recipe, file_state=None,
    ):
        signature = json.dumps(
            _full_resolution_render_signature(
                photo, recipe, file_state,
            ),
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        cache_key = hashlib.sha256(signature).hexdigest()[:16]
        return os.path.join(
            vireo_dir, "originals", f"{photo['id']}_{cache_key}.jpg",
        )

    def _peg_render_mtime_to_source(cache_path, photo):
        """Align a freshly written render's mtime to the photo's source.

        ``_prepared_full_resolution_render`` rejects renders whose mtime
        predates ``photos.file_mtime``. Renders are written with the wall
        clock, so a source whose ``file_mtime`` is in the *future* — clock
        skew on the machine that wrote it, archives that preserve future
        timestamps — would fail that gate immediately and re-render on
        every single request. ``serve_thumbnail`` already documents and
        guards this exact trap; the cost here is a full-resolution decode
        plus edit pipeline per request, so it matters more.

        Use this for *signature-keyed* prepared renders only — the
        signature already encodes the recipe and edit-math version, so
        pegging to ``photos.file_mtime`` alone is enough. For the unedited
        RAW display cache, use :func:`_peg_display_cache_mtime` instead;
        that cache-hit check compares the file against
        ``max(mtime(source), mtime(companion))``, so pegging to the row's
        ``file_mtime`` here would fail the check on every request when a
        paired companion has a later mtime than the RAW row.
        """
        source_mtime = photo["file_mtime"] if photo is not None else None
        if source_mtime is None:
            return
        with contextlib.suppress(OSError, TypeError, ValueError):
            os.utime(cache_path, (float(source_mtime), float(source_mtime)))

    def _peg_display_cache_mtime(cache_path, source_paths):
        """Align an unedited RAW display cache's mtime to its own hit check.

        ``/photos/<id>/original`` decides the display cache is fresh when
        its mtime is ``>= max(mtime(image_path), mtime(companion))``.
        Renders are written with the wall clock, so if either live source
        has a *future* mtime — clock skew, archives that preserve future
        timestamps — the just-written cache fails the check the instant
        it lands and every request re-decodes the RAW plus the companion
        JPEG. And even without clock skew, pegging the display cache to
        ``photos.file_mtime`` (the row's stored mtime for the RAW) would
        fail the check whenever a paired companion JPEG has a later
        filesystem mtime than the RAW row does, which is the common shape
        for a fresh camera dump touched by any post-import step.

        Peg to the same max the cache-hit check consults so a valid
        render satisfies its own gate. Best-effort: a failed ``utime``
        only costs the next request a re-render.
        """
        mtimes = []
        for path in source_paths:
            if not path:
                continue
            try:
                mtimes.append(os.path.getmtime(path))
            except OSError:
                continue
        if not mtimes:
            return
        # Satisfy the gate without backdating the file. ``max(mtimes)`` alone
        # stamps a render of a 2019 RAW with a 2019 mtime, and working-copy
        # quota eviction reads mtime as recency — so a copy generated on
        # demand for an old source would be born at the head of the eviction
        # queue and reclaimed before the user opened the next photo. The gate
        # only needs ``>=``, so clamping up to the wall clock keeps it honest
        # and leaves a usable recency stamp.
        peg = max(max(mtimes), time.time())
        with contextlib.suppress(OSError, TypeError, ValueError):
            os.utime(cache_path, (peg, peg))

    def _serve_trusted_working_copy(path):
        """Serve a working-copy cache hit and stamp it as recently used.

        Callers hold ``working_copy_publication_guard`` — the same lock the
        quota pass takes — so the stamp cannot land between eviction's
        directory scan and its unlink.
        """
        from flask import send_file

        touch_working_copy_access(path)
        return send_file(path, mimetype="image/jpeg")

    def _prepared_full_resolution_render(
        vireo_dir, photo, recipe, file_state=None,
    ):
        cache_path = _full_resolution_render_path(
            vireo_dir, photo, recipe, file_state,
        )
        try:
            if not os.path.isfile(cache_path) or os.path.getsize(cache_path) <= 0:
                return None
            # Same freshness gate ``serve_thumbnail`` uses. The signature
            # hash already covers the normal invalidation case (a scan that
            # updates ``file_mtime`` computes a different cache path), so
            # this check is a no-op for legitimate renders — their mtime is
            # the write time, which is by definition ``>= file_mtime``.
            # It exists to reject a *surviving* render left over when a
            # rowid is recycled and the new photo's signature happens to
            # collide with a previous owner's: ``purge_cached_files_for_
            # recycled_id`` backdates any undeletable survivor to mtime 0,
            # and without this check ``/original`` would happily send the
            # previous owner's pixels since the existence-and-size probe
            # can't distinguish them from a fresh render.
            source_mtime = photo["file_mtime"]
            if (
                source_mtime is not None
                and os.path.getmtime(cache_path) < float(source_mtime)
            ):
                return None
        except OSError:
            return None
        return cache_path

    def _invalidate_photo_render_cache(db, photo_ids):
        """Drop cached rendered derivatives after an edit recipe changes."""
        vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
        thumb_dir = app.config["THUMB_CACHE_DIR"]
        preview_dir = os.path.join(vireo_dir, "previews")
        originals_dir = os.path.join(vireo_dir, "originals")
        external_edits_dir = os.path.join(vireo_dir, "external-edits")
        for pid in photo_ids:
            thumb_cache = os.path.join(thumb_dir, f"{pid}.jpg")
            clear_thumb_path = True
            try:
                if os.path.exists(thumb_cache):
                    os.remove(thumb_cache)
            except OSError:
                clear_thumb_path = not os.path.exists(thumb_cache)
                log.warning(
                    "Failed to remove stale thumbnail cache %s", thumb_cache,
                    exc_info=True,
                )
            for source in ("raw", "jpeg"):
                variant = os.path.join(thumb_dir, f"{pid}_{source}.jpg")
                try:
                    if os.path.exists(variant):
                        os.remove(variant)
                except OSError:
                    log.warning(
                        "Failed to remove stale paired-source thumbnail %s",
                        variant,
                        exc_info=True,
                    )
            # ``<pid>_regen.jpg`` / ``<pid>_raw_regen.jpg`` /
            # ``<pid>_jpeg_regen.jpg`` are the sidecars ``serve_thumbnail``
            # falls back to when the default couldn't be unlinked (a
            # persistent lock). Without this pass, editing the recipe
            # while the default stays locked leaves the sidecar carrying
            # the pre-edit pixels; the freshness gate there compares
            # against the unchanged source mtime and re-serves them.
            for stem in (f"{pid}", f"{pid}_raw", f"{pid}_jpeg"):
                sidecar = os.path.join(thumb_dir, f"{stem}_regen.jpg")
                try:
                    if os.path.exists(sidecar):
                        os.remove(sidecar)
                except OSError:
                    log.warning(
                        "Failed to remove stale regeneration sidecar %s",
                        sidecar,
                        exc_info=True,
                    )
            if clear_thumb_path:
                db.conn.execute(
                    "UPDATE photos SET thumb_path = NULL WHERE id = ?", (pid,),
                )
            tracked_sizes = set()
            removed_preview_rows = []
            for row in db.conn.execute(
                "SELECT size FROM preview_cache WHERE photo_id = ?",
                (pid,),
            ).fetchall():
                size_value = row["size"]
                tracked_sizes.add(str(size_value))
                path = os.path.join(preview_dir, f"{pid}_{size_value}.jpg")
                try:
                    if os.path.exists(path):
                        os.remove(path)
                except OSError:
                    if os.path.exists(path):
                        _invalid_preview_cache_paths.add(path)
                        _mark_preview_cache_invalid(
                            db, pid, size_value, commit=False,
                        )
                    log.warning(
                        "Failed to remove stale preview cache %s",
                        path, exc_info=True,
                    )
                else:
                    removed_preview_rows.append((pid, size_value))
                    _clear_preview_cache_invalid(
                        db, pid, size_value, commit=False,
                    )
            try:
                for name in os.listdir(preview_dir):
                    if not (name.startswith(f"{pid}_") and name.endswith(".jpg")):
                        continue
                    size_part = name[len(f"{pid}_"):-4]
                    if size_part in tracked_sizes:
                        continue
                    path = os.path.join(preview_dir, name)
                    try:
                        os.remove(path)
                    except OSError:
                        if os.path.exists(path):
                            _invalid_preview_cache_paths.add(path)
                            _mark_preview_cache_invalid(
                                db, pid, size_part, commit=False,
                            )
                        log.warning(
                            "Failed to remove stale preview cache %s",
                            path, exc_info=True,
                        )
                    else:
                        _clear_preview_cache_invalid(
                            db, pid, size_part, commit=False,
                        )
            except FileNotFoundError:
                pass
            if removed_preview_rows:
                db.conn.executemany(
                    "DELETE FROM preview_cache WHERE photo_id = ? AND size = ?",
                    removed_preview_rows,
                )
            original_paths = [
                os.path.join(originals_dir, f"{pid}.jpg"),
                *Path(originals_dir).glob(f"{pid}_*.jpg"),
            ]
            for original_path in original_paths:
                try:
                    if os.path.exists(original_path):
                        os.remove(original_path)
                except OSError:
                    log.warning(
                        "Failed to remove stale original cache %s",
                        original_path,
                    )
            external_cache = os.path.join(external_edits_dir, f"{pid}.jpg")
            external_meta = os.path.join(external_edits_dir, f"{pid}.json")
            for path in (external_cache, external_meta):
                try:
                    if os.path.exists(path):
                        os.remove(path)
                except OSError:
                    log.warning(
                        "Failed to remove stale external edit cache %s",
                        path, exc_info=True,
                    )
        db.conn.commit()

    def _queue_edit_recipe_sync(db, photo_id, recipe_json):
        """Queue the current non-destructive edit recipe for XMP sync."""
        db.remove_pending_changes(
            photo_id, "edit_recipe", workspace_id=db._ws_id(), _commit=False,
        )
        db.queue_change(
            photo_id, "edit_recipe", recipe_json or "",
            workspace_id=db._ws_id(), _commit=False,
        )
        db.conn.commit()

    def _count_lines(path):
        if not path:
            return None
        try:
            with open(path) as f:
                return sum(1 for line in f if line.strip())
        except (OSError, UnicodeError):
            return None

    @app.teardown_appcontext
    def _close_db(exc):
        db = g.pop("db", None)
        if db is not None:
            db.conn.close()

    def _reraise_fatal_cleanup_error(exc):
        if isinstance(exc, (KeyboardInterrupt, GeneratorExit)):
            raise exc

    def _cleanup_cached_files_for_deleted_photos(files, progress_callback=None):
        try:
            from preview_cache import cleanup_cached_files_for_deleted_photos
            cleanup_cached_files_for_deleted_photos(
                app.config["THUMB_CACHE_DIR"], files, progress_callback=progress_callback,
            )
        except BaseException as exc:
            _reraise_fatal_cleanup_error(exc)
            log.exception("Failed to clean cached files after delete")

    @app.before_request
    def _enforce_api_v1_token():
        if not request.path.startswith("/api/v1/"):
            return None
        expected = app.config.get("API_TOKEN")
        if not expected:
            # No token configured → deny all v1 traffic.
            return json_error("API token not configured", 401)
        supplied = request.headers.get("X-Vireo-Token", "")
        # ``secrets.compare_digest`` raises ``TypeError`` when either str
        # operand contains a non-ASCII code point, which would surface as a
        # 500 for an attacker-supplied token — encode to bytes so a bogus
        # header is a plain 401 like any other wrong value.
        if not secrets.compare_digest(supplied.encode("utf-8"), expected.encode("utf-8")):
            return json_error("Invalid or missing X-Vireo-Token", 401)
        return None

    app.register_blueprint(system_blueprint)

    @app.route("/api/v1/shutdown", methods=["POST"])
    def api_v1_shutdown():
        import signal
        import threading

        def _shutdown():
            os.kill(os.getpid(), signal.SIGTERM)

        threading.Timer(0.5, _shutdown).start()
        return jsonify({"status": "shutting_down"})

    @app.route("/api/shutdown", methods=["POST"])
    def api_shutdown():
        # Require a non-simple header to block cross-site POSTs.
        # Browsers won't send custom headers cross-origin without a CORS
        # preflight, and we don't serve permissive CORS headers, so a
        # malicious page cannot trigger this endpoint.
        if not request.headers.get("X-Vireo-Shutdown"):
            return json_error("Missing X-Vireo-Shutdown header", 403)

        import signal
        import threading

        def _shutdown():
            os.kill(os.getpid(), signal.SIGTERM)

        threading.Timer(0.5, _shutdown).start()
        return jsonify({"status": "shutting_down"})

    # Load user config (e.g. HF token) on startup
    import config as cfg

    startup_cfg = cfg.load()
    if startup_cfg.get("hf_token"):
        os.environ["HF_TOKEN"] = startup_cfg["hf_token"]

    # Initialize job runner, log broadcaster, and default collections
    _t0 = time.time()
    init_db = Database(
        db_path,
        initialize_schema=(db_path == ":memory:"),
    )
    log.info("Database init took %.2fs (workspace: %s)", time.time() - _t0,
             init_db.get_workspace(init_db._active_workspace_id)["name"])
    # Migrate the legacy 'Needs Classification' default collection BEFORE
    # seeding defaults — otherwise create_default_collections inserts
    # 'Needs Identification' first, then the migration skips renaming
    # because the target name already exists, leaving a duplicate.
    init_db.migrate_default_subject_collection()
    init_db.migrate_default_needs_identification_collection()
    init_db.migrate_default_location_collections()
    # One-shot keyword-name normalization backfill. Database.__init__ only
    # runs it when initialize_schema=True, and every file-backed connection
    # this app opens — including this startup init_db and every per-request
    # connection at `_get_db` — passes initialize_schema=False. Without an
    # explicit run here, an upgraded DB can serve requests with `‘apapane`-
    # style variant rows still present until some background job happens
    # to construct a full `Database()` (initialize_schema=True); in that
    # window an add/rename can miss the legacy row and create duplicate
    # tags or stale XMP. The method is idempotent (db_meta-gated) so
    # subsequent boots are a cheap SELECT.
    init_db.normalize_keyword_data()
    repaired_location_ancestors = init_db.repair_misclassified_location_ancestors()
    if repaired_location_ancestors:
        log.info(
            "Restored %d location hierarchy nodes misclassified as taxonomy",
            repaired_location_ancestors,
        )
    # Ungroup legacy bursts whose stored votes span more than one species.
    # Those rows display one species and, through accept_prediction's
    # vote-winner lookup, tag another; the repair makes them read as the
    # current classifier would have written them. Runs before the first
    # request so no page can render a row this is about to change, and
    # before any accept can act on one. Depends on no taxonomy or config,
    # so unlike the duplicate-species repair it needs no deferral: it is
    # db_meta-gated and self-logging, and later boots pay one marker
    # lookup. Method logs its own totals — the counts are the point, per
    # CORE_PHILOSOPHY.md.
    init_db.repair_mixed_species_prediction_groups()

    # Parsing taxonomy.json is expensive for a full iNaturalist download.
    # Cache the startup instance so overlapping one-time migrations and the
    # immediate background species pass do not each parse it independently.
    _taxonomy_not_loaded = object()
    _startup_taxonomy = _taxonomy_not_loaded

    def _load_startup_taxonomy():
        nonlocal _startup_taxonomy
        # Do not cache a miss: a concurrent first-run taxonomy download can
        # make the file available before the background retry starts.
        if (
            _startup_taxonomy is _taxonomy_not_loaded
            or _startup_taxonomy is None
        ):
            from taxonomy import load_local_taxonomy

            _startup_taxonomy = load_local_taxonomy()
        return _startup_taxonomy

    def _sync_mark_species_only(db, log_label):
        """Load taxonomy and run mark_species_keywords synchronously.

        Returns True when the pass ran (marking either updated rows or
        found nothing to update), False when taxonomy is missing or the
        pass raised. Callers use the return value to gate follow-up work
        that depends on hierarchy leaves being correctly typed as
        taxonomy/is_species.
        """
        tax = _load_startup_taxonomy()
        if tax is None:
            log.debug(
                "[%s] taxonomy not loaded; deferring species marking",
                log_label,
            )
            return False
        try:
            updated = db.mark_species_keywords(tax)
            if updated:
                log.info(
                    "[%s] Marked %d keywords as species from taxonomy",
                    log_label, updated,
                )
            return True
        except Exception:
            log.debug(
                "[%s] mark_species_keywords failed",
                log_label, exc_info=True,
            )
            return False

    # Remove same-photo, same-taxon duplicate associations left by the old
    # hierarchy-import + top-level-confirmation interaction. Idempotent and
    # db_meta-gated, so later boots only pay for a single marker lookup.
    #
    # The repair identifies duplicates via
    # ``(is_species = 1 OR type = 'taxonomy') AND (rank = 'species' OR
    # taxon_id IS NULL)``. On upgraded databases a hierarchical species
    # leaf can still be a plain/general row until mark_species_keywords
    # retypes it, so run marking synchronously first — otherwise the
    # repair query cannot see the leaf, removes nothing, and still stamps
    # its one-shot marker; a subsequent background mark_species_keywords
    # pass could then make the leaf eligible while the redundant root
    # association remains permanently skipped. When taxonomy isn't
    # loaded yet (or marking fails), defer the repair to a later boot
    # rather than stamping the marker over an unmarked hierarchy.
    duplicate_repair_key = Database._DUPLICATE_PHOTO_SPECIES_REPAIR_KEY
    duplicate_repair_pending = init_db.get_meta(duplicate_repair_key) != "1"
    if duplicate_repair_pending:
        # The legacy bug always left a typed top-level species/taxonomy tag
        # beside another tag on the same photo. If no such pair exists, the
        # repair is structurally impossible and it is safe to stamp the
        # one-shot marker without parsing a potentially huge taxonomy file.
        possible_duplicate = init_db.conn.execute(
            """SELECT 1
               FROM photo_keywords species_pk
               JOIN keywords species_k
                 ON species_k.id = species_pk.keyword_id
               WHERE (species_k.is_species = 1
                      OR species_k.type = 'taxonomy')
                 AND EXISTS (
                     SELECT 1
                     FROM photo_keywords other_pk
                     WHERE other_pk.photo_id = species_pk.photo_id
                       AND other_pk.keyword_id != species_pk.keyword_id
                 )
               LIMIT 1"""
        ).fetchone()
        if possible_duplicate is None:
            init_db.set_meta(duplicate_repair_key, "1")
            duplicate_repair_pending = False
            log.info(
                "Skipped duplicate-species startup repair: "
                "no possible duplicate associations"
            )

    if (
        duplicate_repair_pending
        and _sync_mark_species_only(init_db, "sync-startup-species-mark")
    ):
        init_db.repair_duplicate_photo_species()
    # One-time rewrite of the previous miss-threshold defaults (0.25 / 0.15)
    # to the new defaults (0.20 / 0.12) in both ~/.vireo/config.json and
    # workspace overrides. Gated by a marker so it runs once; re-saved
    # legacy values are preserved on subsequent boots.
    cfg.migrate_legacy_miss_thresholds(init_db)
    # One-time rewrite of the previous eye-focus detection default from on to
    # off in both global config and workspace overrides.
    cfg.migrate_eye_detect_default_off(init_db)
    # One-time resolution of the browse.toggle_ui="h" default clashing with
    # any pre-existing browse binding on ``h``. Writes an explicit "" so the
    # user's existing action keeps working; they can re-bind toggle_ui from
    # the shortcuts editor.
    cfg.migrate_toggle_ui_h_conflict()
    # Existing users commonly have the previous Browse card defaults persisted
    # verbatim. Add the new coordinate-source field only for that exact legacy
    # list; customized card layouts remain unchanged.
    cfg.migrate_browse_location_status_field()
    # One-time rename of the "compare" navigation shortcut to "id_conflicts"
    # after the Compare page became ID Conflicts, so a user's saved binding
    # follows the page instead of being orphaned.
    cfg.migrate_compare_nav_id_to_id_conflicts()
    # One-time rewrite of the previous encounter-grouping species weight
    # (0.10) to the new default (0.40) in both ~/.vireo/config.json and
    # workspace overrides. Without this, upgraded installs that had the
    # pipeline block persisted verbatim keep grouping distinct species into
    # one encounter — the intended split behavior only reaches fresh
    # configs. Only the exact legacy value is rewritten; re-saved values
    # are preserved on subsequent boots.
    cfg.migrate_legacy_w_species_default(init_db)
    # One-time rewrite of the global pipeline.default_strategy (legacy
    # hardcoded strategy name) to pipeline.default_process_id (saved_processes
    # id). The workspace-side rewrite happens inside Database(); this covers
    # the global config file so workspaces that inherit the global default
    # don't silently fall back to import-only after upgrade.
    #
    # init_db uses initialize_schema=False for boot perf, so on the first
    # boot after upgrade the saved_processes table isn't guaranteed to
    # exist yet on this connection — the migration would silently defer
    # and any import in this session that would inherit the legacy global
    # default falls back to import-only until the *next* boot. Open a
    # short-lived schema-initializing handle so the migration completes on
    # the very first boot instead. Only pay the schema-init cost if the
    # migration hasn't been stamped yet; subsequent boots short-circuit
    # inside the function and pass ``init_db`` (whose schema state is
    # irrelevant because the marker check runs first).
    if (
        cfg.MIGRATION_DEFAULT_STRATEGY_TO_PROCESS_ID
        not in cfg._migrations_applied(cfg._read_raw())
    ):
        _default_strategy_migration_db = Database(db_path)
        try:
            cfg.migrate_default_strategy_to_process_id(
                _default_strategy_migration_db,
            )
        finally:
            _default_strategy_migration_db.close()
    else:
        cfg.migrate_default_strategy_to_process_id(init_db)
    init_db.create_default_collections_for_all_workspaces()

    # Keep taxonomy typing and duplicate-species repair fresh in the
    # background. Wildlife classification eligibility is stored separately
    # on photos; species marking no longer materializes a Wildlife keyword.
    import threading

    def _retire_wildlife_genre():
        """Run the catalog-wide XMP migration outside startup readiness.

        Large upgraded catalogs can require tens of thousands of sidecar
        reads here. Keeping that work on create_app's calling thread prevents
        the HTTP listener from binding and makes the desktop launcher report
        a false startup failure when its readiness deadline expires.
        """
        retirement_db = None
        started_at = time.time()
        try:
            retirement_db = Database(db_path)
            retired = retirement_db.retire_builtin_wildlife_genre()
            if retired:
                log.info(
                    "Retired the built-in Wildlife genre from %d photo(s)",
                    retired,
                )
            log.info(
                "Wildlife genre retirement finished in %.2fs",
                time.time() - started_at,
            )
            return retired
        except Exception:
            log.exception("Wildlife genre retirement failed")
            return 0
        finally:
            if retirement_db is not None:
                retirement_db.close()

    # Tests and one-shot tools can invoke the pass deterministically without
    # enabling production timers. Production schedules it only after every
    # route has been registered, immediately before create_app returns.
    app._retire_wildlife_genre = _retire_wildlife_genre

    def _mark_species_and_repair(db, log_label):
        """Load taxonomy, mark species keywords, and repair duplicates."""
        tax = _load_startup_taxonomy()
        if tax is None:
            log.debug("[%s] taxonomy not loaded; deferring species marking", log_label)
            return
        try:
            updated = db.mark_species_keywords(tax)
            if updated:
                log.info("[%s] Marked %d keywords as species from taxonomy",
                         log_label, updated)
            repaired = db.repair_duplicate_photo_species()
            if repaired:
                log.info(
                    "[%s] Removed %d duplicate root species associations",
                    log_label, repaired,
                )
        except Exception:
            log.debug(
                "[%s] species marking/repair failed", log_label, exc_info=True,
            )

    def _mark_species():
        bg_db = None
        try:
            bg_db = Database(db_path)
        except Exception:
            log.debug("Could not open background db for species marking", exc_info=True)
            return
        try:
            _mark_species_and_repair(bg_db, "background")
        finally:
            bg_db.close()

    if not os.environ.get("VIREO_DISABLE_STARTUP_BACKFILL_TIMERS"):
        threading.Thread(target=_mark_species, daemon=True).start()

    def _folder_health_loop():
        """Periodically check folder health."""
        import time as _time
        _time.sleep(30)  # Initial delay
        while True:
            health_db = None
            try:
                health_db = Database(db_path)
                changed = health_db.check_folder_health()
                if changed:
                    log.info("Folder health check: %d folder(s) changed status", changed)
                    # A background ok↔missing flip would otherwise leave a
                    # ready /api/photos/missing cache serving the pre-flip
                    # photo list: the modal/banner could offer to delete
                    # rows whose folder just went offline, or hide ghosts
                    # from a folder that just came back, until a later
                    # rescan replaced the entry.
                    _invalidate_missing_originals_cache()
            except Exception:
                log.debug("Folder health check failed", exc_info=True)
            finally:
                if health_db is not None:
                    health_db.close()
            _time.sleep(600)  # 10 minutes

    # Suppressed in tests via ``VIREO_DISABLE_STARTUP_BACKFILL_TIMERS``: the
    # ``app_and_db`` fixture seeds folders at fictional paths like
    # ``/photos/2024`` that don't exist on disk. After the 30s grace period
    # this loop calls ``check_folder_health`` on the tmp_path DB, sees the
    # paths missing, and flips folder status to ``'missing'`` — which causes
    # ``get_photos`` to filter the seeded photos out and any subsequent
    # assertion against them to fail with ``IndexError``. On the slow
    # Windows CI runner the full suite takes ~48 min, so by the time the
    # later predictions/photos tests reach the fixture the timer has long
    # since fired.
    if not os.environ.get("VIREO_DISABLE_STARTUP_BACKFILL_TIMERS"):
        threading.Thread(target=_folder_health_loop, daemon=True).start()

    app._job_runner = JobRunner(db=init_db)
    # XMP sidecars are read-modify-written files; serialize sync jobs so
    # repeated clicks cannot race while touching the same sidecar.
    app._sync_job_lock = threading.Lock()
    app._log_broadcaster = LogBroadcaster(buffer_size=500)
    app._log_broadcaster.install()

    def _cleanup_app_resources(job_timeout=10.0):
        try:
            jobs_stopped = app._job_runner.shutdown(timeout=job_timeout)
        except Exception:
            jobs_stopped = False
            log.exception("Failed to shut down background jobs cleanly")
        try:
            app._log_broadcaster.uninstall()
        except Exception:
            log.exception("Failed to uninstall log broadcaster during cleanup")
        try:
            init_db.close()
        except Exception:
            log.exception("Failed to close database during cleanup")
        return jobs_stopped

    app._cleanup_app_resources = _cleanup_app_resources

    # Live progress of the most recent new-images walk, keyed by
    # (db_path, workspace_id). Written by the walk's progress callback and
    # read by the GET/POST endpoints so a ``pending`` response can say
    # "38,000 files checked, 2,100 new so far" instead of a bare spinner —
    # the transparency the banner-click path needs on multi-minute walks
    # over large network volumes. Values are per-spawn dicts; a new walk
    # replaces the key wholesale, so readers never see torn state.
    app._new_images_walk_progress = {}
    app._missing_originals_lock = threading.Lock()
    app._missing_originals_cache = {}
    app._missing_originals_inflight = {}
    app._missing_originals_errors = {}
    # Monotonic per-key counter bumped whenever the cache is invalidated
    # while a scan is in flight. Each scan snapshots this at start; if the
    # counter has advanced by the time it finishes, the scan's results are
    # from a pre-invalidation view of the library and must be discarded so
    # deleted photos don't reappear in the banner/modal.
    app._missing_originals_generation = {}

    # Working copies are generated by imports, scans, and on-demand reads.
    # Do not warm the library-wide cache at startup: it consumes disk and
    # CPU for photos the user has not requested.

    # ----- thumb_path self-healing backfill -----
    # The dashboard's coverage card counts thumbnails by ``thumb_path IS NOT
    # NULL``, but for a long stretch the column was never populated by
    # production code, so libraries with 40k JPEGs cached on disk reported
    # "0 thumbnails" forever. This pass aligns the column with disk reality
    # for legacy rows, and clears it for photos whose cached file has since
    # been deleted (drift correction).
    #
    # Same shape as the working-copy backfill above: ephemeral JobRunner
    # job (so it shows in the bottom panel), never written to job_history,
    # skipped entirely when a fast count check finds nothing to do.
    def _kickoff_thumb_path_backfill():
        from thumbnails import (
            backfill_thumb_paths,
            thumb_path_backfill_candidate_count,
        )

        tpdb = None
        try:
            tpdb = Database(db_path)
            candidate_count = thumb_path_backfill_candidate_count(
                tpdb, app.config["THUMB_CACHE_DIR"],
            )
        except Exception:
            log.exception("thumb_path backfill: candidate check failed")
            return
        finally:
            if tpdb is not None:
                tpdb.close()
        if candidate_count == 0:
            log.debug("thumb_path backfill: no candidates, skipping")
            return

        runner = app._job_runner
        cache_dir = app.config["THUMB_CACHE_DIR"]

        def work(job):
            thread_db = Database(db_path)
            try:
                active_ws = init_db._active_workspace_id
                if active_ws is not None:
                    thread_db.set_active_workspace(active_ws)

                def progress_cb(current, total):
                    job["progress"]["current"] = current
                    job["progress"]["total"] = total
                    runner.push_event(
                        job["id"],
                        "progress",
                        {
                            "current": current,
                            "total": total,
                            "phase": f"{current:,} / {total:,} photos reconciled",
                        },
                    )

                def status_cb(message, **_phase):
                    runner.push_event(job["id"], "progress", {
                        "phase": message,
                        "current": job["progress"].get("current", 0),
                        "total": job["progress"].get("total", 0),
                    })

                def cancel_check():
                    return runner.is_cancelled(job["id"])

                return backfill_thumb_paths(
                    thread_db, cache_dir,
                    progress_callback=progress_cb,
                    status_callback=status_cb,
                    cancel_check=cancel_check,
                )
            finally:
                thread_db.close()

        try:
            runner.start(
                "thumb_path_backfill", work,
                ephemeral=True,
                config={"trigger": "startup"},
            )
        except Exception:
            log.exception("Failed to start thumb_path backfill job")

    app._kickoff_thumb_path_backfill = _kickoff_thumb_path_backfill

    if not os.environ.get("VIREO_DISABLE_STARTUP_BACKFILL_TIMERS"):
        _thumb_backfill_timer = threading.Timer(6.0, _kickoff_thumb_path_backfill)
        _thumb_backfill_timer.daemon = True
        _thumb_backfill_timer.start()

    # -- Page routes --

    @app.route("/config-defaults.js")
    def config_defaults_js():
        """Expose backend defaults to browser code without template literals.

        Templates are kept strictly Jinja-free (see
        ``test_templates_jinja_free_except_includes``), so platform-aware
        wording is injected here as ``window.*`` globals. This script is loaded
        first in ``_navbar.html``, before any inline page script runs.
        """
        labels = _file_manager_labels()
        return Response(
            "window.VIREO_CONFIG_DEFAULTS = "
            + json.dumps(cfg.DEFAULTS, separators=(",", ":"))
            + ";\nwindow.VIREO_PLATFORM = "
            + json.dumps(sys.platform)
            + ";\nwindow.VIREO_REVEAL_LABEL = "
            + json.dumps(labels["reveal"])
            + ";\nwindow.VIREO_FILE_MANAGER_NAME = "
            + json.dumps(labels["name"])
            + ";\nwindow.VIREO_EDITOR_PATH_PLACEHOLDER = "
            + json.dumps(labels["editor_placeholder"])
            + ";\n",
            mimetype="application/javascript",
        )

    @app.route("/")
    def index():
        # Resume onboarding until the install can actually classify, OR the
        # user explicitly finished/skipped setup. Redirecting on
        # "model downloaded" alone stranded a user who bailed after the model
        # download but before the labels step: setup_complete stays false yet
        # the model is on disk, so they'd land back in the blocked pipeline.
        if classification_readiness(_get_db())["ready"] or cfg.load().get("setup_complete"):
            return redirect("/browse")
        return redirect("/welcome")

    @app.route("/welcome")
    def welcome():
        if request.args.get("force"):
            return render_template("welcome.html")
        if classification_readiness(_get_db())["ready"] or cfg.load().get("setup_complete"):
            return redirect("/browse")
        return render_template("welcome.html")

    @app.route("/api/setup/complete", methods=["POST"])
    def api_setup_complete():
        """Mark first-launch setup as done (called after download or skip)."""
        # Lock + raw read-modify-write so a concurrent settings PATCH isn't
        # reverted and we don't pin every DEFAULTS value into the user's
        # file (see api_pipeline_save_grouping_defaults).
        with _settings_write_lock:
            raw = _read_raw_config_file()
            raw["setup_complete"] = True
            cfg.save(raw)
        return jsonify({"ok": True})

    app.register_blueprint(pages_blueprint)

    # -- API routes --

    def _prepare_browse_photo_dicts(db, photos, stack_items=None):
        """Normalize photo rows and attach optional Browse stack summaries."""
        photo_dicts = [dict(photo) for photo in photos]
        stacks_by_cover = {
            item["cover_id"]: item for item in (stack_items or [])
        }
        for photo in photo_dicts:
            projected = (
                stack_items is not None
                or "_browse_stack_kind" in photo
            )
            kind = photo.pop("_browse_stack_kind", None)
            raw_count = photo.pop("_browse_stack_count", None)
            raw_ids = photo.pop("_browse_stack_member_ids", None)
            # Strip every SQL-only stack helper before the response is
            # serialized. Their names and values are implementation details;
            # Browse consumes only the stable summary below.
            for key in list(photo):
                if key.startswith("_"):
                    photo.pop(key, None)
            item = stacks_by_cover.get(photo.get("id"))
            if item is not None:
                kind = item.get("kind")
                member_ids = list(item.get("member_ids") or [])
            else:
                member_ids = []
                if raw_ids:
                    member_ids = [
                        int(value) for value in str(raw_ids).split(",") if value
                    ]
            count = len(member_ids) if member_ids else int(raw_count or 1)
            if projected:
                photo["browse_stack"] = (
                    {
                        "kind": kind,
                        "count": count,
                        "photo_ids": member_ids,
                    }
                    if kind and count >= 2
                    else None
                )
        attach_location_statuses(db, photo_dicts)
        attach_species(db, photo_dicts)
        attach_species_representatives(db, photo_dicts)
        attach_detections(db, photo_dicts)
        attach_edit_recipes(db, photo_dicts)
        return photo_dicts

    def _request_flag_filter():
        flag = request.args.get("flag", None)
        if flag in (None, ""):
            return None
        if flag not in ("none", "flagged", "rejected"):
            raise ValueError("flag must be 'none', 'flagged', or 'rejected'")
        return flag

    def _request_bool_arg(name):
        raw = request.args.get(name, "")
        return str(raw).strip().lower() in {"1", "true", "yes", "on"}

    def _request_rules_arg():
        """Parse the optional ``rules`` query param (a JSON universal-filter
        rule tree). Returns None when absent; raises ValueError on invalid
        JSON so callers surface a 400. The active visual model is injected
        exactly as /api/photos/query does, keeping every rules-accepting
        endpoint's notion of "has a visual index" consistent.
        """
        raw = request.args.get("rules")
        if not raw:
            return None
        try:
            rules = json.loads(raw)
        except ValueError as exc:
            raise ValueError("rules must be valid JSON") from exc
        return _inject_active_visual_model(rules)

    def _request_photo_ids_arg():
        """Parse the optional ``photo_ids`` query param (comma-separated ints).

        Returns None when absent so callers keep their unscoped behaviour, and
        raises ValueError on a malformed value so a typo surfaces as a 400
        rather than silently widening the query to the whole workspace.

        Capped at the same 1000 ids ``_parse_selection_photo_ids`` allows:
        ``/api/predictions`` runs one ``_photo_in_workspace`` query per id, so
        an unbounded list turns a single GET into unbounded database work.
        """
        raw = request.args.get("photo_ids")
        if raw is None or raw.strip() == "":
            return None
        ids = []
        seen = set()
        for part in raw.split(","):
            part = part.strip()
            if not part:
                continue
            try:
                pid = int(part)
            except ValueError as exc:
                raise ValueError("photo_ids must be integers") from exc
            if pid not in seen:
                ids.append(pid)
                seen.add(pid)
        if not ids:
            raise ValueError("photo_ids must contain at least one id")
        if len(ids) > 1000:
            raise ValueError("too many photo_ids")
        return ids

    _VISUAL_STRENGTH_THRESHOLDS = {"broad": 0.10, "balanced": 0.15, "strict": 0.22}
    # Query-text embeddings keyed by (model, prompt): the ONNX text encode is
    # the expensive step and the same prompt is re-resolved by every surface
    # (grid, summary, calendar, facet counts) plus each typeahead keystroke.
    _text_query_cache = {}

    def _validate_visual_arg(visual):
        """Normalize a visual clause payload or raise ValueError."""
        if visual is None:
            return None
        if not isinstance(visual, dict):
            raise ValueError("visual must be an object")
        prompt = visual.get("prompt")
        if not isinstance(prompt, str) or not prompt.strip():
            raise ValueError("visual.prompt must be a non-empty string")
        strength = visual.get("strength", "balanced")
        # An unhashable strength (e.g. ``["broad"]``) makes ``strength in
        # _VISUAL_STRENGTH_THRESHOLDS`` raise ``TypeError``, which would
        # escape the 400 handler in the collection create/update paths as
        # a 500 (CodeRabbit review r3620473547 outside-diff note).
        if not isinstance(strength, str):
            raise ValueError("visual.strength must be a string")
        if strength not in _VISUAL_STRENGTH_THRESHOLDS:
            raise ValueError("visual.strength must be broad, balanced, or strict")
        return {"prompt": prompt.strip(), "strength": strength}

    def _request_visual_arg():
        """Parse the optional ``visual`` query param (JSON clause)."""
        raw = request.args.get("visual")
        if not raw:
            return None
        try:
            parsed = json.loads(raw)
        except ValueError as exc:
            raise ValueError("visual must be valid JSON") from exc
        return _validate_visual_arg(parsed)

    def _resolve_visual(
        db, rules, visual, collection_id=None, folder_id=None,
        candidate_photo_ids=None,
        include_offline_folders=False,
    ):
        """Run a visual clause over the rule tree's candidate photos.

        Returns ``(info, ordered_ids, sims_by_pid)``. ``info["status"]`` is
        ``ok`` with ids ordered by similarity, or an unhealthy state
        (``no_model`` / ``model_no_text_search`` / ``no_embeddings`` /
        ``encoding_failed``) with ``ordered_ids is None`` — callers then
        apply metadata rules only and surface the state. Never silently
        zero results (design hard requirement).

        ``candidate_photo_ids`` further intersects the rule-derived
        candidate set. The Map endpoint passes plottable ids so a
        workspace whose only embeddings sit on non-plottable photos
        surfaces as ``no_embeddings`` (metadata fallback) instead of
        returning ``ok`` with ids that ``get_geolocated_photos`` will
        silently intersect down to zero.
        """
        import numpy as np
        from models import get_active_model
        base = {"prompt": visual["prompt"], "strength": visual["strength"]}
        active = get_active_model()
        if not active:
            return {**base, "status": "no_model", "model": None}, None, None
        model_name = active["name"]
        base["model"] = model_name
        if active.get("model_type", "bioclip") == "timm":
            return {**base, "status": "model_no_text_search"}, None, None
        candidates = db.query_photo_ids(
            rules, collection_id=collection_id, folder_id=folder_id,
            include_offline_folders=include_offline_folders,
        )
        if candidate_photo_ids is not None:
            restrict = set(candidate_photo_ids)
            candidates = [pid for pid in candidates if pid in restrict]
        emb_pairs = db.get_photos_with_embedding(
            model_name,
            photo_ids=candidates,
            include_offline_folders=include_offline_folders,
        )
        if not emb_pairs:
            return (
                {**base, "status": "no_embeddings",
                 "candidates": len(candidates), "indexed": 0},
                None, None,
            )
        cache_key = (model_name, visual["prompt"])
        query_vec = _text_query_cache.get(cache_key)
        if query_vec is None:
            from text_encoder import encode_text
            try:
                query_vec = encode_text(
                    visual["prompt"],
                    model_str=active["model_str"],
                    pretrained_str=active.get("weights_path", ""),
                )
            except Exception as exc:
                log.exception("Visual clause text encoding failed: %r", visual["prompt"])
                return (
                    {**base, "status": "encoding_failed", "error": str(exc)},
                    None, None,
                )
            if len(_text_query_cache) > 64:
                _text_query_cache.clear()
            _text_query_cache[cache_key] = query_vec
        pids = [pid for pid, _ in emb_pairs]
        emb_matrix = np.stack(
            [np.frombuffer(blob, dtype=np.float32) for _, blob in emb_pairs]
        )
        sims = emb_matrix @ query_vec
        threshold = _VISUAL_STRENGTH_THRESHOLDS[visual["strength"]]
        ordered_ids = []
        sims_by_pid = {}
        for i in np.argsort(sims)[::-1]:
            if sims[i] < threshold:
                break
            pid = pids[int(i)]
            ordered_ids.append(pid)
            sims_by_pid[pid] = round(float(sims[i]), 4)
        info = {**base, "status": "ok", "matched": len(ordered_ids),
                "candidates": len(candidates), "indexed": len(emb_pairs)}
        return info, ordered_ids, sims_by_pid

    def _apply_visual_to_rules(
        db, rules, visual, collection_id=None, folder_id=None,
        candidate_photo_ids=None,
    ):
        """For GET consumers (summary/calendar/values/geo/predictions):
        when the visual clause is healthy, restrict the rules to the
        matched ids (inlined photo_ids — no bound-parameter cap) so
        counts describe the same photos the visually-filtered grid
        shows. Unhealthy → rules unchanged, matching the grid's
        metadata-only fallback.

        Returns ``(rules, visual_info)``. ``visual_info`` is ``None`` when
        no visual clause was requested; otherwise it is the
        ``_resolve_visual`` status dict — ``{status: "ok", matched, …}``
        on a successful clause, or an unhealthy state (``no_model`` /
        ``model_no_text_search`` / ``no_embeddings`` / ``encoding_failed``)
        when the clause fell back to metadata-only. Endpoints whose UI
        renders the visual chip (Map, Browse, Review) must surface this
        so the chip does not silently broaden results.

        ``candidate_photo_ids`` narrows the pre-embedding candidate set —
        used by ``/api/photos/geo`` to keep the visual search inside the
        Map's plottable scope so a workspace with embeddings only on
        non-plottable photos surfaces as ``no_embeddings`` instead of
        returning ``ok`` ids that the endpoint then intersects away.
        """
        if visual is None:
            return rules, None
        base_rules = rules if rules is not None else []
        info, ordered_ids, _sims = _resolve_visual(
            db, base_rules, visual,
            collection_id=collection_id, folder_id=folder_id,
            candidate_photo_ids=candidate_photo_ids,
        )
        if ordered_ids is None:
            return rules, info
        rules_list = (
            [] if rules is None
            else ([rules] if isinstance(rules, dict) else list(rules))
        )
        return rules_list + [{"field": "photo_ids", "value": ordered_ids}], info

    def _request_location_status_filter():
        value = (request.args.get("location_status") or "").strip().lower()
        if not value:
            return None
        if value not in {"exif", "assigned", "none"}:
            raise ValueError(
                "location_status must be 'exif', 'assigned', or 'none'"
            )
        return value

    def _collection_rules_state(db, rules_json):
        """Return parsed collection rules and whether they are degraded."""
        try:
            parsed_rules = json.loads(rules_json)
        except (TypeError, ValueError):
            return None, True
        return parsed_rules, not db.rules_resolvable(parsed_rules)

    @app.route("/api/browse/init")
    def api_browse_init():
        """Combined endpoint for browse page initial load — one request instead of five."""
        import config as cfg
        db = _get_db()
        page = max(1, request.args.get("page", 1, type=int))
        default_per_page = cfg.load().get("photos_per_page", 50)
        per_page = max(1, min(request.args.get("per_page", default_per_page, type=int), _MAX_PER_PAGE))
        sort = request.args.get("sort", "date")
        folder_id = request.args.get("folder_id", None, type=int)
        collection_id = request.args.get("collection_id", None, type=int)
        focus_photo_id = request.args.get("focus_photo_id", None, type=int)
        # A focused deep link needs the requested photo itself to be a grid
        # item. If it is a hidden member of a stack, stack pagination cannot
        # express its position, so focused loads deliberately use ordinary
        # photo rows; the user can re-enable stacks after the handoff.
        stacks = _request_bool_arg("stacks") and focus_photo_id is None

        # Keep the combined first-paint payload on one SQLite read snapshot.
        # Independent SELECT snapshots can straddle a background folder-health
        # commit and combine pre-transition photos/missing IDs with a
        # post-transition folder tree. Since the navbar poll may already have
        # completed, there is no guaranteed immediate observation to repair
        # that split response.
        db.conn.execute("BEGIN")

        # ``db.get_photos(collection_id=...)`` / ``count_filtered_photos`` both
        # expand only ``collections.rules`` — the same rules-only path guarded
        # elsewhere by ``_reject_visual_collection``. A visual-only collection
        # stores ``rules: []``, so running it through that path here would
        # silently widen first paint to every workspace photo. The client's
        # ``bootstrapBrowse()`` calls ``filterByCollection()`` right after,
        # which reloads through ``/api/photos/query`` with the visual clause,
        # but the wrong grid still flashes between the two — and any failure
        # before ``filterByCollection()`` runs leaves the user staring at the
        # widened scope. Drop the ``collection_id`` from the photo query and
        # return an empty grid so the wrong data can never appear (Codex
        # review on PR #1343). Folders/keywords/collections are still returned
        # so the sidebar bootstraps.
        visual_first_paint = False
        if collection_id is not None:
            coll_row = db.conn.execute(
                "SELECT visual_json FROM collections "
                "WHERE id = ? AND workspace_id = ?",
                (collection_id, db._ws_id()),
            ).fetchone()
            if coll_row is not None and coll_row["visual_json"] is not None:
                visual_first_paint = True

        # Snapshot the active workspace's missing-folder IDs so the client's
        # navbar can seed ``_missingFoldersLastIds`` from this init response.
        # Without a baseline, the first /api/folders/missing observation
        # returns false when a background _folder_health_loop flip runs
        # between init and the poll — later polls then see the same IDs and
        # never dispatch, leaving Browse stuck showing the pre-flip state
        # (Codex review r3686191141).
        #
        # This is the first read in the explicit transaction above, so every
        # photo / folder / keyword / collection read below shares the same
        # health snapshot. Ordering alone is insufficient: if the background
        # health loop commits after this query but before get_folder_tree(),
        # and the navbar's initial poll already finished, no immediate poll
        # remains to repair the mixed response (Codex reviews r3686317681 and
        # r3687501744).
        missing_folder_ids = [f["id"] for f in db.get_missing_folders()]
        folder_health_version = db.get_folder_health_version()

        # First paint is scope-only (folder / collection / sort); metadata
        # filter deep links compile into the filter bar client-side, which
        # reloads through /api/photos/query once initialized (Phase 5 —
        # legacy per-field params removed from this endpoint).
        if visual_first_paint:
            photos = []
            total = 0
            underlying_total = 0
            focus_index = None
            focus_page = page
        else:
            try:
                if stacks:
                    photos = db.query_browse_stacks(
                        [], folder_id=folder_id, collection_id=collection_id,
                        page=page, per_page=per_page, sort=sort,
                    )
                    total = db.count_browse_stacks(
                        [], folder_id=folder_id, collection_id=collection_id,
                    )
                    underlying_total = db.count_photos_for_rules(
                        [], folder_id=folder_id, collection_id=collection_id,
                    )
                else:
                    photos = db.get_photos(
                        folder_id=folder_id,
                        collection_id=collection_id,
                        page=page,
                        per_page=per_page,
                        sort=sort,
                    )
            except ValueError as exc:
                db.conn.rollback()
                return json_error(str(exc), 400)
            if not stacks:
                if not any([folder_id, collection_id]):
                    total = db.count_photos()
                else:
                    try:
                        total = db.count_filtered_photos(
                            folder_id=folder_id,
                            collection_id=collection_id,
                        )
                    except ValueError as exc:
                        db.conn.rollback()
                        return json_error(str(exc), 400)
                underlying_total = total
            # Photo deep links need the target's position in the exact sort
            # order used by this first paint. Returning the zero-based index
            # and its bounded page from this read snapshot avoids probing
            # serial 50-photo pages until the target happens to appear. Keep
            # the extra ordered-id query opt-in so ordinary Browse loads retain
            # their existing cost.
            #
            # When the target is already in the first-page ``photos`` fetched
            # above (the common case — Highlights and most native actions open
            # a photo whose sorted position is on page 1), compute the index
            # from that page directly.  Materializing every folder ID would
            # add O(folder size) latency and memory to the critical first
            # paint on the documented 100K- and 1M-photo libraries, even when
            # a lookup was never necessary (Codex review r3792637103).
            focus_index = None
            focus_page = page
            if focus_photo_id is not None:
                local_index = None
                for offset, row in enumerate(photos):
                    if row["id"] == focus_photo_id:
                        local_index = offset
                        break
                if local_index is not None:
                    focus_index = (page - 1) * per_page + local_index
                else:
                    try:
                        focus_index = db.get_photo_position(
                            focus_photo_id,
                            folder_id=folder_id,
                            collection_id=collection_id,
                            sort=sort,
                        )
                    except ValueError as exc:
                        db.conn.rollback()
                        return json_error(str(exc), 400)
                # Return only the bounded page containing the target from the
                # same SQLite read snapshot as its position and total. Sending
                # every preceding row can freeze Browse for a focus deep in a
                # million-photo folder; independent parallel offset requests,
                # meanwhile, allow ingestion/deletion to create overlaps,
                # gaps, and stale totals. One target page avoids both failure
                # modes, and ordinary lazy paging resumes after it.
                if focus_index is not None:
                    focus_page = focus_index // per_page + 1
                    if focus_page != page:
                        try:
                            photos = db.get_photos(
                                folder_id=folder_id,
                                collection_id=collection_id,
                                page=focus_page,
                                per_page=per_page,
                                sort=sort,
                            )
                        except ValueError as exc:
                            db.conn.rollback()
                            return json_error(str(exc), 400)
        folders = db.get_folder_tree()
        keywords = db.get_keyword_tree()
        collections = db.get_collections()

        photo_dicts = _prepare_browse_photo_dicts(db, photos)
        collection_dicts = []
        for c in collections:
            d = dict(c)
            # Flag degraded rules at first paint so a fast click on the
            # sidebar row can't fall into the 400 /photos path before
            # loadCollectionCounts() lands. Only validate the rules — do
            # not run COUNT(DISTINCT p.id) per collection here; that
            # N+1 is what the async loadCollectionCounts() call in
            # bootstrapBrowse() was designed to avoid, and re-adding it
            # to the critical first-paint path makes opening Browse wait
            # on every smart-collection query. Malformed JSON is treated
            # as degraded too — those rules would 400 downstream just
            # like an unresolvable rule.
            parsed_rules, degraded = _collection_rules_state(db, c["rules"])
            if degraded:
                d["can_add_photos"] = False
                d["count_error"] = True
                collection_dicts.append(d)
                app.logger.warning(
                    "Collection %s (%s) has unresolvable rules; marking degraded",
                    c["id"],
                    c["name"],
                )
                continue
            else:
                # A visual-only collection stores ``rules: []`` which
                # ``_collection_accepts_manual_photos`` treats as addable,
                # but ``/add-photos`` would just append to ``photo_ids``
                # without touching ``visual_json`` — the manually added
                # photos would only show up in the reopened collection
                # if they also matched the hidden visual clause, making
                # the add silently ineffective (Codex r3620791304).
                d["can_add_photos"] = (
                    c["visual_json"] is None
                    and _collection_accepts_manual_photos(parsed_rules)
                )
            collection_dicts.append(d)

        response_payload = {
            "photos": photo_dicts,
            "total": total,
            "page": page,
            "per_page": per_page,
            "folders": [dict(f) for f in folders],
            "keywords": [dict(k) for k in keywords],
            "collections": collection_dicts,
            "missing_folder_ids": missing_folder_ids,
            "folder_health_version": folder_health_version,
            "focus_index": focus_index,
            "focus_page": focus_page,
            # The workspace this tree was scoped to. Browse pins it to
            # the destructive folder-removal call so a cross-tab
            # workspace switch between render and click cannot redirect
            # the DELETE at another workspace.
            "active_workspace_id": db._ws_id(),
        }
        if stacks:
            response_payload["underlying_total"] = underlying_total
        response = jsonify(response_payload)
        # End the read transaction after every value in the response has been
        # materialized. rollback() is intentional: this endpoint is read-only
        # and it releases the snapshot without implying a write commit.
        db.conn.rollback()
        return response

    @app.route("/api/folders")
    def api_folders():
        db = _get_db()
        # Browse pins its destructive Remove action to the workspace the
        # tree was rendered against. Fetching the tree and the active
        # workspace ID in two independent requests would let a cross-tab
        # workspace switch pair A's rows with B's id, so opt-in callers
        # get both from a single read snapshot instead of following up
        # with /api/workspaces/active (Codex review r3799038685). The
        # legacy array response is preserved for every other caller.
        include_workspace = request.args.get("with_workspace") in ("1", "true")
        if include_workspace:
            db.conn.execute("BEGIN")
            try:
                folders = [dict(f) for f in db.get_folder_tree()]
                active_workspace_id = db._ws_id()
            finally:
                db.conn.rollback()
            return jsonify(
                {"folders": folders, "active_workspace_id": active_workspace_id}
            )
        folders = db.get_folder_tree()
        return jsonify([dict(f) for f in folders])

    @app.route("/api/photos/extensions")
    def api_photos_extensions():
        """Return the distinct lowercased file extensions present in the
        active workspace, sorted.

        The smart-collection rule editor uses this to populate the value
        dropdown for the Extension field. Free-text was silent-failure
        prone — typing ``JPG`` matched nothing because rows are stored as
        ``.jpg``.
        """
        db = _get_db()
        return jsonify(db.get_workspace_extensions())

    @app.route("/api/folders/missing")
    def api_folders_missing():
        db = _get_db()
        # Keep the rows and their monotonic observation marker on one read
        # snapshot so clients can compare this response with /api/browse/init
        # independent of network delivery order.
        db.conn.execute("BEGIN")
        missing = db.get_missing_folders()
        health_version = db.get_folder_health_version()
        response = jsonify([dict(f) for f in missing])
        response.headers["X-Vireo-Folder-Health-Version"] = str(health_version)
        db.conn.rollback()
        return response

    _MISSING_ORIGINALS_STALE_SECONDS = 30 * 60
    _MISSING_ORIGINALS_BACKOFF_SECONDS = 30 * 60
    _MISSING_ORIGINALS_HEAVY_JOB_TYPES = {
        "scan",
        "pipeline",
        "thumbnails",
        "previews",
        "move-photos",
        "move-folder",
        "sync",
        "classify",
        "precompute-embeddings",
        "cull",
        "develop",
        "extract-masks",
        "regroup",
        "import",
        "import-full",
        "import-in-place",
        "ingest",
        "import-photos",
        "batch-delete",
        "duplicate-scan",
        "offline-cache",
        # Navbar's new-images probe walks the same folders a missing-originals
        # scan would; letting them run concurrently can double the filesystem
        # load on slow NAS/SMB libraries.
        "new_images_walk",
        # Folder-scoped and workspace-wide missing-originals scans have
        # distinct cache keys, so the same-key in-flight coalescing does
        # not catch a workspace scan started while a folder scan is
        # running (or vice versa). Treat any in-flight
        # missing_originals_scan as heavy work so automatic reruns
        # don't kick off a second filesystem walk over the same tree.
        "missing_originals_scan",
        # audit.verify_hashes walks every workspace source file and
        # hashes readable ones — the same NAS/SMB trees a Missing
        # Originals scan touches. Letting the 30-minute automatic
        # missing-originals timer fire during verification would
        # double the I/O on those slow volumes.
        "verify-hashes",
        # Card cleanup reads only archive copies that match one card, but
        # those reads still hit the same NAS/SMB trees.
        "card-cleanup-verify",
    }

    def _utc_iso_now():
        return datetime.now(UTC).isoformat().replace("+00:00", "Z")

    def _parse_missing_originals_folder_id(db):
        folder_id = request.args.get("folder_id")
        if request.is_json:
            body = request.get_json(silent=True) or {}
            if "folder_id" in body:
                folder_id = body.get("folder_id")
        if folder_id in (None, ""):
            return None
        try:
            folder_id = int(folder_id)
        except (TypeError, ValueError):
            raise ValueError("folder_id must be an integer") from None
        linked = db.conn.execute(
            "SELECT 1 FROM workspace_folders WHERE workspace_id = ? AND folder_id = ?",
            (db._active_workspace_id, folder_id),
        ).fetchone()
        if not linked:
            raise LookupError("folder not found")
        return folder_id

    def _missing_originals_key(db, folder_id):
        return (db._db_path, db._active_workspace_id, folder_id)

    def _missing_originals_payload(db, folder_id):
        key = _missing_originals_key(db, folder_id)
        now = time.monotonic()
        with app._missing_originals_lock:
            entry = app._missing_originals_cache.get(key)
            inflight = app._missing_originals_inflight.get(key)
            err = app._missing_originals_errors.get(key)
            # An error recorded after the last cached scan means a later
            # refresh failed. Returning the pre-refresh photo list as a
            # fresh "ready" result would hide the failure — and worse,
            # let the user delete rows whose originals may have been
            # restored between scans. When a scan is in flight the UI
            # already shows "pending", so still surface the stale
            # entry then; otherwise prefer the error state.
            cache_superseded_by_error = (
                entry is not None
                and err is not None
                and not inflight
                and err["set_at"] > entry["set_at"]
            )
            if entry is not None and not cache_superseded_by_error:
                status = "pending" if inflight else "ready"
                photos = entry["photos"]
                checked_at = entry["checked_at"]
                stale = now - entry["set_at"] > _MISSING_ORIGINALS_STALE_SECONDS
                error = None
            elif inflight:
                status = "pending"
                photos = []
                checked_at = None
                stale = False
                error = None
            elif err is not None:
                status = "error"
                photos = []
                checked_at = err["checked_at"]
                stale = False
                error = err["error"]
            else:
                status = "not_ready"
                photos = []
                checked_at = None
                stale = False
                error = None
            backoff_seconds = 0
            if err is not None:
                backoff_seconds = max(0, int(err["backoff_until"] - now))
            return {
                "status": status,
                "pending": bool(inflight),
                "checked_at": checked_at,
                "stale": stale,
                "error": error,
                "job_id": inflight if isinstance(inflight, str) else None,
                "photos": photos,
                "backoff_seconds": backoff_seconds,
                "workspace_id": db._active_workspace_id,
                "folder_id": folder_id,
            }

    def _build_missing_originals_rows(
        db,
        folder_id=None,
        progress_callback=None,
        cancel_callback=None,
    ):
        thumb_dir = app.config["THUMB_CACHE_DIR"]
        vireo_dir = os.path.dirname(thumb_dir)
        preview_dir = os.path.join(vireo_dir, "previews")
        working_dir = os.path.join(vireo_dir, "working")

        def check_cancelled():
            if cancel_callback is not None and cancel_callback():
                raise MissingPhotosCancelled("missing originals scan cancelled")

        # Index preview cache once. The endpoint is polled from the navbar,
        # so per-photo `glob(preview_dir, f"{pid}_*.jpg")` was O(missing ×
        # cache_size) readdirs per request. Build {pid} from a single
        # listdir and check the set in O(1) per row.
        preview_pids: set[int] = set()
        try:
            check_cancelled()
            with os.scandir(preview_dir) as it:
                for entry in it:
                    check_cancelled()
                    name = entry.name
                    # Match `{id}.jpg` (legacy full preview) or `{id}_{size}.jpg`
                    # (sized variant). Anything else is not part of the per-photo
                    # cache and should be ignored.
                    if not name.endswith(".jpg"):
                        continue
                    head = name[:-4].split("_", 1)[0]
                    if head.isdigit():
                        preview_pids.add(int(head))
        except FileNotFoundError:
            pass  # cache dir hasn't been created yet — no previews

        out = []
        for row in db.get_missing_photos(
            folder_id=folder_id,
            progress_callback=progress_callback,
            cancel_callback=cancel_callback,
        ):
            check_cancelled()
            pid = row["id"]
            src = os.path.join(row["folder_path"], row["filename"])
            stem, _ext = os.path.splitext(src)
            # Working copy: the DB path wins when set, but legacy rows from
            # before working_copy_path was tracked can still have a file at
            # the default <vireo>/working/<id>.jpg location — and the batch
            # delete path cleans that up regardless of the DB column. If we
            # only consulted the column the badge would lie about what's
            # about to be removed.
            wc_rel = row["working_copy_path"]
            default_wc = os.path.join(working_dir, f"{pid}.jpg")
            if wc_rel:
                has_wc = os.path.isfile(os.path.join(vireo_dir, wc_rel))
            else:
                has_wc = os.path.isfile(default_wc)
            out.append({
                "id": pid,
                "filename": row["filename"],
                "extension": row["extension"],
                "folder_id": row["folder_id"],
                "folder_path": row["folder_path"],
                "timestamp": row["timestamp"],
                "file_size": row["file_size"],
                "has_thumb": os.path.isfile(os.path.join(thumb_dir, f"{pid}.jpg")),
                "has_preview": pid in preview_pids,
                "has_working_copy": has_wc,
                "has_xmp_sidecar": (
                    os.path.isfile(stem + ".xmp")
                    or os.path.isfile(stem + ".XMP")
                    or os.path.isfile(src + ".xmp")
                    or os.path.isfile(src + ".XMP")
                ),
            })
        attach_nested_edit_recipes(db, out)
        return out

    def _missing_originals_heavy_job_active():
        for job in app._job_runner.list_jobs():
            if job.get("status") not in (
                "running", "pausing", "paused", "queued",
            ):
                continue
            if job.get("type") in _MISSING_ORIGINALS_HEAVY_JOB_TYPES:
                return True
        return False

    def _pending_local_workspace_transition(workspace_id, db=None):
        """Return the queued/running local-workspace transition job, or None.

        ``db``: pass an explicit Database when calling off the request
        thread (job threads have no request context); defaults to the
        request-scoped db via ``_get_db()``.
        """
        # ``has_local_workspace`` only observes the ``local_workspaces`` row
        # a stage worker inserts once it actually runs; a stage/sync/discard
        # that has been enqueued but not yet reached that insert would leave
        # the row absent. A scan or move-folder enqueued in that window
        # passes its own guard and then rebases the catalog after the
        # transition worker later claims the workspace, so the folder /
        # workspace_folders / folders rows those jobs write end up outside
        # the manifest and local_workspace_folders. Detecting the pending
        # transition job in the runner queue closes that race at enqueue.
        if workspace_id is None:
            return None
        for job in app._job_runner.list_jobs():
            if job.get("status") not in (
                "queued", "running", "pausing", "paused",
            ):
                continue
            job_type = job.get("type")
            if job_type in LOCAL_WORKSPACE_JOB_TYPES and job.get("workspace_id") == workspace_id:
                return job
            if job_type in LOCAL_FOLDER_JOB_TYPES:
                if job.get("workspace_id") == workspace_id:
                    return job
                config = job.get("config") or {}
                root_ids = (config.get("root_folder_ids") or []) if isinstance(config, dict) else []
                if db is None:
                    db = _get_db()
                if any(
                    workspace_id in workspace_ids_for_folder_tree(db, int(root_id))
                    for root_id in root_ids
                ):
                    return job
        return None

    def _invalidate_missing_originals_cache(workspace_ids=None):
        """Drop cached Missing Originals results for this app's database.

        Photos are shared across workspaces (a folder can be linked into
        more than one), so a photo-row removal must clear every
        workspace cache that could still list it — scoping to the
        active workspace lets other workspaces keep serving stale
        ready payloads until their next scan.

        ``workspace_ids`` narrows the invalidation to those workspace
        ids. Use it on workspace create/delete to clear entries that
        could otherwise be served to a later workspace that reuses a
        SQLite rowid.
        """
        ws_filter = None if workspace_ids is None else {int(w) for w in workspace_ids}
        with app._missing_originals_lock:
            for store in (
                app._missing_originals_cache,
                app._missing_originals_errors,
            ):
                for key in list(store.keys()):
                    if key[0] != db_path:
                        continue
                    if ws_filter is not None and key[1] not in ws_filter:
                        continue
                    store.pop(key, None)
            # Bump generation for every in-flight scan under this DB so
            # its completion path refuses to write its stale
            # pre-invalidation snapshot back into the cache.
            for key in list(app._missing_originals_inflight.keys()):
                if key[0] != db_path:
                    continue
                if ws_filter is not None and key[1] not in ws_filter:
                    continue
                app._missing_originals_generation[key] = (
                    app._missing_originals_generation.get(key, 0) + 1
                )

    def _start_missing_originals_scan(db, folder_id=None, automatic=False):
        key = _missing_originals_key(db, folder_id)
        scan_started_at = time.monotonic()
        now = scan_started_at
        token = object()
        suppressed_reason = None
        reuse_existing = False
        fresh_cache = False
        with app._missing_originals_lock:
            inflight = app._missing_originals_inflight.get(key)
            if inflight:
                reuse_existing = True
            entry = app._missing_originals_cache.get(key)
            # Gate on when the last scan STARTED, not when it finished. The
            # navbar re-arms its 30-minute automatic timer from POST time,
            # so a scan that takes real wall-clock time to walk the disk
            # leaves ``set_at`` well under the threshold when the next tick
            # arrives — every other automatic scan would otherwise be
            # skipped, and deletions could stay undiscovered for nearly an
            # hour. Legacy entries without ``started_at`` fall back to
            # ``set_at``.
            if (
                not reuse_existing
                and automatic
                and entry is not None
                and now - entry.get("started_at", entry["set_at"])
                < _MISSING_ORIGINALS_STALE_SECONDS
            ):
                fresh_cache = True
            err = app._missing_originals_errors.get(key)
            if (
                not reuse_existing
                and not fresh_cache
                and automatic
                and err is not None
                and now < err["backoff_until"]
            ):
                suppressed_reason = "backoff"
        if reuse_existing:
            return _missing_originals_payload(db, folder_id)
        if fresh_cache:
            return _missing_originals_payload(db, folder_id)
        if automatic and suppressed_reason is None and _missing_originals_heavy_job_active():
            suppressed_reason = "heavy_job_active"
        if suppressed_reason is not None:
            payload = _missing_originals_payload(db, folder_id)
            payload["suppressed"] = True
            payload["reason"] = suppressed_reason
            if suppressed_reason == "heavy_job_active":
                payload["status"] = "skipped"
            return payload
        scan_generation = 0
        with app._missing_originals_lock:
            inflight = app._missing_originals_inflight.get(key)
            if inflight:
                reuse_existing = True
            else:
                app._missing_originals_inflight[key] = token
                scan_generation = app._missing_originals_generation.get(key, 0)
        if reuse_existing:
            return _missing_originals_payload(db, folder_id)

        runner = app._job_runner
        ws_id = db._active_workspace_id
        db_file = db._db_path
        scope_label = "workspace" if folder_id is None else f"folder #{folder_id}"

        def work(job):
            thread_db = None
            try:
                thread_db = Database(db_file)
                if ws_id is not None:
                    thread_db.set_active_workspace(ws_id)

                def progress(payload):
                    current = int(payload.get("photos_considered") or 0)
                    total = int(payload.get("total_photos") or 0)
                    missing_found = int(payload.get("missing_found") or 0)
                    folders_checked = int(payload.get("folders_checked") or 0)
                    current_folder = payload.get("current_folder") or ""
                    job["progress"]["current"] = current
                    job["progress"]["total"] = total
                    job["progress"]["current_file"] = current_folder
                    phase = (
                        f"{folders_checked:,} folders checked, "
                        f"{current:,} photos considered, "
                        f"{missing_found:,} missing"
                    )
                    runner.push_event(job["id"], "progress", {
                        "current": current,
                        "total": total,
                        "current_file": current_folder,
                        "folders_checked": folders_checked,
                        "missing_found": missing_found,
                        "phase": phase,
                    })

                def cancel_check():
                    return runner.is_cancelled(job["id"])

                photos = _build_missing_originals_rows(
                    thread_db,
                    folder_id=folder_id,
                    progress_callback=progress,
                    cancel_callback=cancel_check,
                )
                if cancel_check():
                    return {"cancelled": True, "scope": scope_label}
                checked_at = _utc_iso_now()
                stale = False
                with app._missing_originals_lock:
                    current_gen = app._missing_originals_generation.get(key, 0)
                    if cancel_check():
                        return {"cancelled": True, "scope": scope_label}
                    if current_gen != scan_generation:
                        # A batch delete (or other invalidation) fired
                        # while this scan was walking the disk. Its photo
                        # list reflects the pre-delete library, so writing
                        # it back would resurrect just-removed photos in
                        # the banner. Drop the result and let the next
                        # scan recompute.
                        stale = True
                    else:
                        app._missing_originals_cache[key] = {
                            "photos": photos,
                            "checked_at": checked_at,
                            "set_at": time.monotonic(),
                            "started_at": scan_started_at,
                        }
                        app._missing_originals_errors.pop(key, None)
                return {
                    "missing_count": len(photos),
                    "checked_at": checked_at,
                    "scope": scope_label,
                    "stale": stale,
                }
            except MissingPhotosCancelled:
                raise
            except Exception as exc:
                checked_at = _utc_iso_now()
                with app._missing_originals_lock:
                    current_gen = app._missing_originals_generation.get(key, 0)
                    if current_gen == scan_generation:
                        app._missing_originals_errors[key] = {
                            "error": str(exc) or exc.__class__.__name__,
                            "checked_at": checked_at,
                            "set_at": time.monotonic(),
                            "backoff_until": (
                                time.monotonic()
                                + _MISSING_ORIGINALS_BACKOFF_SECONDS
                            ),
                        }
                raise
            finally:
                if thread_db is not None:
                    thread_db.close()
                with app._missing_originals_lock:
                    if app._missing_originals_inflight.get(key) in (
                        token,
                        job["id"],
                    ):
                        app._missing_originals_inflight.pop(key, None)

        try:
            job_id = runner.start(
                "missing_originals_scan",
                work,
                workspace_id=ws_id,
                config={"scope": scope_label, "folder_id": folder_id},
                ephemeral=False,
                counts_for_badge=True,
            )
        except Exception:
            with app._missing_originals_lock:
                if app._missing_originals_inflight.get(key) is token:
                    app._missing_originals_inflight.pop(key, None)
            raise

        with app._missing_originals_lock:
            if app._missing_originals_inflight.get(key) is token:
                app._missing_originals_inflight[key] = job_id
        payload = _missing_originals_payload(db, folder_id)
        if payload.get("status") != "ready":
            payload["job_id"] = job_id
            payload["pending"] = True
            payload["status"] = "pending"
        return payload

    @app.route("/api/photos/missing")
    def api_photos_missing():
        """Return cached Missing Originals scan status without filesystem work."""
        db = _get_db()
        try:
            folder_id = _parse_missing_originals_folder_id(db)
        except ValueError as exc:
            return json_error(str(exc))
        except LookupError:
            return json_error("folder not found", 404)
        return jsonify(_missing_originals_payload(db, folder_id))

    @app.route("/api/photos/missing/check", methods=["POST"])
    def api_photos_missing_check():
        """Start or reuse a background Missing Originals scan."""
        db = _get_db()
        try:
            folder_id = _parse_missing_originals_folder_id(db)
        except ValueError as exc:
            return json_error(str(exc))
        except LookupError:
            return json_error("folder not found", 404)
        body = request.get_json(silent=True) or {}
        automatic = bool(body.get("automatic"))
        payload = _start_missing_originals_scan(
            db,
            folder_id=folder_id,
            automatic=automatic,
        )
        status_code = 202 if payload.get("pending") else 200
        return jsonify(payload), status_code

    @app.route("/api/folders/check-health", methods=["POST"])
    def api_folders_check_health():
        db = _get_db()
        # ``check_folder_health()`` scans every folder in the DB and returns a
        # global change count, but the client needs to know whether the
        # ACTIVE workspace's missing set changed. Snapshot the workspace-
        # scoped missing IDs before and after so the client's null-baseline
        # fallback in loadMissingFolders() (fired when the modal opens before
        # any poll seeds the snapshot) can distinguish a cross-workspace
        # flip — which must NOT reset the active Browse — from a real
        # active-workspace transition that still needs to notify Browse
        # (Codex review r3686191131).
        ws_missing_before = {f["id"] for f in db.get_missing_folders()}
        changed = db.check_folder_health()
        # A folder flipping ok→missing turns every one of its photos into a
        # ghost, and missing→ok resurrects them. Either transition would
        # otherwise be masked by a ready /api/photos/missing cache until the
        # next full scan.
        if changed:
            _invalidate_missing_originals_cache()
        db.conn.execute("BEGIN")
        missing = db.get_missing_folders()
        ws_missing_after = {f["id"] for f in missing}
        health_version = db.get_folder_health_version()
        response = jsonify({
            "changed": changed,
            "workspace_changed": ws_missing_before != ws_missing_after,
            "missing": [dict(f) for f in missing],
            "folder_health_version": health_version,
        })
        db.conn.rollback()
        return response

    @app.route("/api/photos/missing/delete-sidecars", methods=["POST"])
    def api_photos_missing_delete_sidecars():
        """Delete leftover .xmp sidecar files for photos whose original is gone.

        Body: ``{"photo_ids": [int, ...]}``.

        IDs are resolved server-side against the active workspace — the
        client never names paths directly. Earlier drafts accepted
        ``(folder_path, filename)`` from the body and were usable to
        unlink any ``.xmp`` on disk as long as the paired non-xmp path
        was absent. Now we only touch sidecars whose photo row is in
        the active workspace AND whose source is verified missing.
        """
        body = request.get_json(silent=True) or {}
        photo_ids = body.get("photo_ids") or []
        if not isinstance(photo_ids, list):
            return json_error("photo_ids must be a list")

        db = _get_db()
        ws_id = db._active_workspace_id
        deleted = 0
        skipped = 0
        folder_online_cache = {}
        for raw_id in photo_ids:
            try:
                pid = int(raw_id)
            except (TypeError, ValueError):
                skipped += 1
                continue
            row = db.conn.execute(
                """SELECT p.filename, f.path AS folder_path
                   FROM photos p
                   JOIN folders f ON p.folder_id = f.id
                   JOIN workspace_folders wf ON wf.folder_id = f.id
                   WHERE p.id = ? AND wf.workspace_id = ?""",
                (pid, ws_id),
            ).fetchone()
            if not row:
                skipped += 1
                continue
            folder_path = row["folder_path"]
            folder_online = folder_online_cache.get(folder_path)
            if folder_online is None:
                # Match /api/photos/missing/remove: a path that stats as a
                # directory but can't be enumerated (NAS/share ACL denial,
                # missing search permission) makes ``os.path.exists(src)``
                # unreliable for every child, so we'd otherwise unlink
                # sidecars belonging to originals we couldn't actually
                # verify were missing.
                folder_online = False
                if os.path.isdir(folder_path):
                    try:
                        with os.scandir(folder_path):
                            folder_online = True
                    except OSError:
                        folder_online = False
                folder_online_cache[folder_path] = folder_online
            if not folder_online:
                # Folder is currently unreachable — we can't tell whether
                # the original was restored before the mount went offline,
                # so skip the sidecar (a valid original could have a
                # matching .xmp we would wrongly delete once the volume
                # comes back).
                skipped += 1
                continue
            src = os.path.join(folder_path, row["filename"])
            if os.path.exists(src):
                # Original came back — refuse to touch the sidecar.
                skipped += 1
                continue
            stem, _ = os.path.splitext(src)
            removed_one = False
            for candidate in (stem + ".xmp", stem + ".XMP",
                              src + ".xmp", src + ".XMP"):
                if os.path.isfile(candidate):
                    try:
                        os.remove(candidate)
                        removed_one = True
                    except OSError as e:
                        log.warning("Failed to delete sidecar %s: %s", candidate, e)
            if removed_one:
                deleted += 1
            else:
                skipped += 1
        return jsonify({"deleted": deleted, "skipped": skipped})

    @app.route("/api/photos/missing/remove", methods=["POST"])
    def api_photos_missing_remove():
        """Delete Vireo rows for photos whose originals are still gone.

        Body: ``{"photo_ids": [int, ...], "delete_sidecars": bool,
        "mode": "vireo"|"disk"|"disk_permanent"}``.

        A ready ``/api/photos/missing`` cache is served for up to
        ``_MISSING_ORIGINALS_STALE_SECONDS`` (30 min) without a filesystem
        recheck, so a photo whose original came back between the last
        scan and the user clicking Remove would otherwise be deleted
        from Vireo by trusting the cache. This endpoint pre-checks each
        photo's source on disk in the active workspace and only forwards
        the still-missing IDs to the shared batch-delete implementation.
        Sidecar cleanup follows the same guard, so a restored original
        never loses its ``.xmp`` either.

        Response: ``{deleted, restored: [ids], skipped, sidecars_deleted,
        sidecars_skipped, mode}``. ``restored`` lets the client show which
        photos were saved from the cache-driven delete so the modal can
        surface them (e.g. via toast) instead of silently discarding the
        request.
        """
        body = request.get_json(silent=True) or {}
        photo_ids = body.get("photo_ids") or []
        if not isinstance(photo_ids, list):
            return json_error("photo_ids must be a list")
        delete_sidecars = bool(body.get("delete_sidecars"))
        mode = body.get("mode", "vireo")
        if mode not in ("vireo", "disk", "disk_permanent"):
            return json_error(
                "mode must be 'vireo', 'disk', or 'disk_permanent'"
            )

        db = _get_db()
        ws_id = db._active_workspace_id
        confirmed_ids = []
        restored_ids = []
        folder_offline_ids = []
        skipped = 0
        sidecar_targets = []
        folder_online_cache = {}

        def folder_accessible(folder_path):
            cached = folder_online_cache.get(folder_path)
            if cached is not None:
                return cached
            accessible = False
            if os.path.isdir(folder_path):
                try:
                    with os.scandir(folder_path):
                        accessible = True
                except OSError:
                    accessible = False
            folder_online_cache[folder_path] = accessible
            return accessible

        for raw_id in photo_ids:
            try:
                pid = int(raw_id)
            except (TypeError, ValueError):
                skipped += 1
                continue
            row = db.conn.execute(
                """SELECT p.filename, f.path AS folder_path
                   FROM photos p
                   JOIN folders f ON p.folder_id = f.id
                   JOIN workspace_folders wf ON wf.folder_id = f.id
                   WHERE p.id = ? AND wf.workspace_id = ?""",
                (pid, ws_id),
            ).fetchone()
            if not row:
                skipped += 1
                continue
            folder_path = row["folder_path"]
            if not folder_accessible(folder_path):
                # The parent folder/NAS mount is currently unreachable, so
                # ``os.path.exists(src)`` would return False for every row
                # regardless of whether the original was restored before
                # the volume went offline. Deleting under that ambiguity
                # would remove valid Vireo rows; leave the decision for a
                # later scan (once folder health flips or the volume comes
                # back) instead.
                folder_offline_ids.append(pid)
                continue
            src = os.path.join(folder_path, row["filename"])
            if os.path.exists(src):
                # Original is back on disk — the cached "missing" verdict
                # was stale. Keep the Vireo row (and its sidecar).
                restored_ids.append(pid)
                continue
            confirmed_ids.append(pid)
            if delete_sidecars:
                sidecar_targets.append(src)

        sidecars_deleted = 0
        sidecars_skipped = 0
        if delete_sidecars:
            for src in sidecar_targets:
                stem, _ = os.path.splitext(src)
                removed_one = False
                for candidate in (stem + ".xmp", stem + ".XMP",
                                  src + ".xmp", src + ".XMP"):
                    if os.path.isfile(candidate):
                        try:
                            os.remove(candidate)
                            removed_one = True
                        except OSError as e:
                            log.warning(
                                "Failed to delete sidecar %s: %s", candidate, e
                            )
                if removed_one:
                    sidecars_deleted += 1
                else:
                    sidecars_skipped += 1

        deleted_count = 0
        if confirmed_ids:
            try:
                result = _run_batch_delete(
                    db, confirmed_ids, mode, include_companions=False,
                )
            except ValueError as exc:
                return json_error(str(exc))
            deleted_count = int(result.get("deleted") or 0)
            if deleted_count:
                _invalidate_missing_originals_cache()

        # A cache invalidation is still worth doing when everything came
        # back online: the ready payload we just refused to trust for
        # deletion is also the one the banner will keep serving until the
        # next scan. Dropping it now forces a fresh check the next time
        # the banner/modal asks, so the restored photos stop appearing
        # as ghosts. Do the same when we deferred rows because a folder
        # was offline: the cache is unreliable evidence for those IDs and
        # the next scan (or health flip) needs to replace it.
        if deleted_count == 0 and (restored_ids or folder_offline_ids):
            _invalidate_missing_originals_cache()

        return jsonify({
            "deleted": deleted_count,
            "restored": restored_ids,
            "folder_offline": folder_offline_ids,
            "skipped": skipped,
            "sidecars_deleted": sidecars_deleted,
            "sidecars_skipped": sidecars_skipped,
            "mode": mode,
        })

    @app.route("/api/folders/<int:folder_id>", methods=["GET"])
    def api_folder_get(folder_id):
        """Return a single folder's id, name, and path.

        Powers the folder-tree context menu's "Copy Path" action. A lean
        response on purpose: callers that want the richer tree data already
        have /api/folders for that. Scoped to the active workspace so
        absolute paths from folders hidden in this workspace don't leak.
        """
        db = _get_db()
        folder = db.get_folder(folder_id)
        if not folder:
            return json_error("folder not found", 404)
        linked = db.conn.execute(
            "SELECT 1 FROM workspace_folders WHERE workspace_id = ? AND folder_id = ?",
            (db._active_workspace_id, folder_id),
        ).fetchone()
        if not linked:
            return json_error("folder not found", 404)
        return jsonify({
            "id": folder["id"],
            "name": folder["name"],
            "path": folder["path"],
        })

    @app.route("/api/folders/<int:folder_id>/workspaces", methods=["GET"])
    def api_folder_workspaces(folder_id):
        """List workspaces in which a Browse-visible folder appears."""
        db = _get_db()
        folder = db.get_folder(folder_id)
        if not folder:
            return json_error("folder not found", 404)

        # Match the folder-detail endpoint's active-workspace boundary while
        # also recognizing read-only inheritance from a recursive root. This
        # prevents callers from using hidden folder IDs to enumerate workspace
        # names without mutating the membership table during a GET.
        folder_workspaces = db.get_folder_workspaces(folder_id)
        if not any(
            workspace["id"] == db._active_workspace_id
            for workspace in folder_workspaces
        ):
            return json_error("folder not found", 404)

        workspaces = []
        for workspace in folder_workspaces:
            workspaces.append({
                "id": workspace["id"],
                "name": workspace["name"],
                "is_active": workspace["id"] == db._active_workspace_id,
                "is_root": bool(workspace["is_root"]),
            })
        return jsonify({
            "folder": {
                "id": folder["id"],
                "name": folder["name"],
                "path": folder["path"],
            },
            "workspaces": workspaces,
        })

    @app.route("/api/folders/<int:folder_id>/relocate", methods=["POST"])
    def api_folder_relocate(folder_id):
        db = _get_db()
        body = request.get_json(silent=True) or {}
        new_path = body.get("path", "")
        if not new_path:
            return json_error("path is required")
        if not os.path.isdir(new_path):
            return json_error("path does not exist or is not a directory")

        # Relocating a folder that a local workspace has rebased would leave
        # local_workspace_folders and the manifest pointing at a path this
        # route just moved out from under them, so a later sync/discard could
        # not restore the catalog to the source layout. The guard and the
        # subsequent write must both run under stage_boundary_lock so a stage
        # claim cannot commit between them.
        with stage_boundary_lock():
            local_root_id = local_root_for_folder(db, folder_id)
            if local_root_id is not None:
                return json_error(
                    "Cannot relocate this folder while it has a shared local copy. "
                    "Sync or discard the local copy from any linked workspace first.",
                    409,
                )
            # Staging a descendant rebases its folders.path under local-folders/,
            # so a folders.path subtree scan (as db.relocate_folder does) no
            # longer sees it — while local_folder_mappings.source_path still
            # points at the pre-relocation location. Without this check the
            # relocate would rewrite the ancestor while the manifest keeps
            # pointing at the old descendant path, so a later sync/discard
            # could not restore or publish to the new location.
            descendant_root_id = local_root_under_folder(db, folder_id)
            if descendant_root_id is not None:
                return json_error(
                    "Cannot relocate this folder while a subfolder has a shared local copy. "
                    "Sync or discard the local copy from any linked workspace first.",
                    409,
                )
            staged, owner_ws = folder_has_local_workspace(db, folder_id)
            if staged:
                return json_error(
                    f"Cannot relocate this folder — workspace {owner_ws} has it staged locally. "
                    "Switch to that workspace and sync or discard the local copy first.",
                    409,
                )

            # Capture the old path before the DB rewrite so we can rebase the
            # corresponding darktable output subdir on disk. Developed outputs
            # are nested under developed_folder_key(folder_path), so a path
            # change invalidates the old key and would silently regress export
            # to RAW until the user re-developed.
            old_row = db.conn.execute(
                "SELECT path, status FROM folders WHERE id = ?", (folder_id,)
            ).fetchone()
            old_path = old_row["path"] if old_row else ""

            try:
                cascaded = db.relocate_folder(folder_id, new_path)
            except ValueError as e:
                if old_row and old_row["status"] == "missing":
                    current_row = db.conn.execute(
                        "SELECT status FROM folders WHERE id = ?", (folder_id,)
                    ).fetchone()
                    if current_row and current_row["status"] == "ok":
                        _invalidate_missing_originals_cache()
                return json_error(str(e), 409)

        # Relocation rewrites folders.path (and can merge/delete rows via the
        # missing→existing branch). A ready /api/photos/missing cache would
        # otherwise keep offering the pre-relocation ghost rows for removal
        # even though the originals just came back online at the new path.
        _invalidate_missing_originals_cache()

        import config as cfg
        from export import relocate_developed_dir
        effective_cfg = db.get_effective_config(cfg.load())
        developed_dir = effective_cfg.get("darktable_output_dir", "") or ""
        if developed_dir and old_path:
            relocate_developed_dir(developed_dir, old_path, new_path)
            for child in cascaded:
                relocate_developed_dir(
                    developed_dir, child["old_path"], child["new_path"]
                )
        return jsonify({
            "status": "ok",
            "cascaded": cascaded,
        })

    @app.route("/api/folders/<int:folder_id>", methods=["DELETE"])
    def api_folder_delete(folder_id):
        db = _get_db()
        # Deleting a folder that a local workspace has rebased removes the
        # folders row that local_workspace_folders and the manifest depend on,
        # so a later sync/discard would be unable to restore the catalog. The
        # guard and delete run under stage_boundary_lock so a stage claim
        # cannot commit between them; the local_workspace_folders FK to
        # folders(id) ON DELETE CASCADE is the final safety net.
        with stage_boundary_lock():
            local_root_id = local_root_for_folder(db, folder_id)
            if local_root_id is not None:
                return json_error(
                    "Cannot delete this folder while it has a shared local copy. "
                    "Sync or discard the local copy from any linked workspace first.",
                    409,
                )
            descendant_root_id = local_root_under_folder(db, folder_id)
            if descendant_root_id is not None:
                return json_error(
                    "Cannot delete this folder while a subfolder has a shared local copy. "
                    "Sync or discard the local copy from any linked workspace first.",
                    409,
                )
            staged, owner_ws = folder_has_local_workspace(db, folder_id)
            if staged:
                return json_error(
                    f"Cannot delete this folder — workspace {owner_ws} has it staged locally. "
                    "Switch to that workspace and sync or discard the local copy first.",
                    409,
                )
            result = db.delete_folder(folder_id)
        # Clean up cached files alongside the cascaded photo rows so preview
        # files don't get orphaned on disk (untracked by preview_cache).
        _cleanup_cached_files_for_deleted_photos(result.get("files", []))
        # The cascaded row deletion here is the same shape as any other
        # photo-removal path: without invalidation, a ready
        # /api/photos/missing cache could keep listing ghosts from the
        # now-deleted folder (offered up for removal a second time in
        # the modal) until the next scan runs.
        _invalidate_missing_originals_cache()
        # Don't leak the internal file list to the API response — keep the
        # shape callers expect.
        return jsonify({"deleted_photos": result["deleted_photos"]})

    @app.route("/api/photos")
    def api_photos():
        import config as cfg
        db = _get_db()
        page = request.args.get("page", 1, type=int)
        default_per_page = cfg.load().get("photos_per_page", 50)
        per_page = max(1, min(request.args.get("per_page", default_per_page, type=int), _MAX_PER_PAGE))
        sort = request.args.get("sort", "date")
        folder_id = request.args.get("folder_id", None, type=int)
        collection_id = request.args.get("collection_id", None, type=int)
        # Rules-only path: ``db.get_photos``'s collection restriction is
        # built by ``_build_collection_query`` and evaluates ``rules`` alone.
        # ``/api/v1/photos`` aliases this view, so a headless caller that
        # scopes to a visual collection here would silently widen to every
        # metadata match instead of the saved visual result set (Codex
        # review r3621634298).
        err = _reject_visual_collection(db, collection_id)
        if err is not None:
            return err
        rating_min = request.args.get("rating_min", None, type=int)
        date_from = request.args.get("date_from", None)
        date_to = request.args.get("date_to", None)
        keyword = request.args.get("keyword", None)
        keyword_match_case = _request_bool_arg("keyword_match_case")
        keyword_whole_word = _request_bool_arg("keyword_whole_word")
        color_label = request.args.get("color_label", None)
        try:
            flag = _request_flag_filter()
            location_status = _request_location_status_filter()
        except ValueError as e:
            return json_error(str(e), 400)

        try:
            photos = db.get_photos(
                folder_id=folder_id,
                collection_id=collection_id,
                page=page,
                per_page=per_page,
                sort=sort,
                rating_min=rating_min,
                date_from=date_from,
                date_to=date_to,
                keyword=keyword,
                keyword_match_case=keyword_match_case,
                keyword_whole_word=keyword_whole_word,
                color_label=color_label,
                flag=flag,
                location_status=location_status,
            )
        except ValueError as exc:
            return json_error(str(exc), 400)

        # Total count — use count_photos for unfiltered, otherwise use efficient COUNT query
        if not any([folder_id, collection_id, rating_min, date_from, date_to, keyword, color_label, flag, location_status]):
            total = db.count_photos()
        else:
            try:
                total = db.count_filtered_photos(
                    folder_id=folder_id,
                    collection_id=collection_id,
                    rating_min=rating_min,
                    date_from=date_from,
                    date_to=date_to,
                    keyword=keyword,
                    keyword_match_case=keyword_match_case,
                    keyword_whole_word=keyword_whole_word,
                    color_label=color_label,
                    flag=flag,
                    location_status=location_status,
                )
            except ValueError as exc:
                return json_error(str(exc), 400)

        photo_dicts = [dict(p) for p in photos]
        attach_location_statuses(db, photo_dicts)
        attach_species(db, photo_dicts)
        attach_species_representatives(db, photo_dicts)
        attach_detections(db, photo_dicts)
        attach_edit_recipes(db, photo_dicts)

        return jsonify(
            {
                "photos": photo_dicts,
                "total": total,
                "page": page,
                "per_page": per_page,
            }
        )

    def _inject_active_visual_model(rules):
        """Fill in the active visual model on ``has_visual_index`` leaves
        that don't name one.

        ``/api/filters/fields`` advertises ``Has visual index`` as a plain
        boolean field, so the UI-emitted rule has no ``model`` key. The
        rule engine's fallback then matches any ``photo_embeddings`` row,
        so a photo with only stale embeddings from a previously-active
        model satisfies ``has_visual_index is true`` even though visual
        search (which only loads embeddings for the active model — see
        ``api_photo_text_search``) can't use it. Inject the current active
        model here so the filter and visual search agree on what "has an
        index" means; smart-collection storage paths (POST/PUT
        ``/api/collections``) also normalize before persisting so a
        collection's saved rules match what the preview counter showed at
        save time (Codex review r3621749904) — otherwise the sidebar
        count and the reopened result set silently diverge from the
        preview when embeddings from multiple models exist.

        When no active model is configured (fresh library, or every
        installed model was removed while cached embeddings remain), the
        UI-emitted rule must fail closed instead of falling through to
        "any embedding row" — otherwise ``/api/photos/query`` would
        report photos as visually indexed while ``/api/photos/search``
        returns ``no_model``. Inject a sentinel model name that can never
        match a stored ``photo_embeddings.model`` value, so
        ``has_visual_index is true`` matches nothing and
        ``has_visual_index is false`` matches everything — both correct
        for "there is no usable visual index right now".
        """
        try:
            from models import get_active_model
            active = get_active_model()
        except Exception:
            active = None
        model_name = active.get("name") if active else None
        injected_model = model_name or "__no_active_visual_model__"

        def _walk(node):
            if isinstance(node, dict):
                if "rules" in node and "field" not in node:
                    inner = node.get("rules")
                    # Malformed group (e.g. ``{"mode":"all","rules":null}``):
                    # leave it untouched so ``Database._validate_node`` can
                    # raise a ``ValueError`` that the route turns into a 400.
                    # Iterating ``None`` here would raise ``TypeError`` and
                    # bypass the 400 handler.
                    if not isinstance(inner, list):
                        return node
                    return {**node, "rules": [_walk(r) for r in inner]}
                if node.get("field") == "has_visual_index" and "model" not in node:
                    return {**node, "model": injected_model}
                return node
            if isinstance(node, list):
                return [_walk(r) for r in node]
            return node

        return _walk(rules)

    @app.route("/api/photos/query", methods=["POST"])
    def api_photos_query():
        """Universal-filter photo query: a smart-collection rule tree plus
        sort and paging. Response shape matches /api/photos so pages can
        switch fetch paths without re-plumbing their renderers.

        Design: docs/plans/2026-07-19-universal-filters-design.md.
        """
        db = _get_db()
        payload = request.get_json(silent=True)
        if payload is None or not isinstance(payload, dict):
            return json_error("request body must be a JSON object", 400)
        rules = payload.get("rules")
        if rules is None:
            rules = []
        page = payload.get("page", 1)
        per_page = payload.get("per_page", 50)
        sort = payload.get("sort", "date")
        stacks = payload.get("stacks", False)
        if not isinstance(page, int) or isinstance(page, bool) or page < 1:
            return json_error("page must be a positive integer", 400)
        if not isinstance(per_page, int) or isinstance(per_page, bool) or per_page < 1:
            return json_error("per_page must be a positive integer", 400)
        # sort feeds an unhashable-unsafe ``sort_map.get(sort, ...)`` in
        # ``query_photos``; a JSON array/object here would raise TypeError
        # (not ValueError) and bypass the 400 handler below.
        if not isinstance(sort, str):
            return json_error("sort must be a string", 400)
        if not isinstance(stacks, bool):
            return json_error("stacks must be a boolean", 400)
        per_page = min(per_page, _MAX_PER_PAGE)
        collection_id = payload.get("collection_id")
        if collection_id is not None and (
            not isinstance(collection_id, int) or isinstance(collection_id, bool)
        ):
            return json_error("collection_id must be an integer", 400)
        # Rules-only scoping path: ``query_photo_ids`` / ``query_photos`` /
        # ``count_photos_for_rules`` all funnel through
        # ``_append_collection_restriction`` → ``_build_collection_query``,
        # which reads only ``collections.rules``. An API/headless caller
        # posting ``{"collection_id": <visual id>}`` would therefore silently
        # widen to every metadata match instead of the saved visual result
        # set; the Browse reopen path already sends the stored ``rules`` +
        # ``visual`` without relying on ``collection_id`` (Codex review
        # r3621903988).
        err = _reject_visual_collection(db, collection_id)
        if err is not None:
            return err
        folder_id = payload.get("folder_id")
        if folder_id is not None and (
            not isinstance(folder_id, int) or isinstance(folder_id, bool)
        ):
            return json_error("folder_id must be an integer", 400)
        rules = _inject_active_visual_model(rules)
        try:
            visual = _validate_visual_arg(payload.get("visual"))
        except ValueError as exc:
            return json_error(str(exc), 400)

        include_offline = payload.get("include_offline", False)
        include_availability = payload.get("include_availability", False)
        if not isinstance(include_offline, bool):
            return json_error("include_offline must be a boolean", 400)
        if not isinstance(include_availability, bool):
            return json_error("include_availability must be a boolean", 400)
        # Offline rows are display-only. IDs-only responses feed selection
        # and bulk actions, so those remain restricted to actionable photos.
        if payload.get("ids_only"):
            include_offline = False

        visual_info = None
        if visual is not None:
            try:
                visual_info, ordered_ids, sims_by_pid = _resolve_visual(
                    db, rules, visual,
                    collection_id=collection_id, folder_id=folder_id,
                    include_offline_folders=(
                        include_offline or include_availability
                    ),
                )
            except ValueError as exc:
                return json_error(str(exc), 400)
            if ordered_ids is not None:
                # Healthy visual clause: results are the similarity-ranked
                # matches; sort is relevance by design while it is active.
                availability = None
                folder_statuses = None
                if include_offline or include_availability:
                    inventory_ids = ordered_ids
                    folder_statuses = db.get_photo_folder_statuses(inventory_ids)
                    available_ids = [
                        pid for pid in inventory_ids
                        if folder_statuses.get(pid) in ("ok", "partial")
                    ]
                    if not include_offline:
                        ordered_ids = available_ids
                    availability = {
                        "inventory_total": len(inventory_ids),
                        "available_total": len(available_ids),
                        "offline_total": len(inventory_ids) - len(available_ids),
                    }
                if payload.get("ids_only"):
                    if stacks:
                        # Same cover-first flattening the paginated visual
                        # branch below applies, so Select-all-matching
                        # inserts each stack's visible cover ahead of its
                        # hidden members and Best Batch, burst-review,
                        # and export preview start from the visible first
                        # card rather than a hidden burst frame (Codex
                        # P2 on PR #1561).
                        stack_items = db.collapse_browse_stack_photo_ids(
                            ordered_ids,
                        )
                        stacked_ids = []
                        seen_ids = set()
                        for item in stack_items:
                            cover = item["cover_id"]
                            if cover not in seen_ids:
                                stacked_ids.append(cover)
                                seen_ids.add(cover)
                            for member in item["member_ids"]:
                                if member in seen_ids:
                                    continue
                                stacked_ids.append(member)
                                seen_ids.add(member)
                        return jsonify({"ids": stacked_ids,
                                        "total": len(stacked_ids),
                                        "visual": visual_info})
                    return jsonify({"ids": ordered_ids, "total": len(ordered_ids),
                                    "visual": visual_info})
                # Offline members are display-only, so they never join a
                # stack: each one stays its own item and is left out of the
                # duplicate / burst tallies. Same rule the SQL projection
                # applies in ``_browse_stack_query_parts``.
                offline_ids = (
                    [
                        pid for pid in ordered_ids
                        if folder_statuses.get(pid) not in ("ok", "partial")
                    ]
                    if include_offline and folder_statuses is not None
                    else None
                )
                stack_items = (
                    db.collapse_browse_stack_photo_ids(
                        ordered_ids, standalone_ids=offline_ids,
                    )
                    if stacks else None
                )
                logical_ids = (
                    [item["cover_id"] for item in stack_items]
                    if stack_items is not None else ordered_ids
                )
                start = (page - 1) * per_page
                page_ids = logical_ids[start:start + per_page]
                photos_map = db.get_photos_by_ids(page_ids)
                page_stack_items = (
                    stack_items[start:start + per_page]
                    if stack_items is not None else None
                )
                photo_dicts = _prepare_browse_photo_dicts(
                    db,
                    [photos_map[pid] for pid in page_ids if pid in photos_map],
                    stack_items=page_stack_items,
                )
                similarity_by_cover = {
                    item["cover_id"]: max(
                        (
                            sims_by_pid[pid]
                            for pid in item["member_ids"]
                            if pid in sims_by_pid
                        ),
                        default=None,
                    )
                    for item in (page_stack_items or [])
                }
                for entry in photo_dicts:
                    entry["similarity"] = similarity_by_cover.get(
                        entry["id"], sims_by_pid.get(entry["id"]),
                    )
                    if include_offline and folder_statuses is not None:
                        entry["folder_status"] = folder_statuses.get(entry["id"])
                response = {
                    "photos": photo_dicts,
                    "total": len(logical_ids),
                    "page": page,
                    "per_page": per_page,
                    "visual": visual_info,
                }
                if stacks:
                    # Availability totals below are photo counts, so the
                    # underlying (unstacked) total is what they must agree
                    # with — never the stack count.
                    response["underlying_total"] = len(ordered_ids)
                if availability is not None:
                    response.update(availability)
                return jsonify(response)
            # Unhealthy: fall through to metadata-only results with the
            # status attached so the UI can say why — never silently zero.

        if payload.get("ids_only"):
            # Select-all and other bulk flows need the complete matching id
            # set; it must resolve exactly the photos the filtered grid
            # shows, so it shares this endpoint rather than a legacy path.
            # Under ``stacks=true`` emit each stack's cover ahead of its
            # hidden members — matching the collection ``/photo-ids``
            # projection — so Best Batch, burst-review, and export
            # preview start from the visible first card rather than a
            # hidden burst frame (Codex P2 on PR #1561).
            try:
                if stacks:
                    ids = db.query_photo_ids_stacked(
                        rules, sort=sort,
                        collection_id=collection_id, folder_id=folder_id,
                    )
                else:
                    ids = db.query_photo_ids(rules, sort=sort, collection_id=collection_id,
                                             folder_id=folder_id)
            except ValueError as exc:
                return json_error(str(exc), 400)
            payload_out = {"ids": ids, "total": len(ids)}
            if visual_info is not None:
                payload_out["visual"] = visual_info
            return jsonify(payload_out)
        try:
            underlying_total = db.count_photos_for_rules(
                rules,
                collection_id=collection_id,
                folder_id=folder_id,
                include_offline_folders=include_offline,
            )
            if stacks:
                photos = db.query_browse_stacks(
                    rules, sort=sort, page=page, per_page=per_page,
                    collection_id=collection_id, folder_id=folder_id,
                    include_offline_folders=include_offline,
                )
                total = db.count_browse_stacks(
                    rules, collection_id=collection_id, folder_id=folder_id,
                    include_offline_folders=include_offline,
                )
            else:
                photos = db.query_photos(
                    rules, sort=sort, page=page, per_page=per_page,
                    collection_id=collection_id, folder_id=folder_id,
                    include_offline_folders=include_offline,
                )
                total = underlying_total
        except ValueError as exc:
            return json_error(str(exc), 400)

        photo_dicts = _prepare_browse_photo_dicts(db, photos)

        response = {
            "photos": photo_dicts,
            "total": total,
            "page": page,
            "per_page": per_page,
        }
        if stacks:
            response["underlying_total"] = underlying_total
        if include_offline or include_availability:
            # Availability is always reported in photos, never in stacks:
            # the notice reads "N of M photos available", so it has to agree
            # with the sidebar collection count and with ``underlying_total``
            # — ``total`` is the logical item count once Stacks collapses it.
            try:
                inventory_total = (
                    underlying_total
                    if include_offline
                    else db.count_photos_for_rules(
                        rules,
                        collection_id=collection_id,
                        folder_id=folder_id,
                        include_offline_folders=True,
                    )
                )
                available_total = (
                    db.count_photos_for_rules(
                        rules,
                        collection_id=collection_id,
                        folder_id=folder_id,
                    )
                    if include_offline
                    else underlying_total
                )
            except ValueError as exc:
                return json_error(str(exc), 400)
            response.update({
                "inventory_total": inventory_total,
                "available_total": available_total,
                "offline_total": max(0, inventory_total - available_total),
            })
        if visual_info is not None:
            response["visual"] = visual_info
        return jsonify(response)

    @app.route("/api/filters/fields")
    def api_filter_fields():
        """The filter field registry: one source of truth for the UI picker
        (labels, categories, types, operators, enum values, suggest flags).
        """
        return jsonify({"fields": fields_for_api()})

    @app.route("/api/filters/values")
    def api_filter_values():
        """Typeahead values with live counts for a suggest-capable field.

        ``rules`` (JSON, optional) is the active expression minus the rule
        being edited, so counts answer "how many results would I get" under
        the user's other selections — never a global COUNT(*).
        ``folder_id``/``collection_id`` (optional) narrow the count set to
        the page-scope restriction Browse applies to ``/api/photos/query``,
        so a folder- or dashboard-collection-scoped Browse view shows
        typeahead counts that match its visible grid instead of the whole
        workspace.
        """
        db = _get_db()
        field = request.args.get("field", "")
        if field not in SUGGEST_FIELDS:
            return json_error(f"field {field!r} does not support value suggestions", 400)
        raw_rules = request.args.get("rules")
        rules = []
        if raw_rules:
            try:
                rules = json.loads(raw_rules)
            except ValueError:
                return json_error("rules must be valid JSON", 400)
        q = request.args.get("q") or None
        folder_id = request.args.get("folder_id", None, type=int)
        collection_id = request.args.get("collection_id", None, type=int)
        # ``get_filter_field_values`` narrows counts through
        # ``_build_collection_query``, which reads only ``collections.rules``.
        # Without ``visual``, a saved visual collection would silently widen
        # the typeahead counts to every metadata match (Codex review
        # r3622521597).
        err = _reject_visual_collection(db, collection_id)
        if err is not None:
            return err
        # Clamp ``limit`` to a positive bounded range. Werkzeug's ``type=int``
        # cheerfully parses ``?limit=0``/``?limit=-5`` (SQLite treats a
        # negative ``LIMIT`` as "no limit" and returns everything), and
        # ``?limit=999999`` on a large library would load an unbounded
        # suggestions list. Fallback to the 20-default when parsing fails.
        limit_raw = request.args.get("limit", 20, type=int)
        if limit_raw is None:
            limit_raw = 20
        limit = max(1, min(limit_raw, 500))
        rules = _inject_active_visual_model(rules)
        try:
            visual = _request_visual_arg()
            rules, _visual_info = _apply_visual_to_rules(
                db, rules, visual,
                collection_id=collection_id, folder_id=folder_id,
            )
        except ValueError as exc:
            return json_error(str(exc), 400)
        try:
            values = db.get_filter_field_values(
                field, rules=rules, q=q, limit=limit,
                folder_id=folder_id, collection_id=collection_id,
            )
        except ValueError as exc:
            return json_error(str(exc), 400)
        return jsonify({"field": field, "values": values})

    @app.route("/api/photos/ids")
    def api_photo_ids():
        """Return every photo ID matching the current Browse filters."""
        db = _get_db()
        sort = request.args.get("sort", "date")
        folder_id = request.args.get("folder_id", None, type=int)
        collection_id = request.args.get("collection_id", None, type=int)
        # Rules-only path — see ``api_photos``. ``db.get_photo_ids`` also
        # goes through ``_build_collection_query``, so a visual collection
        # id would silently widen to every metadata match (Codex review
        # r3621634298).
        err = _reject_visual_collection(db, collection_id)
        if err is not None:
            return err
        rating_min = request.args.get("rating_min", None, type=int)
        date_from = request.args.get("date_from", None)
        date_to = request.args.get("date_to", None)
        keyword = request.args.get("keyword", None)
        keyword_match_case = _request_bool_arg("keyword_match_case")
        keyword_whole_word = _request_bool_arg("keyword_whole_word")
        color_label = request.args.get("color_label", None)
        try:
            flag = _request_flag_filter()
            location_status = _request_location_status_filter()
        except ValueError as e:
            return json_error(str(e), 400)

        try:
            photo_ids = db.get_photo_ids(
                folder_id=folder_id,
                collection_id=collection_id,
                sort=sort,
                rating_min=rating_min,
                date_from=date_from,
                date_to=date_to,
                keyword=keyword,
                keyword_match_case=keyword_match_case,
                keyword_whole_word=keyword_whole_word,
                color_label=color_label,
                flag=flag,
                location_status=location_status,
            )
        except ValueError as exc:
            return json_error(str(exc), 400)
        return jsonify({"photo_ids": photo_ids, "total": len(photo_ids)})

    @app.route("/api/photos/calendar")
    def api_photos_calendar():
        db = _get_db()
        from datetime import date

        year = request.args.get("year", date.today().year, type=int)
        folder_id = request.args.get("folder_id", None, type=int)
        collection_id = request.args.get("collection_id", None, type=int)
        # ``get_calendar_data`` narrows through ``_build_collection_query``,
        # which reads only ``collections.rules``. Without ``visual``, a saved
        # visual collection would silently widen calendar counts to every
        # metadata match (Codex review r3622521597).
        err = _reject_visual_collection(db, collection_id)
        if err is not None:
            return err
        try:
            rules = _request_rules_arg()
            visual = _request_visual_arg()
            rules, _visual_info = _apply_visual_to_rules(
                db, rules, visual,
                collection_id=collection_id, folder_id=folder_id,
            )
        except ValueError as e:
            return json_error(str(e), 400)
        try:
            data = db.get_calendar_data(
                year=year, folder_id=folder_id,
                collection_id=collection_id,
                rules=rules,
            )
        except ValueError as e:
            return json_error(str(e), 400)
        return jsonify(data)

    @app.route("/api/browse/summary")
    def api_browse_summary():
        db = _get_db()
        folder_id = request.args.get("folder_id", None, type=int)
        collection_id = request.args.get("collection_id", None, type=int)
        # ``get_browse_summary`` narrows through ``_build_collection_query``,
        # which reads only ``collections.rules``. Without ``visual``, a saved
        # visual collection would silently widen the summary to every
        # metadata match (Codex review r3622521597). Browse itself clears
        # ``activeCollectionId`` when opening a collection into the filter
        # bar, so its ``/api/browse/summary`` calls never carry a visual
        # collection id; this guards direct API callers.
        err = _reject_visual_collection(db, collection_id)
        if err is not None:
            return err
        try:
            rules = _request_rules_arg()
            visual = _request_visual_arg()
            rules, _visual_info = _apply_visual_to_rules(
                db, rules, visual,
                collection_id=collection_id, folder_id=folder_id,
            )
        except ValueError as e:
            return json_error(str(e), 400)
        try:
            summary = db.get_browse_summary(
                folder_id=folder_id,
                collection_id=collection_id,
                rules=rules,
            )
        except ValueError as e:
            return json_error(str(e), 400)
        return jsonify(summary)

    @app.route("/api/photos/<int:photo_id>")
    def api_photo_detail(photo_id):
        db = _get_db()
        # verify_workspace: this response exposes the absolute path and
        # xmp_path, so a photo outside the active workspace must 404 —
        # mirrors serve_thumbnail / api_files_reveal.
        photo = db.get_photo(photo_id, verify_workspace=True)
        if not photo:
            return _photo_not_found_error(legacy_error="not found")

        result = dict(photo)
        attach_location_statuses(db, [result])

        # Parse exif_data JSON into metadata field
        raw_exif = result.pop("exif_data", None)
        if raw_exif:
            try:
                result["metadata"] = json.loads(raw_exif)
            except (ValueError, TypeError):
                result["metadata"] = None
        else:
            result["metadata"] = None

        keywords = db.get_photo_keywords(photo_id)
        result["keywords"] = [dict(k) for k in keywords]
        # Export naming uses the species-rank keyword list, which is narrower
        # than the detail payload's life-list identifications (that list can
        # also contain genus/family rows). Expose the exact export metadata so
        # editor filename previews agree with the file the worker will write.
        result["species"] = db.get_species_keywords_for_photos(
            [photo_id]
        ).get(photo_id, [])

        # Representative block: the photo's eligible species plus whether this
        # photo is the primary species representative. Only the primary (item 0
        # of get_species_representative_lists, which sorts newest-selection
        # first) flips these flags — secondary reps stay false so shared UI
        # code (context menus, panel buttons) can still offer to promote them
        # via set_species_representative's re-select-to-newest behavior.
        # Keep the legacy ``life_list`` key because shared lightbox/menu code
        # reads it.
        representatives = db.get_species_representative_lists(eligible_only=True)
        life_list_species = db.get_photo_life_list_species(photo_id)
        primary_by_species = {
            species: (photo_ids[0] if photo_ids else None)
            for species, photo_ids in representatives.items()
        }
        result["life_list"] = [
            {
                "species": s,
                "is_current_photo": photo_id == primary_by_species.get(s),
                "is_species_representative": photo_id == primary_by_species.get(s),
            }
            for s in life_list_species
        ]
        result["species_representatives"] = result["life_list"]
        result["highlight_list"] = _photo_highlight_entries(db, photo_id)

        # Location section: pre-resolved leaf + parent chain so the photo
        # detail panel can render the filled state without a second roundtrip.
        result["location"] = _serialize_photo_location(db, photo_id)
        result["edit_recipe"] = db.get_photo_edit_recipe(photo_id)
        # The shared lightbox normally warms /original after /full settles.
        # In full-resolution preview mode /full already redirects to /original,
        # so tell the client not to repeat that potentially expensive RAW work.
        import config as cfg
        result["full_uses_original"] = (
            db.get_effective_config(cfg.load()).get("preview_max_size") == 0
        )

        # Read XMP sidecar keywords
        folder = db.conn.execute(
            "SELECT path FROM folders WHERE id = ?", (photo["folder_id"],)
        ).fetchone()
        if folder:
            # Full on-disk path: mirrors the folder-join logic in
            # api_files_reveal. Exposed so the browse-grid "Copy Path"
            # right-click action can read a real filesystem path from the
            # detail response.
            result["path"] = os.path.join(folder["path"], photo["filename"])
            result["folder_name"] = os.path.basename(folder["path"])
            xmp_path = os.path.join(
                folder["path"],
                os.path.splitext(photo["filename"])[0] + ".xmp",
            )
            xmp_keywords = []
            xmp_exists = os.path.exists(xmp_path)
            if xmp_exists:
                from xmp import read_keywords

                xmp_keywords = sorted(read_keywords(xmp_path))
            result["xmp_exists"] = xmp_exists
            result["xmp_keywords"] = xmp_keywords
            result["xmp_path"] = xmp_path
        else:
            result["path"] = ""
            result["folder_name"] = ""
            result["xmp_exists"] = False
            result["xmp_keywords"] = []
            result["xmp_path"] = ""

        return jsonify(result)

    @app.route("/api/photos/by-ids", methods=["POST"])
    def api_photos_by_ids():
        """Return selected photos in caller order, scoped to the active workspace."""
        db = _get_db()
        body = request.get_json(silent=True) or {}
        raw_ids = body.get("photo_ids", [])
        if not isinstance(raw_ids, list):
            return json_error("photo_ids must be a list", 400)
        if not raw_ids:
            return json_error("photo_ids required", 400)
        if len(raw_ids) > 500:
            return json_error("too many photo_ids", 400)

        photo_ids = []
        seen = set()
        for raw in raw_ids:
            if isinstance(raw, bool) or not isinstance(raw, int):
                return json_error("photo_ids must be integers", 400)
            if raw in seen:
                continue
            seen.add(raw)
            photo_ids.append(raw)

        photos = []
        for pid in photo_ids:
            photo = db.get_photo(pid, verify_workspace=True)
            if photo:
                photos.append(dict(photo))
        attach_location_statuses(db, photos)
        attach_species(db, photos)
        attach_species_representatives(db, photos)
        attach_detections(db, photos)
        attach_edit_recipes(db, photos)
        return jsonify({"photos": photos})

    @app.route("/api/capture-time/preview", methods=["POST"])
    def api_capture_time_preview():
        """Preview a capture-time correction for selected photos."""
        from capture_time import build_capture_time_preview

        db = _get_db()
        body = request.get_json(silent=True)
        if body is None:
            body = {}
        elif not isinstance(body, dict):
            return json_error("request body must be a JSON object", 400)
        raw_ids = body.get("photo_ids", [])
        if not isinstance(raw_ids, list):
            return json_error("photo_ids must be a list", 400)
        if not raw_ids:
            return json_error("photo_ids required", 400)
        if len(raw_ids) > 50000:
            return json_error("too many photo_ids", 400)

        photo_ids = []
        seen = set()
        for raw in raw_ids:
            if isinstance(raw, bool) or not isinstance(raw, int):
                return json_error("photo_ids must be integers", 400)
            if raw in seen:
                continue
            seen.add(raw)
            photo_ids.append(raw)

        photos = []
        for pid in photo_ids[:20]:
            photo = db.get_photo(pid, verify_workspace=True)
            if photo:
                photos.append(photo)
        if not photos:
            return json_error("no photos found", 404)

        try:
            preview = build_capture_time_preview(
                photos,
                mode=body.get("mode", "preserve_instant"),
                target_offset=body.get("target_offset"),
                shift_minutes=body.get("shift_minutes"),
                limit=5,
            )
        except ValueError as exc:
            return json_error(str(exc), 400)
        preview["count"] = len(photo_ids)
        return jsonify(preview)

    @app.route("/api/photos/<int:photo_id>/best-batch")
    def api_photo_best_batch(photo_id):
        """Find neighboring burst frames and rank the best photo in that batch."""
        db = _get_db()
        max_gap = request.args.get("gap_seconds", 8.0, type=float)
        max_photos = request.args.get("max_photos", 120, type=int)
        max_gap = max(0.0, min(max_gap, 120.0))
        max_photos = max(2, min(max_photos, 500))

        rows, method_or_error = _best_batch_scope(
            db,
            photo_id,
            max_gap_seconds=max_gap,
            max_photos=max_photos,
        )
        if rows is None:
            return json_error(method_or_error, 404)

        result, error = _build_best_batch_response(db, photo_id, rows)
        if error:
            return json_error(error, 404)
        result["scope_method"] = method_or_error
        attach_nested_edit_recipes(db, result)
        return jsonify(result)

    @app.route("/api/photos/best-batch", methods=["POST"])
    def api_selected_photos_best_batch():
        """Rank an explicit selected set as a temporary best-batch group."""
        db = _get_db()
        body = request.get_json(silent=True) or {}
        raw_ids = body.get("photo_ids", [])
        if not isinstance(raw_ids, list) or not raw_ids:
            return json_error("photo_ids required")
        if len(raw_ids) > 500:
            return json_error("too many photo_ids", 400)

        photo_ids = []
        seen = set()
        for raw in raw_ids:
            if isinstance(raw, bool) or not isinstance(raw, int):
                return json_error("photo_ids must be integers", 400)
            if raw in seen:
                continue
            seen.add(raw)
            photo_ids.append(raw)
        if len(photo_ids) < 2:
            return json_error("at least two selected photos are required", 400)

        placeholders = ",".join("?" for _ in photo_ids)
        rows = db.conn.execute(
            f"""SELECT p.id, p.folder_id, p.filename, p.extension, p.timestamp,
                      p.flag, p.rating, p.quality_score, p.sharpness
               FROM photos p
               JOIN workspace_folders wf ON wf.folder_id = p.folder_id
               JOIN folders f ON f.id = p.folder_id AND f.status IN ('ok', 'partial')
               WHERE wf.workspace_id = ? AND p.id IN ({placeholders})""",
            (db._ws_id(), *photo_ids),
        ).fetchall()
        by_id = {row["id"]: row for row in rows}
        rows = [by_id[pid] for pid in photo_ids if pid in by_id]
        if len(rows) < 2:
            return json_error("at least two selected photos are required", 400)

        result, error = _build_best_batch_response(db, photo_ids[0], rows)
        if error:
            return json_error(error, 404)
        result["scope_method"] = "selected_photos"
        attach_nested_edit_recipes(db, result)
        return jsonify(result)

    @app.route("/api/photos/geo")
    def api_photos_geo():
        db = _get_db()
        folder_id = request.args.get("folder_id", None, type=int)
        focus_photo_id = request.args.get("photo_id", None, type=int)
        try:
            rules = _request_rules_arg()
            visual = _request_visual_arg()
            # Fill in the active visual model on any UI-emitted
            # ``has_visual_index`` rule that omits it. Without this a Map
            # filter for "has index" (rule sent without a ``model`` key)
            # would match any embedding row, so a workspace with stale
            # embeddings from an inactive model would surface photos that
            # are not indexed for the currently-active visual search —
            # /api/photos/query already injects here (line 5691), so the
            # Map path must match to stay consistent.
            rules = _inject_active_visual_model(rules)
            # Restrict the visual candidate set to plottable photos so a
            # workspace whose only embeddings live on non-plottable photos
            # doesn't return ``status: ok`` with ids that
            # ``get_geolocated_photos`` then intersects to zero — the user
            # would see a "visual match" chip over an empty map with no
            # fallback / no-index warning.
            plottable_ids = (
                db.get_plottable_photo_ids(folder_id=folder_id)
                if visual is not None else None
            )
            rules, visual_info = _apply_visual_to_rules(
                db, rules, visual, folder_id=folder_id,
                candidate_photo_ids=plottable_ids,
            )
        except ValueError as e:
            return json_error(str(e), 400)

        try:
            photos = db.get_geolocated_photos(
                folder_id=folder_id,
                rules=rules,
            )
        except ValueError as e:
            return json_error(str(e), 400)

        total_photos = db.count_photos()
        total_without_coordinates = db.count_photos_without_coordinates()
        total_geolocated = total_photos - total_without_coordinates

        total_filtered = len(photos)
        visible_photos = list(photos[:MAP_RENDER_PHOTO_LIMIT])
        # A deep-linked photo must remain reachable even when it falls beyond
        # the safety ceiling in the default date ordering. Replace the last
        # visible row rather than exceeding the bound.
        if (
            focus_photo_id is not None
            and visible_photos
            and all(p["id"] != focus_photo_id for p in visible_photos)
        ):
            focused = next((p for p in photos if p["id"] == focus_photo_id), None)
            if focused is not None:
                visible_photos[-1] = focused

        photo_dicts = [dict(p) for p in visible_photos]
        attach_edit_recipes(db, photo_dicts)

        response = {
            "photos": photo_dicts,
            "total_filtered": total_filtered,
            "total_rendered": len(photo_dicts),
            "render_limit": MAP_RENDER_PHOTO_LIMIT,
            "truncated": total_filtered > len(photo_dicts),
            "total_photos": total_photos,
            "total_geolocated": total_geolocated,
            "total_without_coordinates": total_without_coordinates,
            # Compatibility for older clients; new UI uses coordinate-neutral
            # names because assigned locations are included in these totals.
            "total_with_gps": total_geolocated,
            "total_without_gps": total_without_coordinates,
        }
        # Surface the visual clause's status so the filter bar's visual
        # chip can warn on fallback — without this the chip advertises a
        # visual search that silently returned metadata-only matches.
        if visual_info is not None:
            response["visual"] = visual_info
        return jsonify(response)

