    def _queue_keyword_add(photo_id, keyword_name, workspace_id=None, _commit=True):
        """Queue a keyword add unless it cancels a pending removal."""
        # Normalize before the cancellation lookup: queue_change normalizes
        # on insert, so pending values are stored in clean form and an
        # exact-match cancel against a raw variant would miss its pair.
        keyword_name = normalize_keyword_display(keyword_name)
        if not keyword_name:
            return
        db = _get_db()
        removed = db.remove_pending_changes(
            photo_id, "keyword_remove", keyword_name,
            workspace_id=workspace_id, _commit=_commit,
        )
        # A migration-generated flat removal is obsolete as soon as the user
        # explicitly re-adds that term. Clear it across every workspace that
        # owns the shared sidecar; otherwise "Use XMP" can filter the term
        # out and detach this fresh association before the add is written.
        db.clear_equivalent_flat_removals(
            [{
                "photo_id": photo_id,
                "change_type": "keyword_remove_flat",
                "value": keyword_name,
            }],
            _commit=_commit,
        )
        if removed == 0:
            db.queue_change(
                photo_id, "keyword_add", keyword_name,
                workspace_id=workspace_id, _commit=_commit,
            )

    def _queue_keyword_remove(photo_id, keyword_name, workspace_id=None, _commit=True):
        """Queue a keyword removal unless it cancels a pending add."""
        # See _queue_keyword_add: keep the cancellation lookup in the same
        # normalized form queue_change stores.
        keyword_name = normalize_keyword_display(keyword_name)
        if not keyword_name:
            return
        db = _get_db()
        removed = db.remove_pending_changes(
            photo_id, "keyword_add", keyword_name,
            workspace_id=workspace_id, _commit=_commit,
        )
        if removed == 0:
            db.queue_change(
                photo_id, "keyword_remove", keyword_name,
                workspace_id=workspace_id, _commit=_commit,
            )

    def _queue_location_sync_if_enabled(photo_id, workspace_id=None, _commit=True):
        """Queue GPS sidecar sync or cleanup work for location edits."""
        db = _get_db()
        if workspace_id is None:
            if not db._photo_in_workspace(photo_id):
                return
        elif db.conn.execute(
            """SELECT 1 FROM photos p
               JOIN workspace_folders wf ON wf.folder_id = p.folder_id
               WHERE p.id = ? AND wf.workspace_id = ?""",
            (photo_id, workspace_id),
        ).fetchone() is None:
            return
        # Queue even when assigned-location writes are disabled so sync can
        # remove stale Vireo-authored GPS previously written while enabled.
        db.remove_pending_changes(
            photo_id, "location", workspace_id=workspace_id, _commit=_commit,
        )
        db.queue_change(
            photo_id, "location", "effective",
            workspace_id=workspace_id, _commit=_commit,
        )

    def _photo_location_edit_error(db, photo_id):
        """Return an error response when a photo cannot be edited in this workspace."""
        if db.conn.execute(
            "SELECT 1 FROM photos WHERE id = ?", (photo_id,)
        ).fetchone() is None:
            return _photo_not_found_error()
        if not db._photo_in_workspace(photo_id):
            return json_error(
                f"Photo {photo_id} does not belong to the active workspace", 403,
            )
        return None

    def _normalize_photo_id_list(raw_ids):
        """Validate and de-dupe a JSON ``photo_ids`` list, preserving order."""
        if not isinstance(raw_ids, list) or not raw_ids:
            return None, json_error("photo_ids required", 400)
        photo_ids = []
        seen = set()
        for raw in raw_ids:
            if isinstance(raw, bool) or not isinstance(raw, int):
                return None, json_error("photo_ids must contain only integers", 400)
            if raw not in seen:
                photo_ids.append(raw)
                seen.add(raw)
        if not photo_ids:
            return None, json_error("photo_ids required", 400)
        return photo_ids, None

    def _gps_location_chunks(values, size=800):
        values = list(values)
        for idx in range(0, len(values), size):
            yield values[idx:idx + size]

    def _location_keyword_photo_ids(db, photo_ids):
        """Return ids that already have any linked location keyword."""
        if not photo_ids:
            return set()
        found = set()
        for chunk in _gps_location_chunks(photo_ids):
            placeholders = ",".join("?" for _ in chunk)
            rows = db.conn.execute(
                "SELECT DISTINCT pk.photo_id "
                "FROM photo_keywords pk "
                "JOIN keywords k ON k.id = pk.keyword_id "
                f"WHERE k.type = 'location' AND pk.photo_id IN ({placeholders})",
                chunk,
            ).fetchall()
            found.update(row["photo_id"] for row in rows)
        return found

    _REVERSE_GEOCODE_CACHE_LANGUAGE_KEY = "_vireo_result_language"

    def _google_maps_result_language(config):
        """Return Google's language preference for the current configuration."""
        return "en" if config.get("google_maps_prefer_english", True) else None

    def _google_place_details(place_id, api_key, language):
        """Fetch details while preserving the wrapper's default-on API."""
        if language == "en":
            return places.place_details(place_id, api_key)
        return places.place_details(place_id, api_key, language=None)

    def _google_reverse_geocode(lat, lng, api_key, language):
        """Reverse-geocode while preserving the wrapper's default-on API."""
        if language == "en":
            return places.reverse_geocode(lat, lng, api_key)
        return places.reverse_geocode(lat, lng, api_key, language=None)

    _REVERSE_GEOCODE_CACHE_LEGACY = object()

    def _decode_cached_reverse_geocode(cached, language):
        """Return ``(matches_language, details)`` for a cached response.

        Rows written before the language field existed have no
        ``_vireo_result_language`` key at all; treat those as compatible
        with the current preference so a rollout does not silently
        invalidate every previously cached lookup — and, when no API
        key is configured, force the caller into the ``no_api_key``
        branch instead of reusing the cached result. Post-PR writes
        always include the key (``null`` for the opt-out preference,
        ``"en"`` for the default), so subsequent preference changes
        still invalidate correctly.
        """
        try:
            details = json.loads(cached["response"] or "{}")
        except (ValueError, TypeError):
            details = {}
        if not isinstance(details, dict):
            details = {}
        cached_language = details.pop(
            _REVERSE_GEOCODE_CACHE_LANGUAGE_KEY,
            _REVERSE_GEOCODE_CACHE_LEGACY,
        )
        if cached_language is _REVERSE_GEOCODE_CACHE_LEGACY:
            return True, details
        return cached_language == language, details

    def _encode_cached_reverse_geocode(details, language):
        """Serialize details with the requested language for cache matching.

        The language key is always written — including as ``null`` for
        the opt-out preference — so the decoder can distinguish a
        legacy untagged row from a row explicitly written under
        ``language=None``.
        """
        payload = dict(details) if isinstance(details, dict) else {}
        payload[_REVERSE_GEOCODE_CACHE_LANGUAGE_KEY] = language
        return json.dumps(payload)

    def _resolve_exif_place_for_photo(
        db, photo, api_key, language, grid_cache,
    ):
        """Resolve one photo's EXIF coordinates into normalized place details.

        Returns ``(details, reason)`` where ``details`` is the normalized
        Google-place dict on success and ``reason`` is a short unresolved code
        on failure. Results are de-duped by the DB's reverse-geocode grid so a
        burst in the same cell only performs/cache-checks one lookup.
        """
        lat = photo["latitude"]
        lng = photo["longitude"]
        if lat is None or lng is None:
            return None, "missing_gps"
        try:
            lat = float(lat)
            lng = float(lng)
        except (TypeError, ValueError):
            return None, "invalid_gps"
        if not (math.isfinite(lat) and math.isfinite(lng)):
            return None, "invalid_gps"

        grid = Database._reverse_geocode_grid(lat, lng)
        if grid in grid_cache:
            return grid_cache[grid]

        cached = db.reverse_geocode_cache_get(lat, lng)
        if cached is not None:
            language_matches, details = _decode_cached_reverse_geocode(
                cached, language,
            )
            if language_matches:
                if cached["place_id"] is None:
                    result = (None, "no_match")
                    grid_cache[grid] = result
                    return result
                if not details.get("place_id"):
                    details["place_id"] = cached["place_id"]
                if details.get("place_id"):
                    result = (details, None)
                else:
                    result = (None, "no_match")
                grid_cache[grid] = result
                return result

        if not api_key:
            result = (None, "no_api_key")
            grid_cache[grid] = result
            return result

        try:
            details = _google_reverse_geocode(
                lat, lng, api_key, language,
            )
        except places.PlacesTransientError:
            app.logger.warning(
                "bulk reverse_geocode transient failure for photo=%s lat=%s lng=%s",
                photo["id"],
                lat,
                lng,
            )
            result = (None, "transient_error")
            grid_cache[grid] = result
            return result

        cache_place_id = details.get("place_id") if details else None
        db.reverse_geocode_cache_put(
            lat,
            lng,
            place_id=cache_place_id,
            response_json=_encode_cached_reverse_geocode(details, language),
        )
        if not details or not details.get("place_id"):
            result = (None, "no_match")
        else:
            result = (details, None)
        grid_cache[grid] = result
        return result

    def _bulk_gps_location_source_ids(db, body):
        """Return source photo ids from either ``photo_ids`` or ``collection_id``."""
        raw_ids = body.get("photo_ids")
        if raw_ids:
            return _normalize_photo_id_list(raw_ids)

        collection_id = _coerce_collection_id(body.get("collection_id"))
        if collection_id is False:
            return None, json_error("collection_id must be an integer", 400)
        if collection_id is None:
            return None, json_error("photo_ids or collection_id required", 400)

        row = db.conn.execute(
            "SELECT id, visual_json FROM collections "
            "WHERE id = ? AND workspace_id = ?",
            (collection_id, db._ws_id()),
        ).fetchone()
        if row is None:
            return None, json_error("collection not found", 404)
        # get_collection_photo_ids evaluates ``rules`` only; a visual-only
        # collection would silently expand to every metadata match. The
        # picker filters these out, but reject here as the boundary.
        if row["visual_json"] is not None:
            return None, json_error(_VISUAL_COLLECTION_MSG, 400)
        return db.get_collection_photo_ids(collection_id), None

    def _location_review_groups(photos, cluster_radius_m=750.0):
        """Cluster photos by their observed coordinates for human review.

        Reverse-geocoded place ids are deliberately not involved: they are
        suggestions for the reviewer, not the identity of a coordinate group.
        A small spatial hash keeps the neighbor search close to O(n) for large
        libraries while connected components allow a photographed route to
        remain one reviewable area.
        """
        valid = []
        unresolved = []
        for order, photo in enumerate(photos):
            lat = photo["latitude"]
            lng = photo["longitude"]
            if lat is None or lng is None:
                unresolved.append({
                    "photo_id": photo["id"],
                    "filename": photo["filename"],
                    "reason": "missing_gps",
                })
                continue
            try:
                lat = float(lat)
                lng = float(lng)
            except (TypeError, ValueError):
                lat = lng = math.nan
            if (
                not math.isfinite(lat)
                or not math.isfinite(lng)
                or not -90 <= lat <= 90
                or not -180 <= lng <= 180
            ):
                unresolved.append({
                    "photo_id": photo["id"],
                    "filename": photo["filename"],
                    "reason": "invalid_gps",
                })
                continue
            valid.append({
                "photo": photo,
                "order": order,
                "lat": lat,
                "lng": lng,
            })

        if not valid:
            return [], unresolved

        earth_radius_m = 6_371_000.0
        reference_lat = math.radians(
            sum(item["lat"] for item in valid) / len(valid)
        )
        reference_lng = valid[0]["lng"]

        def projected(item):
            lng_delta = ((item["lng"] - reference_lng + 180.0) % 360.0) - 180.0
            return (
                earth_radius_m * math.radians(lng_delta) * math.cos(reference_lat),
                earth_radius_m * math.radians(item["lat"]),
            )

        parents = list(range(len(valid)))

        def find(index):
            while parents[index] != index:
                parents[index] = parents[parents[index]]
                index = parents[index]
            return index

        def union(left, right):
            left_root = find(left)
            right_root = find(right)
            if left_root != right_root:
                parents[right_root] = left_root

        buckets = {}
        radius_sq = cluster_radius_m * cluster_radius_m
        for index, item in enumerate(valid):
            x_coord, y_coord = projected(item)
            item["x"] = x_coord
            item["y"] = y_coord
            cell = (
                math.floor(x_coord / cluster_radius_m),
                math.floor(y_coord / cluster_radius_m),
            )
            for x_offset in (-1, 0, 1):
                for y_offset in (-1, 0, 1):
                    for neighbor in buckets.get(
                        (cell[0] + x_offset, cell[1] + y_offset), []
                    ):
                        dx = x_coord - valid[neighbor]["x"]
                        dy = y_coord - valid[neighbor]["y"]
                        if dx * dx + dy * dy <= radius_sq:
                            union(index, neighbor)
            buckets.setdefault(cell, []).append(index)

        components = {}
        for index, item in enumerate(valid):
            components.setdefault(find(index), []).append(item)

        ordered = sorted(
            components.values(),
            key=lambda items: min(item["order"] for item in items),
        )
        groups = []
        for group_index, items in enumerate(ordered, start=1):
            center_lat = sum(item["lat"] for item in items) / len(items)
            # Longitudes were normalized around the first input point above;
            # use the same frame so groups around the antimeridian do not get
            # a center near Greenwich.
            lng_deltas = [
                ((item["lng"] - reference_lng + 180.0) % 360.0) - 180.0
                for item in items
            ]
            center_lng = (
                reference_lng + sum(lng_deltas) / len(lng_deltas) + 180.0
            ) % 360.0 - 180.0
            center_x = sum(item["x"] for item in items) / len(items)
            center_y = sum(item["y"] for item in items) / len(items)
            spread_m = max(
                math.hypot(item["x"] - center_x, item["y"] - center_y)
                for item in items
            )
            timestamps = sorted(
                item["photo"]["timestamp"]
                for item in items
                if item["photo"]["timestamp"]
            )
            photo_data = [{
                "id": item["photo"]["id"],
                "filename": item["photo"]["filename"],
                "companion_path": item["photo"]["companion_path"],
                "timestamp": item["photo"]["timestamp"],
                "latitude": item["lat"],
                "longitude": item["lng"],
            } for item in sorted(items, key=lambda item: item["order"])]
            groups.append({
                "id": f"group-{group_index}",
                "count": len(photo_data),
                "photo_ids": [photo["id"] for photo in photo_data],
                "photos": photo_data,
                "sample_filenames": [
                    photo["filename"] for photo in photo_data[:3]
                ],
                "center": {"lat": center_lat, "lng": center_lng},
                "bounds": {
                    "south": min(item["lat"] for item in items),
                    "west": min(item["lng"] for item in items),
                    "north": max(item["lat"] for item in items),
                    "east": max(item["lng"] for item in items),
                },
                "spread_m": round(spread_m, 1),
                "captured_from": timestamps[0] if timestamps else None,
                "captured_to": timestamps[-1] if timestamps else None,
            })
        return groups, unresolved

    @app.route("/api/location-review/preview", methods=["POST"])
    def api_location_review_preview():
        """Return coordinate or capture-time groups without assigning places."""
        body = request.get_json(silent=True) or {}
        mode = body.get("mode", "coordinates")
        if mode not in ("coordinates", "time"):
            return json_error("mode must be coordinates or time", 400)
        gap_minutes = body.get("gap_minutes", 60)
        if type(gap_minutes) is not int or gap_minutes not in (15, 30, 60, 120):
            return json_error("gap_minutes must be 15, 30, 60, or 120", 400)
        db = _get_db()
        if body.get("scope") == "all":
            if "photo_ids" in body or "collection_id" in body:
                return json_error("Choose all photos, photo_ids, or collection_id, not multiple sources", 400)
            photo_ids, error = db.get_photo_ids(), None
        else:
            photo_ids, error = _bulk_gps_location_source_ids(db, body)
        if error is not None:
            return error
        if not photo_ids:
            return jsonify({
                "total": 0,
                "reviewable": 0,
                "groups": [],
                "unresolved": [],
                "skipped": [],
            })

        photos_map = db.get_photos_by_ids(photo_ids)
        if len(photos_map) != len(photo_ids):
            return json_error("One or more photos were not found", 404)
        for photo_id in photo_ids:
            edit_error = _photo_location_edit_error(db, photo_id)
            if edit_error is not None:
                return edit_error

        assigned_ids = _location_keyword_photo_ids(db, photo_ids)
        skipped = [{
            "photo_id": photo_id,
            "filename": photos_map[photo_id]["filename"],
            "reason": "already_has_location",
        } for photo_id in photo_ids if photo_id in assigned_ids]
        review_photos = [
            photos_map[photo_id]
            for photo_id in photo_ids
            if photo_id not in assigned_ids
        ]
        if mode == "time":
            groups = location_review.time_review_groups(review_photos, gap_minutes)
            unresolved = []
            skipped.extend({
                "photo_id": photo["id"], "filename": photo["filename"],
                "reason": "has_coordinates",
            } for photo in review_photos if location_review.has_usable_coordinates(photo))
        else:
            groups, unresolved = _location_review_groups(review_photos)
        return jsonify({
            "total": len(photo_ids),
            "reviewable": sum(group["count"] for group in groups),
            "groups": groups,
            "unresolved": unresolved,
            "skipped": skipped,
        })

    @app.route("/api/location-review/saved-suggestions")
    def api_location_review_saved_suggestions():
        """Return nearby location keywords already used in this workspace."""
        try:
            lat = float(request.args.get("lat", ""))
            lng = float(request.args.get("lng", ""))
            radius_m = float(request.args.get("radius_m", "25000"))
        except (TypeError, ValueError):
            return json_error("invalid coordinates", 400)
        if (
            not math.isfinite(lat)
            or not math.isfinite(lng)
            or not math.isfinite(radius_m)
            or not -90 <= lat <= 90
            or not -180 <= lng <= 180
            or radius_m <= 0
        ):
            return json_error("invalid coordinates", 400)
        radius_m = min(radius_m, 100_000.0)

        db = _get_db()
        rows = db.conn.execute(
            """SELECT k.id, k.name, k.place_id, k.latitude, k.longitude,
                      k.parent_id, COUNT(DISTINCT pk.photo_id) AS photo_count
               FROM keywords k
               JOIN photo_keywords pk ON pk.keyword_id = k.id
               JOIN photos p ON p.id = pk.photo_id
               JOIN workspace_folders wf ON wf.folder_id = p.folder_id
               WHERE wf.workspace_id = ? AND k.type = 'location'
                 AND k.latitude IS NOT NULL AND k.longitude IS NOT NULL
               GROUP BY k.id""",
            (db._ws_id(),),
        ).fetchall()

        def distance_m(row):
            lat1 = math.radians(lat)
            lat2 = math.radians(float(row["latitude"]))
            delta_lat = lat2 - lat1
            delta_lng = math.radians(float(row["longitude"]) - lng)
            value = (
                math.sin(delta_lat / 2) ** 2
                + math.cos(lat1) * math.cos(lat2)
                * math.sin(delta_lng / 2) ** 2
            )
            return 2 * 6_371_000.0 * math.asin(min(1.0, math.sqrt(value)))

        suggestions = []
        for row in rows:
            distance = distance_m(row)
            if distance > radius_m:
                continue
            suggestions.append({
                "keyword_id": row["id"],
                "name": row["name"],
                "place_id": row["place_id"],
                "latitude": row["latitude"],
                "longitude": row["longitude"],
                "photo_count": row["photo_count"],
                "distance_m": round(distance, 1),
                "parent_chain": _walk_parent_chain(db, row["parent_id"]),
            })
        suggestions.sort(key=lambda item: (item["distance_m"], -item["photo_count"], item["name"]))
        return jsonify({"suggestions": suggestions[:8]})

    def _bulk_gps_location_payload(db, body, cancel_check=None):
        """Build preview/apply data for resolving locations from EXIF GPS."""
        photo_ids, error = _bulk_gps_location_source_ids(db, body)
        if error is not None:
            return None, error
        if not photo_ids:
            return {
                "total": 0,
                "resolvable": 0,
                "updated": 0,
                "groups": [],
                "unresolved": [],
                "skipped": [],
            }, None
        photos_map = db.get_photos_by_ids(photo_ids)
        if len(photos_map) != len(photo_ids):
            return None, json_error("One or more photos were not found", 404)
        for pid in photo_ids:
            edit_error = _photo_location_edit_error(db, pid)
            if edit_error is not None:
                return None, edit_error

        assigned_ids = _location_keyword_photo_ids(db, photo_ids)
        import config as cfg
        maps_config = cfg.load()
        api_key = (maps_config.get("google_maps_api_key", "") or "").strip()
        language = _google_maps_result_language(maps_config)

        grid_cache = {}
        groups = {}
        unresolved = []
        skipped = []
        ordered_group_keys = []
        cancelled = False
        for pid in photo_ids:
            if cancel_check is not None and cancel_check():
                cancelled = True
                break
            photo = photos_map[pid]
            if pid in assigned_ids:
                skipped.append({
                    "photo_id": pid,
                    "filename": photo["filename"],
                    "reason": "already_has_location",
                })
                continue
            details, reason = _resolve_exif_place_for_photo(
                db, photo, api_key, language, grid_cache,
            )
            if reason is not None:
                unresolved.append({
                    "photo_id": pid,
                    "filename": photo["filename"],
                    "reason": reason,
                })
                continue

            place_id = details.get("place_id")
            if place_id not in groups:
                groups[place_id] = {
                    "place_id": place_id,
                    "summary": _summarize_details(details),
                    "name": details.get("name") or "",
                    "details": details,
                    "photo_ids": [],
                    "sample_filenames": [],
                }
                ordered_group_keys.append(place_id)
            group = groups[place_id]
            group["photo_ids"].append(pid)
            if len(group["sample_filenames"]) < 3:
                group["sample_filenames"].append(photo["filename"])

        group_list = []
        for place_id in ordered_group_keys:
            group = groups[place_id]
            group_list.append({
                "place_id": group["place_id"],
                "summary": group["summary"],
                "name": group["name"],
                "count": len(group["photo_ids"]),
                "photo_ids": group["photo_ids"],
                "sample_filenames": group["sample_filenames"],
            })

        result = {
            "total": len(photo_ids),
            "resolvable": sum(group["count"] for group in group_list),
            "updated": 0,
            "groups": group_list,
            "unresolved": unresolved,
            "skipped": skipped,
            "_details_by_place_id": {k: v["details"] for k, v in groups.items()},
        }
        if cancelled:
            result["cancelled"] = True
        return result, None

    # -- Edit API routes --

    def _create_current_local_mask_snapshot(
        db, photo_id, *, vireo_dir, native_size,
    ):
        """Snapshot the active immutable mask, retrying cleanup races."""
        import local_masks

        for attempt in range(3):
            variant_row = db.conn.execute(
                "SELECT active_mask_variant FROM photos WHERE id=?",
                (photo_id,),
            ).fetchone()
            variant = (
                variant_row["active_mask_variant"] if variant_row else None
            )
            mask_row = (
                db.get_photo_mask(photo_id, variant) if variant else None
            )
            try:
                return local_masks.create_snapshot(
                    photo_id=photo_id,
                    mask_row=mask_row,
                    vireo_dir=vireo_dir,
                    native_size=native_size,
                )
            except FileNotFoundError:
                if attempt == 2:
                    raise ValueError(
                        "active subject mask changed during snapshot; retry"
                    ) from None
            except ValueError as exc:
                # ``create_snapshot`` can observe a predecessor after the DB
                # lookup but after cleanup at its existence check. Retry only
                # that missing-file result; validation errors are stable.
                if (
                    str(exc) != "active subject mask file is missing"
                    or attempt == 2
                ):
                    raise

    @app.route("/api/photos/<int:photo_id>/wildlife_excluded", methods=["POST"])
    def api_set_wildlife_excluded(photo_id):
        db = _get_db()
        body = request.get_json(silent=True) or {}
        excluded = body.get("excluded")
        if not isinstance(excluded, bool):
            return json_error("excluded must be a boolean")
        old = db.get_photo(photo_id)
        if not old:
            return _photo_not_found_error(legacy_error="not found")
        old_value = "1" if old["wildlife_excluded"] else "0"
        new_value = "1" if excluded else "0"
        try:
            db.update_photo_wildlife_excluded(photo_id, excluded)
        except ValueError as e:
            return json_error(str(e), 403)
        db.record_edit(
            "wildlife_excluded",
            "Excluded from wildlife classification" if excluded else "Included in wildlife classification",
            new_value,
            [{"photo_id": photo_id, "old_value": old_value, "new_value": new_value}],
        )
        return jsonify({"ok": True, "wildlife_excluded": excluded})

    def _local_mask_stale(db, photo_id, recipe):
        if not recipe or not recipe.get("local"):
            return False
        import local_masks
        variant_row = db.conn.execute(
            "SELECT active_mask_variant FROM photos WHERE id=?",
            (photo_id,),
        ).fetchone()
        variant = variant_row["active_mask_variant"] if variant_row else None
        mask_row = db.get_photo_mask(photo_id, variant) if variant else None
        return local_masks.is_stale(recipe, mask_row)

    @app.route("/api/photos/<int:photo_id>/edit-recipe", methods=["GET"])
    def api_get_photo_edit_recipe(photo_id):
        db = _get_db()
        photo = db.get_photo(photo_id, verify_workspace=True)
        if not photo:
            return _photo_not_found_error(legacy_error="not found")
        recipe = db.get_photo_edit_recipe(photo_id)
        return jsonify({
            "photo_id": photo_id,
            "recipe": recipe,
            "local_mask_stale": _local_mask_stale(db, photo_id, recipe),
        })

    @app.route(
        "/api/photos/<int:photo_id>/local-mask/snapshot", methods=["POST"]
    )
    def api_create_local_mask_snapshot(photo_id):
        """Freeze the photo's active SAM mask into an edit-mask snapshot.

        Returns the recipe ``local.mask`` fields the editor embeds when
        saving local adjustments. Renders read only the snapshot, so the
        live mask can regenerate without silently changing committed edits.
        """
        db = _get_db()
        photo = db.get_photo(photo_id, verify_workspace=True)
        if not photo:
            return _photo_not_found_error(legacy_error="not found")
        try:
            mask = _create_current_local_mask_snapshot(
                db,
                photo_id,
                vireo_dir=os.path.dirname(app.config["THUMB_CACHE_DIR"]),
                native_size=_recipe_source_dimensions(photo),
            )
        except ValueError as e:
            return json_error(str(e))
        return jsonify({"mask": mask, "stale": False})

    @app.route("/api/photos/<int:photo_id>/edit-recipe", methods=["PUT", "POST"])
    def api_set_photo_edit_recipe(photo_id):
        db = _get_db()
        body = request.get_json(silent=True)
        if not isinstance(body, dict):
            return json_error("request body must be a JSON object")
        recipe = body.get("recipe", body)
        description = body.get("description")
        if not isinstance(description, str) or not description.strip():
            description = "Updated photo edit recipe"
        if not isinstance(recipe, dict):
            return json_error("recipe must be a JSON object")
        photo = db.get_photo(photo_id, verify_workspace=True)
        if not photo:
            return _photo_not_found_error(legacy_error="not found")
        from image_edits import RecipeError, normalize_recipe, recipe_to_json
        try:
            normalized = normalize_recipe(recipe)
        except RecipeError as e:
            return json_error(str(e))
        local = (normalized or {}).get("local")
        if local:
            import local_masks
            snap = local_masks.snapshot_path(
                os.path.dirname(app.config["THUMB_CACHE_DIR"]),
                photo_id, local["mask"]["ref"],
            )
            if not os.path.exists(snap):
                return json_error(
                    "unknown edit-mask snapshot for this photo; create one "
                    "via POST /api/photos/<id>/local-mask/snapshot first"
                )
        old_recipe = db.get_photo_edit_recipe(photo_id)
        try:
            old_value = recipe_to_json(old_recipe) or ""
            new_recipe = db.set_photo_edit_recipe(photo_id, recipe, verify_workspace=True)
            new_value = recipe_to_json(new_recipe) or ""
        except RecipeError as e:
            return json_error(str(e))
        except ValueError as e:
            return json_error(str(e), 403)
        _invalidate_photo_render_cache(db, [photo_id])
        if old_value != new_value:
            _queue_edit_recipe_sync(db, photo_id, new_value)
            db.record_edit(
                "edit_recipe",
                description.strip(),
                new_value,
                [{"photo_id": photo_id, "old_value": old_value, "new_value": new_value}],
            )
        return jsonify({
            "ok": True,
            "recipe": new_recipe,
            "local_mask_stale": _local_mask_stale(db, photo_id, new_recipe),
        })

    @app.route("/api/photos/<int:photo_id>/edit-recipe", methods=["DELETE"])
    def api_clear_photo_edit_recipe(photo_id):
        db = _get_db()
        photo = db.get_photo(photo_id, verify_workspace=True)
        if not photo:
            return _photo_not_found_error(legacy_error="not found")
        from image_edits import recipe_to_json
        old_recipe = db.get_photo_edit_recipe(photo_id)
        old_value = recipe_to_json(old_recipe) or ""
        try:
            db.clear_photo_edit_recipe(photo_id, verify_workspace=True)
        except ValueError as e:
            return json_error(str(e), 403)
        _invalidate_photo_render_cache(db, [photo_id])
        if old_value:
            _queue_edit_recipe_sync(db, photo_id, "")
            db.record_edit(
                "edit_recipe",
                "Cleared photo edit recipe",
                "",
                [{"photo_id": photo_id, "old_value": old_value, "new_value": ""}],
            )
        return jsonify({"ok": True, "recipe": None})

    @app.route("/api/photos/edit-recipe/apply", methods=["POST"])
    def api_apply_photo_edit_recipe_bulk():
        """Apply one edit recipe to many photos (copy/paste edit settings).

        Replaces each target's recipe with the supplied one and records a
        single undoable batch history entry. Photos missing from the active
        workspace are skipped (reported in ``skipped``) rather than failing
        the whole request.
        """
        db = _get_db()
        body = request.get_json(silent=True)
        if not isinstance(body, dict):
            return json_error("request body must be a JSON object")
        recipe = body.get("recipe")
        if not isinstance(recipe, dict):
            return json_error("recipe must be a JSON object")
        raw_ids = body.get("photo_ids")
        if not isinstance(raw_ids, list) or not raw_ids:
            return json_error("photo_ids must be a non-empty list")
        seen = set()
        ids = []
        for pid in raw_ids:
            if isinstance(pid, bool) or not isinstance(pid, int):
                return json_error("photo_ids must be integers")
            if pid not in seen:
                seen.add(pid)
                ids.append(pid)

        from image_edits import RecipeError, recipe_to_json

        # Validate the incoming recipe once up front so a bad payload fails
        # cleanly before we touch any rows.
        try:
            target_json = recipe_to_json(recipe) or ""
        except RecipeError as e:
            return json_error(str(e))

        description = body.get("description")
        if not isinstance(description, str) or not description.strip():
            description = "Pasted edit settings"
        description = description.strip()

        has_local = bool(recipe.get("local"))
        vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])

        items = []
        applied = []
        skipped = []
        local_errors = {}
        applied_recipes = {}
        for pid in ids:
            photo = db.get_photo(pid, verify_workspace=True)
            if not photo:
                skipped.append(pid)
                continue
            target_recipe = recipe
            if has_local:
                # Local adjustments reference a photo-specific mask, so each
                # target gets its OWN snapshot (frozen from its active mask);
                # the slider values copy, the mask does not. Photos without a
                # usable mask are skipped and reported, not silently given a
                # wrong mask.
                try:
                    target_mask = _create_current_local_mask_snapshot(
                        db,
                        pid,
                        vireo_dir=vireo_dir,
                        native_size=_recipe_source_dimensions(photo),
                    )
                except (ValueError, OSError) as e:
                    # OSError covers disk-write failures inside create_snapshot
                    # (os.makedirs, f.write, os.replace) so a transient I/O
                    # hiccup on one target doesn't abort the whole batch.
                    skipped.append(pid)
                    local_errors[str(pid)] = str(e)
                    continue
                target_recipe = copy.deepcopy(recipe)
                target_local_mask = dict(
                    target_recipe["local"].get("mask") or {}
                )
                target_local_mask.update(target_mask)
                target_recipe["local"]["mask"] = target_local_mask
            old_recipe = db.get_photo_edit_recipe(pid)
            old_value = recipe_to_json(old_recipe) or ""
            try:
                new_recipe = db.set_photo_edit_recipe(pid, target_recipe, verify_workspace=True)
            except (RecipeError, ValueError):
                skipped.append(pid)
                continue
            new_value = recipe_to_json(new_recipe) or ""
            applied.append(pid)
            applied_recipes[str(pid)] = new_recipe
            if old_value != new_value:
                _queue_edit_recipe_sync(db, pid, new_value)
                items.append({
                    "photo_id": pid,
                    "old_value": old_value,
                    "new_value": new_value,
                })

        if applied:
            _invalidate_photo_render_cache(db, applied)
        if items:
            db.record_edit("edit_recipe", description, target_json, items, is_batch=True)
        # ``recipes`` maps each applied id to the recipe actually stored for
        # it — critical when ``has_local`` is true because each target has
        # its own mask snapshot ref, so callers cannot reuse the pasted
        # recipe (or the first applied recipe) for every id. ``recipe`` is
        # kept as the first applied recipe for backwards compatibility.
        payload = {
            "ok": True,
            "applied": applied,
            "skipped": skipped,
            "count": len(applied),
            "recipe": applied_recipes[str(applied[0])] if applied else None,
            "recipes": applied_recipes,
        }
        if local_errors:
            payload["local_errors"] = local_errors
        return jsonify(payload)

    @app.route("/api/edit-presets", methods=["GET", "POST"])
    def api_edit_presets():
        """List or save (upsert by name) global edit presets.

        Presets store an adjustments-only recipe — a reusable look. Geometry
        is stripped on save; see db.save_edit_preset.
        """
        db = _get_db()
        if request.method == "GET":
            return jsonify({"presets": db.list_edit_presets()})
        body = request.get_json(silent=True)
        if not isinstance(body, dict):
            return json_error("request body must be a JSON object")
        recipe = body.get("recipe")
        if not isinstance(recipe, dict):
            return json_error("recipe must be a JSON object")
        try:
            preset = db.save_edit_preset(body.get("name"), recipe)
        except ValueError as e:  # includes RecipeError
            return json_error(str(e))
        return jsonify({"ok": True, "preset": preset})

    @app.route("/api/edit-presets/<int:preset_id>", methods=["DELETE"])
    def api_delete_edit_preset(preset_id):
        db = _get_db()
        if not db.delete_edit_preset(preset_id):
            return json_error("preset not found", 404)
        return jsonify({"ok": True})

    @app.route("/api/photos/<int:photo_id>/edit-history")
    def api_photo_edit_history(photo_id):
        db = _get_db()
        photo = db.get_photo(photo_id, verify_workspace=True)
        if not photo:
            return _photo_not_found_error(legacy_error="not found")
        limit = min(max(1, request.args.get("limit", 50, type=int)), 200)
        rows = db.conn.execute(
            """SELECT eh.id, eh.description, eh.created_at, eh.undone,
                      ehi.old_value, ehi.new_value
               FROM edit_history eh
               JOIN edit_history_items ehi ON ehi.edit_id = eh.id
               WHERE eh.workspace_id = ?
                 AND eh.action_type = 'edit_recipe'
                 AND ehi.photo_id = ?
               ORDER BY eh.created_at DESC, eh.id DESC
               LIMIT ?""",
            (db._ws_id(), photo_id, limit),
        ).fetchall()

        from image_edits import copy_recipe

        def decode_recipe(value):
            if value is None:
                return None
            try:
                return copy_recipe(value)
            except Exception:
                log.warning(
                    "Skipping invalid edit recipe history payload for photo %s",
                    photo_id,
                    exc_info=True,
                )
                return None

        history = []
        for row in rows:
            history.append({
                "id": row["id"],
                "description": row["description"],
                "created_at": row["created_at"],
                "undone": bool(row["undone"]),
                "old_recipe": decode_recipe(row["old_value"]),
                "new_recipe": decode_recipe(row["new_value"]),
            })
        return jsonify({
            "photo_id": photo_id,
            "current_recipe": db.get_photo_edit_recipe(photo_id),
            "history": history,
        })

    @app.route("/api/files/reveal", methods=["POST"])
    def api_files_reveal():
        """Reveal a photo or folder in the OS file manager.

        Body: {"photo_id": <int>} OR {"folder_id": <int>}

        Photo reveals select the file in its parent directory (macOS ``open
        -R``, Windows ``explorer /select,``, Linux ``xdg-open <parent dir>``).
        Folder reveals open the folder itself (macOS ``open -R <dir>``,
        Windows ``explorer <dir>``, Linux ``xdg-open <dir>``) — this differs
        from the photo case on Windows where we deliberately skip ``/select,``
        so the user sees the folder's contents rather than its parent.

        Returns: {"ok": True} on success; {"ok": False, "reason": "..."} if
        the subprocess failed to launch; 404 if the id is unknown; 400 if
        neither id was provided or either is malformed.
        """
        body = request.get_json(silent=True) or {}
        pid_raw = body.get("photo_id")
        fid_raw = body.get("folder_id")

        if pid_raw is None and fid_raw is None:
            return json_error("photo_id or folder_id required")

        db = _get_db()
        is_folder = False
        path = ""

        if pid_raw is not None:
            try:
                pid_int = int(pid_raw)
            except (TypeError, ValueError):
                return json_error("photo_id must be an integer")
            # verify_workspace=True enforces that the photo's folder is
            # linked to the active workspace — otherwise this endpoint would
            # expose absolute filesystem paths for photos hidden from the
            # current workspace.
            photo = db.get_photo(pid_int, verify_workspace=True)
            if not photo:
                return json_error("photo not found", 404)
            folder_row = db.conn.execute(
                "SELECT path FROM folders WHERE id = ?", (photo["folder_id"],)
            ).fetchone()
            folder_path = folder_row["path"] if folder_row else ""
            if not folder_path or not photo["filename"]:
                return jsonify({"ok": False, "reason": "no path"})
            path = os.path.join(folder_path, photo["filename"])
        else:
            try:
                fid_int = int(fid_raw)
            except (TypeError, ValueError):
                return json_error("folder_id must be an integer")
            folder = db.get_folder(fid_int)
            if not folder:
                return json_error("folder not found", 404)
            # Reject reveal for folders not linked to the active workspace,
            # matching the photo branch's verify_workspace gate.
            linked = db.conn.execute(
                "SELECT 1 FROM workspace_folders WHERE workspace_id = ? AND folder_id = ?",
                (db._active_workspace_id, fid_int),
            ).fetchone()
            if not linked:
                return json_error("folder not found", 404)
            folder_path = folder["path"]
            if not folder_path:
                return jsonify({"ok": False, "reason": "no path"})
            path = folder_path
            is_folder = True

        try:
            if sys.platform == "darwin":
                # "open -R <dir>" reveals the folder inside its parent; that's
                # the right behavior for folder reveals too, consistent with
                # how Finder treats folder-targeted reveal.
                proc = subprocess.run(
                    ["open", "-R", "--", path],
                    timeout=5,
                    check=False,
                    capture_output=True,
                    text=True,
                    **no_window_kwargs(),
                )
            elif sys.platform.startswith("win"):
                # explorer.exe's exit status is not a reliable success signal
                # (see the returncode-check gate below), so a stale catalog
                # entry whose path no longer exists would otherwise silently
                # return ok=True and produce a bogus "Revealed in File
                # Explorer" toast. Preflight the target path so those cases
                # surface as failures instead.
                if is_folder:
                    if not os.path.isdir(path):
                        return jsonify({"ok": False, "reason": "folder not found"})
                    # Open the folder itself so the user sees its contents.
                    proc = subprocess.run(
                        ["explorer", path],
                        timeout=5,
                        check=False,
                        capture_output=True,
                        text=True,
                        **no_window_kwargs(),
                    )
                else:
                    if not os.path.isfile(path):
                        return jsonify({"ok": False, "reason": "photo file not found"})
                    proc = subprocess.run(
                        ["explorer", f"/select,{path}"],
                        timeout=5,
                        check=False,
                        capture_output=True,
                        text=True,
                        **no_window_kwargs(),
                    )
            else:
                # xdg-open on a file has inconsistent behavior across desktops
                # (some open the image viewer, not the file manager), so for
                # photo reveals we open the parent directory instead. Passing
                # a directory to xdg-open opens the folder in the file manager,
                # which is exactly what we want for folder reveals.
                #
                # Because photo reveals target the parent directory rather than
                # the file itself, xdg-open will happily succeed for a stale
                # catalog entry whose folder still exists but whose photo has
                # been deleted or moved — the user gets a "revealed" toast even
                # though nothing is selected. Verify the photo file exists first
                # so those cases surface as failures instead of false successes.
                if not is_folder and not os.path.isfile(path):
                    return jsonify({"ok": False, "reason": "photo file not found"})
                target = path if is_folder else (os.path.dirname(path) or path)
                # xdg-open doesn't honor `--`; abspath guarantees a leading `/`
                # so a crafted leading-dash path can't be parsed as a flag.
                target = os.path.abspath(target)
                proc = subprocess.run(
                    ["xdg-open", target],
                    timeout=5,
                    check=False,
                    capture_output=True,
                    text=True,
                    **no_window_kwargs(),
                )
            # explorer.exe's exit status is not a reliable success signal:
            # `explorer /select,<path>` (and `explorer <folder>`) routinely
            # return 1 even when File Explorer opens correctly, with nothing
            # useful on stdout/stderr. Skipping the returncode check on Windows
            # avoids reporting "reveal failed" for reveals that actually worked.
            if not sys.platform.startswith("win") and proc.returncode != 0:
                reason = (proc.stderr or proc.stdout or "").strip()
                if not reason:
                    reason = f"reveal command exited {proc.returncode}"
                return jsonify({"ok": False, "reason": reason})
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError) as exc:
            return jsonify({"ok": False, "reason": str(exc)})
        return jsonify({"ok": True})

    @app.route("/api/photos/<int:photo_id>/keywords", methods=["POST"])
    def api_add_keyword(photo_id):
        db = _get_db()
        body = request.get_json(silent=True) or {}
        keyword_id = body.get("keyword_id")
        name = body.get("name", "")
        name = name.strip() if isinstance(name, str) else ""
        if keyword_id is not None:
            if isinstance(keyword_id, bool) or not isinstance(keyword_id, int):
                return json_error("keyword_id must be an integer")
            keyword_row = db.conn.execute(
                "SELECT id, name FROM keywords WHERE id = ?", (keyword_id,)
            ).fetchone()
            if keyword_row is None:
                return json_error("keyword not found", 404)
            kid = keyword_row["id"]
            name = keyword_row["name"]
        else:
            if not name:
                return json_error("name required")
            # Validate kw_type at the boundary (isinstance guard against
            # non-hashable JSON; membership against the canonical enum).
            # Pass it through to add_keyword so its type-reconciliation logic
            # runs — a post-update SQL `UPDATE keywords SET type = ?` would
            # silently rewrite an existing user-typed row (e.g. someone's
            # 'individual' Charlie) and bypass the taxonomy/general upgrade
            # rules in add_keyword.
            kw_type_raw = body.get("type")
            kw_type = (
                kw_type_raw
                if isinstance(kw_type_raw, str) and kw_type_raw in KEYWORD_TYPES
                else None
            )
            try:
                kid = db.add_keyword(name, kw_type=kw_type)
            except ValueError as exc:
                return json_error(str(exc))
            # Queue/record the stored spelling: add_keyword normalizes
            # punctuation and applies the species casing convention, so it
            # can differ from the raw request name.
            stored = db.conn.execute(
                "SELECT name FROM keywords WHERE id = ?", (kid,)
            ).fetchone()
            if stored:
                name = stored["name"]
        # tag_photo is INSERT OR IGNORE, so a repeated Add click on a
        # keyword the photo already carries would still queue a
        # keyword_add sidecar change and record a keyword_add edit whose
        # undo calls untag_photo — removing the pre-existing tag. Skip
        # the pending/history bookkeeping when the row already exists, so
        # the second click is a true no-op (mirrors the batch route's
        # already_tagged precheck).
        already_tagged = db.conn.execute(
            "SELECT 1 FROM photo_keywords WHERE photo_id = ? AND keyword_id = ?",
            (photo_id, kid),
        ).fetchone() is not None
        if already_tagged:
            return jsonify({"ok": True, "keyword_id": kid})
        # source='manual': a person clicked Add. Stamping the association
        # itself keeps authorship recoverable after _prune_edit_history()
        # drops the keyword_add entry recorded just below.
        db.tag_photo(photo_id, kid, source='manual')
        _queue_keyword_add(photo_id, name)
        db.record_edit('keyword_add', f'Added keyword "{name}"', str(kid),
                       [{'photo_id': photo_id, 'old_value': '', 'new_value': str(kid)}])
        return jsonify({"ok": True, "keyword_id": kid})

    @app.route(
        "/api/photos/<int:photo_id>/keywords/<int:keyword_id>", methods=["DELETE"]
    )
    def api_remove_keyword(photo_id, keyword_id):
        db = _get_db()
        keywords = db.get_photo_keywords(photo_id)
        kw_name = ""
        for k in keywords:
            if k["id"] == keyword_id:
                kw_name = k["name"]
                break
        db.untag_photo(photo_id, keyword_id)
        _queue_keyword_remove(photo_id, kw_name)
        db.record_edit('keyword_remove', f'Removed keyword "{kw_name}"', str(keyword_id),
                       [{'photo_id': photo_id, 'old_value': str(keyword_id), 'new_value': ''}])
        return jsonify({"ok": True})

    @app.route("/api/selection/keyword-suggestions", methods=["POST"])
    def api_selection_keyword_suggestions():
        """Return selected keywords and which selected photos carry each one."""
        db = _get_db()
        body = request.get_json(silent=True) or {}
        photo_ids, err = _parse_selection_photo_ids(body)
        if err is not None:
            return err

        rows = []
        batch_size = 800
        for i in range(0, len(photo_ids), batch_size):
            chunk = photo_ids[i:i + batch_size]
            placeholders = ",".join("?" for _ in chunk)
            rows.extend(db.conn.execute(
                f"""SELECT pk.photo_id, k.id, k.name, k.type
                    FROM photo_keywords pk
                    JOIN keywords k ON k.id = pk.keyword_id
                    WHERE pk.photo_id IN ({placeholders})
                    ORDER BY LOWER(k.name), k.id""",
                chunk,
            ).fetchall())

        selected_count = len(photo_ids)
        by_keyword = {}
        for row in rows:
            entry = by_keyword.setdefault(
                row["id"],
                {
                    "id": row["id"],
                    "name": row["name"],
                    "type": row["type"],
                    "photo_ids": set(),
                },
            )
            entry["photo_ids"].add(row["photo_id"])

        keywords = []
        for entry in by_keyword.values():
            count = len(entry["photo_ids"])
            missing_count = selected_count - count
            present_photo_ids = [
                pid for pid in photo_ids if pid in entry["photo_ids"]
            ]
            missing_photo_ids = [
                pid for pid in photo_ids if pid not in entry["photo_ids"]
            ]
            item = {
                "id": entry["id"],
                "name": entry["name"],
                "type": entry["type"],
                "count": count,
                "missing_count": missing_count,
                "present_photo_ids": present_photo_ids,
                "missing_photo_ids": missing_photo_ids,
            }
            keywords.append(item)
        keywords.sort(
            key=lambda item: (-item["count"], item["name"].lower(), item["id"])
        )
        suggestions = [item for item in keywords if 0 < item["count"] < selected_count]
        return jsonify({
            "selected_count": selected_count,
            "keywords": keywords,
            "suggestions": suggestions,
        })

    def _prediction_consensus_species(row):
        """Species ``accept_prediction`` will actually apply for this row.

        Non-grouped predictions accept as their own ``species``. A grouped
        (burst) prediction accepts as the burst's winning species, derived
        from the per-individual vote counts stored in
        ``prediction_review.individual`` — a Robin/Robin/Sparrow burst
        accepts as Robin even from the minority Sparrow frame.

        The Browse panel and the selection aggregator both group by species,
        so they must group by *this* species — otherwise a minority frame
        surfaces a Sparrow Accept button that silently tags Robin. Kept as a
        module-level helper so the two callers stay in lockstep.
        """
        species = row["species"]
        if not row["group_id"] or not row["individual"]:
            return species
        try:
            votes = json.loads(row["individual"])
        except (TypeError, ValueError):
            return species
        if not isinstance(votes, dict) or not votes:
            return species
        try:
            return max(votes, key=lambda sp: votes[sp])
        except (TypeError, ValueError):
            return species

    def _effective_category_resolver(db, photo_ids):
        """Build ``(photo_id, species) -> category`` against *current* keywords.

        ``predictions.category`` is a snapshot of how the prediction compared
        to the photo's keywords at classification time, and nothing rewrites
        it when keywords change afterwards (the only writers are the classify
        path and duplicate merge). So a photo that gained a Robin keyword
        after a pending Sparrow prediction was stored as ``new`` still reads
        ``new`` — and Browse would offer a bare Accept that tags a species
        conflicting with what the photo already says. ``CORE_PHILOSOPHY.md``
        forbids exactly that: the button must mean what the user reads it as.

        Returns ``match``/``new``/``refinement``/``broader``/``conflict`` from
        ``compare_prediction_to_keywords`` — Compare's vocabulary, because
        this is Compare's computation, shared rather than reimplemented (see
        ``api_predictions_compare``). Callers treat
        ``refinement``/``broader``/``conflict`` as ambiguous, the same set
        Browse's ``predictionIsAmbiguous`` refuses to offer a bare Accept for.

        Two details are load-bearing and are the reason this goes through the
        same helpers Compare uses rather than a raw keyword query:

        * ``get_species_keywords_for_photos`` canonicalizes a hierarchy alias
          through its linked taxon's root, and ``resolve_species_display_name``
          does the same for the prediction label. Comparing raw
          ``keywords.name`` text would make a photo tagged with the leaf
          ``Desert Verdin`` read as *conflicting* with a ``Verdin``
          prediction whenever the taxonomy file is unavailable — inventing an
          ambiguity and sending a settled photo to Review.
        * the comparison runs on the species the accept path would actually
          apply (the burst consensus), not the row's own label.

        Returns None when no comparison is possible (compare or the photo set
        unavailable) so callers can fall back to the stored snapshot.
        """
        photo_ids = [pid for pid in dict.fromkeys(photo_ids) if pid is not None]
        if not photo_ids:
            return None
        try:
            from compare import compare_prediction_to_keywords
        except Exception:
            return None
        # Cached by mtime inside load_local_taxonomy, so this is a lookup on
        # the hot path rather than a re-parse per request. None degrades
        # compare_prediction_to_keywords to exact-text matching, which is
        # still current-state truth — better than a stale column either way,
        # and a missing or corrupt taxonomy file must never hard-fail the
        # endpoint.
        try:
            from taxonomy import load_local_taxonomy
            taxonomy = load_local_taxonomy()
        except Exception:
            taxonomy = None
        species_by_photo = db.get_species_keywords_for_photos(photo_ids)
        resolved = {}
        cache = {}

        def _category(photo_id, species):
            if not species or photo_id is None:
                return None
            if species not in resolved:
                try:
                    resolved[species] = db.resolve_species_display_name(species)
                except Exception:
                    resolved[species] = species
            key = (photo_id, resolved[species])
            if key not in cache:
                comparison = compare_prediction_to_keywords(
                    resolved[species],
                    species_by_photo.get(photo_id, []),
                    taxonomy,
                )
                cache[key] = (
                    comparison.get("category")
                    if isinstance(comparison, dict) else None
                )
            return cache[key]

        return _category

    _EFFECTIVE_AMBIGUOUS_CATEGORIES = frozenset(
        {"refinement", "broader", "conflict"}
    )
    # Stored-snapshot categories that mean the same thing, used only when no
    # fresh comparison is available.
    _STORED_AMBIGUOUS_CATEGORIES = frozenset({"disagreement", "refinement"})

    def _prediction_is_ambiguous(effective_category, stored_category):
        """Would a bare Accept here be dishonest?

        The fresh comparison wins outright when there is one. ORing it with
        the stored snapshot would make ambiguity a one-way ratchet: a photo
        whose conflicting keyword has since been removed would keep being
        routed to Review forever, naming a conflict that no longer exists —
        the same staleness bug in the other direction. The snapshot is the
        fallback for when no fresh comparison could be made at all.
        """
        if effective_category is not None:
            return effective_category in _EFFECTIVE_AMBIGUOUS_CATEGORIES
        return stored_category in _STORED_AMBIGUOUS_CATEGORIES

    def _ambiguous_prediction_ids(db, rows):
        """Which of ``rows`` a bare Accept must not act on.

        The one definition of "ambiguous" for the pair of endpoints that
        need it: the selection panel, which splits its payload into
        ``acceptable_prediction_ids`` and ``ambiguous_prediction_ids``, and
        ``batch-accept``, which re-derives the same verdict before writing.
        Two conditions, both of which mean a bare Accept would decide
        something the user has not been shown:

        * an ``alternative`` sibling on the row's ``(detection, model)`` —
          the classifier offered a runner-up, so accepting picks a winner on
          the user's behalf;
        * a disagreement/refinement against the photo's species keywords,
          judged by ``_prediction_is_ambiguous`` on the *current* keywords
          (see ``_effective_category_resolver`` for why the stored
          ``category`` column cannot be trusted for this).

        ``batch-accept`` recomputes rather than trusting the payload because
        the panel's split is a snapshot: a keyword added from Review, a
        second Browse tab, or an XMP sync between render and click makes a
        row ambiguous while it is still ``pending``, so the decided-status
        precondition alone cannot catch it. The panel's own refresh handles
        mutations inside one document; only the server sees the rest. This
        lives here — not once per endpoint — for the reason rounds 7 and 8
        established for the status precondition and the accept scope: a rule
        with two implementations is a rule that drifts.

        ``rows`` are prediction rows carrying ``id``, ``photo_id``,
        ``detection_id``, ``model``, ``category``, ``species``, ``group_id``
        and ``individual``. Returns the ambiguous subset of their ids.
        """
        rows = list(rows)
        if not rows:
            return set()
        photo_ids = list(dict.fromkeys(
            row["photo_id"] for row in rows if row["photo_id"] is not None
        ))
        # Keyed by (detection, model) exactly as /api/predictions nests
        # alternatives, so "has alternatives" means the same thing in Browse,
        # in this check, and in Review.
        alt_keys = {
            (row["detection_id"], row["model"])
            for row in db.get_predictions(
                photo_ids=photo_ids, status="alternative",
            )
        }
        effective_category_of = _effective_category_resolver(db, photo_ids)
        ambiguous = set()
        for row in rows:
            # Compared on the species the accept path would actually apply
            # (the burst consensus), not the row's own label.
            species = _prediction_consensus_species(row)
            effective_category = (
                effective_category_of(row["photo_id"], species)
                if effective_category_of is not None and species else None
            )
            if (
                (row["detection_id"], row["model"]) in alt_keys
                or _prediction_is_ambiguous(effective_category, row["category"])
            ):
                ambiguous.add(row["id"])
        return ambiguous

    def _parse_selection_photo_ids(body):
        """Validate a selection payload's ``photo_ids``.

        Returns ``(photo_ids, None)`` or ``(None, error_response)``. Shared by
        the keyword and prediction selection panels so both enforce the same
        cap and workspace scoping — a selection that is safe to read keywords
        for is exactly the selection that is safe to read predictions for.
        """
        db = _get_db()
        raw_ids = body.get("photo_ids", [])
        if not isinstance(raw_ids, list) or not raw_ids:
            return None, json_error("photo_ids required")

        photo_ids = []
        seen = set()
        for raw in raw_ids:
            if isinstance(raw, bool) or not isinstance(raw, int):
                return None, json_error("photo_ids must be integers")
            if raw not in seen:
                photo_ids.append(raw)
                seen.add(raw)
        if not photo_ids:
            return None, json_error("photo_ids required")
        if len(photo_ids) > _MAX_SELECTION_PHOTOS:
            return None, json_error("too many photo_ids", 400)

        for pid in photo_ids:
            if not db._photo_in_workspace(pid):
                return None, json_error(
                    f"Photo {pid} does not belong to the active workspace", 403
                )
        return photo_ids, None

    @app.route("/api/selection/prediction-suggestions", methods=["POST"])
    def api_selection_prediction_suggestions():
        """Aggregate pending predictions across a selection, grouped by species.

        The keyword panel next to this one answers "what have I already
        tagged"; this answers "what does the classifier think I should tag".
        Aggregation is by species match key rather than prediction id because
        each selected photo carries its own prediction row.

        Predictions the Browse panel must not offer a bare Accept for —
        those with an alternative sibling, or a disagreement/refinement
        against existing keywords — are returned separately in
        ``ambiguous_prediction_ids`` so the button can name the count it
        will actually act on. ``CORE_PHILOSOPHY.md`` forbids an "Accept on
        38" that quietly accepts 35.
        """
        db = _get_db()
        body = request.get_json(silent=True) or {}
        photo_ids, err = _parse_selection_photo_ids(body)
        if err is not None:
            return err

        # Apply the workspace's confidence floor, exactly as the single-photo
        # panel does. Without it a real catalog fills this list with 2%-and-up
        # noise wearing an actionable "Accept on 1" button. The hidden count
        # is reported rather than dropped.
        import config as cfg
        threshold = db.get_effective_config(cfg.load()).get(
            "classifier_confidence", 0.0
        ) or 0.0
        all_pending = db.get_predictions(photo_ids=photo_ids, status="pending")
        pending = [
            row for row in all_pending if (row["confidence"] or 0.0) >= threshold
        ]
        below_threshold_count = len(all_pending) - len(pending)
        # Which of these rows a bare Accept must not touch — an alternative
        # sibling, or a disagreement/refinement against the photo's *current*
        # species keywords. Computed by the same helper ``batch-accept``
        # re-runs before writing, so the button's promise and the endpoint's
        # precondition cannot describe different sets.
        ambiguous_row_ids = _ambiguous_prediction_ids(db, pending)

        order = {pid: i for i, pid in enumerate(photo_ids)}
        by_key = {}
        for row in pending:
            # Group by the species the accept path will actually apply, not
            # the raw per-frame label: for a burst whose frames disagree,
            # ``accept_prediction`` uses the individual-vote consensus, so a
            # Robin/Robin/Sparrow burst must aggregate under Robin — the
            # Sparrow minority frame would otherwise surface its own bucket
            # advertising an Accept button that tags Robin.
            species = _prediction_consensus_species(row)
            if not species:
                continue
            key = keyword_match_key(species) or species.casefold()
            entry = by_key.setdefault(key, {
                "species": species,
                "models": set(),
                "rows_by_photo": {},
                "confidences": [],
            })
            entry["models"].add(row["model"])
            # ``row["confidence"]`` is the classifier's confidence in the
            # row's own per-frame label. For a burst whose consensus differs
            # from that label — a Sparrow-labelled frame in a Robin-majority
            # burst — the raw score reflects Sparrow evidence, not Robin,
            # and pooling it under Robin would rank the bucket at Sparrow's
            # 95% and let the earlier threshold filter keep Robin actionable
            # on the strength of a vote for someone else. Only credit
            # confidence when the raw label agrees with the consensus.
            raw_species = row["species"]
            row_matches_consensus = bool(
                raw_species
                and (keyword_match_key(raw_species) or raw_species.casefold())
                == key
            )
            if row_matches_consensus:
                entry["confidences"].append(row["confidence"] or 0.0)
            ambiguous = row["id"] in ambiguous_row_ids
            # One photo can hold several detections of the same species, or
            # the same detection classified by several models. Keep every
            # matching prediction id so the batch accept flips them all —
            # keywording the photo once and leaving nothing pending in Review.
            # Submitting only the top-confidence id used to accept that row,
            # keyword the photo, and then hide the sibling rows behind the
            # "already keyworded" filter with no way to resolve them.
            photo_entry = entry["rows_by_photo"].setdefault(row["photo_id"], {
                "ids": [],
                "max_confidence": None,
                "ambiguous": False,
            })
            photo_entry["ids"].append((row["confidence"] or 0, row["id"]))
            if ambiguous:
                photo_entry["ambiguous"] = True
            if row_matches_consensus:
                conf = row["confidence"] or 0
                if (
                    photo_entry["max_confidence"] is None
                    or conf > photo_entry["max_confidence"]
                ):
                    photo_entry["max_confidence"] = conf

        # Resolve "already carries this species" against linked taxa, not
        # spelling, so a hierarchical Birds|Verdin tag counts as keyworded.
        # Look up existing rows only — asking here must not create keywords.
        kid_by_key = {}
        for row in db.conn.execute(
            "SELECT id, name FROM keywords WHERE is_species = 1 OR type = 'taxonomy'"
        ).fetchall():
            kid_by_key.setdefault(keyword_match_key(row["name"]), row["id"])

        results = []
        # A bucket-level suppression used to sit here: when the threshold was
        # active and ``entry["confidences"]`` came out empty, the bucket was
        # dropped and counted into a ``suppressed_borrowed_count`` the panel
        # rendered as its own empty state. Both are gone, because the state
        # they described is gone. ``confidences`` can only be empty when
        # *every* contributing row's raw label disagrees with the consensus
        # the accept path applies, and that is precisely the legacy shape
        # ``Database.repair_mixed_species_prediction_groups`` clears at
        # startup: after the repair a grouped row's consensus is its own
        # species, so every surviving row credits its own bucket. Keeping a
        # filter plus a second piece of empty-state vocabulary for an
        # unreachable case is its own transparency cost — the user would be
        # asked to learn a distinction the data can no longer produce.
        #
        # The credit gate above stays. It is four lines, it computes the
        # right number rather than hiding a row, and if the invariant it
        # rests on ever regressed it degrades to "confidence unknown"
        # instead of quoting one species' score beside another's name.
        for key, entry in by_key.items():
            predicted_ids = sorted(entry["rows_by_photo"], key=lambda p: order[p])
            kid = kid_by_key.get(key)
            keyworded = (
                db.get_photos_with_equivalent_species(predicted_ids, kid)
                if kid is not None else set()
            )
            missing_ids = [p for p in predicted_ids if p not in keyworded]
            # A pending prediction on an already-keyworded photo still has to
            # go somewhere: dropping it would leave Review holding the same
            # row the panel just told the user was "already keyworded", and
            # the user has no way to clear it from Browse. ``accept_prediction``
            # already supports a status-only accept — ``add_keyword`` is
            # idempotent and the ``already_has_species`` branch skips the
            # re-tag — so an unambiguous keyworded row is safe to include
            # here. Ambiguous keyworded rows still route to Review, same as
            # ambiguous missing ones, because their resolution needs Review's
            # full comparison UI.
            acceptable, ambiguous_ids, ambiguous_photos = [], [], []
            acceptable_photos = []
            for pid in predicted_ids:
                row = entry["rows_by_photo"][pid]
                # Highest confidence first so a stable, obvious order lands in
                # the payload (and any downstream truncation keeps the
                # strongest evidence per photo).
                ids_here = [
                    rid for _c, rid in sorted(row["ids"], reverse=True)
                ]
                if row["ambiguous"]:
                    ambiguous_ids.extend(ids_here)
                    ambiguous_photos.append(pid)
                else:
                    acceptable.extend(ids_here)
                    acceptable_photos.append(pid)
            # Photo-level count for the button label. A photo with several
            # matching detections contributes several ids to ``acceptable``, so
            # ``len(acceptable)`` overcounts the photos that would be touched.
            acceptable_photo_count = len(acceptable_photos)
            already_keyworded_acceptable = sum(
                1 for pid in acceptable_photos if pid in keyworded
            )
            results.append({
                "species": entry["species"],
                "models": sorted(entry["models"]),
                "predicted_count": len(predicted_ids),
                # Count of photos already carrying this species keyword. Kept
                # informational — the panel labels them so the user knows
                # some of the "Accept on N" targets will status-only flip
                # without re-tagging.
                "keyworded_count": len(predicted_ids) - len(missing_ids),
                # Subset of ``acceptable_photo_count`` whose keyword is
                # already present. Lets the UI say "already keyworded on M
                # of N" without recomputing the intersection client-side.
                "acceptable_keyworded_count": already_keyworded_acceptable,
                "predicted_photo_ids": predicted_ids,
                "missing_photo_ids": missing_ids,
                "prediction_ids": acceptable + ambiguous_ids,
                "acceptable_prediction_ids": acceptable,
                "acceptable_photo_ids": acceptable_photos,
                "acceptable_photo_count": acceptable_photo_count,
                "ambiguous_prediction_ids": ambiguous_ids,
                "ambiguous_photo_ids": ambiguous_photos,
                # ``confidences`` can be empty when every credit-eligible row
                # was a minority frame whose raw label disagreed with the
                # consensus (see above). ``None`` renders as
                # ``formatPredictionConfidence(null)`` → "confidence unknown"
                # rather than inventing a 0% or misattributing a minority
                # frame's score to the consensus species.
                "min_confidence": (
                    min(entry["confidences"]) if entry["confidences"] else None
                ),
                "max_confidence": (
                    max(entry["confidences"]) if entry["confidences"] else None
                ),
            })
        # Breadth first, then strength: the panel collapses to the top few, so
        # a species predicted on every selected photo at 100% must outrank one
        # predicted on the same photos at 20%.
        results.sort(key=lambda item: (
            -item["predicted_count"],
            -(item["max_confidence"] or 0.0),
            item["species"].lower(),
        ))
        return jsonify({
            "selected_count": len(photo_ids),
            "predictions": results,
            "threshold": threshold,
            "below_threshold_count": below_threshold_count,
        })

    @app.route("/api/selection/wildlife-state", methods=["POST"])
    def api_selection_wildlife_state():
        """Aggregate wildlife_excluded state across the full selection.

        The browse panel may hold IDs that are not yet loaded into the
        client-side grid (e.g. after "Select all matching"), so the counts
        must be derived server-side or the batch include/exclude controls
        would silently omit off-page photos and hide the buttons that
        should still be available for them.

        Any submitted IDs that are missing or outside the active workspace
        are reported as ``missing_count`` so the panel can surface an
        incomplete selection instead of implying the counts cover
        everything the user picked. Without that signal the state endpoint
        and the batch endpoint disagree on what "the selection" means and
        the panel can show actions for a subset that then fail when
        applied to the full list.
        """
        db = _get_db()
        body = request.get_json(silent=True) or {}
        raw_ids = body.get("photo_ids", [])
        if not isinstance(raw_ids, list):
            return json_error("photo_ids required")

        photo_ids = []
        seen = set()
        for raw in raw_ids:
            if isinstance(raw, bool) or not isinstance(raw, int):
                return json_error("photo_ids must be integers")
            if raw not in seen:
                photo_ids.append(raw)
                seen.add(raw)
        if not photo_ids:
            return jsonify({
                "requested_count": 0,
                "selected_count": 0,
                "included_count": 0,
                "excluded_count": 0,
                "missing_count": 0,
            })

        ws_id = db._ws_id()
        included = 0
        excluded = 0
        batch_size = 800
        for i in range(0, len(photo_ids), batch_size):
            chunk = photo_ids[i:i + batch_size]
            placeholders = ",".join("?" for _ in chunk)
            rows = db.conn.execute(
                f"""SELECT COALESCE(p.wildlife_excluded, 0) AS excluded
                    FROM photos p
                    WHERE p.id IN ({placeholders})
                      AND EXISTS (
                          SELECT 1 FROM workspace_folders wf
                          WHERE wf.folder_id = p.folder_id
                            AND wf.workspace_id = ?
                      )""",
                [*chunk, ws_id],
            ).fetchall()
            for row in rows:
                if row["excluded"]:
                    excluded += 1
                else:
                    included += 1

        accessible = included + excluded
        return jsonify({
            "requested_count": len(photo_ids),
            "selected_count": accessible,
            "included_count": included,
            "excluded_count": excluded,
            "missing_count": len(photo_ids) - accessible,
        })

    @app.route("/api/keywords/<int:keyword_id>", methods=["PUT"])
    def api_update_keyword(keyword_id):
        db = _get_db()
        body = request.get_json(silent=True) or {}
        # Capture old identity and tagged photos BEFORE the update: a rename
        # or retype can merge this row into a normalized same-slot peer, in
        # which case the original id and its photo_keywords rows are gone
        # afterwards (update_keyword returns the surviving id).
        old_row = db.conn.execute(
            """SELECT name, is_species, type
               FROM keywords WHERE id = ?""",
            (keyword_id,),
        ).fetchone()
        affected = []
        # Capture affected photos whenever a rename OR a retype is being
        # requested: update_keyword's merge-into-peer path can move photo
        # tags for either kind of change (a type-only PUT with an existing
        # same-name peer under the new type moves the tagged photos onto the
        # peer's stored spelling), and without the snapshot the
        # keyword_remove/keyword_add sidecar queueing below iterates an
        # empty list and XMP keeps exporting the old spelling until another
        # edit occurs.
        if body.get("name") or body.get("type"):
            affected = db.conn.execute(
                """SELECT pk.photo_id, wf.workspace_id
                   FROM photo_keywords pk
                   JOIN photos p ON p.id = pk.photo_id
                   JOIN workspace_folders wf ON wf.folder_id = p.folder_id
                   WHERE pk.keyword_id = ?""",
                (keyword_id,),
            ).fetchall()
        # Apply the update first — if it raises, no sidecar changes are queued
        try:
            effective_id = db.update_keyword(keyword_id, **body)
        except ValueError as e:
            return json_error(str(e), 400)
        # Queue sidecar updates only after a successful DB update, using the
        # STORED spelling of the surviving row — update_keyword normalizes
        # the requested name, so it can differ from the raw request value.
        new_row = db.conn.execute(
            """SELECT name, is_species, type
               FROM keywords WHERE id = ?""",
            (effective_id,),
        ).fetchone()
        if (
            old_row is not None and new_row is not None
            and old_row["name"] != new_row["name"]
        ):
            old_name = old_row["name"]
            new_name = new_row["name"]
            old_is_species_keyword = (
                old_row["is_species"] == 1 or old_row["type"] == "taxonomy"
            )
            new_is_species_keyword = (
                new_row["is_species"] == 1 or new_row["type"] == "taxonomy"
            )
            if old_is_species_keyword and new_is_species_keyword:
                pairs = [
                    (row["photo_id"], row["workspace_id"]) for row in affected
                ]
                db.rename_photo_preferences_species(
                    old_name,
                    new_name,
                    pairs,
                )
                db.rename_species_highlights_species(
                    old_name,
                    new_name,
                    pairs,
                )
            for row in affected:
                _queue_keyword_remove(row["photo_id"], old_name, workspace_id=row["workspace_id"])
                _queue_keyword_add(row["photo_id"], new_name, workspace_id=row["workspace_id"])
        # keywords.html's updateType/renameKeyword/bulk-apply handlers refetch
        # only when `merged` is truthy; without it the UI keeps the deleted
        # source id and its next edit/delete would 404 or hit the wrong row.
        merged = effective_id != keyword_id
        return jsonify({"ok": True, "keyword_id": effective_id, "merged": merged})

    @app.route("/api/keywords/<int:keyword_id>", methods=["DELETE"])
    def api_delete_keyword(keyword_id):
        db = _get_db()
        # Queue sidecar removals for all affected workspaces
        kw_row = db.conn.execute(
            "SELECT name FROM keywords WHERE id = ?", (keyword_id,)
        ).fetchone()
        if kw_row:
            affected = db.conn.execute(
                """SELECT pk.photo_id, wf.workspace_id
                   FROM photo_keywords pk
                   JOIN photos p ON p.id = pk.photo_id
                   JOIN workspace_folders wf ON wf.folder_id = p.folder_id
                   WHERE pk.keyword_id = ?""",
                (keyword_id,),
            ).fetchall()
            for row in affected:
                _queue_keyword_remove(row["photo_id"], kw_row["name"], workspace_id=row["workspace_id"])
        db.conn.execute("UPDATE keywords SET parent_id = NULL WHERE parent_id = ?", (keyword_id,))
        db.conn.execute("DELETE FROM photo_keywords WHERE keyword_id = ?", (keyword_id,))
        db.conn.execute("DELETE FROM keywords WHERE id = ?", (keyword_id,))
        db.conn.commit()
        return jsonify({"ok": True})

    def _summarize_details(details):
        """Build a short human-friendly summary string from a Place Details dict.

        Format: ``"<leaf name> · <broadest 1-2 parents>"``. Google's
        ``address_components`` are ordered narrowest-first, so the broadest
        parents (country, state) sit at the END of the list. We pick at most
        the last two, dedupe against the leaf name, and join with " · ".

        Examples::

            "Central Park · New York · United States"
            "Some Lighthouse · Iceland"
            "JustALeaf"  # if no usable parent components
        """
        leaf = (details or {}).get("name", "") or ""
        components = (details or {}).get("address_components") or []

        # Broadest 1-2 parents = last two components (Google orders broad-last).
        tail = components[-2:] if len(components) >= 2 else components[-1:]
        # Walk in reverse so we render broadest-first to broader-second
        # ("New York · United States" reads better than "United States · New York"
        # given the leaf comes first; iNaturalist uses leaf-then-narrowest-up).
        # Actually: leaf · narrowest-parent · ... · broadest-parent reads most
        # naturally for breadcrumbs. So reverse the tail so the closest parent
        # is first.
        parts = [leaf] if leaf else []
        for comp in reversed(tail):
            name = (comp or {}).get("name") or (comp or {}).get("long_name") or ""
            if not name:
                continue
            if name == leaf or name in parts:
                continue
            parts.append(name)

        if not parts:
            return ""
        return " · ".join(parts)

    def _coerce_place_id(candidate):
        """Return a stripped string ``place_id`` for any JSON scalar value."""
        if candidate is None:
            return ""
        if isinstance(candidate, str):
            return candidate.strip()
        return str(candidate).strip()

    def _extract_place_id(body):
        """Extract ``place_id`` from top-level or nested client place payloads."""
        candidate = body.get("place_id")
        if candidate is None and isinstance(body.get("place"), dict):
            candidate = body["place"].get("place_id")
        if candidate is None and isinstance(body.get("details"), dict):
            candidate = body["details"].get("place_id")
        return _coerce_place_id(candidate)

    def _extract_keyword_id(body):
        """Return an integer keyword_id from a JSON body, or None."""
        candidate = body.get("keyword_id")
        if candidate is None:
            return None
        if isinstance(candidate, bool):
            return None
        if isinstance(candidate, int):
            return candidate
        if isinstance(candidate, str):
            stripped = candidate.strip()
            if stripped.isdigit():
                return int(stripped)
        return None

    def _location_keyword_edit_error(db, keyword_id):
        """Return an error response unless ``keyword_id`` is a location keyword."""
        if keyword_id is None:
            return json_error("invalid keyword_id", 400)
        row = db.conn.execute(
            "SELECT id, type FROM keywords WHERE id = ?", (keyword_id,),
        ).fetchone()
        if row is None:
            return _keyword_not_found_error()
        if row["type"] != "location":
            return json_error("keyword is not a location", 400)
        return None

    def _normalize_client_place_details(body):
        """Normalize a Google Maps JS Place payload from the request body.

        Browser autocomplete already receives geometry and address components
        when the Maps JS key is valid. Accepting that payload avoids a second
        server-side Place Details request, which can fail for correctly
        referrer-restricted browser keys.
        """
        raw = body.get("place") or body.get("details")
        if not isinstance(raw, dict):
            return None

        place_id = _coerce_place_id(raw.get("place_id"))
        if not place_id:
            return None
        body_place_id = _coerce_place_id(body.get("place_id"))
        if body_place_id and body_place_id != place_id:
            return None

        def first_present(*values):
            for value in values:
                if value is not None:
                    return value
            return None

        geometry = raw.get("geometry")
        geometry_location = {}
        if isinstance(geometry, dict):
            location = geometry.get("location")
            if isinstance(location, dict):
                geometry_location = location
        lat_value = first_present(
            raw.get("lat"),
            raw.get("latitude"),
            geometry_location.get("lat") if isinstance(geometry_location, dict) else None,
        )
        lng_value = first_present(
            raw.get("lng"),
            raw.get("longitude"),
            geometry_location.get("lng") if isinstance(geometry_location, dict) else None,
        )
        try:
            lat = float(lat_value)
            lng = float(lng_value)
        except (TypeError, ValueError):
            return None
        if (
            not math.isfinite(lat)
            or not math.isfinite(lng)
            or lat < -90
            or lat > 90
            or lng < -180
            or lng > 180
        ):
            return None

        raw_components = raw.get("address_components")
        if not isinstance(raw_components, list):
            raw_components = []
        components = []
        for comp in raw_components:
            if not isinstance(comp, dict):
                continue
            name = comp.get("name") or comp.get("long_name") or ""
            if not name:
                continue
            types = comp.get("types")
            if not isinstance(types, list):
                types = []
            components.append({
                "name": name,
                "short_name": comp.get("short_name") or "",
                "types": types,
            })

        raw_types = raw.get("types")
        if not isinstance(raw_types, list):
            raw_types = []

        return {
            "place_id": place_id,
            "name": raw.get("name") or raw.get("formatted_address") or "",
            "types": raw_types,
            "lat": lat,
            "lng": lng,
            "address_components": components,
        }

    def _walk_parent_chain(db, leaf_parent_id):
        """Walk ``parent_id`` upward from ``leaf_parent_id`` to the root.

        Returns a list of ``{"id": int, "name": str}`` dicts in broadest →
        narrowest order, EXCLUDING the leaf itself. Pass the leaf's
        ``parent_id`` (i.e. the *first* parent), not the leaf's own id.

        Depth cap of 10 — chains are bounded ~5 in practice, but guard
        against pathological/malformed cycles (link_keyword_to_place
        already prevents creating cycles, but a corrupted DB could).
        """
        parents = []
        current_parent_id = leaf_parent_id
        for _ in range(10):
            if current_parent_id is None:
                break
            row = db.conn.execute(
                "SELECT id, name, parent_id FROM keywords WHERE id = ?",
                (current_parent_id,),
            ).fetchone()
            if row is None:
                break
            parents.append({"id": row["id"], "name": row["name"]})
            current_parent_id = row["parent_id"]
        # Reverse so broadest (e.g. country) comes first, narrowest last.
        parents.reverse()
        return parents

    def _serialize_photo_location(db, photo_id):
        """Return a summary dict for the photo's current location keyword.

        The shape matches the JSON the location section UI expects::

            {
                "keyword_id":   int,
                "name":         str,
                "place_id":     str | None,
                "latitude":     float | None,
                "longitude":    float | None,
                "parent_chain": [{"id": int, "name": str}, ...],  # broadest -> narrowest, EXCLUDES leaf
            }

        Returns ``None`` if the photo has no ``type='location'`` keyword link.
        """
        leaf = db.conn.execute(
            "SELECT k.id, k.name, k.place_id, k.latitude, k.longitude, k.parent_id "
            "FROM photo_keywords pk "
            "JOIN keywords k ON k.id = pk.keyword_id "
            "WHERE pk.photo_id = ? AND k.type = 'location' "
            "LIMIT 1",
            (photo_id,),
        ).fetchone()
        if leaf is None:
            return None

        return {
            "keyword_id": leaf["id"],
            "name": leaf["name"],
            "place_id": leaf["place_id"],
            "latitude": leaf["latitude"],
            "longitude": leaf["longitude"],
            "parent_chain": _walk_parent_chain(db, leaf["parent_id"]),
        }

    def _serialize_photo_locations(db, photo_ids):
        """Bulk form of :func:`_serialize_photo_location`.

        Sync review can contain thousands of location changes.  Looking up
        each leaf and then walking the same parent chain once per photo turns
        that review into tens of thousands of SQLite queries.  Fetch leaves
        in chunks and reuse each distinct hierarchy instead.
        """
        if not photo_ids:
            return {}

        leaves = {}
        # Keep the first linked location, matching the single-photo helper's
        # LIMIT 1 behavior without relying on a window-function result shape.
        for start in range(0, len(photo_ids), 400):
            chunk = photo_ids[start:start + 400]
            placeholders = ",".join("?" for _ in chunk)
            rows = db.conn.execute(
                f"""
                SELECT pk.photo_id, k.id, k.name, k.place_id, k.latitude,
                       k.longitude, k.parent_id
                FROM photo_keywords pk
                JOIN keywords k ON k.id = pk.keyword_id
                WHERE pk.photo_id IN ({placeholders})
                  AND k.type = 'location'
                ORDER BY pk.rowid
                """,
                chunk,
            ).fetchall()
            for row in rows:
                leaves.setdefault(row["photo_id"], row)

        chain_cache = {}
        result = {}
        for photo_id, leaf in leaves.items():
            parent_id = leaf["parent_id"]
            if parent_id not in chain_cache:
                chain_cache[parent_id] = _walk_parent_chain(db, parent_id)
            result[photo_id] = {
                "keyword_id": leaf["id"],
                "name": leaf["name"],
                "place_id": leaf["place_id"],
                "latitude": leaf["latitude"],
                "longitude": leaf["longitude"],
                "parent_chain": chain_cache[parent_id],
            }
        return result

    def _serialize_keyword(db, keyword_id):
        """Return a summary dict for a single ``type='location'`` keyword row.

        Same shape as :func:`_serialize_photo_location` (leaf fields + a
        broadest-first parent chain), but keyed on the keyword id directly
        rather than via a photo. Used by the ``link-place`` route, which
        operates on a keyword and isn't tied to a photo.

        Returns ``None`` if the keyword does not exist.
        """
        leaf = db.conn.execute(
            "SELECT id, name, place_id, latitude, longitude, parent_id "
            "FROM keywords WHERE id = ?",
            (keyword_id,),
        ).fetchone()
        if leaf is None:
            return None
        return {
            "keyword_id": leaf["id"],
            "name": leaf["name"],
            "place_id": leaf["place_id"],
            "latitude": leaf["latitude"],
            "longitude": leaf["longitude"],
            "parent_chain": _walk_parent_chain(db, leaf["parent_id"]),
        }

    # Location keywords don't propagate to dc:subject sidecars — structured XMP (exif:GPS*, Iptc4xmpCore:Location) is a future feature.
    @app.route("/api/photos/<int:photo_id>/location", methods=["POST"])
    def api_set_photo_location(photo_id):
        """Attach a Google place to ``photo_id`` via the autocomplete flow.

        Body: ``{"place_id": "ChIJ..."}``. Looks up the place via
        :func:`places.place_details`, upserts the leaf + parent chain into
        ``keywords``, and links the leaf to the photo (replacing any existing
        ``type='location'`` link).
        """
        body = request.get_json(silent=True) or {}
        keyword_id = _extract_keyword_id(body)
        place_id = _extract_place_id(body)
        if keyword_id is None and not place_id:
            return json_error("missing place_id", 400)

        db = _get_db()
        # Guard against stale clients (e.g. tab open after photo deleted).
        # Without this, set_photo_location's INSERT into photo_keywords
        # raises a FK IntegrityError that surfaces as a 500.
        edit_error = _photo_location_edit_error(db, photo_id)
        if edit_error is not None:
            return edit_error

        if keyword_id is not None:
            keyword_error = _location_keyword_edit_error(db, keyword_id)
            if keyword_error is not None:
                return keyword_error
            db.set_photo_location(photo_id, keyword_id)
            _queue_location_sync_if_enabled(photo_id)
            location = _serialize_photo_location(db, photo_id)
            db.record_edit(
                'location_set',
                f"set location: {location.get('name', 'unknown') if location else 'unknown'}",
                str(keyword_id),
                [{'photo_id': photo_id, 'old_value': '', 'new_value': str(keyword_id)}],
            )
            return jsonify({"location": location})

        details = _normalize_client_place_details(body)
        if details is None:
            import config as cfg
            maps_config = cfg.load()
            key = maps_config.get("google_maps_api_key", "")
            if not key:
                return _google_maps_not_configured_error()
            details = _google_place_details(
                place_id,
                key,
                _google_maps_result_language(maps_config),
            )
            if details is None:
                return _google_place_not_found_error()

        try:
            leaf_id = db.upsert_place_chain(details)
        except RuntimeError as err:
            # _upsert_one_keyword raises RuntimeError when the parent-chain
            # build hits an existing keyword of a different type at the same
            # (name, parent_id). Mirror /api/keywords/<id>/link-place's 409.
            return _location_name_conflict_response(err)
        db.set_photo_location(photo_id, leaf_id)
        _queue_location_sync_if_enabled(photo_id)
        db.record_edit(
            'location_set',
            f"set location: {details.get('name', 'unknown')}",
            str(leaf_id),
            [{'photo_id': photo_id, 'old_value': '', 'new_value': str(leaf_id)}],
        )
        return jsonify({"location": _serialize_photo_location(db, photo_id)})

    @app.route("/api/photos/<int:photo_id>/location/text", methods=["POST"])
    def api_set_photo_location_text(photo_id):
        """Attach a free-text location keyword (no Google data) to ``photo_id``.

        Body: ``{"name": "the meadow behind the cabin"}``. Used when the user
        types a name and hits Enter without picking a Google suggestion, or
        when no API key is configured. Reuses the ``location_set`` audit
        action_type so the audit log filters consistently across both paths.
        """
        body = request.get_json(silent=True) or {}
        name = body.get("name") or ""
        if not name.strip():
            return json_error("missing name", 400)
        stripped = name.strip()
        latitude = body.get("latitude")
        longitude = body.get("longitude")
        if (latitude is None) != (longitude is None):
            return json_error("latitude and longitude must be provided together", 400)
        if latitude is not None:
            try:
                latitude = float(latitude)
                longitude = float(longitude)
            except (TypeError, ValueError):
                return json_error("invalid coordinates", 400)
            if (
                not math.isfinite(latitude)
                or not math.isfinite(longitude)
                or not -90 <= latitude <= 90
                or not -180 <= longitude <= 180
            ):
                return json_error("invalid coordinates", 400)

        db = _get_db()
        edit_error = _photo_location_edit_error(db, photo_id)
        if edit_error is not None:
            return edit_error
        try:
            leaf_id = db.get_or_create_text_location(stripped)
        except ValueError:
            # Defensive: validation above should already catch empty input.
            return json_error("missing name", 400)
        if latitude is not None:
            db.conn.execute(
                "UPDATE keywords SET latitude = COALESCE(latitude, ?), "
                "longitude = COALESCE(longitude, ?) WHERE id = ?",
                (latitude, longitude, leaf_id),
            )
            db.conn.commit()
        db.set_photo_location(photo_id, leaf_id)
        _queue_location_sync_if_enabled(photo_id)
        db.record_edit(
            'location_set',
            f"set location: {stripped}",
            str(leaf_id),
            [{'photo_id': photo_id, 'old_value': '', 'new_value': str(leaf_id)}],
        )
        return jsonify({"location": _serialize_photo_location(db, photo_id)})

    @app.route("/api/batch/location/text", methods=["POST"])
    def api_batch_set_photo_location_text():
        """Attach one free-text location keyword to multiple photos."""
        body = request.get_json(silent=True) or {}
        raw_ids = body.get("photo_ids", [])
        if not isinstance(raw_ids, list) or not raw_ids:
            return json_error("photo_ids required", 400)

        photo_ids = []
        seen = set()
        for raw in raw_ids:
            if isinstance(raw, bool) or not isinstance(raw, int):
                return json_error("photo_ids must contain only integers", 400)
            if raw not in seen:
                photo_ids.append(raw)
                seen.add(raw)
        if not photo_ids:
            return json_error("photo_ids required", 400)
        if len(photo_ids) > 1000:
            return json_error("too many photo_ids", 400)

        name = body.get("name") or ""
        if not name.strip():
            return json_error("missing name", 400)
        stripped = name.strip()
        latitude = body.get("latitude")
        longitude = body.get("longitude")
        if (latitude is None) != (longitude is None):
            return json_error("latitude and longitude must be provided together", 400)
        if latitude is not None:
            try:
                latitude = float(latitude)
                longitude = float(longitude)
            except (TypeError, ValueError):
                return json_error("invalid coordinates", 400)
            if (
                not math.isfinite(latitude)
                or not math.isfinite(longitude)
                or not -90 <= latitude <= 90
                or not -180 <= longitude <= 180
            ):
                return json_error("invalid coordinates", 400)

        db = _get_db()
        for pid in photo_ids:
            edit_error = _photo_location_edit_error(db, pid)
            if edit_error is not None:
                return edit_error

        try:
            leaf_id = db.get_or_create_text_location(stripped)
        except ValueError:
            return json_error("missing name", 400)
        if latitude is not None:
            # A custom name chosen from the map should be available as a
            # nearby saved suggestion next time. Preserve an existing
            # location's established map point when the name is reused.
            db.conn.execute(
                "UPDATE keywords SET latitude = COALESCE(latitude, ?), "
                "longitude = COALESCE(longitude, ?) WHERE id = ?",
                (latitude, longitude, leaf_id),
            )
            db.conn.commit()

        items = []
        for pid in photo_ids:
            db.set_photo_location(pid, leaf_id)
            _queue_location_sync_if_enabled(pid, _commit=False)
            items.append({
                "photo_id": pid,
                "old_value": "",
                "new_value": str(leaf_id),
            })
        if items:
            db.record_edit(
                "location_set",
                f"set location: {stripped} on {len(items)} photos",
                str(leaf_id),
                items,
                is_batch=True,
                _commit=False,
            )
        db.conn.commit()
        db._prune_edit_history()
        return jsonify({
            "ok": True,
            "updated": len(items),
            "location": _serialize_photo_location(db, photo_ids[0]),
        })

    @app.route("/api/batch/location", methods=["POST"])
    def api_batch_set_photo_location():
        """Attach one Google place location to multiple photos."""
        body = request.get_json(silent=True) or {}
        raw_ids = body.get("photo_ids", [])
        if not isinstance(raw_ids, list) or not raw_ids:
            return json_error("photo_ids required", 400)

        photo_ids = []
        seen = set()
        for raw in raw_ids:
            if isinstance(raw, bool) or not isinstance(raw, int):
                return json_error("photo_ids must contain only integers", 400)
            if raw not in seen:
                photo_ids.append(raw)
                seen.add(raw)
        if not photo_ids:
            return json_error("photo_ids required", 400)
        if len(photo_ids) > 1000:
            return json_error("too many photo_ids", 400)

        keyword_id = _extract_keyword_id(body)
