    @app.route("/api/places/reverse-geocode", methods=["GET"])
    def api_reverse_geocode():
        """Reverse-geocode (lat, lng) via Google, with a SQLite grid cache.

        Query params: ``lat``, ``lng`` (floats). Returns
        ``{"place_id": <str|null>, "summary": <str|null>}``.

        Cache layer is keyed on ~110m grid (see ``Database._reverse_geocode_grid``).
        A row with ``place_id=None`` is a cached negative — Google was previously
        asked and had no match, and we serve null without re-asking.

        When no ``google_maps_api_key`` is configured we degrade to ``null``
        WITHOUT writing to the cache. Caching null in that branch would make
        already-asked grids stay null forever once the user finally adds a
        key, which is exactly the wrong UX.
        """
        try:
            lat = float(request.args.get("lat", ""))
            lng = float(request.args.get("lng", ""))
        except (TypeError, ValueError):
            return json_error("invalid coords", 400)
        # float() accepts "nan" and "inf"; both blow up downstream in
        # _reverse_geocode_grid's int(round(...)). Reject explicitly.
        if not (math.isfinite(lat) and math.isfinite(lng)):
            return json_error("invalid coords", 400)

        import config as cfg

        maps_config = cfg.load()
        language = _google_maps_result_language(maps_config)
        db = _get_db()
        cached = db.reverse_geocode_cache_get(lat, lng)
        if cached is not None:
            language_matches, details = _decode_cached_reverse_geocode(
                cached, language,
            )
            if language_matches:
                if cached["place_id"] is None:
                    # Cached negative — Google previously had no match here.
                    return jsonify({"place_id": None, "summary": None})
                return jsonify({
                    "place_id": cached["place_id"],
                    "summary": _summarize_details(details),
                })

        # Cache miss.
        key = maps_config.get("google_maps_api_key", "")
        if not key:
            # Don't cache here — see docstring.
            return jsonify({"place_id": None, "summary": None})

        try:
            details = _google_reverse_geocode(lat, lng, key, language)
        except places.PlacesTransientError:
            # OVER_QUERY_LIMIT / REQUEST_DENIED / network blip — Google
            # may answer this later, so do NOT cache. Returning null here
            # just suppresses the EXIF suggestion for this request; the
            # next request will retry Google.
            app.logger.warning(
                "reverse_geocode transient failure for lat=%s lng=%s — not caching",
                lat, lng,
            )
            return jsonify({"place_id": None, "summary": None})

        cache_place_id = details.get("place_id") if details else None
        db.reverse_geocode_cache_put(
            lat, lng,
            place_id=cache_place_id,
            response_json=_encode_cached_reverse_geocode(details, language),
        )
        if details is None:
            return jsonify({"place_id": None, "summary": None})
        return jsonify({
            "place_id": cache_place_id,
            "summary": _summarize_details(details),
        })

    @app.route("/api/keywords/<int:keyword_id>/link-place", methods=["POST"])
    def api_link_keyword_to_place(keyword_id):
        """Attach Google place data to an existing keyword.

        Body: ``{"place_id": "ChIJ..."}``, optionally with a normalized
        ``place`` object from Google Maps JS autocomplete. When the client
        does not provide details, looks up the place via
        :func:`places.place_details` and delegates to
        :meth:`Database.link_keyword_to_place`, which UPDATEs the target row
        in-place — or, if another keyword already owns this ``place_id``,
        re-points the target's ``photo_keywords`` rows onto the canonical row
        and deletes the now-empty target.

        Response: ``{"keyword": <serialized leaf+chain>, "merged": <bool>}``.
        ``merged`` is True when an existing place-bearing row absorbed the
        target.

        Error modes:
        - 400 ``missing place_id`` — empty body.
        - 400 ``no_api_key`` — config has no ``google_maps_api_key``.
        - 404 ``place_not_found`` — Google had no record of ``place_id``.
        - 404 ``keyword_not_found`` — ``keyword_id`` doesn't exist.
        - 409 ``name_conflict`` — the parent chain would clash with an
          existing keyword of a different ``type`` at the same
          ``(name, parent_id)``. Carries a user-facing ``message`` plus an
          ``error_detail`` string from the underlying RuntimeError for
          debugging.
        """
        body = request.get_json(silent=True) or {}
        place_id = _extract_place_id(body)
        if not place_id:
            return json_error("missing place_id", 400)

        details = _normalize_client_place_details(body)
        if details is None:
            import config as cfg
            maps_config = cfg.load()
            key = maps_config.get("google_maps_api_key", "")
            if not key:
                return _google_maps_not_configured_error()
            details = _google_place_details(
                place_id,
                key,
                _google_maps_result_language(maps_config),
            )
            if details is None:
                return _google_place_not_found_error()

        db = _get_db()
        try:
            result = db.link_keyword_to_place(keyword_id, details)
        except ValueError as err:
            # Database raises ValueError both for "missing id" and "wrong
            # type". Distinguish so callers can tell a 404 from a 400.
            msg = str(err)
            if "is type" in msg:
                return jsonify({
                    "error": "wrong_keyword_type",
                    "code": "invalid_request",
                    "message": (
                        "Only location keywords can be linked to Google Maps "
                        "places."
                    ),
                    "error_detail": msg,
                    "request_id": getattr(g, "request_id", None),
                }), 400
            return _keyword_not_found_error()
        except RuntimeError as err:
            # _upsert_one_keyword raises RuntimeError when the parent-chain
            # build hits an existing keyword of a different type at the same
            # (name, parent_id). Surface the message for debugging.
            return _location_name_conflict_response(err)

        # Audit log: this action isn't tied to a single photo (it operates on
        # a keyword), so we omit the per-photo items list. ``photo_id`` in
        # ``edit_history_items`` is FK-constrained to ``photos.id``, so a
        # placeholder like 0 would IntegrityError. The ``new_value`` column on
        # the parent ``edit_history`` row carries the canonical keyword id;
        # the ``description`` carries the place name and the source-id pair.
        db.record_edit(
            'location_link',
            (
                f"linked keyword {keyword_id} to place: "
                f"{details.get('name', 'unknown')} "
                f"(canonical keyword_id={result['keyword_id']}, "
                f"merged={result['merged']})"
            ),
            str(result['keyword_id']),
            [],
        )

        photo_rows = db.conn.execute(
            """SELECT DISTINCT pk.photo_id, wf.workspace_id
               FROM photo_keywords pk
               JOIN photos p ON p.id = pk.photo_id
               JOIN workspace_folders wf ON wf.folder_id = p.folder_id
               WHERE pk.keyword_id = ?""",
            (result["keyword_id"],),
        ).fetchall()
        for row in photo_rows:
            _queue_location_sync_if_enabled(
                row["photo_id"],
                workspace_id=row["workspace_id"],
                _commit=False,
            )
        if photo_rows:
            db.conn.commit()

        return jsonify({
            "keyword": _serialize_keyword(db, result["keyword_id"]),
            "merged": result["merged"],
        })

    # -- Batch operations --

    @app.route("/api/batch/best-batch-flags", methods=["POST"])
    def api_batch_best_batch_flags():
        db = _get_db()
        body = request.get_json(silent=True) or {}
        best_photo_id = body.get("best_photo_id")
        reject_photo_ids = body.get("reject_photo_ids", [])
        if isinstance(best_photo_id, bool) or not isinstance(best_photo_id, int):
            return json_error("best_photo_id must be an integer")
        if not isinstance(reject_photo_ids, list):
            return json_error("reject_photo_ids must be a list")
        normalized_reject_ids = []
        seen_reject_ids = set()
        for pid in reject_photo_ids:
            if isinstance(pid, bool) or not isinstance(pid, int):
                return json_error("reject_photo_ids must contain only integers")
            if pid == best_photo_id:
                return json_error("best_photo_id cannot also be rejected")
            if pid not in seen_reject_ids:
                normalized_reject_ids.append(pid)
                seen_reject_ids.add(pid)

        desired_flags = {best_photo_id: "flagged"}
        desired_flags.update({pid: "rejected" for pid in normalized_reject_ids})
        photo_ids = list(desired_flags.keys())
        photos_map = db.get_photos_by_ids(photo_ids)
        if len(photos_map) != len(photo_ids):
            return json_error("One or more photos were not found", 404)
        try:
            for pid in photo_ids:
                db._verify_photo_in_workspace(pid)
        except ValueError as e:
            return json_error(str(e), 403)

        items = []
        for pid in photo_ids:
            new_flag = desired_flags[pid]
            old_flag = photos_map[pid]["flag"]
            db.conn.execute(
                "UPDATE photos SET flag = ? WHERE id = ?",
                (new_flag, pid),
            )
            db.queue_flag_change_if_enabled(pid, new_flag, _commit=False)
            items.append({
                "photo_id": pid,
                "old_value": old_flag,
                "new_value": new_flag,
            })
        reject_count = len(normalized_reject_ids)
        description = (
            f"Best Batch: flagged best photo and rejected {reject_count} "
            f"{'photo' if reject_count == 1 else 'photos'}"
        )
        db.record_edit(
            "flag",
            description,
            "best_batch_apply",
            items,
            is_batch=True,
            _commit=False,
        )
        db.conn.commit()
        db._prune_edit_history()
        return jsonify({
            "ok": True,
            "updated": len(items),
            "photos": {
                str(pid): {"flag": desired_flags[pid]}
                for pid in photo_ids
            },
        })

    @app.route("/api/batch/keyword", methods=["POST"])
    def api_batch_keyword():
        db = _get_db()
        body = request.get_json(silent=True) or {}
        photo_ids = body.get("photo_ids", [])
        keyword_id = body.get("keyword_id")
        name = body.get("name", "")
        name = name.strip() if isinstance(name, str) else ""
        if not photo_ids:
            return json_error("photo_ids required")
        if keyword_id is not None:
            if isinstance(keyword_id, bool) or not isinstance(keyword_id, int):
                return json_error("keyword_id must be an integer")
            keyword_row = db.conn.execute(
                "SELECT id, name FROM keywords WHERE id = ?", (keyword_id,)
            ).fetchone()
            if keyword_row is None:
                return json_error("keyword not found", 404)
            kid = keyword_row["id"]
            name = keyword_row["name"]
        else:
            if not name:
                return json_error("photo_ids and name required")
            # Route kw_type through add_keyword so its type-reconciliation logic
            # runs (preserves existing user-typed rows; only upgrades 'general').
            # See api_add_keyword for the rationale.
            kw_type_raw = body.get("type")
            kw_type = (
                kw_type_raw
                if isinstance(kw_type_raw, str) and kw_type_raw in KEYWORD_TYPES
                else None
            )
            try:
                kid = db.add_keyword(name, kw_type=kw_type)
            except ValueError as exc:
                return json_error(str(exc))
            # Queue/record the stored spelling (see api_add_keyword).
            stored = db.conn.execute(
                "SELECT name FROM keywords WHERE id = ?", (kid,)
            ).fetchone()
            if stored:
                name = stored["name"]

        already_tagged = set()
        batch_size = 800
        for i in range(0, len(photo_ids), batch_size):
            chunk = list(photo_ids[i:i + batch_size])
            placeholders = ",".join("?" for _ in chunk)
            existing_rows = db.conn.execute(
                f"""SELECT photo_id FROM photo_keywords
                    WHERE keyword_id = ? AND photo_id IN ({placeholders})""",
                [kid] + chunk,
            ).fetchall()
            already_tagged.update(row["photo_id"] for row in existing_rows)
        added_ids = [pid for pid in photo_ids if pid not in already_tagged]

        for pid in added_ids:
            # See api_add_keyword: an explicit user action stamps durable
            # provenance so pruned edit history cannot orphan authorship.
            db.tag_photo(pid, kid, source='manual')
            _queue_keyword_add(pid, name)
        items = [{'photo_id': pid, 'old_value': '', 'new_value': str(kid)} for pid in added_ids]
        if items:
            db.record_edit('keyword_add', f'Added "{name}" to {len(added_ids)} photos',
                           str(kid), items, is_batch=True)
        return jsonify({"ok": True, "updated": len(added_ids)})

    @app.route("/api/batch/wildlife-excluded", methods=["POST"])
    def api_batch_wildlife_excluded():
        """Include or exclude a selection from wildlife processing.

        Missing or out-of-workspace IDs are skipped rather than rejecting
        the entire batch so the endpoint stays consistent with
        ``/api/selection/wildlife-state``: the state endpoint aggregates
        over the accessible subset, and this endpoint applies the change
        to the same subset instead of failing when the panel-supplied
        selection contains a stray ID. The count of skipped IDs is
        returned so the caller can surface it in the same transparent way
        as the state endpoint's ``missing_count``.
        """
        db = _get_db()
        body = request.get_json(silent=True) or {}
        raw_ids = body.get("photo_ids", [])
        excluded = body.get("excluded")
        if not isinstance(raw_ids, list) or not raw_ids:
            return json_error("photo_ids required")
        if not isinstance(excluded, bool):
            return json_error("excluded must be a boolean")

        photo_ids = []
        seen = set()
        for raw in raw_ids:
            if isinstance(raw, bool) or not isinstance(raw, int):
                return json_error("photo_ids must be integers")
            if raw not in seen:
                photo_ids.append(raw)
                seen.add(raw)

        ws_id = db._ws_id()
        accessible_state = {}
        batch_size = 800
        for i in range(0, len(photo_ids), batch_size):
            chunk = photo_ids[i:i + batch_size]
            placeholders = ",".join("?" for _ in chunk)
            rows = db.conn.execute(
                f"""SELECT p.id, COALESCE(p.wildlife_excluded, 0) AS excluded
                    FROM photos p
                    WHERE p.id IN ({placeholders})
                      AND EXISTS (
                          SELECT 1 FROM workspace_folders wf
                          WHERE wf.folder_id = p.folder_id
                            AND wf.workspace_id = ?
                      )""",
                [*chunk, ws_id],
            ).fetchall()
            for row in rows:
                accessible_state[row["id"]] = int(row["excluded"])
        accessible_ids = [pid for pid in photo_ids if pid in accessible_state]
        skipped_count = len(photo_ids) - len(accessible_ids)

        desired = 1 if excluded else 0
        changed_ids = [
            photo_id
            for photo_id in accessible_ids
            if accessible_state[photo_id] != desired
        ]
        items = []
        for photo_id in changed_ids:
            old_value = "1" if accessible_state[photo_id] else "0"
            db.conn.execute(
                "UPDATE photos SET wildlife_excluded = ? WHERE id = ?",
                (desired, photo_id),
            )
            items.append({
                "photo_id": photo_id,
                "old_value": old_value,
                "new_value": "1" if excluded else "0",
            })

        if items:
            description = (
                "Excluded from wildlife classification"
                if excluded
                else "Included in wildlife classification"
            )
            db.record_edit(
                "wildlife_excluded",
                f"{description}: {len(items)} photos",
                "1" if excluded else "0",
                items,
                is_batch=True,
                _commit=False,
            )
            db.conn.commit()
            db._prune_edit_history()

        return jsonify({
            "ok": True,
            "updated": len(changed_ids),
            "wildlife_excluded": excluded,
            "photo_ids": changed_ids,
            "skipped_count": skipped_count,
        })

    @app.route("/api/batch/keyword-remove", methods=["POST"])
    def api_batch_keyword_remove():
        db = _get_db()
        body = request.get_json(silent=True) or {}
        photo_ids = body.get("photo_ids", [])
        keyword_id = body.get("keyword_id")
        if not isinstance(photo_ids, list) or not photo_ids:
            return json_error("photo_ids required")
        if isinstance(keyword_id, bool) or not isinstance(keyword_id, int):
            return json_error("keyword_id must be an integer")

        clean_ids = []
        seen = set()
        for raw in photo_ids:
            if isinstance(raw, bool) or not isinstance(raw, int):
                return json_error("photo_ids must be integers")
            if raw not in seen:
                clean_ids.append(raw)
                seen.add(raw)
        if not clean_ids:
            return json_error("photo_ids required")

        keyword_row = db.conn.execute(
            "SELECT id, name FROM keywords WHERE id = ?", (keyword_id,)
        ).fetchone()
        if keyword_row is None:
            return json_error("keyword not found", 404)

        for pid in clean_ids:
            if not db._photo_in_workspace(pid):
                return json_error(
                    f"Photo {pid} does not belong to the active workspace", 403
                )

        tagged_ids = []
        batch_size = 800
        for i in range(0, len(clean_ids), batch_size):
            chunk = clean_ids[i:i + batch_size]
            placeholders = ",".join("?" for _ in chunk)
            rows = db.conn.execute(
                f"""SELECT photo_id FROM photo_keywords
                    WHERE keyword_id = ? AND photo_id IN ({placeholders})""",
                [keyword_id] + chunk,
            ).fetchall()
            tagged_ids.extend(row["photo_id"] for row in rows)

        tagged_set = set(tagged_ids)
        removed_ids = [pid for pid in clean_ids if pid in tagged_set]
        name = keyword_row["name"]
        for pid in removed_ids:
            db.untag_photo(pid, keyword_id)
            _queue_keyword_remove(pid, name)

        items = [
            {"photo_id": pid, "old_value": str(keyword_id), "new_value": ""}
            for pid in removed_ids
        ]
        if items:
            db.record_edit(
                "keyword_remove",
                f'Removed "{name}" from {len(removed_ids)} photos',
                str(keyword_id),
                items,
                is_batch=True,
            )
        return jsonify({"ok": True, "updated": len(removed_ids)})

    def _run_batch_delete(
        db, photo_ids, mode="vireo", include_companions=False, paths=None,
        progress_callback=None,
    ):
        """Delete photos using the same phases for sync and job endpoints."""
        paths = paths or []

        def emit(
            phase, current=0, total=0, current_file="", detail="", failed=0,
            stage_failures=None,
        ):
            if progress_callback:
                payload = {
                    "phase": phase,
                    "current": current,
                    "total": total,
                    "current_file": current_file,
                    "detail": detail,
                    "failed": failed,
                }
                # ``stage_failures`` lets a single emit attribute failure counts
                # to specific stages so the frontend does not have to rely on
                # a specific per-stage emit having arrived first. The disk and
                # catalog phases each report their own count while Finishing
                # sends the merged map, so a dropped intermediate event cannot
                # silently promote a partial stage to green complete.
                if stage_failures:
                    payload["stage_failures"] = dict(stage_failures)
                progress_callback(payload)

        if mode == "disk_permanent" and paths:
            # Retry path: DB rows were already deleted by the initial
            # disk-mode call, so the photos table can't vouch for these
            # paths — but their parent directories still have folders rows.
            # Only delete files that live directly in a Vireo-managed
            # folder; anything else (a crafted request naming arbitrary
            # files) is refused, not removed.
            trashed = 0
            trash_failed = []
            total_paths = len(paths)
            emit("Deleting files permanently", 0, total_paths)
            for idx, p in enumerate(paths, start=1):
                if not isinstance(p, str) or not p:
                    emit("Deleting files permanently", idx, total_paths)
                    continue
                candidates = {os.path.dirname(p), os.path.dirname(os.path.realpath(p))}
                known = db.conn.execute(
                    f"SELECT 1 FROM folders WHERE path IN ({','.join('?' for _ in candidates)})",
                    list(candidates),
                ).fetchone()
                if not known:
                    log.warning(
                        "Refusing disk_permanent retry for path outside Vireo folders: %s", p
                    )
                    trash_failed.append({"path": p, "error": "not in a Vireo folder"})
                    emit("Deleting files permanently", idx, total_paths, os.path.basename(p))
                    continue
                if not os.path.isfile(p):
                    emit("Deleting files permanently", idx, total_paths, os.path.basename(p))
                    continue
                try:
                    os.remove(p)
                    trashed += 1
                except OSError:
                    log.warning("Permanent delete failed for %s", p, exc_info=True)
                    trash_failed.append({"path": p})
                emit("Deleting files permanently", idx, total_paths, os.path.basename(p))
            return {
                "ok": True, "deleted": 0, "trashed": trashed,
                "trash_failed": trash_failed,
            }

        if not photo_ids:
            raise ValueError("photo_ids required")
        if mode not in ("vireo", "disk", "disk_permanent"):
            raise ValueError("mode must be 'vireo', 'disk', or 'disk_permanent'")

        def remove_catalog_rows(ids, *, expand_companions, revalidate_identity=None):
            """Atomically remove resolved catalog rows, then clean caches.

            ``revalidate_identity`` is an optional ``{photo_id: (folder_id,
            filename, folder_path)}`` map captured at the start of the disk
            operation. When provided, each row is re-checked inside the delete
            transaction and skipped if any of those three fields has changed
            since — a concurrent ``/api/jobs/move-photos`` can commit a new
            ``folder_id`` while the disk-delete's stale-path
            ``os.path.isfile`` check is already reporting "gone", and a
            concurrent ``/api/jobs/move-folder`` can leave ``folder_id`` and
            ``filename`` unchanged while renaming the underlying
            ``folders.path``. Deleting by id alone in either case would
            discard the row for a photo that now lives at a completely
            different path. Skipped ids are returned as ``skipped_ids`` so
            the caller can surface them alongside filesystem failures.
            """
            result = {
                "deleted": 0, "ids": [], "files": [], "skipped_ids": [],
            }
            skipped_ids = []
            total = len(ids)
            prepared = 0
            emit(
                "Removing from Vireo", 0, total,
                detail="Preparing database changes; nothing is committed yet.",
            )
            revalidating = bool(revalidate_identity)
            # BEGIN IMMEDIATE takes the write lock up front so no other writer
            # (notably move-photos or move-folder) can commit an identity
            # change between the revalidation SELECT and the DELETE that
            # follows. Without it, a move committed after the SELECT but
            # before the DELETE would let us delete a row that no longer
            # matches the identity we verified.
            if revalidating:
                db.conn.execute("BEGIN IMMEDIATE")
            try:
                if revalidating:
                    verified_ids = []
                    for chunk in _chunked(ids):
                        placeholders = ",".join("?" for _ in chunk)
                        current = {
                            row["id"]: (
                                row["folder_id"],
                                row["filename"],
                                row["folder_path"],
                                row["companion_path"],
                            )
                            for row in db.conn.execute(
                                f"SELECT p.id, p.folder_id, p.filename, "
                                f"p.companion_path, f.path AS folder_path "
                                f"FROM photos p "
                                f"JOIN folders f ON f.id = p.folder_id "
                                f"WHERE p.id IN ({placeholders})",
                                list(chunk),
                            )
                        }
                        for photo_id in chunk:
                            expected = revalidate_identity.get(photo_id)
                            actual = current.get(photo_id)
                            if actual is None:
                                # Row already gone — a concurrent delete beat
                                # us to it. The requested end state already
                                # holds, so treat it as successfully deleted
                                # rather than a stale identity we couldn't
                                # verify. Reporting it in ``failed_photo_ids``
                                # here would leave the client showing a photo
                                # that is absent from both catalog and disk
                                # until reload.
                                continue
                            if expected is not None and actual == expected:
                                verified_ids.append(photo_id)
                            else:
                                skipped_ids.append(photo_id)
                    ids_to_delete = verified_ids
                else:
                    ids_to_delete = list(ids)

                for chunk in _chunked(ids_to_delete):
                    chunk_result = db.delete_photos(
                        chunk,
                        include_companions=expand_companions,
                        commit=False,
                    )
                    result["deleted"] += chunk_result["deleted"]
                    result["ids"].extend(chunk_result["ids"])
                    result["files"].extend(chunk_result["files"])
                    prepared += len(chunk)
                    emit(
                        "Removing from Vireo", min(prepared, total), total,
                        detail=(
                            "Preparing database changes; nothing is committed yet."
                        ),
                    )
                db.conn.commit()
            except Exception:
                db.conn.rollback()
                raise
            result["skipped_ids"] = skipped_ids

            emit(
                "Removed from Vireo", result["deleted"], result["deleted"],
                detail="Database changes committed.",
            )
            emit("Pruning pipeline cache", 0, 1)
            try:
                db.prune_pipeline_cache_for_ids(result["ids"])
            except BaseException as exc:
                _reraise_fatal_cleanup_error(exc)
                log.exception("Failed to prune pipeline cache after delete")
            emit("Pruning pipeline cache", 1, 1)

            def cache_progress(current, total_files, filename):
                emit("Cleaning cached files", current, total_files, filename)

            emit("Cleaning cached files", 0, len(result["files"]))
            _cleanup_cached_files_for_deleted_photos(
                result["files"], progress_callback=cache_progress,
            )
            return result

        # Database-only mode has no filesystem prerequisite and retains the
        # original all-or-nothing catalog transaction.
        if mode == "vireo":
            result = remove_catalog_rows(
                photo_ids, expand_companions=include_companions,
            )
            emit("Finishing", 1, 1)
            return {
                "ok": True,
                "deleted": result["deleted"],
                "trashed": 0,
                "trash_failed": [],
                "failed_photo_ids": [],
            }

        # Disk modes resolve paths without changing SQLite. A photo's catalog
        # row is removed only after its primary file reached the requested end
        # state. A companion without its own photo row is processed first; if
        # that fails, its primary is left untouched and its row remains
        # retryable.
        resolved = db.resolve_photos_for_delete(
            photo_ids, include_companions=include_companions,
        )
        files = resolved["files"]
        primary_paths = {
            f["photo_id"]: os.path.join(f["folder_path"], f["filename"])
            for f in files
        }
        # Snapshot each row's identity so the catalog-removal step can verify
        # the row still points at the same file it did when we resolved paths.
        # Without this, a concurrent /api/jobs/move-photos can commit a new
        # folder_id and remove the source file mid-run; our stale-path
        # os.path.isfile would then read "already gone" and we would delete
        # a row that now represents the moved file at a different location.
        # The folder_path is included so a concurrent /api/jobs/move-folder,
        # which keeps folder_id and filename unchanged while renaming
        # ``folders.path``, is also caught — otherwise the row would still be
        # deleted even though the copied file remains at the new path.
        # ``companion_path`` is included so a concurrent scan that pairs a
        # RAW with a JPEG mid-delete (scanner.py: ``UPDATE photos SET
        # companion_path`` on the primary, ``DELETE FROM photos`` on the
        # merged companion) is also caught — otherwise the primary's tuple
        # would still match, and we'd trash only the pre-pair paths and
        # remove the primary row, orphaning the newly-paired companion file
        # on disk with no catalog entry.
        resolved_identity = {
            f["photo_id"]: (
                f["folder_id"], f["filename"], f["folder_path"],
                f["companion_path"],
            )
            for f in files
        }
        catalog_primary_paths = set(primary_paths.values())
        extra_companions = {}
        if include_companions:
            for f in files:
                companion_path = f.get("companion_path")
                if not companion_path:
                    continue
                # ``companion_path`` is stored as either a relative filename
                # inside the same folder or an absolute path (see the same
                # resolution in new_images.py:35-40). Joining an absolute
                # path with the folder path would silently target the wrong
                # file — the disk op would either fail or, worse, trash the
                # wrong photo without ever pruning the correct catalog row.
                companion = (
                    companion_path if os.path.isabs(companion_path)
                    else os.path.join(f["folder_path"], companion_path)
                )
                if companion not in catalog_primary_paths:
                    extra_companions.setdefault(f["photo_id"], set()).add(companion)

        disk_phase = (
            "Moving files to Trash"
            if mode == "disk" else "Deleting files permanently"
        )
        all_disk_paths = list(dict.fromkeys(
            [path for paths_for_id in extra_companions.values() for path in paths_for_id]
            + list(primary_paths.values())
        ))
        emit(disk_phase, 0, len(all_disk_paths))

        disk_paths_finished = 0

        def operate(paths_to_change):
            nonlocal disk_paths_finished
            if not paths_to_change:
                return 0, set(), []
            if mode == "disk":
                progress_offset = disk_paths_finished

                def trash_progress(current, _total, filename):
                    emit(
                        disk_phase, progress_offset + current,
                        len(all_disk_paths), filename,
                    )

                result = _trash_paths(
                    paths_to_change, progress_callback=trash_progress,
                )
                disk_paths_finished += len(paths_to_change)
                return result
            successful = set()
            failures = []
            removed = 0
            # Snapshot each parent's st_dev before deletion so a mount that
            # vanishes mid-batch can be detected even when the mount point
            # remains visible on the underlying local FS (see
            # ``_snapshot_parent_device``).
            parent_devs = {
                path: _snapshot_parent_device(path)
                for path in paths_to_change
            }
            for filepath in paths_to_change:
                if not os.path.isfile(filepath):
                    # Same live-parent gate as ``_trash_paths`` — a
                    # disconnected mount also makes ``os.path.isfile``
                    # return False, and treating that as "already gone"
                    # would prune the catalog row for a photo that
                    # reappears when the volume comes back.
                    if _path_confirmed_gone(
                        filepath, parent_devs.get(filepath),
                    ):
                        log.warning("File already missing: %s", filepath)
                        successful.add(filepath)
                    else:
                        log.warning(
                            "Permanent delete preflight: source "
                            "unreachable for %s", filepath,
                        )
                        failures.append({
                            "path": filepath,
                            "error": "Source path is unreachable",
                        })
                    disk_paths_finished += 1
                    emit(
                        disk_phase, disk_paths_finished,
                        len(all_disk_paths), os.path.basename(filepath),
                    )
                    continue
                try:
                    os.remove(filepath)
                    successful.add(filepath)
                    removed += 1
                except OSError as exc:
                    log.warning(
                        "Permanent delete failed for %s", filepath,
                        exc_info=True,
                    )
                    failures.append({"path": filepath, "error": str(exc)})
                disk_paths_finished += 1
                emit(
                    disk_phase, disk_paths_finished,
                    len(all_disk_paths), os.path.basename(filepath),
                )
            return removed, successful, failures

        companion_paths = list(dict.fromkeys(
            path for paths_for_id in extra_companions.values()
            for path in paths_for_id
        ))
        trashed, companion_success, companion_failures = operate(companion_paths)
        eligible_ids = {
            photo_id for photo_id in resolved["ids"]
            if extra_companions.get(photo_id, set()) <= companion_success
        }
        eligible_primary_paths = [
            primary_paths[photo_id] for photo_id in resolved["ids"]
            if photo_id in eligible_ids and photo_id in primary_paths
        ]
        primary_moved, primary_success, primary_failures = operate(
            eligible_primary_paths,
        )
        trashed += primary_moved
        successful_ids = [
            photo_id for photo_id in resolved["ids"]
            if photo_id in eligible_ids
            and primary_paths.get(photo_id) in primary_success
        ]
        successful_id_set = set(successful_ids)
        failed_ids = [
            photo_id for photo_id in resolved["ids"]
            if photo_id not in successful_id_set
        ]

        failure_by_path = {
            failure["path"]: failure
            for failure in companion_failures + primary_failures
        }
        trash_failed = []
        for photo_id in failed_ids:
            failed_paths = [
                path for path in extra_companions.get(photo_id, set())
                if path not in companion_success
            ]
            primary = primary_paths.get(photo_id)
            if not failed_paths and primary not in primary_success:
                failed_paths.append(primary)
            for filepath in failed_paths:
                detail = dict(failure_by_path.get(filepath) or {
                    "path": filepath,
                    "error": "A companion file could not be removed",
                })
                detail["photo_id"] = photo_id
                trash_failed.append(detail)

        disk_failed_photos = len(failed_ids)
        emit(
            disk_phase, len(all_disk_paths), len(all_disk_paths),
            detail=(
                f"{len(successful_ids)} photo(s) ready for catalog removal; "
                f"{disk_failed_photos} retained after filesystem errors."
            ),
            failed=disk_failed_photos,
            stage_failures={"files": disk_failed_photos},
        )
        result = remove_catalog_rows(
            successful_ids,
            expand_companions=False,
            revalidate_identity=resolved_identity,
        )
        # Rows whose identity changed between resolve and catalog-removal
        # weren't deleted — surface them alongside filesystem failures so
        # the client keeps them visible and doesn't report them as trashed.
        skipped_ids = result.get("skipped_ids", []) or []
        catalog_failed_photos = len(skipped_ids)
        if skipped_ids:
            already_failed = set(failed_ids)
            for photo_id in skipped_ids:
                trash_failed.append({
                    "photo_id": photo_id,
                    "path": primary_paths.get(photo_id, ""),
                    "error": (
                        "Photo was moved to a new folder during this delete; "
                        "the catalog row was preserved"
                    ),
                })
            failed_ids = failed_ids + [
                photo_id for photo_id in skipped_ids
                if photo_id not in already_failed
            ]
            # Re-emit the catalog stage with the retained count so the frontend
            # transitions it from complete → partial. Without this, the initial
            # "Removed from Vireo" event marks the stage green and Finishing
            # later carries a higher failed count that the frontend can't
            # attribute to any stage.
            emit(
                "Removed from Vireo",
                result["deleted"], result["deleted"] + catalog_failed_photos,
                detail=(
                    f"{catalog_failed_photos} photo(s) retained "
                    "due to concurrent moves."
                ),
                failed=catalog_failed_photos,
                stage_failures={"catalog": catalog_failed_photos},
            )
        emit(
            "Finishing", 1, 1,
            failed=len(failed_ids),
            stage_failures={
                "files": disk_failed_photos,
                "catalog": catalog_failed_photos,
            },
        )
        return {
            "ok": True,
            "deleted": result["deleted"],
            "trashed": trashed,
            "trash_failed": trash_failed,
            "failed_photo_ids": failed_ids,
        }

    @app.route("/api/batch/delete", methods=["POST"])
    def api_batch_delete():
        """Delete photos from Vireo, optionally moving files to trash."""
        db = _get_db()
        body = request.get_json(silent=True) or {}
        photo_ids = body.get("photo_ids", [])
        mode = body.get("mode", "vireo")
        include_companions = body.get("include_companions", False)
        # For disk_permanent retry: accept paths directly since DB rows
        # were already deleted in the initial disk-mode call.
        paths = body.get("paths", [])

        try:
            result = _run_batch_delete(
                db, photo_ids, mode, include_companions, paths=paths,
            )
        except ValueError as exc:
            return json_error(str(exc))
        if result.get("deleted"):
            _invalidate_missing_originals_cache()
        return jsonify(result)

    @app.route("/api/jobs/batch-delete", methods=["POST"])
    @background_job
    def api_job_batch_delete(ctx):
        """Start a background delete job with phase progress."""
        body = request.get_json(silent=True) or {}
        photo_ids = body.get("photo_ids", [])
        mode = body.get("mode", "vireo")
        include_companions = body.get("include_companions", False)
        paths = body.get("paths", [])

        if mode not in ("vireo", "disk", "disk_permanent"):
            return json_error("mode must be 'vireo', 'disk', or 'disk_permanent'")
        if not photo_ids and not (mode == "disk_permanent" and paths):
            return json_error("photo_ids required")

        def work(job):
            thread_db = ctx.thread_db()
            started = time.time()

            def progress(payload):
                current = payload.get("current", 0)
                total = payload.get("total", 0)
                job["progress"]["current"] = current
                job["progress"]["total"] = total
                job["progress"]["current_file"] = payload.get("current_file", "")
                ctx.runner.push_event(job["id"], "progress", {
                    **payload,
                    "rate": round(current / max(time.time() - started, 0.01), 1)
                    if current else 0,
                })

            try:
                result = _run_batch_delete(
                    thread_db,
                    photo_ids,
                    mode,
                    include_companions,
                    paths=paths,
                    progress_callback=progress,
                )
                if result.get("deleted"):
                    _invalidate_missing_originals_cache()
                return result
            finally:
                thread_db.conn.close()

        return ctx.start(
            "batch-delete",
            work,
            config={
                "photo_count": len(photo_ids or []),
                "mode": mode,
                "include_companions": bool(include_companions),
                "path_count": len(paths or []),
            },
        )

    # -- Undo --

    def _edit_recipe_history_updates(db, edit_id):
        from image_edits import recipe_to_json
        rows = db.conn.execute(
            "SELECT photo_id FROM edit_history_items WHERE edit_id = ?",
            (edit_id,),
        ).fetchall()
        photo_ids = [r["photo_id"] for r in rows]
        if not photo_ids:
            return {}
        _invalidate_photo_render_cache(db, photo_ids)
        updates = {}
        for photo_id in photo_ids:
            recipe = db.get_photo_edit_recipe(photo_id)
            updates[str(photo_id)] = recipe
            _queue_edit_recipe_sync(
                db, photo_id, recipe_to_json(recipe) or "",
            )
        return updates

    def _refresh_pipeline_cache_species_from_edit(db, entry):
        """Rewrite the pipeline cache's species fields to match the DB after
        undo / redo of a species-affecting edit.

        The ``/api/encounters/species`` route writes the new confirmed set
        onto its target burst (or encounter) and persists the cache in the
        same request, so undo / redo of that write leaves the cache showing
        the pre-undo confirmed set even though the DB tags have flipped. Read
        the affected photos' current species from the DB and rebuild the
        cache's per-photo, per-burst, and per-encounter species fields so a
        Process / Rapid Review reload matches what ``/api/encounters/species``
        would see now.
        """
        action = entry.get("action_type") if entry else None
        if action == "pipeline_grouping":
            # A species edit whose cache write changed the encounter
            # structure is recorded as a grouping edit wrapping the photo
            # edit; the grouping restore already put bursts and encounters
            # back from its snapshot, so only the per-photo lists remain.
            try:
                payload = json.loads(entry.get("new_value") or "{}")
            except (TypeError, ValueError):
                payload = {}
            if payload.get("photo_only"):
                # Retired after its cache snapshot went stale: the newer
                # cache belongs to a later analysis and must stay untouched;
                # only the photo edit was reversed.
                return
            action = (payload.get("photo_edit") or {}).get("action_type")
        if action not in ("species_replace", "keyword_add", "prediction_accept"):
            return
        photo_id_rows = db.conn.execute(
            "SELECT DISTINCT photo_id FROM edit_history_items WHERE edit_id = ?",
            (entry["id"],),
        ).fetchall()
        photo_ids = [r["photo_id"] for r in photo_id_rows if r["photo_id"] is not None]
        if not photo_ids:
            return
        try:
            species_by_photo = db.get_species_keywords_for_photos(photo_ids)
            # Photos with no surviving species tags must still be included so
            # the cache clears their confirmed_species_list — get_species_
            # keywords_for_photos omits them entirely.
            for pid in photo_ids:
                species_by_photo.setdefault(pid, [])
            from pipeline import refresh_cache_species_for_photos
            cache_dir = os.path.dirname(db_path)
            # Photos only: burst overrides and encounter fields are owned by
            # the grouping/species-confirm history entries (restored from
            # their recorded snapshots), and a plain keyword edit never
            # changed them.
            refresh_cache_species_for_photos(
                cache_dir, db._active_workspace_id, species_by_photo,
                photos_only=True,
            )
        except Exception:
            log.exception(
                "Failed to refresh pipeline cache species after undo/redo of %s",
                action,
            )
    def _history_flags_changed(db, entry):
        action = entry["action_type"]
        if action == "pipeline_grouping":
            action = (json.loads(entry["new_value"]).get("photo_edit") or {}).get("action_type")
        if action != "flag":
            return False
        return db.conn.execute(
            "SELECT 1 FROM edit_history_items WHERE edit_id = ? AND old_value != new_value LIMIT 1",
            (entry["id"],),
        ).fetchone() is not None

    @app.route("/api/undo", methods=["POST"])
    def api_undo():
        """Undo the most recent undoable edit.

        A prediction-decision route, so it takes the shared writer lock:
        ``prediction_accept`` entries restore ``prediction_review`` statuses,
        and undo is check-then-write like every other decision path — it reads
        the newest undoable entry, then rewrites the statuses that entry
        recorded. Without the lock it can restore a status on top of a batch
        decision that landed in between, and two overlapping undos can pick
        the same entry and apply it twice.
        """
        db = _get_db()
        undone = []

        def _apply():
            entry = db.undo_last_edit()
            if entry is None:
                return json_error("nothing to undo")
            undone.append(entry)
            return None

        from services.grouping_history import GroupingHistoryConflict

        try:
            early = _under_prediction_decision_lock(db, _apply)
        except GroupingHistoryConflict as exc:
            return json_error(str(exc), 409)
        if early is not None:
            return early
        result = undone[0]
        edit_recipe_updates = None
        if result.get("action_type") == "edit_recipe":
            # Deliberately outside the locked section: this queues XMP sync
            # rows and commits them itself, and it touches no prediction
            # state, so it has nothing to serialize against.
            edit_recipe_updates = _edit_recipe_history_updates(db, result["id"])
        _refresh_pipeline_cache_species_from_edit(db, result)
        response = {"ok": True, "undone": result["description"], "flags_changed": _history_flags_changed(db, result)}
        if edit_recipe_updates is not None:
            response["action_type"] = "edit_recipe"
            response["edit_recipes"] = edit_recipe_updates
        return jsonify(response)

    @app.route("/api/undo/status")
    def api_undo_status():
        db = _get_db()
        from db import Database
        non_undoable = Database._NON_UNDOABLE
        placeholders = ",".join("?" for _ in non_undoable)
        latest = db.conn.execute(
            f"SELECT id, description FROM edit_history WHERE workspace_id = ? AND undone = 0 AND action_type NOT IN ({placeholders}) "
            "ORDER BY created_at DESC, id DESC LIMIT 1",
            (db._ws_id(), *non_undoable),
        ).fetchone()
        if not latest:
            return jsonify({"available": False, "description": "", "count": 0})
        total = db.conn.execute(
            f"SELECT COUNT(*) FROM edit_history WHERE workspace_id = ? AND undone = 0 AND action_type NOT IN ({placeholders})",
            (db._ws_id(), *non_undoable),
        ).fetchone()[0]
        return jsonify({
            "available": True,
            "description": latest["description"],
            "id": latest["id"],
            "count": total,
        })

    @app.route("/api/redo", methods=["POST"])
    def api_redo():
        """Redo the most recently undone edit.

        Under the prediction decision lock for the reason ``api_undo`` gives.
        """
        db = _get_db()
        redone = []

        def _apply():
            entry = db.redo_last_undo()
            if entry is None:
                return json_error("nothing to redo")
            redone.append(entry)
            return None

        from services.grouping_history import GroupingHistoryConflict

        try:
            early = _under_prediction_decision_lock(db, _apply)
        except GroupingHistoryConflict as exc:
            return json_error(str(exc), 409)
        if early is not None:
            return early
        result = redone[0]
        edit_recipe_updates = None
        if result.get("action_type") == "edit_recipe":
            # Outside the locked section, for the reason ``api_undo`` gives.
            edit_recipe_updates = _edit_recipe_history_updates(db, result["id"])
        _refresh_pipeline_cache_species_from_edit(db, result)
        response = {"ok": True, "redone": result["description"], "flags_changed": _history_flags_changed(db, result)}
        if edit_recipe_updates is not None:
            response["action_type"] = "edit_recipe"
            response["edit_recipes"] = edit_recipe_updates
        return jsonify(response)

