    @app.route("/api/workspace/classification-inventory")
    def api_workspace_classification_inventory():
        """Per-(model × label-set) classification coverage for the active workspace.

        Builds a cross-product of downloaded or previously used classifier
        models × label sets on disk, merges in counts from `classifier_runs`, identifies
        stale rows (predictions whose fingerprint no longer matches any
        label file) and legacy rows (predictions from a model not in the
        current registry), and returns a structured payload for the
        dashboard inventory panel. See
        ``docs/plans/2026-05-06-classification-inventory-design.md``.
        """
        import config as cfg
        from labels import get_saved_labels, load_merged_labels, read_label_file
        from labels_fingerprint import TOL_SENTINEL, compute_fingerprint
        from models import get_models

        db = _get_db()
        ws_id = db._active_workspace_id
        if not ws_id:
            return json_error("No active workspace", status=400)
        ws = db.get_workspace(ws_id)
        min_conf = db.get_effective_config(cfg.load()).get(
            "detector_confidence", 0.2,
        )

        db_inv = db.get_classification_inventory(ws_id, min_conf=min_conf)
        total_dets = db_inv["total_real_detections"]
        db_pairs = {
            (p["classifier_model"], p["labels_fingerprint"]): p
            for p in db_inv["pairs"]
        }

        # Available label sets: read each saved .txt and recompute fingerprint
        # so the inventory's identity matches what the classify job would use.
        label_sets = []
        seen_paths = set()
        for ls in get_saved_labels():
            path = ls.get("labels_file", "")
            if not path or not os.path.exists(path) or path in seen_paths:
                continue
            seen_paths.add(path)
            try:
                species = read_label_file(path)
                if species.identities:
                    species = load_merged_labels([ls])
            except OSError:
                continue
            label_sets.append({
                "name": ls.get("name") or os.path.splitext(os.path.basename(path))[0],
                "path": path,
                "filename": os.path.basename(path),
                "fingerprint": compute_fingerprint(species),
            })

        # Dedupe by fingerprint: duplicate-content files (rename/copy) share a
        # fingerprint and the same db_pair stats. Emitting both rows would
        # double-count subtotals and inflate pending coverage. Keep the
        # alphabetically-first name as the canonical representative.
        deduped_by_fp = {}
        for ls in sorted(label_sets, key=lambda x: x["name"].lower()):
            deduped_by_fp.setdefault(ls["fingerprint"], ls)
        label_sets = list(deduped_by_fp.values())

        # Keep the full registry for identifying legacy and stale results.
        # Custom models without an explicit model_type default to bioclip
        # (same as classify/pipeline).
        from models import supports_tree_of_life
        all_models = [
            m for m in get_models()
            if m.get("model_type", "bioclip") in ("bioclip", "timm")
        ]

        models_out = []
        seen_keys = set()  # (model_name, fingerprint) we've placed in models_out
        used_model_names = {model_name for model_name, _fp in db_pairs}

        for m in all_models:
            model_name = m.get("name") or m.get("id")
            # Uninstalled models with no history in this workspace are not
            # pending work and should not inflate inventory coverage totals.
            if not m.get("downloaded") and model_name not in used_model_names:
                continue
            # Capability question — does this model TYPE ship ToL text
            # embeddings? Ask supports_tree_of_life(model_str), not the raw
            # `files` manifest: bioclip-2.5's ToL artifacts are declared
            # under `optional_files` so a straight `"tol_embeddings.npy" in
            # m.get("files", [])` would drop ToL coverage from this
            # inventory entirely — no current-pair emit and no stale-row
            # for prior ToL runs, because TOL_SENTINEL is always in
            # current_fps for the model.
            supports_tol = supports_tree_of_life(m.get("model_str", ""))
            is_closed_set = m.get("model_type") == "timm"

            pairs = []
            if is_closed_set:
                key = (model_name, TOL_SENTINEL)
                pairs.append(_inventory_pair(
                    label_set="(intrinsic)", label_set_path=None,
                    fingerprint=TOL_SENTINEL, is_tol=False, is_intrinsic=True,
                    db_pair=db_pairs.get(key, {}), total=total_dets,
                ))
                seen_keys.add(key)
            else:
                for ls in sorted(label_sets, key=lambda x: x["name"].lower()):
                    key = (model_name, ls["fingerprint"])
                    pairs.append(_inventory_pair(
                        label_set=ls["name"], label_set_path=ls["filename"],
                        fingerprint=ls["fingerprint"], is_tol=False,
                        is_intrinsic=False,
                        db_pair=db_pairs.get(key, {}), total=total_dets,
                    ))
                    seen_keys.add(key)
                if supports_tol:
                    key = (model_name, TOL_SENTINEL)
                    pairs.append(_inventory_pair(
                        label_set="Tree of Life", label_set_path=None,
                        fingerprint=TOL_SENTINEL, is_tol=True,
                        is_intrinsic=False,
                        db_pair=db_pairs.get(key, {}), total=total_dets,
                    ))
                    seen_keys.add(key)

            models_out.append({
                "id": m.get("id"),
                "name": model_name,
                "supports_tol": supports_tol,
                "downloaded": bool(m.get("downloaded")),
                "legacy": False,
                "subtotal": _inventory_subtotal(pairs),
                "pairs": pairs,
            })

        # Legacy: a (model, fp) in the DB whose model isn't in the current
        # registry. Group those rows under one entry per legacy model name.
        registry_names = {m.get("name") or m.get("id") for m in all_models}
        legacy_groups = {}
        for (model_name, fp), p in db_pairs.items():
            if model_name in registry_names:
                continue
            legacy_groups.setdefault(model_name, []).append((fp, p))
        for model_name, fp_pairs in sorted(legacy_groups.items()):
            pairs = []
            for fp, p in sorted(fp_pairs, key=lambda x: x[0]):
                pairs.append(_inventory_pair(
                    label_set=("Tree of Life" if fp == TOL_SENTINEL
                               else "fp:" + fp[:8]),
                    label_set_path=None, fingerprint=fp,
                    is_tol=(fp == TOL_SENTINEL), is_intrinsic=False,
                    db_pair=p, total=total_dets,
                ))
                seen_keys.add((model_name, fp))
            models_out.append({
                "id": None,
                "name": model_name,
                "supports_tol": False,
                "downloaded": False,
                "legacy": True,
                "subtotal": _inventory_subtotal(pairs),
                "pairs": pairs,
            })

        # Stale: a (current model, fingerprint) in the DB whose fingerprint
        # is not currently on disk and isn't TOL. Single-file fingerprints
        # come from the label_sets above; merged-set fingerprints come from
        # the labels_fingerprints sidecar (one row per distinct merge the
        # classify job has ever produced). A merged row is current if all
        # its sources still exist and re-merging them reproduces the same
        # fingerprint; otherwise the contents drifted and it's stale.
        current_fps = {ls["fingerprint"] for ls in label_sets} | {TOL_SENTINEL}
        for row in db.get_labels_fingerprints():
            sources = row.get("sources") or []
            if len(sources) <= 1:
                continue  # single-file already covered by label_sets
            if not all(os.path.exists(s) for s in sources):
                continue
            try:
                merged = load_merged_labels([{"labels_file": source} for source in sources])
            except OSError:
                continue
            if compute_fingerprint(merged) == row["fingerprint"]:
                current_fps.add(row["fingerprint"])
        stale = []
        for (model_name, fp), p in db_pairs.items():
            if model_name not in registry_names:
                continue  # legacy, already grouped
            if fp in current_fps:
                continue
            # The stale UI labels this column "Predictions", so report rows
            # from `predictions` (one per species) rather than distinct
            # detection IDs from `classifier_runs`. A top-k run with k species
            # per detection would otherwise undercount stale work.
            stale.append({
                "model": model_name,
                "fingerprint": fp,
                "stale_count": p.get("predictions_count", 0),
                "last_run": p.get("last_run"),
            })

        # Grand total: classified across all rows (including stale/legacy);
        # pending across the current cross-product only (forward-looking work).
        grand_classified_all = sum(
            p.get("classified_dets", 0) for p in db_inv["pairs"]
        )
        grand_pending = sum(
            pp["pending_dets"] for m in models_out
            for pp in m["pairs"] if not m["legacy"]
        )
        denom = grand_classified_all + grand_pending
        grand_coverage = (
            round(100.0 * grand_classified_all / denom, 1) if denom > 0 else 0.0
        )

        return jsonify({
            "workspace_id": ws_id,
            "workspace_name": ws["name"] if ws else None,
            "min_conf": min_conf,
            "total_real_detections": total_dets,
            "total_photos": db.count_photos(),
            "models": models_out,
            "stale": stale,
            "grand_total": {
                "classified_dets": grand_classified_all,
                "pending_dets": grand_pending,
                "coverage_pct": grand_coverage,
                "total_predictions_rows": db_inv["total_predictions_rows"],
            },
        })

    @app.route("/api/sync/status")
    def api_sync_status():
        db = _get_db()
        changes = db.get_pending_changes()
        change_type_counts = {}
        photo_ids = set()
        for change in changes:
            photo_ids.add(change["photo_id"])
            change_type = change["change_type"]
            change_type_counts[change_type] = (
                change_type_counts.get(change_type, 0) + 1
            )
        return jsonify(
            {
                "pending_count": len(changes),
                "pending_photo_count": len(photo_ids),
                "change_type_counts": change_type_counts,
            }
        )

    @app.route("/api/sync/preview")
    def api_sync_preview():
        """Preview pending changes with the XMP values they will replace.

        Supplying ``limit`` enables progressive photo pagination.  Omitting
        it retains the original all-at-once response for compatibility with
        existing API callers.
        """
        db = _get_db()
        raw_limit = request.args.get("limit")
        raw_offset = request.args.get("offset", "0")
        if raw_limit is None:
            if raw_offset != "0":
                return json_error("offset requires limit")
            limit = None
            offset = 0
        else:
            try:
                limit = int(raw_limit)
                offset = int(raw_offset)
            except (TypeError, ValueError):
                return json_error("limit and offset must be integers")
            if limit < 1 or limit > 200:
                return json_error("limit must be between 1 and 200")
            if offset < 0:
                return json_error("offset must be non-negative")

        requested_revision = request.args.get("revision")
        snapshot = _sync_preview_get_snapshot(
            db, db._ws_id(), requested_revision,
        )
        revision = snapshot["revision"]
        if requested_revision and requested_revision != revision:
            return json_error(
                "pending changes changed while the review was loading",
                409,
                code="sync_preview_changed",
                message="Pending changes changed. Restarting the review.",
            )

        all_photos = snapshot["all_photos"]
        total_photos = len(all_photos)
        total_changes = snapshot["total_changes"]
        change_type_counts = snapshot["change_type_counts"]
        if total_changes == 0:
            return jsonify({
                "photos": [],
                "total_changes": 0,
                "total_photos": 0,
                "change_type_counts": {},
                "offset": offset,
                "next_offset": None,
                "has_more": False,
                "revision": revision,
            })

        # Enrichment below mutates the per-change dicts (``creates_xmp_sidecar``,
        # ``presentation``, …), so copy the slice before touching it — the
        # underlying photos/changes lists live inside the cached snapshot and
        # are re-served across page requests for the same revision.
        page_slice = (
            all_photos
            if limit is None
            else all_photos[offset:offset + limit]
        )
        page_photos = [
            {
                "photo_id": photo["photo_id"],
                "filename": photo["filename"],
                "folder": photo["folder"],
                "changes": [dict(change) for change in photo["changes"]],
            }
            for photo in page_slice
        ]

        import config as cfg

        effective_config = db.get_effective_config(cfg.load())
        write_locations = bool(
            effective_config.get("write_assigned_location_to_xmp", False)
        )
        sync_flags = bool(effective_config.get("sync_flags_to_xmp", False))
        location_photo_ids = [
            photo["photo_id"]
            for photo in page_photos
            if any(change["type"] == "location" for change in photo["changes"])
        ]
        assigned_locations = _serialize_photo_locations(db, location_photo_ids)
        folder_accessibility = {}
        for photo in page_photos:
            xmp_path = os.path.join(
                photo["folder"],
                os.path.splitext(photo["filename"])[0] + ".xmp",
            )
            # Mirror the folder-accessibility guard in ``sync_to_xmp``: if
            # the photo's folder is offline (a common NAS case), sync
            # records the photo as ``folder not accessible`` and never
            # runs any writer, so the review must not present writes
            # against it either.
            folder = photo["folder"]
            if folder not in folder_accessibility:
                folder_accessibility[folder] = (
                    not bool(folder) or os.path.isdir(folder)
                )
            folder_offline = not folder_accessibility[folder]
            photo["folder_offline"] = folder_offline
            if folder_offline:
                # Skip filesystem access entirely — an unreachable XMP path
                # would just re-derive the same "no sidecar" fallback.
                metadata = {
                    "status": "folder_offline",
                    "keywords": set(),
                    "hierarchical_keywords": set(),
                    "rating": None,
                    "rating_writable": False,
                    "flag": None,
                    "location": None,
                    "previous_location": None,
                    "location_source": None,
                    "edit_recipe": None,
                }
            else:
                metadata = read_sync_preview_metadata(xmp_path)
            assigned_location = None
            if (
                not folder_offline
                and any(change["type"] == "location" for change in photo["changes"])
            ):
                assigned_location = assigned_locations.get(photo["photo_id"])
            # Map normalized-key -> original add value so a paired
            # keyword_remove can display the clean spelling the paired
            # ``write_sidecar`` will end up writing.
            keyword_add_values_by_key = {}
            for change in photo["changes"]:
                if change["type"] == "keyword_add" and change["value"]:
                    key = keyword_match_key(change["value"])
                    if key:
                        keyword_add_values_by_key.setdefault(
                            key, change["value"],
                        )
            keyword_add_keys = set(keyword_add_values_by_key.keys())
            for change in photo["changes"]:
                auto_includes_keyword_add = bool(
                    change["type"] in {"keyword_remove", "keyword_remove_flat"}
                    and keyword_match_key(change["value"]) in keyword_add_keys
                )
                change["auto_includes_keyword_add"] = (
                    auto_includes_keyword_add
                )
                change["paired_keyword_rename"] = bool(
                    change["type"] == "keyword_remove"
                    and auto_includes_keyword_add
                )
                # An offline folder never runs any writer, so nothing
                # creates a sidecar during that sync.
                change["creates_xmp_sidecar"] = (
                    not folder_offline
                    and (
                        auto_includes_keyword_add
                        or _sync_preview_change_creates_sidecar(
                            change,
                            sync_flags=sync_flags,
                            write_locations=write_locations,
                            assigned_location=assigned_location,
                        )
                    )
                )

            sidecar_will_exist = any(
                change["creates_xmp_sidecar"] for change in photo["changes"]
            )
            for change in photo["changes"]:
                paired_add_value = None
                if change["type"] == "keyword_remove" and change[
                    "paired_keyword_rename"
                ]:
                    paired_add_value = keyword_add_values_by_key.get(
                        keyword_match_key(change["value"])
                    )
                if (
                    change["change_type"] == "rating"
                    and not folder_offline
                    and not metadata.get("rating_writable")
                ):
                    change["rating_requires_sidecar"] = True
                    change["presentation_without_sidecar"] = (
                        _sync_preview_presentation(
                            change,
                            metadata,
                            assigned_location=assigned_location,
                            write_locations=write_locations,
                            sidecar_will_exist=False,
                            sync_flags=sync_flags,
                            paired_keyword_rename=change[
                                "paired_keyword_rename"
                            ],
                            paired_add_value=paired_add_value,
                        )
                    )
                    change["presentation_with_sidecar"] = (
                        _sync_preview_presentation(
                            change,
                            metadata,
                            assigned_location=assigned_location,
                            write_locations=write_locations,
                            sidecar_will_exist=True,
                            sync_flags=sync_flags,
                            paired_keyword_rename=change[
                                "paired_keyword_rename"
                            ],
                            paired_add_value=paired_add_value,
                        )
                    )
                    change["presentation"] = change[
                        "presentation_with_sidecar"
                        if sidecar_will_exist
                        else "presentation_without_sidecar"
                    ]
                    continue
                change["presentation"] = _sync_preview_presentation(
                    change,
                    metadata,
                    assigned_location=assigned_location,
                    write_locations=write_locations,
                    sync_flags=sync_flags,
                    paired_keyword_rename=change["paired_keyword_rename"],
                    paired_add_value=paired_add_value,
                    folder_offline=folder_offline,
                )

        page_end = offset + len(page_photos)
        has_more = page_end < total_photos
        result = {
            "photos": page_photos,
            "total_changes": total_changes,
            "total_photos": total_photos,
            "change_type_counts": change_type_counts,
            "offset": offset,
            "next_offset": page_end if has_more else None,
            "has_more": has_more,
            "revision": revision,
            "location_sync_enabled": write_locations,
        }
        # The sync dialog needs edit recipes for correctly versioned rendered
        # thumbnails, but not the species/life-list enrichment performed by
        # _attach_nested_edit_recipes.
        recipe_map = db.get_photo_edit_recipes(
            [photo["photo_id"] for photo in page_photos]
        )
        for photo in page_photos:
            photo["edit_recipe"] = recipe_map.get(photo["photo_id"])
        # A slow sidecar or network-folder read can leave the queue time to
        # change after the snapshot was validated above. Never mark the final
        # page complete from that stale snapshot: the client will restart the
        # progressive review on this existing conflict response.
        if (
            not has_more
            and _sync_preview_pending_fingerprint(db, db._ws_id())
            != snapshot["fingerprint"]
        ):
            return json_error(
                "pending changes changed while the review was loading",
                409,
                code="sync_preview_changed",
                message="Pending changes changed. Restarting the review.",
            )
        return jsonify(result)

    @app.route("/api/sync/discard", methods=["POST"])
    def api_sync_discard():
        """Discard specific pending changes."""
        db = _get_db()
        body = request.get_json(silent=True) or {}
        if body.get("discard_all") is True:
            revision = body.get("revision")
            if not isinstance(revision, str) or not revision:
                return json_error("revision required for discard_all")

            ws_id = db._ws_id()
            try:
                # Validate and delete under one write transaction. This keeps
                # another request from replacing or adding a pending row
                # between the revision check and the workspace-wide delete.
                db.conn.execute("BEGIN IMMEDIATE")
                snapshot = _sync_preview_get_snapshot(db, ws_id, revision)
                if snapshot["revision"] != revision:
                    db.conn.rollback()
                    return json_error(
                        "pending changes changed since they were reviewed",
                        409,
                        code="sync_preview_changed",
                        message=(
                            "Pending changes changed. Review them again before "
                            "discarding all."
                        ),
                    )
                changes = db.conn.execute(
                    "SELECT * FROM pending_changes WHERE workspace_id = ?",
                    (ws_id,),
                ).fetchall()
                db.conn.execute(
                    "DELETE FROM pending_changes WHERE workspace_id = ?",
                    (ws_id,),
                )
                db.clear_equivalent_flat_removals(changes, _commit=False)
                if changes:
                    items = _discard_history_items(db, changes)
                    db.record_edit(
                        "discard",
                        f"Discarded {len(changes)} pending changes",
                        "",
                        items,
                        is_batch=len(changes) > 1,
                        _commit=False,
                    )
                db.conn.commit()
            except Exception:
                db.conn.rollback()
                raise

            if changes:
                db._prune_edit_history()
            log.info("Discarded all %d pending changes", len(changes))
            return jsonify({"ok": True, "discarded": len(changes)})

        change_ids = body.get("change_ids", [])
        if not change_ids:
            return json_error("change_ids required")

        # Look up changes before deleting so we can record what was discarded.
        # Keep each IN clause below SQLite's bound-parameter limit, just as
        # clear_pending does for the subsequent delete.
        from db import _chunks  # noqa: PLC0415
        changes = []
        for chunk in _chunks(change_ids):
            placeholders = ",".join("?" for _ in chunk)
            changes.extend(db.conn.execute(
                f"SELECT * FROM pending_changes "
                f"WHERE id IN ({placeholders}) AND workspace_id = ?",
                list(chunk) + [db._ws_id()],
            ).fetchall())

        db.clear_pending(
            change_ids, clear_equivalent_flat_removals=True,
        )

        # Record discard in history (not undoable)
        if changes:
            items = _discard_history_items(db, changes)
            db.record_edit('discard',
                           f'Discarded {len(changes)} pending changes',
                           '', items, is_batch=len(changes) > 1)

        # Report what was actually deleted: clear_pending only removes rows
        # that exist in the active workspace, which is exactly the set the
        # SELECT above found.
        log.info("Discarded %d pending changes", len(changes))
        return jsonify({"ok": True, "discarded": len(changes)})

    # -- Collection API routes --

    @app.route("/api/collections")
    def api_collections():
        db = _get_db()
        collections = db.get_collections()
        result = []
        for c in collections:
            d = dict(c)
            # A single collection with an unresolvable rule must not 500 the
            # whole list — that blanks every collection dropdown in the UI.
            # Degrade to an unknown count and flag it so the client can show
            # the collection instead of hiding all of them.
            #
            # Only rule-validation failures degrade to count_error: the pickers
            # tell users to fix the rule, so labelling a locked/corrupt DB or a
            # bad generated query as count_error would send them to edit rules
            # that aren't the actual problem. ValueError covers both malformed
            # rules (raised by _build_query_from_rules) and malformed JSON in
            # the rules column (json.JSONDecodeError is a ValueError subclass).
            # Anything else bubbles up as a 500 so real infra failures surface.
            #
            # Visual collections narrow the result set at open time via the
            # filter bar's visual clause; ``count_collection_photos`` only
            # evaluates ``rules``, so a saved visual collection with e.g.
            # ``rules: []`` would return the workspace-wide metadata count
            # here while Browse shows a much smaller set on reopen
            # (Codex review r3620935217). Resolving the visual clause on
            # every listing would run the embedding for every visual
            # collection on every page load — too expensive. Omit the count
            # instead: the sidebar (browse.html) renders an empty count
            # span for null photo_count, and the ✦ visual marker already
            # tells users this collection is visually resolved.
            #
            # Still validate the metadata rules though — skipping the count
            # was also the only validation path that caught malformed JSON
            # or unresolvable rule fields. Without this check, a visual
            # collection with degraded rules would look healthy in the
            # sidebar and only 400 later when Browse routes those bad rules
            # through ``/api/photos/query`` (Codex review r3621304875).
            if c["visual_json"] is not None:
                d["photo_count"] = None
                d["available_photo_count"] = None
                d["offline_photo_count"] = None
                _, degraded = _collection_rules_state(db, c["rules"])
                if degraded:
                    d["count_error"] = True
                    app.logger.warning(
                        "Visual collection %s (%s) has unresolvable rules; marking degraded",
                        c["id"],
                        c["name"],
                    )
            else:
                try:
                    counts = db.count_collection_photo_availability(c["id"])
                    d["photo_count"] = counts["total"]
                    d["available_photo_count"] = counts["available"]
                    d["offline_photo_count"] = counts["offline"]
                except ValueError:
                    app.logger.exception(
                        "Failed to count photos for collection %s (%s)",
                        c["id"],
                        c["name"],
                    )
                    d["photo_count"] = None
                    d["available_photo_count"] = None
                    d["offline_photo_count"] = None
                    d["count_error"] = True
            # Degraded rows must never advertise manual-add support: the
            # add-to-collection modal filters only on can_add_photos, and
            # /api/collections/<id>/add-photos calls set(ids_rule["value"])
            # on the existing rule — which 500s on any malformed photo_ids
            # payload (non-scalar entries, non-list value, etc.). If the
            # rule is bad enough to fail count, it isn't safe to merge into.
            if d.get("count_error"):
                d["can_add_photos"] = False
            elif c["visual_json"] is not None:
                # Visual collections store ``rules: []`` which
                # ``_collection_accepts_manual_photos`` treats as addable,
                # but ``/add-photos`` would only append to ``photo_ids``
                # and leave ``visual_json`` alone — the manually added
                # photos would only surface in the reopened collection
                # if they also matched the hidden visual prompt, so
                # the add is silently ineffective (Codex r3620791304).
                d["can_add_photos"] = False
            else:
                try:
                    d["can_add_photos"] = _collection_accepts_manual_photos(
                        json.loads(c["rules"])
                    )
                except (TypeError, ValueError):
                    d["can_add_photos"] = False
            # ``has_visual`` lets clients that funnel a collection through
            # the legacy rules-only path (``/api/collections/<id>/photos``,
            # ``/photo-ids``, pipeline/Misses ``collection_id`` callers) hide,
            # disable, or reject visual collections. Those paths
            # evaluate ``rules`` only — a visual-only collection would
            # otherwise silently widen the scope to every metadata match.
            # Browse opens the same collection into the filter bar, where
            # the visual clause IS resolved (see collectionsById /
            # loadExpression), so surfacing the flag here lets the two
            # flows behave differently without every caller re-parsing
            # ``visual_json``.
            d["has_visual"] = c["visual_json"] is not None
            result.append(d)
        return jsonify(result)

    @app.route("/api/collections", methods=["POST"])
    def api_create_collection():
        db = _get_db()
        body = request.get_json(silent=True) or {}
        import json

        name = body.get("name", "").strip()
        rules = body.get("rules", [])
        if not name:
            return json_error("name required")
        try:
            # Pin ``has_visual_index`` leaves to the active model before
            # counting/persisting so the sidebar count on reopen matches
            # what the save-time preview counter showed — otherwise a
            # library with embeddings from multiple models silently
            # widens the collection to "any embedding exists" (Codex
            # review r3621749904).
            rules = _inject_active_visual_model(rules)
            db.count_photos_for_rules(rules)
            # The visual clause is saved alongside rules — a collection
            # saved from an expression with a visual component must
            # reproduce the same result set on reopen, not silently drop
            # to metadata-only.
            visual = _validate_visual_arg(body.get("visual"))
        except ValueError as e:
            return json_error(str(e), 400)
        cid = db.add_collection(
            name, json.dumps(rules),
            visual_json=json.dumps(visual) if visual else None,
        )
        return jsonify({"ok": True, "id": cid})

    @app.route("/api/collections/preview", methods=["POST"])
    def api_collection_preview():
        """Live count of photos that would match an unsaved rules list.

        Body: {"rules": [...]}. Returns {"count": N}. Used by the smart-
        collection modal to show "Matches: N photos" as the user edits
        rules. Returns 400 on malformed rules or syntactically invalid JSON.
        """
        db = _get_db()
        # Parse the body manually rather than calling request.get_json(silent=True),
        # because silent=True collapses three different states into None (no
        # body, wrong Content-Type, malformed JSON), and we want malformed
        # JSON to surface as a 400 rather than be silently treated as {}.
        raw = request.get_data(cache=False)
        if not raw:
            body = {}
        else:
            try:
                body = json.loads(raw)
            except ValueError:
                return json_error("request body must be valid JSON", 400)
        # Flask returns top-level JSON lists/numbers/strings as-is, so guard
        # against `body.get(...)` raising AttributeError on non-object payloads
        # (e.g. a client posting `[]` directly).
        if not isinstance(body, dict):
            return json_error("request body must be a JSON object", 400)
        rules = body.get("rules", [])
        try:
            count = db.count_photos_for_rules(rules)
        except ValueError as e:
            # Validation in _build_query_from_rules raises ValueError for every
            # input shape SQLite could not bind, so we don't need to catch
            # sqlite3 errors here — letting them surface as 5xx keeps real
            # backend faults (locked DB, OperationalError, etc.) from being
            # misclassified as client errors.
            return json_error(str(e), 400)
        return jsonify({"count": count})

    @app.route("/api/collections/<int:collection_id>", methods=["DELETE"])
    def api_delete_collection(collection_id):
        db = _get_db()
        db.delete_collection(collection_id)
        return jsonify({"ok": True})

    @app.route("/api/collections/<int:collection_id>", methods=["PUT"])
    def api_update_collection(collection_id):
        """Update a collection. Body: {"name": "...", "rules": [...|group]}."""
        db = _get_db()
        body = request.get_json(silent=True) or {}
        row = db.conn.execute(
            "SELECT id, name, rules FROM collections WHERE id = ? AND workspace_id = ?",
            (collection_id, db._ws_id()),
        ).fetchone()
        if not row:
            return json_error("collection not found", 404)

        updates = []
        params = []
        if "name" in body:
            name = (body.get("name") or "").strip()
            if not name:
                return json_error("name required")
            updates.append("name = ?")
            params.append(name)
        if "rules" in body:
            rules = body.get("rules")
            try:
                # Same active-model pinning as POST so the persisted
                # rules match what the save-time preview counted
                # (Codex review r3621749904).
                rules = _inject_active_visual_model(rules)
                db.count_photos_for_rules(rules)
            except ValueError as e:
                return json_error(str(e), 400)
            updates.append("rules = ?")
            params.append(json.dumps(rules))
        if "visual" in body:
            try:
                visual = _validate_visual_arg(body.get("visual"))
            except ValueError as e:
                return json_error(str(e), 400)
            updates.append("visual_json = ?")
            params.append(json.dumps(visual) if visual else None)
        if updates:
            params.extend([collection_id, db._ws_id()])
            db.conn.execute(
                f"UPDATE collections SET {', '.join(updates)} "
                "WHERE id = ? AND workspace_id = ?",
                params,
            )
            db.conn.commit()
        return jsonify({"ok": True})

    @app.route("/api/collections/<int:collection_id>/add-photos", methods=["POST"])
    def api_collection_add_photos(collection_id):
        """Add photos to a static collection by appending to its photo_ids rule."""
        db = _get_db()
        body = request.get_json(silent=True) or {}
        photo_ids = body.get("photo_ids", [])
        if not isinstance(photo_ids, list):
            return json_error("photo_ids must be a list")
        if not photo_ids:
            return json_error("photo_ids required")
        # Non-int entries would either crash sorted() against the existing
        # int ids or persist strings that never match `p.id IN (...)` —
        # mirrors api_photos_by_ids' validation.
        for pid in photo_ids:
            if isinstance(pid, bool) or not isinstance(pid, int):
                return json_error("photo_ids must be integers")

        row = db.conn.execute(
            "SELECT rules, visual_json FROM collections WHERE id = ? AND workspace_id = ?",
            (collection_id, db._ws_id()),
        ).fetchone()
        if not row:
            return json_error("Collection not found", 404)

        # Belt-and-suspenders backstop for the picker gate: a visual
        # collection stores ``rules: []`` which passes
        # ``_collection_accepts_manual_photos``, but appending to
        # ``photo_ids`` here would not touch ``visual_json``, so the
        # manually added photos would only surface on reopen if they
        # also matched the hidden visual prompt — a silent no-op
        # (Codex r3620791304). Reject the request explicitly so the UI
        # picker (which already hides these) can't be bypassed by a
        # bookmarked or hand-crafted POST.
        if row["visual_json"] is not None:
            return json_error(
                "Cannot add photos to a visual collection; open it in "
                "Browse and refine the visual clause instead.",
                400,
            )

        rules = json.loads(row["rules"])
        if not _collection_accepts_manual_photos(rules):
            return json_error("Cannot add photos to this collection", 400)

        def _find_photo_ids_rule(node):
            if isinstance(node, list):
                for child in node:
                    found = _find_photo_ids_rule(child)
                    if found is not None:
                        return found
            elif isinstance(node, dict):
                if node.get("field") == "photo_ids":
                    return node
                if "rules" in node:
                    return _find_photo_ids_rule(node.get("rules"))
            return None

        ids_rule = _find_photo_ids_rule(rules)

        if ids_rule is None:
            ids_rule = {"field": "photo_ids", "value": []}
            if isinstance(rules, list):
                rules.append(ids_rule)
            elif isinstance(rules, dict) and isinstance(rules.get("rules"), list):
                rules["rules"].append(ids_rule)
            else:
                rules = [ids_rule]

        # Merge new IDs
        existing = set(ids_rule["value"])
        for pid in photo_ids:
            existing.add(pid)
        ids_rule["value"] = sorted(existing)

        db.conn.execute(
            "UPDATE collections SET rules = ? WHERE id = ? AND workspace_id = ?",
            (json.dumps(rules), collection_id, db._ws_id()),
        )
        db.conn.commit()
        return jsonify({"ok": True, "total": len(ids_rule["value"])})

    @app.route("/api/collections/<int:collection_id>/duplicate", methods=["POST"])
    def api_collection_duplicate(collection_id):
        """Duplicate a collection within the active workspace. Returns {id}."""
        db = _get_db()
        try:
            new_id = db.duplicate_collection(collection_id)
        except ValueError:
            return json_error("collection not found", 404)
        return jsonify({"ok": True, "id": new_id})

    def _collection_row(db, collection_id):
        """Return the (workspace-scoped) collection row or None."""
        return db.conn.execute(
            "SELECT id, name, rules, visual_json FROM collections "
            "WHERE id = ? AND workspace_id = ?",
            (collection_id, db._ws_id()),
        ).fetchone()

    _VISUAL_COLLECTION_MSG = (
        "This collection has a visual-search clause. The rules-only "
        "endpoint would silently widen the scope to every metadata "
        "match, so it is refused here. Open the collection from Browse "
        "to see the visual results."
    )

    def _reject_visual_collection(db, collection_id):
        """Return a 400 response if the collection is visual, else None.

        The consumers that call ``db.get_collection_photos`` /
        ``collection_photo_ids`` (pipeline stages, sharpness/cull/classify/
        regroup/masks jobs, predictions-compare, the Misses legacy API, import
        preview) evaluate ``rules`` only. A visual-only collection would
        otherwise silently scope those runs to every metadata-matching
        photo instead of the visually-matched subset — the fix Codex
        flagged in review r3620423210. Pickers hide these collections too,
        but this is the source-of-truth boundary check.

        Coerce the raw JSON value before the ``visual_json`` lookup:
        SQLite's ``WHERE id = ?`` still matches integer id 1 when handed
        ``"1"`` or ``True``, so an early ``isinstance`` bail-out would let
        a string- or bool-typed id skip the guard and hit the rules-only
        path anyway (Codex review r3620636582). Return a 400 on an
        unparseable id so callers can't silently widen the scope.
        """
        coerced = _coerce_collection_id(collection_id)
        if coerced is None:
            return None
        if coerced is False:
            return json_error("collection_id must be an integer", 400)
        row = _collection_row(db, coerced)
        if row is not None and row["visual_json"] is not None:
            return json_error(_VISUAL_COLLECTION_MSG, 400)
        return None

    @app.route("/api/collections/<int:collection_id>/photos")
    def api_collection_photos(collection_id):
        import config as cfg
        db = _get_db()
        # This endpoint evaluates ``rules`` only (see
        # ``get_collection_photos`` → ``_build_collection_query``); reject
        # visual collections up front so the pipeline/review/etc. consumers
        # that hit it don't silently scope to every metadata-matching
        # photo instead of the visually-matched subset.
        err = _reject_visual_collection(db, collection_id)
        if err is not None:
            return err
        page = request.args.get("page", 1, type=int)
        default_per_page = cfg.load().get("photos_per_page", 50)
        per_page = max(1, min(request.args.get("per_page", default_per_page, type=int), _MAX_PER_PAGE))
        sort = request.args.get("sort", "date")
        stacks = _request_bool_arg("stacks")
        # If the saved rules can't be resolved (e.g. an unknown field/op left
        # over from an older schema), surface a 400 instead of a 500 so
        # callers can render a real error — this is the same collection state
        # that /api/collections flags with count_error=True.
        try:
            underlying_total = db.count_collection_photos(collection_id)
            if stacks:
                photos = db.query_browse_stacks(
                    [], collection_id=collection_id, sort=sort,
                    page=page, per_page=per_page,
                )
                total = db.count_browse_stacks([], collection_id=collection_id)
            else:
                photos = db.get_collection_photos(
                    collection_id, page=page, per_page=per_page, sort=sort,
                )
                total = underlying_total
        except ValueError as e:
            app.logger.exception(
                "Collection %s has unresolvable rules", collection_id
            )
            return json_error(f"collection rules cannot be resolved: {e}", 400)
        photo_dicts = _prepare_browse_photo_dicts(db, photos)
        response = {
            "photos": photo_dicts,
            "page": page,
            "per_page": per_page,
            "total": total,
        }
        if stacks:
            response["underlying_total"] = underlying_total
        return jsonify(response)

    @app.route("/api/collections/<int:collection_id>/photo-ids")
    def api_collection_photo_ids(collection_id):
        """Return every photo ID matching a collection.

        Accepts ``sort`` and ``stacks`` so Select-all-matching keeps the
        same insertion order the grid shows — Best Batch seed,
        burst-review order, and export preview all read the first
        ``selectedPhotos`` entry, and a date-only ordering here would
        pick a different photo whenever the grid is sorted by
        name/rating/sharpness/quality. ``stacks=true`` further emits
        each stack's cover before its hidden members so the first id is
        always the visible top-level card even when the quality-ranked
        cover isn't the stack's earliest member under the sort (Codex
        P2 on PR #1561).
        """
        db = _get_db()
        err = _reject_visual_collection(db, collection_id)
        if err is not None:
            return err
        sort = request.args.get("sort", "date")
        stacks = _request_bool_arg("stacks")
        try:
            if stacks:
                photo_ids = db.get_collection_photo_ids_stacked(
                    collection_id, sort=sort,
                )
            else:
                photo_ids = db.get_collection_photo_ids(collection_id, sort=sort)
        except ValueError as e:
            app.logger.exception(
                "Collection %s has unresolvable rules", collection_id
            )
            return json_error(f"collection rules cannot be resolved: {e}", 400)
        return jsonify({"photo_ids": photo_ids, "total": len(photo_ids)})

    # -- Highlights --

    def _parse_highlight_photo_ids(body):
        raw_ids = body.get("photo_ids", [])
        if not isinstance(raw_ids, list) or not raw_ids:
            return None, "photo_ids required"
        photo_ids = []
        seen = set()
        for raw in raw_ids:
            if isinstance(raw, bool) or not isinstance(raw, int):
                return None, "photo_ids must be integers"
            if raw not in seen:
                photo_ids.append(raw)
                seen.add(raw)
        return photo_ids, None

    def _validate_highlight_photo_ids(db, photo_ids):
        found_ids = set()
        batch_size = 800
        for i in range(0, len(photo_ids), batch_size):
            chunk = photo_ids[i:i + batch_size]
            placeholders = ",".join("?" for _ in chunk)
            found_ids.update(
                r["id"] for r in db.conn.execute(
                    f"SELECT id FROM photos WHERE id IN ({placeholders})",
                    chunk,
                ).fetchall()
            )
        missing = [pid for pid in photo_ids if pid not in found_ids]
        if missing:
            return f"Unknown photo_ids: {missing}", 404
        outside = [pid for pid in photo_ids if not db._photo_in_workspace(pid)]
        if outside:
            return (
                f"Photo IDs do not belong to the active workspace: {outside}",
                403,
            )
        return None, None

    def _highlight_top_predictions(db, photo_ids):
        if not photo_ids:
            return {}
        ws = db._ws_id()
        results = {}
        batch_size = 800
        for i in range(0, len(photo_ids), batch_size):
            chunk = photo_ids[i:i + batch_size]
            placeholders = ",".join("?" for _ in chunk)
            rows = db.conn.execute(
                f"""SELECT photo_id, id, species, confidence, classifier_model,
                          group_id, status
                   FROM (
                       SELECT d.photo_id, pr.id, pr.species, pr.confidence,
                              pr.classifier_model,
                              pr_rev.group_id,
                              COALESCE(pr_rev.status, 'pending') AS status,
                              ROW_NUMBER() OVER (
                                  PARTITION BY d.photo_id
                                  ORDER BY pr.confidence DESC, pr.id DESC
                              ) AS rn
                       FROM detections d
                       JOIN predictions pr ON pr.detection_id = d.id
                       LEFT JOIN prediction_review pr_rev
                         ON pr_rev.prediction_id = pr.id
                        AND pr_rev.workspace_id = ?
                       WHERE d.photo_id IN ({placeholders})
                         AND pr.species IS NOT NULL
                         AND COALESCE(pr_rev.status, 'pending') != 'rejected'
                         AND pr.labels_fingerprint = (
                             SELECT pr2.labels_fingerprint FROM predictions pr2
                             WHERE pr2.detection_id = pr.detection_id
                               AND pr2.classifier_model = pr.classifier_model
                             ORDER BY pr2.created_at DESC, pr2.id DESC
                             LIMIT 1
                         )
                   ) WHERE rn = 1""",
                (ws, *chunk),
            ).fetchall()
            for row in rows:
                results[row["photo_id"]] = row
        return results

    def _parse_photo_preference_body(body, require_photo=True):
        purpose = body.get("purpose", "")
        species = body.get("species", "")
        purpose = purpose.strip() if isinstance(purpose, str) else ""
        species = species.strip() if isinstance(species, str) else ""
        if purpose not in {"species_representative", "life_list", "highlights"}:
            return None, (
                "purpose must be one of species_representative, "
                "life_list, or highlights"
            )
        if not species:
            return None, "species required"
        # Canonicalize to the spelling add_keyword would store (see
        # _parse_species_highlight_body) so the eligibility prechecks and
        # the DB setters all key on one string.
        species = _get_db().resolve_species_display_name(species)
        if not species:
            return None, "species required"

        photo_id = body.get("photo_id")
        # Ordered highlights are per-photo (multiple photos per species),
        # so photo_id is always required for purpose=highlights — even on
        # DELETE, where representative purposes let it be omitted to clear
        # the whole species preference.
        needs_photo = require_photo or purpose == "highlights"
        if needs_photo:
            if isinstance(photo_id, bool) or not isinstance(photo_id, int):
                return None, "photo_id must be an integer"
        else:
            photo_id = None

        return {
            "purpose": purpose,
            "canonical_purpose": (
                "highlights" if purpose == "highlights"
                else "species_representative"
            ),
            "species": species,
            "photo_id": photo_id,
        }, None

    def _photo_can_be_life_list_preference(db, species, photo_id):
        ws = db._ws_id()
        # Accept a hierarchy leaf whose taxon links back to a root
        # identification with the same curation name. See the matching
        # comment on Database.get_species_representative_lists: after
        # root-repair the photo may only carry the hierarchical leaf
        # ("verdin"), whose spelling differs from the root ("Verdin") even
        # though the same taxon is still attached. Without this fallback,
        # updating a preserved root-key preference would fail eligibility.
        # Eligibility mirrors :meth:`Database.get_life_list_candidates` and
        # `get_photo_life_list_species` — both admit linked higher-rank
        # taxonomy identifications so a photo tagged only with a genus /
        # family / class entry can save the life-list representative for
        # the entry it actually renders under. Ancestor suppression is
        # applied via the shared clause so the write is denied for an
        # ancestor keyword (``Aves``) when the same photo carries a
        # descendant identification (``American Robin``); saving
        # ``Aves`` there would render as ``is_current_photo`` false on
        # the next read (see :meth:`get_species_representative_lists`)
        # and leave a curation row nothing else considers eligible.
        row = db.conn.execute(
            f"""SELECT 1
               FROM photo_keywords pk
               JOIN keywords k ON k.id = pk.keyword_id
                AND (k.is_species = 1 OR k.type = 'taxonomy')
               JOIN photos p ON p.id = pk.photo_id
                AND COALESCE(p.flag, 'none') != 'rejected'
               JOIN workspace_folders wf ON wf.folder_id = p.folder_id
                AND wf.workspace_id = ?
               JOIN folders f ON f.id = p.folder_id
                AND f.status IN ('ok', 'partial')
               WHERE pk.photo_id = ?
                 AND (
                     k.name = ?
                     OR (
                         k.taxon_id IS NOT NULL
                         AND EXISTS (
                             SELECT 1 FROM keywords root
                             WHERE root.parent_id IS NULL
                               AND (root.is_species = 1
                                    OR root.type = 'taxonomy')
                               AND root.taxon_id = k.taxon_id
                               AND root.name = ?
                         )
                     )
                 )
                 {_LIFE_LIST_ANCESTOR_SUPPRESSION_CLAUSE}
               LIMIT 1""",
            (ws, photo_id, species, species),
        ).fetchone()
        return row is not None

    def _photo_can_be_highlights_preference(db, species, photo_id):
        candidates = db.get_highlights_candidates(None, min_quality=0.0)
        buckets, _unidentified = _collect_highlight_buckets(
            candidates, confidence_threshold=0.0,
            canonicalize_species=_species_canonicalizer(db),
        )
        for bucket in buckets:
            if bucket["species"] != species:
                continue
            return any(p["id"] == photo_id for p in bucket["photos"])
        return False

    def _photo_can_be_preference(db, purpose, species, photo_id):
        # Ordered highlights use their own (stricter) eligibility check —
        # the photo must appear in the workspace's highlight buckets for
        # this species. Representative-style purposes (species_representative,
        # life_list) only require the photo to carry the species keyword.
        if purpose == "highlights":
            return _photo_can_be_highlights_preference(db, species, photo_id)
        return _photo_can_be_life_list_preference(db, species, photo_id)

    @app.route("/api/photo-preferences", methods=["POST"])
    def api_photo_preferences_set():
        db = _get_db()
        body = request.get_json(silent=True) or {}
        parsed, error = _parse_photo_preference_body(body)
        if error:
            return json_error(error)
        error, status = _validate_highlight_photo_ids(db, [parsed["photo_id"]])
        if error:
            return json_error(error, status)
        if not _photo_can_be_preference(
            db, parsed["purpose"], parsed["species"], parsed["photo_id"]
        ):
            return json_error(
                "photo_id is not eligible for that purpose/species", 400,
            )
        # Route legacy `purpose=highlights` writes to the ordered-highlights
        # table so a cached Highlights page or older client doesn't silently
        # overwrite the species representative instead.
        if parsed["purpose"] == "highlights":
            rank = db.add_species_highlight(
                parsed["species"], parsed["photo_id"]
            )
            return jsonify({"ok": True, **parsed, "rank": rank})
        db.set_species_representative(
            parsed["species"], parsed["photo_id"], _commit=False
        )
        # Only promote to `species_highlights` when the photo is actually a
        # Highlights candidate. Otherwise the row is invisible on the
        # Highlights page (which filters by quality_score) — the user could
        # neither see it nor remove it.
        rank = None
        if _photo_can_be_highlights_preference(
            db, parsed["species"], parsed["photo_id"]
        ):
            rank = db.promote_species_highlight(
                parsed["species"], parsed["photo_id"], _commit=False
            )
        db.conn.commit()
        return jsonify({"ok": True, **parsed, "highlight_rank": rank})

    @app.route("/api/photo-preferences", methods=["DELETE"])
    def api_photo_preferences_clear():
        db = _get_db()
        body = request.get_json(silent=True) or {}
        parsed, error = _parse_photo_preference_body(body, require_photo=False)
        if error:
            return json_error(error)
        # See the POST handler: `purpose=highlights` targets one row in the
        # ordered-highlights table, so it needs a photo_id (enforced by
        # _parse_photo_preference_body) and routes to remove_species_highlight
        # rather than clearing all representative rows for the species.
        if parsed["purpose"] == "highlights":
            removed = db.remove_species_highlight(
                parsed["species"], parsed["photo_id"]
            )
            return jsonify({
                "ok": True,
                "purpose": parsed["canonical_purpose"],
                "species": parsed["species"],
                "photo_id": parsed["photo_id"],
                "removed": removed,
            })
        db.clear_species_representative(parsed["species"])
        return jsonify({
            "ok": True,
            "purpose": parsed["canonical_purpose"],
            "species": parsed["species"],
        })

    def _parse_species_highlight_body(body, require_direction=False):
        species = body.get("species", "")
        species = species.strip() if isinstance(species, str) else ""
        if not species:
            return None, "species required"
        # Canonicalize to the spelling add_keyword would store: the client
        # sends bucket labels, which for unconfirmed buckets derive from
        # prediction casing. The eligibility precheck compares against
        # canonical bucket keys and the DB setters canonicalize on write,
        # so parse-time canonicalization keeps all three in agreement.
        species = _get_db().resolve_species_display_name(species)
        if not species:
            return None, "species required"
        photo_id = body.get("photo_id")
        if isinstance(photo_id, bool) or not isinstance(photo_id, int):
            return None, "photo_id must be an integer"
        parsed = {"species": species, "photo_id": photo_id}
        if require_direction:
            direction = body.get("direction", "")
            direction = direction.strip().lower() if isinstance(direction, str) else ""
            if direction not in {"up", "down"}:
                return None, "direction must be up or down"
            parsed["direction"] = direction
        return parsed, None

    @app.route("/api/species-highlights", methods=["POST"])
    def api_species_highlights_add():
        db = _get_db()
        body = request.get_json(silent=True) or {}
        parsed, error = _parse_species_highlight_body(body)
        if error:
            return json_error(error)
        error, status = _validate_highlight_photo_ids(db, [parsed["photo_id"]])
        if error:
            return json_error(error, status)
        if not _photo_can_be_highlights_preference(
            db, parsed["species"], parsed["photo_id"]
        ):
            return json_error(
                "photo_id is not eligible as a highlight for that species", 400,
            )
        rank = db.add_species_highlight(parsed["species"], parsed["photo_id"])
        return jsonify({"ok": True, **parsed, "rank": rank})

    @app.route("/api/species-highlights", methods=["DELETE"])
    def api_species_highlights_remove():
        db = _get_db()
        body = request.get_json(silent=True) or {}
        parsed, error = _parse_species_highlight_body(body)
        if error:
            return json_error(error)
        error, status = _validate_highlight_photo_ids(db, [parsed["photo_id"]])
        if error:
            return json_error(error, status)
        removed = db.remove_species_highlight(parsed["species"], parsed["photo_id"])
        return jsonify({"ok": True, **parsed, "removed": removed})

    @app.route("/api/species-highlights/order", methods=["PATCH", "POST"])
    def api_species_highlights_order():
        db = _get_db()
        body = request.get_json(silent=True) or {}
        parsed, error = _parse_species_highlight_body(body, require_direction=True)
        if error:
            return json_error(error)
        error, status = _validate_highlight_photo_ids(db, [parsed["photo_id"]])
        if error:
            return json_error(error, status)
        ok = db.move_species_highlight(
            parsed["species"], parsed["photo_id"], parsed["direction"]
        )
        if not ok:
            return json_error("highlight not found", 404)
        return jsonify({"ok": True, **parsed})

    def _build_highlights_payload(
        db,
        scope="folder",
        folder_id=None,
        min_quality=0.0,
        confidence_threshold=0.70,
        limit_per_bucket=20,
        species_filter="",
        species_match_case=False,
        species_whole_word=False,
        search_query="",
        search_match_case=False,
        search_whole_word=False,
        confirmation_filter="all",
        highlight_filter="all",
        representative_filter="all",
    ):
        folders = db.get_folders_with_quality_data()
        if scope == "workspace":
            folder_id = None
        elif folder_id is None and folders:
            folder_id = folders[0]["id"]  # Most recent
        limit_per_bucket = max(1, min(int(limit_per_bucket), 100))
        species_filter = (species_filter or "").strip()
        confirmation_filter = _normalize_highlight_confirmation_filter(
            confirmation_filter
        )
        highlight_filter = _normalize_highlight_presence_filter(highlight_filter)
        representative_filter = _normalize_highlight_presence_filter(
            representative_filter
        )

        candidates = db.get_highlights_candidates(folder_id, min_quality=min_quality)
        total_in_scope = db.count_filtered_photos(folder_id=folder_id)

        buckets, unidentified_photos = _collect_highlight_buckets(
            candidates, confidence_threshold, confirmation_filter,
            canonicalize_species=_species_canonicalizer(db),
        )
        eligible_count = sum(b["photo_count"] for b in buckets) + len(
            unidentified_photos
        )
        if species_filter:
            buckets = [
                b for b in buckets
                if text_search_match(
                    b["species"],
                    species_filter,
                    species_match_case,
                    species_whole_word,
                )
            ]
            if not text_search_match(
                "unidentified",
                species_filter,
                species_match_case,
                species_whole_word,
            ):
                unidentified_photos = []

        buckets, unidentified_photos = _filter_highlight_sections(
            buckets,
            unidentified_photos,
            search_query,
            search_match_case,
            search_whole_word,
        )
        _apply_ordered_highlights(db, buckets)
        _apply_highlight_preferences(db, buckets)
        buckets, unidentified_photos = _filter_highlight_curation_state(
            buckets,
            unidentified_photos,
            highlight_filter,
            representative_filter,
        )

        def limited_bucket(bucket):
            photos = bucket["photos"]
            limited = photos[:limit_per_bucket]
            return {
                **bucket,
                "photos": limited,
                "loaded_count": len(limited),
                "has_more": len(photos) > len(limited),
            }

        limited_buckets = [limited_bucket(b) for b in buckets]
        unidentified_limited = unidentified_photos[:limit_per_bucket]
        visible_photos = []
        for bucket in limited_buckets:
            visible_photos.extend(bucket["photos"])
        visible_photos.extend(unidentified_limited)
        attach_edit_recipes(db, visible_photos)

        return {
            "buckets": limited_buckets,
            "unidentified": {
                "photo_count": len(unidentified_photos),
                "photos": unidentified_limited,
                "loaded_count": len(unidentified_limited),
                "has_more": len(unidentified_photos) > len(unidentified_limited),
                "unanalyzed_count": _bucket_unanalyzed_count(unidentified_photos),
            },
            "folders": [
                {"id": f["id"], "name": f["name"], "photo_count": f["photo_count"]}
                for f in folders
            ],
            "meta": {
                "total_in_scope": total_in_scope,
                "eligible": eligible_count,
                "limit_per_bucket": limit_per_bucket,
                "confirmation": confirmation_filter,
                "highlight_selection": highlight_filter,
                "species_representative": representative_filter,
                "search": (search_query or "").strip(),
            },
            "scope": "workspace" if folder_id is None else "folder",
        }

    @app.route("/api/highlights")
    def api_highlights():
        db = _get_db()
        payload = _build_highlights_payload(
            db,
            scope=request.args.get("scope", "folder"),
            folder_id=request.args.get("folder_id", type=int),
            min_quality=request.args.get("min_quality", 0.0, type=float),
            confidence_threshold=request.args.get(
                "confidence_threshold", 0.70, type=float
            ),
            limit_per_bucket=request.args.get("limit_per_bucket", 20, type=int),
            species_filter=request.args.get("species") or "",
            species_match_case=_request_bool_arg("species_match_case"),
            species_whole_word=_request_bool_arg("species_whole_word"),
            search_query=request.args.get("q") or "",
            search_match_case=_request_bool_arg("q_match_case"),
            search_whole_word=_request_bool_arg("q_whole_word"),
            confirmation_filter=request.args.get("confirmation") or "all",
            highlight_filter=request.args.get("highlight_selection") or "all",
            representative_filter=(
                request.args.get("species_representative") or "all"
            ),
        )
        return jsonify(payload)

    def _build_life_list_payload(
        db,
        photos_per_species=12,
        photo_offset=0,
        species_filter=None,
    ):
        rows = db.get_life_list_candidates(species=species_filter)
        locations_by_species = db.get_life_list_locations(species=species_filter)
        class_by_taxon = db.get_class_ancestors_for_taxa({
            row["taxon_id"] for row in rows if row["taxon_id"] is not None
        })
        photo_offset = max(0, int(photo_offset))
        if photos_per_species is None:
            photo_limit = None
        else:
            photo_limit = max(
                1, min(int(photos_per_species), 100)
            )

        # Canonicalize each row's species to the root keyword's stored
        # spelling. After repair_duplicate_photo_species detaches a
        # redundant root row, a photo may only carry the hierarchy leaf
        # (``verdin``) whose spelling differs from the curation-keyed
        # root (``Verdin``); without canonicalization, that photo would
        # sit in its own ``verdin`` bucket, its curation on
        # ``Verdin`` would never apply, and single-species API loads
        # for ``Verdin`` would return an entry named ``verdin``.
        canonicalize = _species_canonicalizer(db)
        merged_locations = {}
        for raw_species, locations in locations_by_species.items():
            canonical = canonicalize(raw_species) or raw_species
            existing = merged_locations.setdefault(canonical, [])
            for loc in locations:
                if loc not in existing:
                    existing.append(loc)
        locations_by_species = merged_locations

        buckets = {}
        for row in rows:
            r = dict(row)
            r["species"] = canonicalize(r["species"]) or r["species"]
            entry = buckets.setdefault(r["species"], {
                "scientific_name": None,
                "common_name": None,
                "taxon_id": None,
                "taxon_rank": None,
                "taxonomic_class": None,
                "photos": [],
                "seen_ids": set(),
            })
            # Two keyword rows can share a name (different parents); take
            # the first linked taxon's names for the species entry.
            if entry["scientific_name"] is None:
                entry["scientific_name"] = r.get("scientific_name")
            if entry["common_name"] is None:
                entry["common_name"] = r.get("common_name")
            if entry["taxon_id"] is None and r.get("taxon_id") is not None:
                entry["taxon_id"] = r["taxon_id"]
                entry["taxon_rank"] = r.get("taxon_rank")
                entry["taxonomic_class"] = class_by_taxon.get(r["taxon_id"])
            # A photo tagged with two same-name species keywords would
            # otherwise be appended once per row, inflating photo_count
            # and duplicating cards in the lightbox.
            if r["id"] in entry["seen_ids"]:
                continue
            entry["seen_ids"].add(r["id"])
            entry["photos"].append({
                "id": r["id"],
                "filename": r["filename"],
                "timestamp": r.get("timestamp"),
                "rating": r.get("rating") or 0,
                "flag": r.get("flag") or "none",
                "quality_score": r.get("quality_score"),
                "subject_sharpness": r.get("subject_sharpness"),
                "subject_size": r.get("subject_size"),
                "sharpness": r.get("sharpness"),
                "subject_tenengrad": r.get("subject_tenengrad"),
                "bg_tenengrad": r.get("bg_tenengrad"),
                "crop_complete": r.get("crop_complete"),
                "bg_separation": r.get("bg_separation"),
                "subject_clip_high": r.get("subject_clip_high"),
                "subject_clip_low": r.get("subject_clip_low"),
                "subject_y_median": r.get("subject_y_median"),
                "noise_estimate": r.get("noise_estimate"),
                "eye_tenengrad": r.get("eye_tenengrad"),
            })

        def compact(photo):
            return {
                "id": photo["id"],
                "filename": photo["filename"],
                "timestamp": photo.get("timestamp"),
                "flag": photo.get("flag") or "none",
                "quality_score": photo.get("quality_score"),
                "highlight_score": photo.get("highlight_score"),
                "reasons": photo.get("reasons") or [],
                "is_species_representative": bool(
                    photo.get("is_species_representative")
                ),
                "is_life_list_photo": bool(photo.get("is_species_representative")),
                "is_highlighted": bool(photo.get("is_highlighted")),
                "highlight_rank": photo.get("highlight_rank"),
            }

        species_entries = []
        distinct_photo_ids = set()
        representatives = db.get_species_representative_lists(species=species_filter)
        highlights_by_species = db.get_species_highlights(species=species_filter)
        for species, entry in buckets.items():
            photos = entry["photos"]
            distinct_photo_ids.update(p["id"] for p in photos)
            timestamps = [p["timestamp"] for p in photos if p.get("timestamp")]
            _highlight_score_bucket(photos)
            representative_ids = representatives.get(species) or []
            representative_order = {
                photo_id: idx for idx, photo_id in enumerate(representative_ids)
            }
            preferred_id = representative_ids[0] if representative_ids else None
            highlight_ranks = highlights_by_species.get(species, {})
            for photo in photos:
                rank = highlight_ranks.get(photo["id"])
                photo["is_highlighted"] = rank is not None
                photo["highlight_rank"] = rank
                photo["is_species_representative"] = (
                    photo["id"] in representative_order
                )
            preferred_applied = any(
                photo.get("is_species_representative") for photo in photos
            )
            if not preferred_applied and highlight_ranks:
                valid_highlights = [
                    (highlight_ranks[p["id"]], p["id"])
                    for p in photos
                    if p["id"] in highlight_ranks
                ]
                if valid_highlights:
                    _, highlight_id = min(valid_highlights)
                    for idx, photo in enumerate(photos):
                        if photo["id"] == highlight_id:
                            if idx:
                                photos.insert(0, photos.pop(idx))
                            break
            # Life List curation order is explicit representative selection,
            # then Picks (the P flag), then the existing highlight/algorithmic
            # ranking. Keep ranked positions as the final tie-breaker so
            # multiple Picks retain their quality order and non-Picks behave
            # exactly as before.
            ranked_position = {
                photo["id"]: idx for idx, photo in enumerate(photos)
            }
            photos.sort(key=lambda photo: (
                0 if photo["id"] in representative_order else (
                    1 if photo.get("flag") == "flagged" else 2
                ),
                representative_order.get(photo["id"], 0),
                ranked_position.get(photo["id"], 0),
            ))
            best_photo = photos[0] if photos else {}
            if best_photo.get("is_species_representative"):
                best_source = "representative"
            elif best_photo.get("flag") == "flagged":
                best_source = "pick"
            elif best_photo.get("is_highlighted"):
                best_source = "highlight"
            else:
                best_source = "algorithm"
            if photo_limit is None:
                top = photos[photo_offset:]
            else:
                top = photos[photo_offset:photo_offset + photo_limit]
            species_entries.append({
                "species": species,
                "scientific_name": entry["scientific_name"],
                "common_name": entry["common_name"],
                "taxon_id": entry["taxon_id"],
                "taxon_rank": entry["taxon_rank"],
                "taxonomic_class": entry["taxonomic_class"],
                "photo_count": len(photos),
                "first_seen": min(timestamps) if timestamps else None,
                "last_seen": max(timestamps) if timestamps else None,
                "locations": locations_by_species.get(species, []),
                "preferred_photo_id": preferred_id,
                "has_preferred_photo": preferred_applied,
                "best_source": best_source,
                "best": compact(photos[0]) if photos else None,
                "photos": [compact(p) for p in top],
                "loaded_count": min(len(photos), photo_offset + len(top)),
                "has_more": photo_offset + len(top) < len(photos),
            })

        # Life-list numbering: chronological by first photographed date,
        # the way birders count lifers. Species with no capture time go
        # last, alphabetically, so they still get a stable number.
        species_entries.sort(key=lambda e: (
            e["first_seen"] is None,
            e["first_seen"] or "",
            _life_list_alphabetical_key(e["species"]),
            e["species"].lower(),
        ))
        for i, e in enumerate(species_entries, start=1):
            e["number"] = i
        life_list_photos = []
        for entry in species_entries:
            if entry.get("best"):
                life_list_photos.append(entry["best"])
            life_list_photos.extend(entry.get("photos") or [])
        attach_edit_recipes(db, life_list_photos)

        return {
            "species": species_entries,
            "meta": {
                "species_count": len(species_entries),
                "photo_count": len(distinct_photo_ids),
                "photos_per_species": photo_limit,
            },
        }

    @app.route("/api/life-list")
    def api_life_list():
        db = _get_db()
        payload = _build_life_list_payload(
            db,
            photos_per_species=request.args.get("photos_per_species", 100, type=int),
        )
        return jsonify(payload)

    @app.route("/api/life-list/species")
    def api_life_list_species():
        db = _get_db()
        species = (request.args.get("species") or "").strip()
        if not species:
            return json_error("species required")
        offset = max(0, request.args.get("offset", 0, type=int))
        limit = max(1, min(request.args.get("limit", 100, type=int), 500))
        payload = _build_life_list_payload(
            db,
            photos_per_species=limit,
            photo_offset=offset,
            species_filter=species,
        )
        if not payload["species"]:
            return json_error("species not found", 404)
        entry = payload["species"][0]
        return jsonify({
            "species": entry["species"],
            "photos": entry["photos"],
            "photo_count": entry["photo_count"],
            "loaded_count": entry["loaded_count"],
            "has_more": entry["has_more"],
        })

    @app.route("/api/life-list/explorer")
    def api_life_list_explorer():
        db = _get_db()
        root_id = request.args.get("root", type=int)  # None -> default Aves
        return jsonify(_build_explorer_payload(db, root_id=root_id))

    @app.route("/api/life-list/explorer/species")
    def api_life_list_explorer_species():
        db = _get_db()
        genus_id = request.args.get("genus", type=int)
        if not genus_id:
            return jsonify({"genus_id": None, "species": []})
