    @app.route("/api/embedding-cache")
    def api_embedding_cache():
        """Return info about cached label embeddings."""
        from classifier import CACHE_DIR

        if not os.path.isdir(CACHE_DIR):
            return jsonify({"entries": [], "total_size": 0})
        from embedding_cache import CHECKPOINT_SUFFIX

        entries = []
        total_size = 0
        for f in sorted(os.listdir(CACHE_DIR)):
            if f.endswith(CHECKPOINT_SUFFIX):
                # Partial progress from a paused or interrupted
                # computation, not a usable embedding set.
                continue
            if f.endswith(".npy") or f.endswith(".pt"):
                fp = os.path.join(CACHE_DIR, f)
                size = os.path.getsize(fp)
                total_size += size
                entries.append({"file": f, "size": size})
        # Reusable individual labels live below their encoder identity.
        # Aggregate them instead of shipping thousands of filenames to Settings.
        label_size = 0
        label_count = 0
        for root, _dirs, files in os.walk(os.path.join(CACHE_DIR, "labels")):
            for name in files:
                if name.endswith(".npy") and not name.endswith(CHECKPOINT_SUFFIX):
                    try:
                        label_size += os.path.getsize(os.path.join(root, name))
                        label_count += 1
                    except FileNotFoundError:
                        pass  # a concurrent cache clear won
        if label_count:
            entries.append({"file": "Reusable species labels", "size": label_size, "label_count": label_count})
            total_size += label_size
        return jsonify({"entries": entries, "total_size": total_size})

    @app.route("/api/embedding-matrix")
    def api_embedding_matrix():
        """Return which model+labels combinations have cached embeddings."""
        from classifier import _embedding_is_cached, _resolve_model_dir
        from labels import get_saved_labels, read_label_file
        from models import get_models

        # Only BioCLIP-style models use per-label text embeddings. timm models
        # have a fixed class head and never need embedding precomputation, so
        # excluding them here prevents the Settings UI from offering a
        # "Compute" button that would fail with a missing-file error.
        models = [
            m for m in get_models()
            if m["downloaded"] and m.get("model_type", "bioclip") != "timm"
        ]
        label_sets = get_saved_labels()

        matrix = []
        for ls in label_sets:
            labels_file = ls.get("labels_file", "")
            if not labels_file or not os.path.exists(labels_file):
                continue
            labels = read_label_file(labels_file)
            row = {
                "labels_name": ls.get("name", ""),
                "labels_file": labels_file,
                "species_count": len(labels),
                "models": {},
            }
            for m in models:
                model_dir = _resolve_model_dir(m["model_str"], m.get("weights_path"))
                row["models"][m["id"]] = {
                    "cached": _embedding_is_cached(
                        labels, m["model_str"], model_dir
                    ),
                    "model_name": m["name"],
                }
            matrix.append(row)

        return jsonify(
            {
                "models": [{"id": m["id"], "name": m["name"]} for m in models],
                "matrix": matrix,
            }
        )

    @app.route("/api/jobs/precompute-embeddings", methods=["POST"])
    @background_job
    def api_job_precompute_embeddings(ctx):
        body = request.get_json(silent=True) or {}
        model_id = body.get("model_id")
        labels_file = body.get("labels_file")
        if not model_id or not labels_file:
            return json_error("model_id and labels_file required")

        def work(job):
            from classifier import precompute_label_embeddings
            from labels import read_label_file
            from models import get_models

            # Find the model
            models = get_models()
            model = None
            for m in models:
                if m["id"] == model_id:
                    model = m
                    break
            if not model or not model["downloaded"]:
                raise RuntimeError(f"Model {model_id} not found or not downloaded")
            if model.get("model_type", "bioclip") == "timm":
                raise RuntimeError(
                    f"Model {model['name']} has a fixed class head and does "
                    "not use per-label embeddings — nothing to precompute."
                )

            ctx.runner.push_event(
                job["id"],
                "progress",
                {
                    "current": 0,
                    "total": 0,
                    "current_file": f'Loading {model["name"]} and computing embeddings...',
                    "rate": 0,
                },
            )

            labels = read_label_file(labels_file)

            log.info(
                "Pre-computing embeddings: %d labels with %s",
                len(labels),
                model["name"],
            )

            def _progress(current, total):
                ctx.runner.push_event(
                    job["id"],
                    "progress",
                    {
                        "current": current,
                        "total": total,
                        "current_file": f"Computing embeddings ({current}/{total} labels)…",
                        "rate": 0,
                    },
                )

            from classifier import ClassifierLoadPaused

            def _pause_requested():
                return ctx.runner.pause_requested(job["id"])

            def _cancelled():
                # Pure cancel probe: the pause is handled by the retry
                # loop below, outside the embedding single-flight, so the
                # producer never parks while equal-key waiters are joined.
                return ctx.runner.cancellation_requested(job["id"])

            # The shared service loads only the text side and joins an
            # equal-key pipeline/precompute already doing this work.
            while True:
                try:
                    precompute_label_embeddings(
                        labels=labels,
                        model_str=model["model_str"],
                        pretrained_str=model["weights_path"],
                        progress_callback=_progress,
                        cancel_check=_cancelled,
                        pause_check=_pause_requested,
                    )
                    break
                except ClassifierLoadPaused:
                    # Progress is checkpointed. Park here with no shared
                    # lock held; the next attempt resumes from the
                    # checkpoint. A Cancel during the pause surfaces on
                    # the retry through the cancel probe.
                    log.info(
                        "Pre-computing embeddings paused; parking until "
                        "Resume",
                    )
                    ctx.runner.is_cancelled(job["id"])
                    continue

            return {"labels": len(labels), "model": model["name"]}

        return ctx.start(
            "precompute-embeddings",
            work,
            config={
                "model_id": model_id,
                "labels_file": labels_file,
            },
            pausable=True,
            runtime_warning=build_cpu_runtime_warning(
                "precompute-embeddings",
                work_units=runtime_warning_work_units(
                    "precompute labels file",
                    lambda: _count_lines(labels_file),
                ),
                reason="large_embedding_precompute_cpu_only",
            ),
        )

