    @app.route("/api/inat/prepare/<int:photo_id>")
    def api_inat_prepare(photo_id):
        """Prepare iNaturalist submission data for a photo."""
        import config as cfg

        db = _get_db()
        photo = db.conn.execute(
            """SELECT p.*, f.path as folder_path FROM photos p
               JOIN folders f ON f.id = p.folder_id WHERE p.id = ?""",
            (photo_id,),
        ).fetchone()
        if not photo:
            return json_error("Photo not found", 404)
        if not db._photo_in_workspace(photo_id):
            return json_error(
                f"Photo {photo_id} does not belong to the active workspace", 403,
            )

        # Use the current-fingerprint helper so a photo with cached
        # predictions from multiple label sets doesn't prefill iNat with
        # a species from a stale label set. Apply the workspace-effective
        # detector_confidence floor so we never prefill a taxon from a
        # detection the UI threshold hides.
        min_conf = db.get_effective_config(cfg.load()).get(
            "detector_confidence", 0.2
        )
        pred = db.get_top_prediction_for_photo(
            photo_id, min_detector_confidence=min_conf,
        )

        species = pred["species"] if pred else ""
        scientific = pred["scientific_name"] if pred else ""

        loc = db.get_effective_photo_location(photo_id)
        lat = loc["latitude"] if loc else None
        lng = loc["longitude"] if loc else None
        # The browser uploader does not document query parameters for
        # pre-filling an observation. In particular, taxon_name is an
        # observation-search parameter, not an uploader parameter. Open the
        # generic uploader and keep the prepared metadata in this response for
        # Vireo's authenticated direct-upload flow.
        upload_url = "https://www.inaturalist.org/observations/upload"

        # Check submission history
        subs = db.get_inat_submissions([photo_id])
        already = photo_id in subs

        user_cfg = cfg.load()
        mode = "direct" if user_cfg.get("inat_token") else "quick"

        return jsonify({
            "species": species,
            "scientific_name": scientific,
            "confidence": pred["confidence"] if pred else 0,
            "timestamp": photo["timestamp"],
            "latitude": lat,
            "longitude": lng,
            "filename": photo["filename"],
            "edit_recipe": db.get_photo_edit_recipe(photo_id),
            "upload_url": upload_url,
            "mode": mode,
            "direct_upload_enabled": mode == "direct",
            "photo_upload_requires_token": mode != "direct",
            "already_submitted": already,
            "existing_observation_url": subs[photo_id]["observation_url"] if already else None,
        })

    @app.route("/api/inat/validate-token", methods=["POST"])
    def api_inat_validate_token():
        """Validate an iNaturalist API token."""
        import inat
        body = request.json or {}
        token = body.get("token", "")
        if not token:
            return json_error("Token is required")
        try:
            result = inat.validate_token(token)
        except inat.InatApiError as exc:
            return json_error(str(exc), 502)
        if result is None:
            return json_error("Invalid or expired token", 401)
        return jsonify(result)

    @app.route("/api/inat/token", methods=["POST"])
    def api_inat_save_token():
        """Validate and save an iNaturalist token from the submission modal."""
        nonlocal _inat_token_request_generation

        import config as cfg
        import inat

        body = request.get_json(silent=True) or {}
        token = str(body.get("token") or "").strip()
        if not token:
            return json_error("Token is required")
        with _settings_write_lock:
            _advance_inat_token_generation()
            request_generation = _inat_token_request_generation
            token_at_validation_start = _read_raw_config_file().get(
                "inat_token", "",
            )
        try:
            user = inat.validate_token(token)
        except inat.InatApiError as exc:
            return json_error(str(exc), 502)
        if user is None:
            return json_error("Invalid or expired token", 401)

        # Preserve the raw config shape instead of writing cfg.load(), which
        # would pin every default into config.json.  Invalid tokens never reach
        # disk; validation and persistence are one user action in this flow.
        # Only the newest validation request may persist: remote validation can
        # finish out of order when a modal is closed and reopened, and an older
        # response must not overwrite the token chosen by the newer flow.
        with _settings_write_lock:
            if request_generation != _inat_token_request_generation:
                return json_error(
                    "A newer token validation superseded this request", 409,
                )
            raw = _read_raw_config_file()
            if raw.get("inat_token", "") != token_at_validation_start:
                return json_error(
                    "The iNaturalist token changed while this request was "
                    "being validated", 409,
                )
            raw["inat_token"] = token
            cfg.save(raw)
        return jsonify({"ok": True, "login": user.get("login")})

    @app.route("/api/inat/export", methods=["POST"])
    @background_job
    def api_inat_export(ctx):
        """Export edited JPEGs with only the selected iNaturalist metadata."""
        import config as cfg
        from inat_export import (
            InatExportError,
            export_inat_photo,
            reveal_inat_exports,
        )

        body = request.get_json(silent=True) or {}
        destination = str(body.get("destination") or "").strip()
        submissions = body.get("submissions")
        if not destination:
            return json_error("destination is required")
        if not os.path.isabs(destination):
            return json_error("destination must be an absolute path")
        if not isinstance(submissions, list) or not submissions:
            return json_error("submissions array is required")
        if len(submissions) > _MAX_SELECTION_PHOTOS:
            return json_error("too many photos in selection", 400)
        normalized_submissions = []
        for item in submissions:
            if not isinstance(item, dict):
                return json_error("each submission must be an object")
            raw_photo_id = item.get("photo_id")
            if isinstance(raw_photo_id, (bool, float)):
                return json_error("photo_id must be an integer")
            try:
                photo_id = int(raw_photo_id)
            except (TypeError, ValueError):
                return json_error("photo_id must be an integer")
            normalized = dict(item)
            normalized["photo_id"] = photo_id
            if normalized.get("include_location", False):
                latitude = normalized.get("latitude")
                longitude = normalized.get("longitude")
                if isinstance(latitude, bool) or isinstance(longitude, bool):
                    return json_error(
                        "latitude and longitude must be finite numbers",
                    )
                try:
                    latitude = float(latitude)
                    longitude = float(longitude)
                except (TypeError, ValueError):
                    return json_error(
                        "latitude and longitude must be finite numbers",
                    )
                if not math.isfinite(latitude) or not math.isfinite(longitude):
                    return json_error(
                        "latitude and longitude must be finite numbers",
                    )
                if not -90 <= latitude <= 90 or not -180 <= longitude <= 180:
                    return json_error(
                        "latitude or longitude is out of range",
                    )
                normalized["latitude"] = latitude
                normalized["longitude"] = longitude
            normalized_submissions.append(normalized)
        submissions = normalized_submissions

        db = _get_db()
        effective_cfg = db.get_effective_config(cfg.load())
        quality = effective_cfg.get("working_copy_quality", 92)
        wc_max_size = effective_cfg.get("working_copy_max_size", 4096)
        developed_dir = effective_cfg.get("darktable_output_dir", "") or ""
        vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
        reveal = bool(body.get("reveal", False))

        def work(job):
            thread_db = ctx.thread_db()
            exported = []
            errors = []
            total = len(submissions)
            job["progress"]["total"] = total
            try:
                for index, item in enumerate(submissions, start=1):
                    if ctx.runner.is_cancelled(job["id"]):
                        break
                    photo_id = item["photo_id"]
                    photo = thread_db.get_photo(
                        photo_id, verify_workspace=True,
                    )
                    if not photo:
                        errors.append({
                            "photo_id": photo_id,
                            "error": "Photo not found",
                        })
                        job["progress"]["current"] = index
                        ctx.runner.push_event(job["id"], "progress", {
                            "current": index,
                            "total": total,
                            "current_file": "",
                            "phase": "Exporting for iNaturalist",
                        })
                        continue

                    metadata = {}
                    if item.get("include_taxon", False):
                        taxon_name = str(
                            item.get("taxon_name") or ""
                        ).strip()
                        if taxon_name:
                            metadata["taxon_name"] = taxon_name
                    if item.get("include_date", False):
                        observed_on = str(
                            item.get("observed_on") or ""
                        ).strip()
                        if observed_on:
                            # The modal discloses a calendar date, not capture
                            # time or timezone, so export only that snapshot.
                            metadata["timestamp"] = observed_on[:10]
                    if item.get("include_location", False):
                        latitude = item.get("latitude")
                        longitude = item.get("longitude")
                        if (
                            latitude not in (None, "")
                            and longitude not in (None, "")
                        ):
                            metadata["latitude"] = latitude
                            metadata["longitude"] = longitude
                    if item.get("include_description", False):
                        description = str(
                            item.get("description") or ""
                        ).strip()
                        if description:
                            metadata["description"] = description[:10000]

                    try:
                        path = export_inat_photo(
                            thread_db,
                            vireo_dir,
                            photo_id,
                            destination,
                            metadata,
                            quality=quality,
                            working_copy_max_size=wc_max_size,
                            developed_dir=developed_dir,
                        )
                        exported.append({
                            "photo_id": photo_id,
                            "path": path,
                            "filename": os.path.basename(path),
                        })
                    except (InatExportError, OSError, ValueError) as exc:
                        errors.append({
                            "photo_id": photo_id,
                            "error": str(exc),
                        })
                    finally:
                        job["progress"]["current"] = index
                        job["progress"]["current_file"] = photo["filename"]
                        ctx.runner.push_event(job["id"], "progress", {
                            "current": index,
                            "total": total,
                            "current_file": photo["filename"],
                            "phase": "Exporting for iNaturalist",
                        })

                revealed = False
                cancelled = ctx.runner.is_cancelled(job["id"])
                if exported and reveal and not cancelled:
                    revealed = reveal_inat_exports(
                        [item["path"] for item in exported], destination,
                    )
                return {
                    "ok": bool(exported),
                    "exported": exported,
                    "errors": errors,
                    "destination": destination,
                    "revealed": revealed,
                }
            finally:
                thread_db.close()

        return ctx.start(
            "inat-export",
            work,
            pausable=True,
            config={
                "photo_ids": [item["photo_id"] for item in submissions],
                "destination": destination,
            },
        )

    def _inat_edit_recipe_source(photo, recipe, fallback_path):
        from image_loader import RAW_EXTENSIONS

        vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
        folders = {photo["folder_id"]: photo["folder_path"]}
        primary_is_raw = (
            os.path.splitext(photo["filename"])[1].lower() in RAW_EXTENSIONS
        )
        if recipe.get("crop"):
            source_path, using_working_copy = _recipe_render_source(
                photo, recipe, 0, vireo_dir, folders,
            )
            return source_path or fallback_path, bool(using_working_copy)

        # For RAW primaries, skip the working-copy short-circuit while the
        # RAW source is available: legacy working copies predate the
        # highlight-preserving RAW decode and would feed iNat a clipped JPEG
        # to apply the recipe to. If the RAW source is offline/missing, the
        # working copy is the only local fallback.
        wc_rel = photo["working_copy_path"]
        if wc_rel and (
            not primary_is_raw or not os.path.exists(fallback_path)
        ):
            wc_path = (
                wc_rel if os.path.isabs(wc_rel)
                else os.path.join(vireo_dir, wc_rel)
            )
            if (
                os.path.exists(wc_path)
                and _path_satisfies_recipe_render(wc_path, photo, recipe, 0)
            ):
                return wc_path, True

        companion_path = photo["companion_path"]
        raw_source_available = os.path.exists(fallback_path)
        # RAW primaries are decoded with RAW_DECODE_PRESERVE_HIGHLIGHTS later;
        # only use the clipped camera JPEG when the RAW source is offline.
        if companion_path and (not primary_is_raw or not raw_source_available):
            companion = os.path.join(photo["folder_path"], companion_path)
            if (
                os.path.exists(companion)
                and _path_satisfies_recipe_render(companion, photo, recipe, 0)
            ):
                return companion, False
        return fallback_path, False

    def _inat_upload_photo_path(db, photo, fallback_path):
        import config as cfg

        vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
        recipe = db.get_photo_edit_recipe(photo["id"])
        if not recipe:
            return fallback_path, None

        import local_masks as _local_masks
        from image_edits import (
            EDIT_MATH_VERSION,
            apply_recipe_to_loaded_image,
            recipe_to_json,
        )
        from image_loader import (
            RAW_DECODE_PRESERVE_HIGHLIGHTS,
            RAW_EXTENSIONS,
            load_image,
        )

        source_path, using_working_copy = _inat_edit_recipe_source(
            photo, recipe, fallback_path,
        )
        fallback_available = bool(
            fallback_path and os.path.isfile(fallback_path)
        )
        # When the original is offline the working copy is the only usable
        # local source; the retry-from-original recovery below cannot save us.
        # Hold the publication/eviction guard through the exists → getmtime →
        # decode window so quota enforcement cannot unlink the working copy
        # mid-upload. Guard is an RLock, so nested acquisitions inside
        # load_image are safe.
        pin_working_copy = using_working_copy and not fallback_available
        source_pin_cm = (
            working_copy_publication_guard()
            if pin_working_copy else contextlib.nullcontext()
        )
        with source_pin_cm:
            if not source_path or not os.path.isfile(source_path):
                if using_working_copy and fallback_available:
                    # Quota enforcement can unlink the working copy between
                    # recipe-source resolution and this existence check.
                    source_path = fallback_path
                    using_working_copy = False
                else:
                    return None, f"{photo['filename']}: source file missing"

            out_dir = os.path.join(vireo_dir, "inat-uploads")
            os.makedirs(out_dir, exist_ok=True)
            out_path = os.path.join(out_dir, f"{photo['id']}.jpg")
            meta_path = os.path.join(out_dir, f"{photo['id']}.json")
            try:
                source_mtime = os.path.getmtime(source_path)
            except FileNotFoundError:
                if using_working_copy and fallback_available:
                    source_path = fallback_path
                    using_working_copy = False
                    source_mtime = os.path.getmtime(source_path)
                else:
                    return None, f"{photo['filename']}: source file missing"
            recipe_json = recipe_to_json(recipe) or ""
            # Include the edit-math version so a math bump invalidates this
            # cached render — the JPEG is keyed by recipe/source/mtime, none
            # of which change when only the per-pixel rendering math does, so
            # without this we'd keep submitting stale renders to iNaturalist
            # after a deploy.
            expected_meta = {
                "recipe": recipe_json,
                "source_path": source_path,
                "source_mtime": source_mtime,
                "edit_math_version": EDIT_MATH_VERSION,
            }
            try:
                if os.path.isfile(out_path) and os.path.isfile(meta_path):
                    with open(meta_path, encoding="utf-8") as f:
                        cached_meta = json.load(f)
                    if cached_meta == expected_meta:
                        return out_path, None
            except (OSError, ValueError, TypeError):
                pass

            # Derive the decode mode from the primary photo's extension rather
            # than source_path so a future change to source_path resolution
            # (working copy, companion JPEG fallback, etc.) cannot silently
            # bypass RAW_DECODE_PRESERVE_HIGHLIGHTS for a RAW primary.
            primary_is_raw = (
                os.path.splitext(photo["filename"])[1].lower()
                in RAW_EXTENSIONS
            )
            raw_decode = (
                RAW_DECODE_PRESERVE_HIGHLIGHTS if primary_is_raw else None
            )
            load_kwargs = {"raw_decode": raw_decode} if raw_decode else {}
            img = load_image(source_path, max_size=None, **load_kwargs)
            if img is None and using_working_copy and fallback_path and (
                os.path.isfile(fallback_path)
                and os.path.abspath(fallback_path)
                != os.path.abspath(source_path)
            ):
                # Working copy was evicted between validation and decode;
                # retry from the original before the companion fallback so
                # RAW primaries still use the highlight-preserving decode.
                retry_img = load_image(
                    fallback_path, max_size=None, **load_kwargs,
                )
                if retry_img is not None:
                    img = retry_img
                    source_path = fallback_path
                    using_working_copy = False
                    try:
                        source_mtime = os.path.getmtime(source_path)
                    except OSError:
                        pass
                    expected_meta["source_path"] = source_path
                    expected_meta["source_mtime"] = source_mtime
        expected_w, expected_h = 0, 0
        needs_companion = False
        if primary_is_raw:
            # libraw may return the embedded JPEG when demosaic fails — see
            # _external_edit_handoff_path for the same gate. Without this an
            # unsupported RAW would upload clipped/undersized pixels to
            # iNaturalist even when a usable sidecar JPEG exists. Both axes
            # checked via the shared helper.
            expected_w, expected_h = _recipe_source_dimensions(photo)
            needs_companion = img is None or _image_is_smaller_than_expected(
                img, expected_w, expected_h,
            )
        if needs_companion:
            # Mirror _external_edit_handoff_path: libraw may fail to decode
            # this RAW variant, but the full-size companion JPEG can still
            # carry the recipe for iNaturalist. Without this fallback the
            # upload silently fails for RAW+JPEG pairs whose RAW is
            # unsupported. Cache key stays on the RAW source — see comment
            # in _external_edit_handoff_path for the contract trade-off.
            companion_path = photo["companion_path"]
            folder_path = photo["folder_path"]
            if folder_path and companion_path:
                companion_abs = os.path.join(folder_path, companion_path)
                if (
                    os.path.exists(companion_abs)
                    and os.path.abspath(companion_abs)
                    != os.path.abspath(source_path)
                ):
                    companion_img = load_image(companion_abs, max_size=None)
                    # Prefer companion when it covers the expected size on
                    # both axes — a long-edge-only check misses cases like a
                    # 6000x3376 embedded preview "tying" a 6000x4000 sidecar
                    # and losing the short-edge content.
                    if _companion_image_can_replace_raw_result(
                        companion_img, img, expected_w, expected_h,
                    ):
                        if img is None:
                            log.info(
                                "iNat upload RAW decode failed for photo %s; "
                                "falling back to companion JPEG %s",
                                photo["id"], companion_abs,
                            )
                        else:
                            log.info(
                                "iNat upload RAW decode fell back to "
                                "undersized embedded JPEG (%dx%d) for "
                                "photo %s; using companion JPEG %s (%dx%d)",
                                img.size[0], img.size[1], photo["id"],
                                companion_abs,
                                companion_img.size[0],
                                companion_img.size[1],
                            )
                            img.close()
                        img = companion_img
                    elif companion_img is not None:
                        companion_img.close()
        if img is None:
            return None, f"{photo['filename']}: failed to load image"
        rendered = None
        tmp_path = None
        fd = None
        try:
            rendered = apply_recipe_to_loaded_image(
                img, recipe,
                native_size=_recipe_source_dimensions(photo),
                local_mask=_local_masks.load_snapshot(
                    vireo_dir, photo["id"], recipe,
                ),
            )
            quality = cfg.load().get("working_copy_quality", 92)
            fd, tmp_path = tempfile.mkstemp(
                prefix=f".{photo['id']}.", suffix=".jpg.tmp", dir=out_dir,
            )
            os.close(fd)
            fd = None
            rendered.save(tmp_path, format="JPEG", quality=quality)
            os.replace(tmp_path, out_path)
            with open(meta_path, "w", encoding="utf-8") as f:
                json.dump(expected_meta, f, sort_keys=True)
        except Exception:
            if fd is not None:
                with contextlib.suppress(OSError):
                    os.close(fd)
            with contextlib.suppress(OSError):
                if tmp_path:
                    os.unlink(tmp_path)
            raise
        finally:
            if rendered is not None:
                rendered.close()
            if rendered is not img:
                img.close()
        return out_path, None

    @app.route("/api/inat/submit", methods=["POST"])
    def api_inat_submit():
        """Submit a single observation to iNaturalist."""
        import config as cfg
        import inat

        user_cfg = cfg.load()
        token = user_cfg.get("inat_token")
        if not token:
            return json_error("iNaturalist token not configured. Add it in Settings.")

        data = request.json or {}
        photo_id = data.get("photo_id")
        if not photo_id:
            return json_error("photo_id is required")

        db = _get_db()
        photo = db.conn.execute(
            """SELECT p.*, f.path as folder_path FROM photos p
               JOIN folders f ON f.id = p.folder_id WHERE p.id = ?""",
            (photo_id,),
        ).fetchone()
        if not photo:
            return json_error("Photo not found", 404)
        if not db._photo_in_workspace(photo_id):
            return json_error(
                f"Photo {photo_id} does not belong to the active workspace", 403,
            )

        photo_path = os.path.join(photo["folder_path"], photo["filename"])
        if not os.path.isfile(photo_path):
            recipe = db.get_photo_edit_recipe(photo_id)
            wc_rel = photo["working_copy_path"]
            wc_abs = (
                wc_rel if wc_rel and os.path.isabs(wc_rel)
                else os.path.join(
                    os.path.dirname(app.config["THUMB_CACHE_DIR"]), wc_rel,
                )
                if wc_rel else None
            )
            companion_abs = (
                os.path.join(photo["folder_path"], photo["companion_path"])
                if photo["companion_path"] else None
            )
            if not (
                recipe
                and (
                    (wc_abs and os.path.isfile(wc_abs))
                    or (companion_abs and os.path.isfile(companion_abs))
                )
            ):
                return json_error("Photo file not found on disk", 404)

        upload_path, upload_error = _inat_upload_photo_path(db, photo, photo_path)
        if upload_error:
            return json_error(upload_error, 500)

        # Use overrides from request, or fall back to DB data. The helper
        # picks the highest-confidence prediction from the CURRENT
        # fingerprint, scoped to the active workspace, and respecting the
        # workspace-effective detector_confidence floor — submitting a
        # stale or below-threshold taxon to iNaturalist is permanent and
        # not easily reversible.
        min_conf = db.get_effective_config(user_cfg).get(
            "detector_confidence", 0.2
        )
        pred = db.get_top_prediction_for_photo(
            photo_id, min_detector_confidence=min_conf,
        )

        default_taxon = (
            (pred["scientific_name"] or pred["species"]) if pred else None
        )
        taxon = data.get("taxon_name", default_taxon)
        observed_on = (
            data["observed_on"]
            if "observed_on" in data
            else (photo["timestamp"][:10] if photo["timestamp"] else None)
        )
        loc = db.get_effective_photo_location(photo_id)
        photo_lat = loc["latitude"] if loc else None
        photo_lng = loc["longitude"] if loc else None
        has_latitude = "latitude" in data
        has_longitude = "longitude" in data
        if has_latitude != has_longitude:
            return json_error(
                "latitude and longitude must be provided together", 400,
            )
        if has_latitude:
            lat = data["latitude"]
            lng = data["longitude"]
        else:
            lat = photo_lat
            lng = photo_lng

        try:
            obs_id, obs_url = inat.submit_observation(
                token=token,
                photo_path=upload_path,
                taxon_name=taxon,
                observed_on=observed_on,
                latitude=lat,
                longitude=lng,
                description=data.get("description"),
                geoprivacy=data.get("geoprivacy", "open"),
            )
        except inat.InatAuthError as e:
            return json_error(str(e), 401)
        except inat.InatPartialUploadError as e:
            return jsonify({
                "error": str(e),
                "partial": True,
                "observation_id": e.observation_id,
                "observation_url": e.observation_url,
            }), 502
        except inat.InatApiError as e:
            return json_error(str(e), 502)

        db.record_inat_submission(photo_id, obs_id, obs_url)
        return jsonify({"observation_id": obs_id, "observation_url": obs_url})

    @app.route("/api/inat/submit-batch", methods=["POST"])
    def api_inat_submit_batch():
        """Submit multiple observations to iNaturalist."""
        import config as cfg
        import inat

        user_cfg = cfg.load()
        token = user_cfg.get("inat_token")
        if not token:
            return json_error("iNaturalist token not configured. Add it in Settings.")

        submissions = (request.json or {}).get("submissions", [])
        if not submissions:
            return json_error("submissions array is required")

        db = _get_db()
        # Resolve the workspace-effective detector_confidence floor once for
        # the whole batch — read-time thresholding means below-threshold
        # detections should never seed an iNat submission.
        min_conf = db.get_effective_config(user_cfg).get(
            "detector_confidence", 0.2
        )
        results = []
        for sub in submissions:
            photo_id = sub.get("photo_id")
            has_latitude = "latitude" in sub
            has_longitude = "longitude" in sub
            if has_latitude != has_longitude:
                results.append({
                    "photo_id": photo_id,
                    "error": "latitude and longitude must be provided together",
                })
                continue
            photo = db.conn.execute(
                """SELECT p.*, f.path as folder_path FROM photos p
                   JOIN folders f ON f.id = p.folder_id WHERE p.id = ?""",
                (photo_id,),
            ).fetchone()
            if not photo:
                results.append({"photo_id": photo_id, "error": "Photo not found"})
                continue
            if not db._photo_in_workspace(photo_id):
                results.append({
                    "photo_id": photo_id,
                    "error": (
                        f"Photo {photo_id} does not belong to the active workspace"
                    ),
                })
                continue

            photo_path = os.path.join(photo["folder_path"], photo["filename"])
            if not os.path.isfile(photo_path):
                results.append({"photo_id": photo_id, "error": "Photo file not found on disk"})
                continue

            upload_path, upload_error = _inat_upload_photo_path(
                db, photo, photo_path,
            )
            if upload_error:
                results.append({"photo_id": photo_id, "error": upload_error})
                continue

            # Current-fingerprint + workspace-scoped top prediction,
            # respecting the active detector_confidence floor — avoids
            # submitting a stale-label-set or now-hidden taxon to iNaturalist.
            pred = db.get_top_prediction_for_photo(
                photo_id, min_detector_confidence=min_conf,
            )

            default_taxon = (
                (pred["scientific_name"] or pred["species"])
                if pred else None
            )
            taxon = sub.get("taxon_name", default_taxon)
            observed_on = (
                sub["observed_on"]
                if "observed_on" in sub
                else (
                    photo["timestamp"][:10]
                    if photo["timestamp"] else None
                )
            )
            loc = db.get_effective_photo_location(photo_id)
            photo_lat = loc["latitude"] if loc else None
            photo_lng = loc["longitude"] if loc else None
            if has_latitude:
                lat = sub["latitude"]
                lng = sub["longitude"]
            else:
                lat = photo_lat
                lng = photo_lng

            try:
                obs_id, obs_url = inat.submit_observation(
                    token=token,
                    photo_path=upload_path,
                    taxon_name=taxon,
                    observed_on=observed_on,
                    latitude=lat,
                    longitude=lng,
                    description=sub.get("description"),
                    geoprivacy=sub.get("geoprivacy", "open"),
                )
                db.record_inat_submission(photo_id, obs_id, obs_url)
                results.append({"photo_id": photo_id, "observation_id": obs_id, "observation_url": obs_url})
            except inat.InatPartialUploadError as e:
                results.append({
                    "photo_id": photo_id,
                    "error": str(e),
                    "partial": True,
                    "observation_id": e.observation_id,
                    "observation_url": e.observation_url,
                })
            except (inat.InatAuthError, inat.InatApiError) as e:
                results.append({"photo_id": photo_id, "error": str(e)})

        return jsonify({"results": results})

    @app.route("/api/inat/submissions")
    def api_inat_submissions():
        """Return submission records for a set of photo IDs."""
        raw = request.args.get("photo_ids", "")
        if not raw:
            return json_error("photo_ids parameter is required")
        try:
            photo_ids = [int(x.strip()) for x in raw.split(",") if x.strip()]
        except ValueError:
            return json_error("photo_ids must be comma-separated integers")

        db = _get_db()
        subs = db.get_inat_submissions(photo_ids)
        # Convert keys to strings for JSON
        return jsonify({str(k): v for k, v in subs.items()})

    @app.route("/api/system/info")
    def api_system_info():
        """Return system information: ONNX Runtime, hardware."""
        info = runtime_execution_info()
        import config as cfg
        from platform_support import platform_support_info

        try:
            effective = _get_db().get_effective_config(cfg.load())
        except Exception:
            effective = cfg.load()
        info["platform_support"] = platform_support_info(effective)

        # "installed" requires both module AND weights — module-only
        # lets classify silently fall back to full-image classification.
        try:
            from detector import MEGADETECTOR_ONNX_PATH

            if os.path.isfile(MEGADETECTOR_ONNX_PATH):
                size_mb = round(os.path.getsize(MEGADETECTOR_ONNX_PATH) / 1024 / 1024, 1)
                info["megadetector"] = "installed"
                info["megadetector_detail"] = "MegaDetector V6 (YOLOv9-c) — subject detection for crop-based classification"
                info["megadetector_weights"] = "downloaded"
                info["megadetector_weights_path"] = MEGADETECTOR_ONNX_PATH
                info["megadetector_weights_size"] = f"{size_mb} MB"
            else:
                info["megadetector"] = "weights_missing"
                info["megadetector_detail"] = "Weights not downloaded — subject detection disabled until the MegaDetector V6 ONNX model is downloaded from the pipeline models page."
                info["megadetector_weights"] = "not downloaded"
                info["megadetector_weights_path"] = None
                info["megadetector_weights_size"] = None
        except ImportError:
            info["megadetector"] = "unavailable"
            info["megadetector_detail"] = "detector module not available"

        return jsonify(info)

    @app.route("/api/megadetector/download", methods=["POST"])
    @background_job
    def api_megadetector_download(ctx):
        """Download MegaDetector ONNX model as a background job."""

        def work(job):
            from detector import MEGADETECTOR_ONNX_DIR, MEGADETECTOR_ONNX_PATH
            from huggingface_hub import hf_hub_download
            from models import ONNX_REPO

            os.makedirs(MEGADETECTOR_ONNX_DIR, exist_ok=True)

            ctx.runner.push_event(job["id"], "progress", {
                "phase": "Downloading MegaDetector ONNX model...",
                "current": 0, "total": 1,
            })

            import shutil

            cached_path = hf_hub_download(
                repo_id=ONNX_REPO,
                filename="model.onnx",
                subfolder="megadetector-v6",
            )

            dest = MEGADETECTOR_ONNX_PATH
            if cached_path != dest:
                shutil.copy2(cached_path, dest)

            if not os.path.isfile(dest):
                raise RuntimeError("Download completed but ONNX file not found")

            size_mb = round(os.path.getsize(dest) / 1024 / 1024, 1)
            return {"status": "downloaded", "size": f"{size_mb} MB", "path": dest}

        return ctx.start("download-megadetector", work)

    @app.route("/api/megadetector/delete", methods=["POST"])
    def api_megadetector_delete():
        """Delete MegaDetector ONNX model from disk."""
        import shutil

        import detector
        from detector import MEGADETECTOR_ONNX_DIR

        removed = []
        if os.path.isdir(MEGADETECTOR_ONNX_DIR):
            shutil.rmtree(MEGADETECTOR_ONNX_DIR)
            removed.append(MEGADETECTOR_ONNX_DIR)

        # Clear the cached singleton so it reloads next time
        detector._session = None

        return jsonify({"deleted": removed, "count": len(removed)})

    @app.route("/api/scan/status")
    def api_scan_status():
        db = _get_db()

        # DB file size
        db_size = 0
        if os.path.exists(db_path):
            db_size = os.path.getsize(db_path)

        # Thumbnail cache size
        thumb_dir = app.config["THUMB_CACHE_DIR"]
        thumb_size = 0
        if os.path.isdir(thumb_dir):
            for f in os.listdir(thumb_dir):
                fp = os.path.join(thumb_dir, f)
                if os.path.isfile(fp):
                    thumb_size += os.path.getsize(fp)

        # ``photo_count`` is the workspace's total inventory (includes photos
        # in folders flagged 'missing'), so the dashboard's headline number
        # stays honest when an external drive is unmounted instead of
        # collapsing to 0. ``accessible_photo_count`` is the actionable
        # subset; when it's lower, the dashboard surfaces the gap.
        # ``keyword_count`` likewise reports inventory-wide so the Keywords
        # card agrees with the Top Species / Other Keywords charts (which
        # also count photos in missing folders).
        return jsonify(
            {
                "photo_count": db.count_photos_in_workspace(),
                "accessible_photo_count": db.count_photos(),
                "missing_folder_count": len(db.get_missing_folders()),
                "folder_count": db.count_folders(),
                "keyword_count": db.count_keywords_in_workspace(),
                "pending_changes": db.count_pending_changes(),
                "db_size": db_size,
                "thumb_cache_size": thumb_size,
            }
        )

    # -- Job API routes --

    def _build_scan_work(
        roots, incremental, active_ws, repair_missing_metadata=False,
    ):
        """Build the background work function for a scan job.

        Shared by ``POST /api/jobs/scan`` and
        ``POST /api/folders/<id>/rescan`` so per-folder rescans reuse the
        same scan + thumbnail pipeline as a full scan.

        ``roots`` may be a single path string (back-compat, one root) or a
        list of paths. When multiple roots are given they are scanned
        **serially** inside this single job -- that's the whole point of
        this wrapper: parallel scan jobs used to fight for the SQLite
        writer lock, so we now process roots one after another. A failure
        on one root does not abort the others; the error is recorded and
        the job ends in ``"failed"`` (mixed-outcome rollup convention).
        """
        import config as cfg

        runner = app._job_runner

        # Back-compat: accept a bare string in addition to a list.
        if isinstance(roots, str):
            roots_list = [roots]
        else:
            roots_list = list(roots)

        def work(job):
            from scanner import ScanCancelled
            from scanner import scan as do_scan

            thread_db = Database(db_path)
            thread_db.set_active_workspace(active_ws)
            # Check folder health before scanning to prevent duplicate imports
            if thread_db.check_folder_health():
                _invalidate_missing_originals_cache()

            # Accumulator so multi-root progress doesn't rewind at each
            # root boundary. scanner.scan() reports (current, total) local
            # to its invocation; we fold those into cumulative counters
            # that the SSE/status stream reads.
            # Track both the last reported *processed* count and the
            # last reported *total* for the current root. On root
            # boundary we advance the cumulative baseline by the
            # processed count (not the planned total) so a root that
            # fails mid-scan doesn't inflate the baseline with phantom
            # files the next root would start above.
            scan_acc = {"prior": 0, "last_current": 0, "last_total": 0}
            # Photos that actually reached the catalog, summed across roots
            # from each scan()'s counts sink. Kept separate from the
            # progress accumulator above: progress counts every file the
            # scan disposes of (including ones skipped because they
            # vanished under a dropped mount), which is what a progress bar
            # needs but overstates the result line.
            indexed_acc = {"n": 0}

            def progress_cb(current, total):
                scan_acc["last_current"] = current
                scan_acc["last_total"] = total
                cum_current = scan_acc["prior"] + current
                cum_total = scan_acc["prior"] + total
                job["progress"]["current"] = cum_current
                job["progress"]["total"] = cum_total
                runner.update_step(
                    job["id"], "scan",
                    progress={"current": cum_current, "total": cum_total},
                )
                runner.push_event(
                    job["id"],
                    "progress",
                    {
                        "current": cum_current,
                        "total": cum_total,
                        "current_file": job["progress"].get("current_file", ""),
                        "rate": round(
                            cum_current / max(time.time() - job["_start_time"], 0.01), 1
                        ),
                        "phase": "Scanning photos",
                    },
                )

            def advance_scan_acc():
                # Use processed count, not planned total — a root that
                # raised mid-scan will have last_current < last_total,
                # and starting the next root above the actual processed
                # count would overreport photos indexed.
                scan_acc["prior"] += scan_acc["last_current"]
                scan_acc["last_current"] = 0
                scan_acc["last_total"] = 0

            job["_start_time"] = time.time()
            runner.set_steps(job["id"], [
                {"id": "scan", "label": "Scan photos"},
                {"id": "thumbnails", "label": "Generate thumbnails"},
            ])
            runner.update_step(job["id"], "scan", status="running")
            effective_cfg = thread_db.get_effective_config(cfg.load())
            pipeline_cfg = effective_cfg.get("pipeline", {})

            def status_cb(message, phase_current=None, phase_total=None, phase_label=None):
                progress_payload = {
                    "phase": phase_label or message,
                    "current": job["progress"].get("current", 0),
                    "total": job["progress"].get("total", 0),
                    "current_file": message,
                    "rate": 0,
                    "phase_current": phase_current,
                    "phase_total": phase_total,
                    "phase_label": phase_label,
                }
                runner.update_step(job["id"], "scan", current_file=message)
                runner.push_event(job["id"], "progress", progress_payload)

            def cancel_check():
                return runner.is_cancelled(job["id"])

            def pause_check():
                return runner.pause_requested(job["id"])

            def cancel_only_check():
                return runner.cancellation_requested(job["id"])

            vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])

            # Per-root failures are caught and recorded rather than
            # re-raised so a failure on root A doesn't prevent root B
            # from scanning. Any failure flips the job to "failed" at
            # the end (mixed-outcome rollup).
            #
            # Track roots by failure class so the rollup below can
            # distinguish "this root's scan raised" (no photos indexed
            # — thumbnails can skip) from "this root's scan succeeded
            # but cache invalidation raised" (photos DID get indexed —
            # thumbnails must still run). Using len(root_errors) alone
            # double-counts roots that hit both failure classes and
            # misclassifies cache-only failures as scan failures.
            root_errors = []
            scan_failed_roots = set()
            cache_failed_roots = set()
            cancelled = False
            for idx, root in enumerate(roots_list, 1):
                if cancel_check():
                    cancelled = True
                    break
                phase = (
                    f"Scanning root {idx} of {len(roots_list)}: {root}"
                    if len(roots_list) > 1
                    else "Scanning photos"
                )
                runner.push_event(job["id"], "progress", {
                    "phase": phase,
                    "current": job["progress"].get("current", 0),
                    "total": job["progress"].get("total", 0),
                    "current_file": phase,
                    "rate": 0,
                })
                # Counts sink rather than the return value: scan() commits
                # rows as it goes and can raise (or be cancelled) after
                # thousands have landed. Reading the sink in `finally`
                # credits that work on every exit path — a root that dies
                # late would otherwise report zero photos indexed.
                root_counts = {}
                try:
                    do_scan(
                        root, thread_db,
                        progress_callback=progress_cb,
                        incremental=incremental,
                        extract_full_metadata=pipeline_cfg.get("extract_full_metadata", True),
                        status_callback=status_cb,
                        vireo_dir=vireo_dir,
                        thumb_cache_dir=app.config["THUMB_CACHE_DIR"],
                        cancel_check=cancel_check,
                        pause_check=pause_check,
                        cancel_only_check=cancel_only_check,
                        repair_missing_metadata=repair_missing_metadata,
                        counts=root_counts,
                    )
                except Exception as exc:
                    if isinstance(exc, ScanCancelled) and cancel_check():
                        log.info("Scan job %s cancelled during root %s", job["id"], root)
                        cancelled = True
                        break
                    log.exception("Scan failed for root %s", root)
                    scan_failed_roots.add(root)
                    msg = f"[{root}] {exc}"
                    root_errors.append(msg)
                    if msg not in job["errors"]:
                        job["errors"].append(msg)
                finally:
                    # Credit whatever this root indexed regardless of how
                    # it exited — completed, raised, or cancelled. The
                    # rows are committed either way, so the summary must
                    # count them either way.
                    indexed_acc["n"] += root_counts.get("indexed", 0)
                    # scanner.scan commits photo rows incrementally, so
                    # even a mid-scan failure can leave DB state that
                    # invalidates cached new-image counts. A failure
                    # here must surface: the shared cache has a 5-min
                    # TTL, so users would see stale "new images" counts
                    # with no job-level failure signal if we swallowed
                    # these errors. Keep the try/except so we still
                    # advance scan_acc and try the remaining roots,
                    # but record the failure into root_errors so the
                    # job is flagged failed at the rollup below.
                    try:
                        _invalidate_new_images_after_scan(thread_db, root)
                    except Exception as cache_exc:
                        log.exception(
                            "Failed to invalidate new-image cache for %s", root,
                        )
                        cache_failed_roots.add(root)
                        cache_msg = (
                            f"[{root}] cache invalidation failed "
                            f"after scan: {cache_exc}"
                        )
                        root_errors.append(cache_msg)
                        if cache_msg not in job["errors"]:
                            job["errors"].append(cache_msg)
                    # scanner.scan touches disk and may add or remove
                    # photo rows; a ready Missing Originals payload
                    # computed before the scan can now be stale (e.g.
                    # user restored an original before running "Rescan
                    # this Folder"). The pre-scan health-check
                    # invalidation only fires when a folder flips
                    # missing/ok, so also drop the cache once the scan
                    # itself has run — even on partial failure, since
                    # rows are committed incrementally.
                    try:
                        _invalidate_missing_originals_cache()
                    except Exception:
                        log.exception(
                            "Failed to invalidate missing-originals cache for %s",
                            root,
                        )
                    advance_scan_acc()

            if cancelled or cancel_check():
                # Same indexed count as the completed path, not the
                # progress counter. Otherwise "N photos" would mean two
                # different things depending on which branch produced it,
                # and a cancelled scan of a dropped share would report a
                # full house of photos it never cataloged.
                photo_count = indexed_acc["n"]
                runner.update_step(
                    job["id"], "scan", status="cancelled",
                    summary=f"{photo_count} photos (cancelled)",
                )
                runner.update_step(
                    job["id"], "thumbnails", status="skipped",
                    summary="skipped (cancelled)",
                )
                return {"photos_indexed": photo_count, "cancelled": True}

            # Count what the scans reported as indexed, not the progress
            # counter. On a clean run they agree; they diverge exactly when
            # the run went wrong — progress advances for files that were
            # discovered and then skipped (vanished under a mount that
            # dropped mid-scan), so "N photos" would read as a success
            # line for a scan that cataloged nothing.
            photo_count = indexed_acc["n"]
            # Unique roots that hit any failure class. Counting unique
            # roots (not error entries) avoids inflating the "N of M"
            # summary when a single root raises in both scan and cache
            # invalidation.
            failed_root_count = len(scan_failed_roots | cache_failed_roots)
            metadata_warning = _scan_metadata_warning()
            if root_errors:
                scan_summary = (
                    f"{photo_count} photos ({failed_root_count} of "
                    f"{len(roots_list)} root"
                    f"{'s' if len(roots_list) != 1 else ''} failed)"
                )
                if metadata_warning:
                    scan_summary += f" — {metadata_warning}"
                runner.update_step(
                    job["id"], "scan", status="failed", summary=scan_summary,
                    error=root_errors[0], error_count=len(root_errors),
                )
            else:
                scan_summary = f"{photo_count} photos"
                if metadata_warning:
                    scan_summary += f" — {metadata_warning}"
                runner.update_step(
                    job["id"], "scan", status="completed",
                    summary=scan_summary,
                )
            # Skip the thumbnail phase when EVERY requested root's scan
            # raised. generate_all() walks the whole library looking
            # for missing thumbnails — running it after a total scan
            # failure does a long, unrelated pass and delays the
            # failure feedback the user actually needs. When at least
            # one root's scan succeeded we still run thumbs so those
            # newly-indexed photos get covered. Cache-invalidation
            # failures do NOT gate this decision: the scan for that
            # root did produce indexed photos that need thumbnails.
            all_roots_failed = (
                bool(roots_list) and len(scan_failed_roots) == len(roots_list)
            )

            if all_roots_failed:
                log.info(
                    "All %d scan root(s) failed; skipping thumbnail phase",
                    len(roots_list),
                )
                runner.update_step(
                    job["id"], "thumbnails", status="skipped",
                    summary="skipped (all scan roots failed)",
                )
                thumb_result = None
            else:
                runner.update_step(job["id"], "thumbnails", status="running")

                # Auto-generate thumbnails for new photos only
                from thumbnails import generate_all

                log.info("Generating thumbnails...")
                runner.push_event(
                    job["id"],
                    "progress",
                    {
                        "current": 0,
                        "total": 0,
                        "current_file": "Checking for new thumbnails...",
                        "rate": 0,
                        "phase": "Generating thumbnails",
                    },
                )

                def thumb_cb(current, total):
                    job["progress"]["current"] = current
                    job["progress"]["total"] = total
                    runner.push_event(
                        job["id"],
                        "progress",
                        {
                            "current": current,
                            "total": total,
                            "current_file": "",
                            "rate": round(
                                current / max(time.time() - job["_start_time"], 0.01), 1
                            ),
                            "phase": "Generating thumbnails",
                        },
                    )

                thumb_result = generate_all(
                    thread_db, app.config["THUMB_CACHE_DIR"], progress_callback=thumb_cb,
                    vireo_dir=vireo_dir,
                )
                from thumbnails import format_summary as thumb_summary
                runner.update_step(job["id"], "thumbnails", status="completed",
                                   summary=thumb_summary(thumb_result))

            # Mixed-outcome rollup: any failed root => job is "failed".
            # JobRunner._run_job dedupes job["errors"] by exact string
            # match. Raise the first per-root message (already recorded
            # above) so no extra aggregate entry is appended — that
            # would inflate error_count in job/history output. The
            # "N of M roots failed" context is already visible via the
            # scan step's summary and error_count set above.
            if root_errors:
                raise RuntimeError(root_errors[0])

            return {"photos_indexed": photo_count, "thumbnails": thumb_result}

        return work

    @app.route("/api/jobs/scan", methods=["POST"])
    @background_job
    def api_job_scan(ctx):
        """Queue a scan job.

        Body accepts either:
          * ``{"root": "/path"}`` -- single root (back-compat).
          * ``{"roots": ["/a", "/b", ...]}`` -- multiple roots, scanned
            serially inside a single job. Multi-root support avoids the
            SQLite writer-lock contention that used to happen when the
            UI enqueued one job per root (PR #634 added retry/backoff
            as defense-in-depth; this is the root-cause fix).
        """
        body = request.get_json(silent=True) or {}
        incremental = body.get("incremental", False)

        # Normalize inputs. Prefer the explicit plural form when both are
        # provided; a caller who sends ``roots`` has opted into the new API.
        if "roots" in body:
            roots_in = body.get("roots")
            if not isinstance(roots_in, list) or not roots_in:
                return json_error("roots must be a non-empty list")
            roots_list = [str(r) for r in roots_in if r]
            if not roots_list:
                return json_error("roots must be a non-empty list")
        else:
            root = body.get("root", "")
            if not root:
                return json_error("root path required")
            roots_list = [root]

        from image_loader import is_excluded_scan_path

        for r in roots_list:
            # Reject other-app data bundles (Apple Photos / Aperture / Photo
            # Booth) before any stat: ``os.path.isdir`` on a ``.photoslibrary``
            # path — or a symlink to one — itself trips the macOS
            # "access data from other apps" TCC prompt, defeating the guards
            # inside scan().
            if is_excluded_scan_path(r):
                return json_error(
                    f"path is inside a macOS app-managed library and cannot "
                    f"be scanned: {r}"
                )
            if not os.path.isdir(r):
                return json_error(f"directory not found: {r}")

        # Remember scan roots (skip temp directories from tests)
        import tempfile

        import config as cfg

        tmp_prefix = os.path.realpath(tempfile.gettempdir())
        # Lock + raw read-modify-write so a concurrent settings PATCH isn't
        # reverted and we don't pin every DEFAULTS value into the user's
        # file (see api_pipeline_save_grouping_defaults).
        with _settings_write_lock:
            raw = _read_raw_config_file()
            saved_roots = raw.get("scan_roots")
            if not isinstance(saved_roots, list):
                saved_roots = []
            changed = False
            for r in roots_list:
                if os.path.realpath(r).startswith(tmp_prefix):
                    continue
                if r not in saved_roots:
                    saved_roots.insert(0, r)
                    changed = True
            if changed:
                raw["scan_roots"] = saved_roots
                cfg.save(raw)

        # A workspace with active local state has its folder paths rebased
        # into the managed copy; scanner.scan() calls
        # db.add_folder(link_to_workspace=True) for every folder it discovers,
        # so any new root scanned here would add folder/workspace_folders rows
        # that the manifest and local_workspace_folders don't cover — sync and
        # discard could not rebase or remove them, and the workspace would mix
        # unmanaged source paths with the managed local copy. Refuse until
        # the local copy is synced or discarded, mirroring the folder-add,
        # folder-remove, and move-folders guards. Also refuse when a
        # stage/sync/discard job is queued or running but hasn't yet touched
        # local_workspaces — otherwise the scan enqueued in that window
        # could add unmanaged rows before the transition worker claims the
        # workspace.
        if ctx.workspace_id is not None:
            with stage_boundary_lock():
                if has_local_workspace(_get_db(), ctx.workspace_id):
                    return json_error(
                        "Cannot scan folders while working locally. Sync or discard the local copy first.",
                        409,
                    )
                pending = _pending_local_workspace_transition(ctx.workspace_id)
                if pending:
                    return json_error(
                        f"Wait for the {pending['type']} job to finish before scanning; "
                        "otherwise the scan would add folder rows the workspace's local "
                        "manifest doesn't cover.",
                        409,
                    )

        work = _build_scan_work(roots_list, incremental, ctx.workspace_id)

        job_config = {"roots": roots_list, "incremental": incremental}
        # Back-compat: keep ``root`` in config when exactly one was given,
        # so existing consumers (history viewers, etc.) still find it.
        if len(roots_list) == 1:
            job_config["root"] = roots_list[0]

        return ctx.start(
            "scan", work, config=job_config,
            pausable=True,
        )

    @app.route("/api/folders/<int:folder_id>/rescan", methods=["POST"])
    @background_job
    def api_folder_rescan(ctx, folder_id):
        """Queue a scan job scoped to the given folder's path.

        Body (optional): {"incremental": bool}
        Returns: {"job_id": "scan-..."} on success; 404 if the folder id
        is unknown or not linked to the active workspace.
        """
        body = request.get_json(silent=True) or {}
        incremental = bool(body.get("incremental", False))
        db = _get_db()
        folder = db.get_folder(folder_id)
        if not folder:
            return json_error("folder not found", 404)
        # Folders are global but scans emit workspace-scoped data (predictions,
        # pending_changes). Reject rescans of folders the active workspace has
        # no claim on — otherwise a stale UI or crafted request could pollute
        # this workspace with scan output from an unrelated folder, and
        # add_folder's auto-link would silently attach it.
        linked = db.conn.execute(
            "SELECT 1 FROM workspace_folders WHERE workspace_id = ? AND folder_id = ?",
            (ctx.workspace_id, folder_id),
        ).fetchone()
        if not linked:
            return json_error("folder not found", 404)
        root = folder["path"]
        from image_loader import is_excluded_scan_path
        # See api_job_scan for why this must run before os.path.isdir.
        if is_excluded_scan_path(root):
            return json_error(
                f"folder is inside a macOS app-managed library and cannot "
                f"be scanned: {root}"
            )
        if not os.path.isdir(root):
            return json_error(f"folder path no longer exists: {root}")

        work = _build_scan_work(root, incremental, ctx.workspace_id)

        return ctx.start(
            "scan", work,
            config={
                "root": root,
                "incremental": incremental,
                "folder_id": folder_id,
            },
            pausable=True,
        )

    @app.route("/api/jobs/scan-workspace", methods=["POST"])
    @background_job
    def api_job_scan_workspace(ctx):
        """Queue an incremental scan across every root folder of the active
        workspace.

        Powers the "Rescan entire workspace" option. Roots that no longer
        resolve on disk are skipped (they're surfaced separately by the
        missing-folders flow) and reported back in ``skipped`` so the UI can
        be honest about what actually ran. Returns 400 with a message when no
        root is currently reachable, so the caller never shows "rescan
        started" for a no-op.
        """
        body = request.get_json(silent=True) or {}
        incremental = bool(body.get("incremental", True))
        db = _get_db()
        roots = [r["path"] for r in db.get_workspace_folder_roots(ctx.workspace_id)]
        existing = [r for r in roots if os.path.isdir(r)]
        skipped = [r for r in roots if not os.path.isdir(r)]
        if not existing:
            if roots:
                return json_error("no workspace folders are currently on disk")
            return json_error("this workspace has no folders to rescan")

        work = _build_scan_work(existing, incremental, ctx.workspace_id)
        job_config = {"roots": existing, "incremental": incremental}
        if len(existing) == 1:
            job_config["root"] = existing[0]
        return ctx.start(
            "scan", work, config=job_config,
            pausable=True,
            extra={"roots": existing, "skipped": skipped},
        )

    def _metadata_repair_count(db, workspace_id, root_paths=None):
        # Don't filter by ``folders.status``: that column is only refreshed
        # by ``check_folder_health`` (10-minute loop or the manual
        # "check missing folders" flow), so a workspace whose drive was
        # unplugged and is now reconnected still reads as ``status='missing'``
        # until then. The readiness endpoint fires as soon as the Import
        # page opens; if we filtered by ``status``, users would see 0
        # repairable photos and the repair route would 409 with "no
        # photos need metadata repair" even though ``os.path.isdir`` would
        # let the repair job scan them.
        #
        # ``root_paths`` scopes the count to real-time reachable roots
        # (based on ``os.path.isdir``). When a workspace mixes an offline
        # drive with photos missing EXIF and a separate reachable drive
        # with no repairable rows, an unscoped count combined with a
        # non-empty ``reachable_roots`` list would enable the Repair
        # button and start a job that finishes without ever touching the
        # offline photos — Codex's "repeating repair job" pathology. The
        # scoped count reflects only what the repair pass would actually
        # process. ``None`` preserves the unscoped legacy shape for any
        # future caller that wants a workspace-wide figure.
        params = [workspace_id]
        where_extra = ""
        if root_paths is not None:
            if not root_paths:
                return 0
            normalized_roots = [
                r.replace("\\", "/").rstrip("/") for r in root_paths if r
            ]
            if not normalized_roots:
                return 0
            clauses = []
            for norm in normalized_roots:
                prefix = norm + "/"
                # Match ``f.path`` normalized to forward slashes either
                # exactly against the root or as a boundary-preserving
                # prefix. ``substr(...)=prefix`` avoids the wildcard
                # collision LIKE would introduce (e.g. a folder called
                # ``photos_backup`` incorrectly matching a reachable
                # ``photos`` root because ``_`` matches any character
                # in LIKE without ESCAPE).
                clauses.append(
                    "(REPLACE(f.path, '\\', '/') = ? "
                    "OR substr(REPLACE(f.path, '\\', '/'), 1, ?) = ?)"
                )
                params.extend([norm, len(prefix), prefix])
            where_extra = " AND (" + " OR ".join(clauses) + ")"
        rows = db.conn.execute(
            "SELECT DISTINCT p.id, p.filename, "
            "f.id AS folder_id, f.path AS folder_path "
            "FROM photos p "
            "JOIN folders f ON f.id = p.folder_id "
            "JOIN workspace_folders wf ON wf.folder_id = f.id "
            "WHERE wf.workspace_id = ? "
            "AND p.exif_data IS NULL"
            + where_extra
            + " ORDER BY f.path, p.filename",
            params,
        ).fetchall()

        # A database row is only repairable when its original still exists.
        # The incremental repair scan discovers files from disk, so counting
        # a deleted/moved original here would leave the Repair button enabled
        # forever for a job that can never visit that row. Enumerate each
        # candidate folder once instead of statting every photo individually;
        # this keeps readiness responsive for large degraded imports.
        from image_loader import is_excluded_scan_path

        folder_files = {}
        repairable = 0
        for row in rows:
            folder_id = row["folder_id"]
            folder_path = row["folder_path"]
            if folder_id not in folder_files:
                if is_excluded_scan_path(folder_path):
                    folder_files[folder_id] = None
                else:
                    try:
                        with os.scandir(folder_path) as entries:
                            folder_files[folder_id] = {
                                entry.name for entry in entries if entry.is_file()
                            }
                    except OSError:
                        # The folder disappeared or became unreadable after
                        # root reachability was checked. Treat its rows as
                        # unavailable rather than offering a no-op repair.
                        folder_files[folder_id] = None

            names = folder_files[folder_id]
            if names is None:
                continue
            filename = row["filename"]
            if filename in names:
                repairable += 1
                continue
            # Preserve the filesystem's own case and Unicode matching rules
            # for a catalog name that did not compare byte-for-byte with the
            # directory entry (notably default APFS and NTFS volumes).
            if os.path.isfile(os.path.join(folder_path, filename)):
                repairable += 1
        return repairable

    @app.route("/api/jobs/repair-metadata", methods=["POST"])
    @background_job
    def api_job_repair_metadata(ctx):
        """Incrementally rescan reachable roots that contain missing EXIF."""
        from image_loader import is_excluded_scan_path
        from metadata import exiftool_status

        status = exiftool_status()
        if not status["available"]:
            return jsonify({
                "error": "Repair ExifTool before repairing photo metadata.",
                "code": "exiftool_required",
                "exiftool": status,
            }), 409

        db = _get_db()
        roots = [r["path"] for r in db.get_workspace_folder_roots(ctx.workspace_id)]
        # See api_import_readiness for why excluded bundles must be filtered
        # before os.path.isdir here (macOS TCC prompt on Photos Library).
        existing = [
            root for root in roots
            if not is_excluded_scan_path(root) and os.path.isdir(root)
        ]
        if not existing:
            return json_error("no metadata-repair folders are currently on disk")
        # Count against the actually-reachable roots so the response's
        # ``photo_count`` matches what the job will process. An unscoped
        # count could report photos under an offline sibling root that
        # this job will never touch.
        repair_count = _metadata_repair_count(db, ctx.workspace_id, existing)
        if not repair_count:
            return json_error("no photos need metadata repair", 409)

        work = _build_scan_work(
            existing, True, ctx.workspace_id, repair_missing_metadata=True,
        )
        job_config = {
            "roots": existing,
            "incremental": True,
            "repair_metadata": True,
            "repair_photo_count": repair_count,
        }
        if len(existing) == 1:
            job_config["root"] = existing[0]
        return ctx.start(
            "metadata-repair", work, config=job_config, pausable=True,
            extra={"photo_count": repair_count, "roots": existing},
        )

    @app.route("/api/duplicates/apply", methods=["POST"])
    def api_duplicates_apply():
        """Apply resolver decisions for the given list of file hashes.

        Body: {"hashes": ["<hash>", ...]}. For each hash we look up every
        non-rejected photo sharing it and hand that set to
        apply_duplicate_resolution, which picks a winner via the pure
        resolver and flags the losers as rejected. Returns the total number
        of photos rejected across all hashes.
        """
        body = request.get_json(silent=True)
        if not isinstance(body, dict):
            return json_error("hashes required")
        hashes = body.get("hashes")
        if not isinstance(hashes, list) or not hashes:
            return json_error("hashes required")

        for h in hashes:
            if not isinstance(h, str) or not h:
                return json_error("hashes must be a list of non-empty strings")

        db = _get_db()
        total_rejected = 0
        for h in hashes:
            rows = db.conn.execute(
                "SELECT id FROM photos "
                "WHERE file_hash = ? AND (flag IS NULL OR flag != 'rejected')",
                (h,),
            ).fetchall()
            if len(rows) < 2:
                continue
            result = db.apply_duplicate_resolution([r["id"] for r in rows])
            total_rejected += result.get("rejected", 0)
        return jsonify({"rejected_count": total_rejected})

    @app.route("/api/folders/reveal", methods=["POST"])
    def api_folders_reveal():
        """Reveal a batch of folder paths in the OS file manager.

        Body: ``{"paths": [str, ...]}``. Backs the bulk-decide UI's
        "Reveal in Finder" button, which opens every folder in a bucket
        with a single click.

        Each path must exist as a row in the ``folders`` table — refusing
        arbitrary filesystem paths is the security boundary, otherwise
        a malicious caller could probe paths via the side-channel of
        whether the OS file manager opened. Unknown paths are returned
        in ``skipped`` rather than 404'd so a single bad path doesn't
        kill a bucket-wide batch.

        Returns ``{"ok": True, "revealed": [str], "skipped":
        [{"path", "reason"}], "failed": [{"path", "reason"}]}``.
        """
        body = request.get_json(silent=True)
        if not isinstance(body, dict):
            return json_error("paths required")
        paths = body.get("paths")
        if not isinstance(paths, list) or not paths:
            return json_error("paths required")
        for p in paths:
            if not isinstance(p, str) or not p:
                return json_error("paths must be a list of non-empty strings")

        db = _get_db()
        # Validate every path against the ``folders`` table — refusing
        # arbitrary filesystem paths is the security boundary, otherwise
        # a caller could probe disk via the OS-window-opens side channel.
        # Don't gate on workspace_folders: duplicate scans are
        # library-wide (file_hash is global), so a bucket can legitimately
        # surface folders linked only to another workspace, and Vireo is
        # a single-user app where workspaces are organizational rather
        # than access-bound.
        # Normalize both sides so legacy/relocated rows stored with a
        # trailing separator still match bucket-UI paths derived from
        # ``os.path.dirname(...)`` — same trap bulk_resolve_by_folder
        # patched.
        norm_paths = [os.path.normpath(p) for p in paths]
        all_rows = db.conn.execute("SELECT path FROM folders").fetchall()
        known_norm = {os.path.normpath(r["path"]) for r in all_rows}

        revealed = []
        skipped = []
        failed = []
        for path, norm in zip(paths, norm_paths, strict=True):
            if norm not in known_norm:
                skipped.append({"path": path, "reason": "not a known folder"})
                continue
            try:
                if sys.platform == "darwin":
                    proc = subprocess.run(["open", "-R", "--", path],
                                          timeout=5, check=False,
                                          **no_window_kwargs())
                elif sys.platform.startswith("win"):
                    # Folder reveal opens the folder itself (no /select,)
                    # so the user sees its contents.
                    proc = subprocess.run(["explorer", path],
                                          timeout=5, check=False,
                                          **no_window_kwargs())
                else:
                    # xdg-open doesn't honor `--`; abspath guarantees a
                    # leading slash so a crafted leading-dash path can't
                    # be parsed as a flag.
                    proc = subprocess.run(
                        ["xdg-open", os.path.abspath(path)],
                        timeout=5, check=False,
                        **no_window_kwargs(),
                    )
                # check=False returns a CompletedProcess for every exit
                # code; classify non-zero as failed so the UI doesn't
                # report success when nothing actually opened (e.g.
                # unmounted volume, stale path).
                if proc.returncode != 0:
                    failed.append({
                        "path": path,
                        "reason": f"reveal command exited {proc.returncode}",
                    })
                else:
                    revealed.append(path)
            except (FileNotFoundError, subprocess.TimeoutExpired, OSError) as exc:
                failed.append({"path": path, "reason": str(exc)})

        return jsonify({
            "ok": True,
            "revealed": revealed,
            "skipped": skipped,
            "failed": failed,
        })

    @app.route("/api/duplicates/bulk-resolve", methods=["POST"])
    def api_duplicates_bulk_resolve():
        """Force-resolve a batch of duplicate groups by keeping the photo
        whose folder matches ``keep_folder``.

        Body: ``{"file_hashes": [str, ...], "keep_folder": str}``. For each
        hash, the photo in ``keep_folder`` becomes the kept winner; every
        other non-rejected photo sharing the hash becomes rejected, with
        rating/keywords merged onto the winner.

        Returns ``{"ok": True, "resolved_count": int, "resolved":
        [{"file_hash", "winner_id", "loser_ids"}], "skipped":
        [{"file_hash", "reason"}]}``. ``loser_ids`` is surfaced so the UI
        can chain into ``/api/duplicates/delete-loser-files`` when the
        user opted in to immediate trash.
        """
        body = request.get_json(silent=True)
        if not isinstance(body, dict):
            return json_error("file_hashes and keep_folder required")
        file_hashes = body.get("file_hashes")
        keep_folder = body.get("keep_folder")
        if not isinstance(file_hashes, list) or not file_hashes:
            return json_error("file_hashes required")
        if not isinstance(keep_folder, str) or not keep_folder:
            return json_error("keep_folder required")
        for h in file_hashes:
            if not isinstance(h, str) or not h:
                return json_error("file_hashes must be a list of non-empty strings")

        db = _get_db()
        result = db.bulk_resolve_by_folder(file_hashes, keep_folder)
        return jsonify({
            "ok": True,
            "resolved_count": len(result["resolved"]),
            "resolved": result["resolved"],
            "skipped": result["skipped"],
        })

    @app.route("/api/duplicates/delete-loser-files", methods=["POST"])
    def api_duplicates_delete_loser_files():
        """Move duplicate loser files to OS Trash and remove their DB rows.

        Body: {"photo_ids": [int, ...]}. For each id we require:
          - the row's flag is 'rejected' (already auto-resolved or
            user-applied), AND
          - at least one OTHER photo with the same ``file_hash`` is NOT
            rejected (the kept "winner" anchor that makes this row a
            duplicate-loser rather than an unrelated rejection).

        Validating both conditions prevents this endpoint from being misused
        to trash files for arbitrary rejected photos (e.g. a photo the user
        manually rejected for non-duplicate reasons).

        After a successful trash we also delete the loser's photo row (and
        its cached thumbnail / preview / working-copy files). Without that,
        ``/api/duplicates/disk-cleanup-summary`` would keep reporting the
        same count forever — the summary predicate can't cheaply tell that
        the on-disk file has been removed (stat'ing every loser path on a
        slow network volume would make the banner poll expensive). Deleting
        the row makes the count correct without a stat. The keywords/rating
        were merged onto the winner during ``apply_duplicate_resolution``,
        so nothing of value is lost. If the user later restores the file
        from Trash and re-scans, the auto-resolve hook re-creates the row
        and the cycle is idempotent.

        Returns ``{trashed: N, skipped: [{id, reason}, ...],
        failed: [{id, path, error}, ...]}``.
        """
        body = request.get_json(silent=True)
        if not isinstance(body, dict):
            return json_error("photo_ids required")
        photo_ids = body.get("photo_ids")
        if not isinstance(photo_ids, list) or not photo_ids:
            return json_error("photo_ids required")
        for pid in photo_ids:
            # ``bool`` is a subclass of ``int`` in Python, so a bare
            # ``isinstance(pid, int)`` would accept ``True``/``False`` as
            # valid ids — and ``True`` would then be treated as photo id 1.
            # Reject booleans explicitly so ``{"photo_ids": [true]}`` can't
            # trick the endpoint into trashing whichever rejected row
            # happens to have id 1.
            if isinstance(pid, bool) or not isinstance(pid, int):
                return json_error("photo_ids must be a list of integers")

        db = _get_db()
        # Chunk the lookup SELECT — bulk cleanup actions may hand us thousands
        # of ids at once, and SQLite builds with the legacy 999-parameter cap
        # would otherwise fail before any cleanup runs.
        rows_by_id = {}
        for chunk in _chunked(photo_ids):
            placeholders = ",".join("?" * len(chunk))
            chunk_rows = db.conn.execute(
                f"""SELECT p.id, p.flag, p.file_hash, p.filename,
                           f.path AS folder_path
                    FROM photos p
                    LEFT JOIN folders f ON f.id = p.folder_id
                    WHERE p.id IN ({placeholders})""",
                chunk,
            ).fetchall()
            for r in chunk_rows:
                rows_by_id[r["id"]] = r

        # One query per distinct hash to find kept-row anchors. Cheap because
        # the hash column is indexed and a typical bulk action shares hashes
        # across many photo_ids only when the user clicks "trash all losers"
        # for one library — still a small number of distinct hashes.
        hashes = {r["file_hash"] for r in rows_by_id.values() if r["file_hash"]}
        anchored_hashes = set()
        for h in hashes:
            anchor = db.conn.execute(
                "SELECT 1 FROM photos "
                "WHERE file_hash = ? AND (flag IS NULL OR flag != 'rejected') LIMIT 1",
                (h,),
            ).fetchone()
            if anchor is not None:
                anchored_hashes.add(h)

        trash_candidates = []
        trashed_pids = []
        skipped = []
        failed = []
        # Classify paths via the bounded kernel mount table BEFORE any
        # per-path stat. Calling ``os.path.isfile`` on an unhealthy SMB path
        # can block indefinitely inside this endpoint, meaning the new
        # network routing inside ``_trash_paths`` would never even be
        # reached; a stat failure would also be misread as "already
        # missing" and drop the DB row for a photo that reappears on
        # remount. Local paths keep the existing preflight — a fast, safe
        # stat on the local FS — so the "file already missing" reporting
        # contract for manually-cleaned local losers is preserved.
        network_roots = _network_volume_roots()
        for pid in photo_ids:
            row = rows_by_id.get(pid)
            if row is None:
                skipped.append({"id": pid, "reason": "photo not found"})
                continue
            if row["flag"] != "rejected":
                skipped.append({"id": pid, "reason": "photo is not rejected"})
                continue
            if not row["file_hash"] or row["file_hash"] not in anchored_hashes:
                # No kept row shares this hash — refuse to trash. Treat as
                # "not a duplicate loser" so the user can't accidentally use
                # this endpoint to delete files for unrelated rejected rows.
                skipped.append({"id": pid, "reason": "no duplicate winner exists"})
                continue
            filepath = os.path.join(row["folder_path"] or "", row["filename"] or "")
            if _path_on_network_volume(filepath, network_roots):
                # Never stat a network path from this thread — delegate
                # entirely to ``_trash_paths``, which routes network
                # candidates through a time-bounded Finder subprocess. If
                # the file is truly gone, Finder will report "missing" and
                # the bounded mount-identity revalidation there decides
                # whether to accept it as end-state or preserve the row.
                trash_candidates.append((pid, filepath))
                continue
            file_existed = os.path.isfile(filepath)
            if not file_existed:
                # File was removed outside Vireo (e.g. user trashed in Finder).
                # Drop the orphan DB row anyway so the summary count drops —
                # without this, manually-cleaned losers would also "report
                # forever". The "skipped" status still surfaces the no-op to
                # the caller for accurate reporting.
                skipped.append({"id": pid, "reason": "file already missing"})
                trashed_pids.append(pid)
                continue
            trash_candidates.append((pid, filepath))

        # Track paths whose end state already held (local preflight found
        # them absent, or Finder reported them missing on a still-mounted
        # network volume). Without this the network path would silently
        # succeed with ``trashed: 0`` and empty ``skipped``/``failed``,
        # leaving the UI stuck on "Moving to Trash..." — the local branch
        # already surfaces "file already missing" and the network branch
        # must match so cleanup is a terminal state either way.
        already_missing_paths = set()
        # Pass through our mount-table snapshot — including an explicit
        # ``None`` when our own query failed — so ``_trash_paths`` does
        # not re-query and overwrite our fail-closed classification. If
        # its second query happened to succeed after the share detached,
        # a custom-mount path we already flagged network (via the
        # ``/Volumes`` fallback in ``_path_on_network_volume``) would be
        # silently reclassified as local, reintroducing the unbounded-I/O
        # hang this routing exists to prevent.
        trashed, successful_paths, trash_failures = _trash_paths(
            [filepath for _pid, filepath in trash_candidates],
            already_missing_out=already_missing_paths,
            network_roots=network_roots,
        )
        failure_by_path = {
            failure["path"]: failure for failure in trash_failures
        }
        for pid, filepath in trash_candidates:
            if filepath in successful_paths:
                if filepath in already_missing_paths:
                    skipped.append({
                        "id": pid, "reason": "file already missing",
                    })
                trashed_pids.append(pid)
                continue
            failure = failure_by_path.get(filepath) or {}
            failed.append({
                "id": pid,
                "path": filepath,
                "error": failure.get("error", "Trash operation failed"),
            })

        # Drop DB rows + cached derivatives for every photo whose file is now
        # gone. Chunked so ``delete_photos``' five internal IN-clause queries
        # can't trip the SQLite parameter cap on large bulk actions; without
        # chunking, a 1000+ id request would raise OperationalError on legacy
        # builds AFTER files were already trashed, leaving the DB inconsistent.
        if trashed_pids:
            try:
                all_files = []
                deleted_rows = 0
                for chunk in _chunked(trashed_pids):
                    result = db.delete_photos(chunk)
                    all_files.extend(result.get("files", []))
                    deleted_rows += result.get("deleted", 0)
                _cleanup_cached_files_for_deleted_photos(all_files)
                if deleted_rows:
                    _invalidate_missing_originals_cache()
            except Exception:
                # Files are already in Trash; if the row delete fails we
                # surface a 500 so the caller knows reconciliation is
                # incomplete. Without raising, the summary count would stay
                # inflated and the caller would have no signal that the
                # cleanup is half-done.
                log.exception(
                    "DB row delete failed after trashing %d files", len(trashed_pids),
                )
                return jsonify({
                    "ok": False,
                    "error": "trashed files but failed to clean up DB rows",
                    "trashed": trashed,
                    "skipped": skipped,
                    "failed": failed,
                }), 500

        return jsonify({
            "ok": True,
            "trashed": trashed,
            "skipped": skipped,
            "failed": failed,
        })

    @app.route("/api/duplicates/last-scan", methods=["GET"])
    def api_duplicates_last_scan():
        """Return the most recent completed duplicate-scan's result.

        The /duplicates page only holds proposals in JS memory, so
        navigating away and back used to require a full rescan. This
        lets the page restore prior results from ``job_history`` instead.

        Library-wide on purpose: duplicate detection itself ignores
        workspace scope (photos are global), so the result of any
        completed scan is valid for any active workspace — even though
        the row carries the triggering workspace's id.

        Response: ``{found: false}`` or
        ``{found: true, job_id, started_at, finished_at, result}``.
        """
        db = _get_db()
        row = db.conn.execute(
            """SELECT id, started_at, finished_at, result
                 FROM job_history
                WHERE type = 'duplicate-scan'
                  AND status = 'completed'
                  AND result IS NOT NULL
                ORDER BY finished_at DESC
                LIMIT 1"""
        ).fetchone()
        if row is None:
            return jsonify({"found": False})
        try:
            result = json.loads(row["result"])
        except (json.JSONDecodeError, TypeError):
            return jsonify({"found": False})
        attach_nested_edit_recipes(db, result)
        return jsonify({
            "found": True,
            "job_id": row["id"],
            "started_at": row["started_at"],
            "finished_at": row["finished_at"],
            "result": result,
        })

    @app.route("/api/duplicates/disk-cleanup-summary", methods=["GET"])
    def api_duplicates_disk_cleanup_summary():
        """Return counts of duplicate-loser files that may still be on disk.

        Body: ``{count: int, total_size: int, file_hashes: [str, ...]}``.

        Powers the navbar banner that surfaces the volume of cleanup
        available — without it, auto-resolved duplicates from scan are
        invisible to the user.

        ``count`` is the number of rejected photo rows whose hash is also
        held by a non-rejected row (i.e. duplicate losers, not unrelated
        rejections). ``total_size`` is the sum of their stored ``file_size``
        — a best-effort estimate; we do NOT stat each path here because
        slow network volumes (e.g. SMB) would make this endpoint expensive
        on every banner poll. The bulk-trash endpoint validates each file
        exists before trashing.
        """
        db = _get_db()
        row = db.conn.execute(
            """
            SELECT COUNT(*) AS n, COALESCE(SUM(file_size), 0) AS total_bytes
            FROM photos p
            WHERE p.flag = 'rejected'
              AND p.file_hash IS NOT NULL
              AND EXISTS (
                  SELECT 1 FROM photos q
                  WHERE q.file_hash = p.file_hash AND (q.flag IS NULL OR q.flag != 'rejected')
              )
            """
        ).fetchone()
        return jsonify({
            "count": row["n"],
            "total_size": row["total_bytes"],
        })

    @app.route("/api/jobs/previews", methods=["POST"])
    @background_job
    def api_job_previews(ctx):
        body = request.get_json(silent=True) or {}
        collection_id = body.get("collection_id")
        requested_photo_ids = body.get("photo_ids")
        if requested_photo_ids is not None:
            if (
                not isinstance(requested_photo_ids, list)
                or any(
                    isinstance(photo_id, bool)
                    or not isinstance(photo_id, int)
                    or photo_id <= 0
                    for photo_id in requested_photo_ids
                )
            ):
                return json_error("photo_ids must be a list of positive integers")
            requested_photo_ids = list(dict.fromkeys(requested_photo_ids))
        if collection_id is not None and requested_photo_ids is not None:
            return json_error("collection_id and photo_ids cannot be combined")
        db = _get_db()
        err = _reject_visual_collection(db, collection_id)
        if err is not None:
            return err

        def work(job):
            import contextlib

            import config as cfg

            thread_db = ctx.thread_db()
            vireo_dir = os.path.dirname(app.config["THUMB_CACHE_DIR"])
            # Use workspace-effective config so per-workspace preview_max_size
            # overrides are honored — otherwise precompute warms the wrong
            # size and /photos/<id>/full (which uses workspace overrides) still
            # misses on first view.
            effective = thread_db.get_effective_config(cfg.load())
            raw_size = effective.get("preview_max_size")
            if raw_size == 0:
                # "Full resolution" — /full redirects to /original so
                # there's no size-suffixed file to warm. Skip precompute
                # rather than produce untracked {id}.jpg files.
                job["_start_time"] = time.time()
                return {"generated": 0, "skipped": 0, "total": 0,
                        "note": "skipped (preview_max_size=0)"}
            max_size = int(raw_size or 1920)

            preview_quality = effective.get("preview_quality", 90)
            preview_dir = os.path.join(vireo_dir, "previews")
            os.makedirs(preview_dir, exist_ok=True)

            if requested_photo_ids is not None:
                photos = []
                for photo_id in requested_photo_ids:
                    scoped_photo = thread_db.get_photo(
                        photo_id, verify_workspace=True,
                    )
                    if scoped_photo is not None:
                        photos.append(scoped_photo)
            elif collection_id:
                photos = thread_db.get_collection_photos(collection_id, per_page=999999)
            else:
                photos = thread_db.get_photos(per_page=999999)

            folders = {f["id"]: f["path"] for f in thread_db.get_folder_tree()}
            total = len(photos)
            generated = 0
            skipped = 0
            failed = 0
            job["_start_time"] = time.time()

            for i, photo in enumerate(photos):
                if ctx.runner.is_cancelled(job["id"]):
                    break
                detail_photo = thread_db.get_photo(photo["id"]) or photo
                cache_path = os.path.join(preview_dir, f'{photo["id"]}_{max_size}.jpg')
                recipe = thread_db.get_photo_edit_recipe(photo["id"])
                if os.path.exists(cache_path):
                    cache_row = None
                    with contextlib.suppress(Exception):
                        cache_row = thread_db.preview_cache_get(photo["id"], max_size)
                    if recipe and cache_row is None:
                        with contextlib.suppress(OSError):
                            os.remove(cache_path)
                        if os.path.exists(cache_path):
                            skipped += 1
                            log.info(
                                "Skipping untracked edited preview for photo %s; "
                                "existing cache file could not be removed",
                                photo["id"],
                            )
                            continue
                    else:
                        skipped += 1
                        # Adopt untracked unedited files so precompute output is
                        # visible to eviction and /api/preview-cache.
                        # Best-effort: photo may be deleted mid-job (FK error).
                        with contextlib.suppress(Exception):
                            if cache_row is None:
                                thread_db.preview_cache_insert(
                                    photo["id"],
                                    max_size,
                                    os.path.getsize(cache_path),
                                )
                        continue

                if not os.path.exists(cache_path):
                    folder_path = folders.get(detail_photo["folder_id"])
                    try:
                        materialized = materialize_preview(
                            thread_db,
                            detail_photo,
                            folder_path,
                            size=max_size,
                            vireo_dir=vireo_dir,
                            preview_quality=preview_quality,
                            recipe=recipe,
                            cache_path=cache_path,
                        )
                    except (ArtifactProducerFailed, PreviewMaterializationError) as exc:
                        # A source we could not read is a failure, not a
                        # cache hit; counting it as skipped made an
                        # all-unreadable run look fully cached.
                        failed += 1
                        log.info(
                            "Preview warmup failed for photo %s: %s",
                            photo["id"], exc,
                        )
                    else:
                        if materialized.generated:
                            generated += 1
                        else:
                            skipped += 1

                ctx.runner.push_event(
                    job["id"],
                    "progress",
                    {
                        "current": i + 1,
                        "total": total,
                        "current_file": photo["filename"],
                        "rate": round(
                            (i + 1) / max(time.time() - job["_start_time"], 0.01), 1
                        ),
                        "phase": "Generating previews",
                    },
                )

            # Park a pause requested during the final iteration before the
            # eviction pass, which can unlink many previews and rewrite their
            # database rows. Without this checkpoint the accepted request
            # would remain ``pausing`` while eviction ran, and a cancel from
            # that state could leave the cache mid-eviction.
            if ctx.runner.is_cancelled(job["id"]):
                return {"generated": generated, "skipped": skipped,
                        "failed": failed, "total": total}

            # Run a single eviction pass at the end so the batch doesn't
            # fsync after every photo.
            evict_preview_cache_if_over_quota(thread_db, vireo_dir)

            return {"generated": generated, "skipped": skipped,
                    "failed": failed, "total": total}

        return ctx.start(
            "previews",
            work,
            pausable=True,
            config={
                "collection_id": collection_id,
                "photo_ids": requested_photo_ids,
            },
        )

    @app.route("/api/jobs/ingest", methods=["POST"])
    @background_job
    def api_job_ingest(ctx):
        body = request.get_json(silent=True) or {}
        source = body.get("source", "")
        destination = body.get("destination", "")
        file_types = body.get("file_types", "both")
        folder_template = body.get("folder_template", "%Y/%Y-%m-%d")
        skip_duplicates = body.get("skip_duplicates", True)
        verify_by_hash = bool(body.get("verify_by_hash"))

        if not source or not destination:
            return json_error("source and destination are required")
        from image_loader import is_excluded_scan_path
        # See api_job_scan for why this must run before os.path.isdir.
        if is_excluded_scan_path(source):
            return json_error(
                f"source is inside a macOS app-managed library and cannot "
                f"be imported: {source}"
            )
        if not os.path.isdir(source):
            return json_error(f"source directory not found: {source}")
        if not os.path.isabs(destination):
            return json_error("destination must be an absolute path")
        from ingest import _is_unsafe_path
        if folder_template and _is_unsafe_path(folder_template):
            return json_error("folder_template must be a relative path without '..' or backslashes")

        def work(job):
            from ingest import ingest as do_ingest

            thread_db = ctx.thread_db()

            job["_start_time"] = time.time()

            def progress_cb(current, total, filename):
                job["progress"]["current"] = current
                job["progress"]["total"] = total
                job["progress"]["current_file"] = filename
                ctx.runner.push_event(
                    job["id"],
                    "progress",
                    {
                        "current": current,
                        "total": total,
                        "current_file": filename,
                        "rate": round(
                            current / max(time.time() - job["_start_time"], 0.01), 1
                        ),
                        "phase": "Importing photos",
                    },
                )

            result = do_ingest(
                source_dir=source,
                destination_dir=destination,
                db=thread_db,
                file_types=file_types,
                folder_template=folder_template,
                skip_duplicates=skip_duplicates,
                verify_by_hash=verify_by_hash,
                progress_callback=progress_cb,
                pause_callback=lambda: ctx.checkpoint(job),
            )
            return result

        return ctx.start(
            "ingest",
            work,
            pausable=True,
            config={
                "source": source,
                "destination": destination,
                "file_types": file_types,
                "folder_template": folder_template,
            },
        )

    # -- Move job routes --

    @app.route("/api/jobs/move-photos", methods=["POST"])
    @background_job
    def api_job_move_photos(ctx):
        """Move selected photos to a destination directory."""
        body = request.get_json(silent=True) or {}
        photo_ids = body.get("photo_ids", [])
        destination = body.get("destination", "")
        rule_id = body.get("rule_id")

        if not photo_ids:
            return json_error("photo_ids required")
        if not destination:
            return json_error("destination required")
        if not os.path.isabs(destination):
            return json_error("destination must be an absolute path")

        import config as cfg
        effective_cfg = _get_db().get_effective_config(cfg.load())
        developed_dir = effective_cfg.get("darktable_output_dir", "") or ""

        def work(job):
            from move import move_photos

            thread_db = ctx.thread_db()

            job["_start_time"] = time.time()
            job["progress"]["total"] = len(photo_ids)

            def progress_cb(current, total, filename):
                job["progress"]["current"] = current
                job["progress"]["total"] = total
                job["progress"]["current_file"] = filename
                ctx.runner.push_event(job["id"], "progress", {
                    "current": current,
                    "total": total,
                    "current_file": filename,
                    "rate": round(
                        current / max(time.time() - job["_start_time"], 0.01), 1
                    ),
                    "phase": "Moving photos",
                })

            result = move_photos(
                db=thread_db,
                photo_ids=photo_ids,
                destination=destination,
                progress_cb=progress_cb,
                developed_dir=developed_dir,
                cancel_check=lambda: ctx.runner.cancellation_requested(job["id"]),
                pause_requested=lambda: ctx.runner.pause_requested(job["id"]),
                pause_callback=lambda: ctx.runner.is_cancelled(job["id"]),
            )
            if int(result.get("moved") or 0) > 0:
                try:
                    _invalidate_missing_originals_cache()
                except Exception:
                    log.exception(
                        "Failed to invalidate missing-originals cache "
                        "after move-photos job",
                    )

            if rule_id:
                thread_db.touch_move_rule(rule_id)

            return result

        return ctx.start(
            "move-photos", work, pausable=True,
            config={"photo_ids": photo_ids, "destination": destination},
        )

